INSERT INTO _exercise_staging (id, name, category, equipment, primary_muscles, secondary_muscles, description, video_code, video_filename, gender, is_custom, created_at, steps_to_perform, movement_pattern, force_type, movement_type, laterality, plane_of_motion, difficulty_level, complexity_score, strength_rating, hypertrophy_rating, power_rating, endurance_rating, body_position, bench_angle, grip_type, grip_width, optimal_rep_range_min, optimal_rep_range_max, placement_in_workout, fatigability, popularity_score, home_gym_friendly, instructions, workout_type, practicality_score, fat_loss_rating, general_fitness_rating, is_compound, supersetable, exercise_family, base_exercise_name, complementary_families, is_equipment_primary, equipment_category, duration_based, recommended_sets, rest_seconds, muscles_worked_count, priority_build_muscle, priority_get_lean, priority_home, priority_gym) VALUES
('13f4a816-dbcb-4a21-b445-afac98cf42fd', 'Kneeling Core Mobilization', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'This stretch specifically works on your full body, promoting flexibility and reducing muscle tightness. Kneeling helps eliminate lower body momentum from the movement. Flexibility work like this enhances performance and prevents stiffness.', '92821201', '92821201-Kneeling-Core-Mobilization-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:34.322534+00', '1. Kneel on the floor (use a pad for comfort if needed). 2. Move into the stretch position for Kneeling Core Mobilization. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 38, 2, 6, FALSE, TRUE, 'mobility', 'Kneeling Core Mobilization', 'squat, leg_extension, lunge', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('13ffcd32-ed44-4e49-a40c-3f71089eee9a', 'Incline Row (Dumbbell)', 'Back', 'Dumbbells, Incline Bench', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'Target your rhomboids and mid-traps with this rowing movement. You''ll also feel your biceps, rear delts working to support the movement. The incline angle shifts emphasis toward the upper portion of the target muscles. Using dumbbells requires more stabilization than barbell variations. A strong back improves posture, prevents injury, and balances pressing movements.', '3271201', '03271201-Dumbbell-Incline-Row_Back-FIX2_.mp4', 'male', FALSE, '2025-12-03 23:26:23.172397+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Incline Row. 2. Pull the weight toward your torso, leading with your elbow(s). 3. Squeeze your shoulder blades together at the peak contraction. 4. Extend back out with control, feeling the stretch in your back. 5. Continue for your target rep count, maintaining good form throughout. Keep your core engaged for stability.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 8, NULL, TRUE, NULL, 'Strength', 85, 7, 9, TRUE, FALSE, 'dumbbell_row', 'Incline Row', 'lat_pulldown, bent_over_row, pull_up', TRUE, 'dumbbell', FALSE, 4, 120, 4, 92, 90, 92, 90),
('14008598-987c-46dc-aeb6-5f3e8e01e2be', 'Seated Thoracic Spine Mobilization (Chair)', 'Full Body', 'Chair', '{"Full Body"}'::text[], '{}'::text[], 'The Seated Thoracic Spine Mobilization On A Chair provides a deep stretch for your full body, ideal for recovery and mobility work. The seated position helps isolate the target muscles by removing momentum. Flexibility work like this enhances performance and prevents stiffness.', '93351201', '93351201-Sitting-Thoracic-Spine-Mobilization-on-a-Chair-(fe.mp4', 'female', FALSE, '2025-12-03 23:26:37.877283+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Move into the stretch position for Seated Thoracic Spine Mobilization On A Chair. 4. Ease into the stretch until you feel gentle tension (not pain). 5. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 23, 2, 6, FALSE, TRUE, 'mobility', 'Seated Thoracic Spine Mobilization On A Chair', 'running, elliptical, rowing_cardio', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('1402af2d-0b24-4573-8317-5448e4a361c5', 'Hip Thrust On Knees (Resistance Band)', 'Legs', 'Resistance Band', '{"Glutes"}'::text[], '{"Hamstrings","Core"}'::text[], 'Build stronger glutes with this thrusting movement focused on hip extension. Secondary activation of your hamstrings provides additional muscle engagement. The band creates increasing tension as it stretches, challenging the lockout. Strong legs are the foundation for athletic performance and functional fitness.', '32361201', '32361201-Resistance-Band-Hip-Thrusts-on-Knees-(Female)_Hips.mp4', 'female', FALSE, '2025-12-03 23:26:36.128549+00', '1. Secure the resistance band appropriately for Resistance Band Hip Thrusts On Knees. 2. Drive through your heels to lift your hips toward the ceiling. 3. Squeeze your glutes hard at the top of the movement. 4. Lower your hips back down with control. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 75, 7, 8, TRUE, TRUE, 'hip_thrust', 'Hip Thrust On Knees', 'glute_bridge, romanian_deadlift, leg_curl', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('14089701-37e9-4593-a1ad-ba42c7ccf88d', 'Standing Kickback (Dumbbell)', 'Arms', 'Dumbbells', '{"Triceps"}'::text[], '{"Rear Delts"}'::text[], 'Build stronger triceps with this kicking exercise for bigger arms. Secondary activation of your hamstrings provides additional muscle engagement. The standing position engages your core for stability. The dumbbell variation provides freedom of movement and greater range of motion. Dedicated arm training builds both strength and muscular definition.', '4201201', '04201201-Dumbbell-Standing-Kickback_Upper-Arms.mp4', 'male', FALSE, '2025-12-03 23:26:21.249384+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Standing Kickback. 2. Stand tall with your feet firmly planted. 3. Keep your upper arm stationary and extend your forearm back. 4. Squeeze at full extension, then return with control. 5. Continue for your target rep count, maintaining good form throughout. Maintain consistent tempo throughout the set.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 64, 5, 7, FALSE, TRUE, 'tricep_kickback', 'Standing Kickback', 'lat_pulldown, bent_over_row, pull_up', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('142d3d17-a099-447b-ae07-cd6f4f886414', 'Triceps Extension (TRX)', 'Arms', 'TRX', '{"Triceps"}'::text[], '{"Chest","Shoulders"}'::text[], 'This extension movement isolates your triceps for improved arm development. Suspension training adds instability, increasing core activation throughout. Arm strength supports grip, pulling, and pushing in compound movements.', '11041201', '11041201-Suspender-Triceps-Extension-(female)_Upper-Arms_.mp4', 'female', FALSE, '2025-12-03 23:26:39.623429+00', '1. Adjust the TRX/suspension straps to the appropriate length for Suspender Triceps Extension. 2. Extend at the elbow until your arm is straight, squeezing the tricep. 3. Lower with control, keeping your upper arm stationary. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'tricep_extension', 'Suspender Triceps Extension', 'tricep_pushdown, close_grip_bench', FALSE, 'trx', FALSE, 3, 60, 2, 68, 85, 85, 70),
('1432fbce-9bc6-423f-9df3-3968c94cedc0', 'Reverse Lunge Forward Lunge', 'Legs', 'Bodyweight', '{"Glutes"}'::text[], '{"Quads","Hamstrings"}'::text[], 'Target the front of your thighs with this lunging exercise for quad development. Secondary activation of your glutes, hamstrings provides additional muscle engagement. No equipment needed—your body provides all the resistance. Lower body strength improves everything from walking to heavy compound lifts. Works well as both a primary exercise or accessory movement. Consistency with this movement will yield noticeable results.', '80921201', '80921201-Reverse-Lunge-Forward-Lunge-(female)_Thighs_.mp4', 'female', FALSE, '2025-12-03 23:26:36.266593+00', '1. Step backward, lowering your back knee toward the floor. 2. Push through your front/working leg to return to the starting position. 3. Complete all reps with control before resting. Control the movement—avoid using momentum. Works well for quads activation.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'lunge', 'Reverse Lunge Forward Lunge', 'split_squat, step_up, squat', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('14362b57-b02f-407a-9995-9972a24960ff', 'Kneeling Pike Push Up (On Bench)', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'The Kneeling Pike Push Up (on Bench) is a pushing exercise that targets your delts for shoulder development. The triceps, front delts assist throughout the movement, making this a well-rounded exercise. Kneeling helps eliminate lower body momentum from the movement. Shoulder development enhances both performance and upper body aesthetics.', '79251201', '79251201-Kneeling-Pike-Push-up-(on-Bench)-(female)_Shoulder.mp4', 'female', FALSE, '2025-12-03 23:26:34.487002+00', '1. Kneel on the floor (use a pad for comfort if needed). 2. Keep your body in a straight line from head to heels throughout. 3. Lower your chest toward the floor by bending your elbows. 4. Push through your palms to return to the starting position. 5. Complete all reps with control before resting. Keep tension on the target muscles throughout. A solid choice for shoulders day.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'push_up', 'Kneeling Pike Push Up', 'bench_press, chest_fly, dip', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('144282ec-f330-4c96-8c6e-a36c61a6988f', 'Peroneals Stretch', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Peroneals Stretch isolates your calf muscles through a stretching motion. No equipment needed—your body provides all the resistance. Lower body strength improves everything from walking to heavy compound lifts.', '43251201', '43251201-Peroneals-Stretch-(female)_Calves.mp4', 'female', FALSE, '2025-12-03 23:26:35.667316+00', '1. Set up in the starting position for Peroneals Stretch. 2. Execute the movement with proper form, focusing on your calves. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'stretch_general', 'Peroneals Stretch', 'stretch_hip, stretch_back, stretch_shoulder', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('14469020-d775-4863-b183-5446068e6150', 'Change Plyo Side Lunge (Dumbbell)', 'Legs', 'Dumbbells', '{"Quads"}'::text[], '{"Glutes","Inner Thighs"}'::text[], 'Build stronger quads with this lunging movement that develops leg drive and power. The glutes, hamstrings assist throughout the movement, making this a well-rounded exercise. The dumbbell variation provides freedom of movement and greater range of motion. Leg training boosts metabolism and builds functional, real-world strength.', '72651201', '72651201-Dumbbell-Change-Plyo-Side-Lunge-(male)_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:29.483269+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Change Plyo Side Lunge. 2. Step to the side, bending that knee while keeping the other leg straight. 3. Push through your front/working leg to return to the starting position. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 82, 9, 8, TRUE, TRUE, 'lunge', 'Change Plyo Side Lunge', 'split_squat, step_up, squat', TRUE, 'dumbbell', FALSE, 3, 60, 4, 92, 90, 92, 90),
('144e8738-3f12-4d17-9bc1-46c4811f7e34', 'Hip Extension - Standing (Machine)', 'Legs', 'Machine', '{"Glutes"}'::text[], '{"Hamstrings"}'::text[], 'Build stronger glutes with this extension movement focused on hip extension. You''ll also feel your hamstrings working to support the movement. The standing position engages your core for stability. Machine exercises are great for isolating muscles and training to failure safely. Strong legs are the foundation for athletic performance and functional fitness.', '10311201', '10311201-Lever-Standing-Hip-Extension_Hips.mp4', 'male', FALSE, '2025-12-03 23:26:27.504261+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Standing Hip Extension. 2. Begin in a standing position with good posture. 3. Extend through the target joint(s) for Lever Standing Hip Extension. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, FALSE, NULL, 'Strength', 80, 5, 7, FALSE, TRUE, 'glute_kickback', 'Lever Standing Hip Extension', 'hip_thrust, lunge, squat', FALSE, 'machine', FALSE, 3, 60, 2, 80, 75, 20, 88),
('1455963c-3f96-4e11-9e4d-73ac912c0ba0', 'Glute Ham Raise With Extended Arms', 'Legs', 'Bodyweight', '{"Glutes"}'::text[], '{"Hamstrings"}'::text[], 'The Glute Ham Raise With Extended Arms is a hip-dominant raising exercise that targets your glutes. A versatile bodyweight movement perfect for home or gym training. Leg training boosts metabolism and builds functional, real-world strength.', '48901201', '48901201-Glute-Ham-Raise-with-Extended-Arms_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:25.341124+00', '1. Raise the weight in the prescribed direction for Glute Ham Raise With Extended Arms. 2. Lower with control, maintaining tension throughout. 3. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'glute_exercise', 'Glute Ham Raise With Extended Arms', 'hip_thrust, glute_bridge, leg_curl', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('14592fd7-e2d6-42e6-94c0-9abecf6c9465', 'Spiderman Rollout (Barbell)', 'Core', 'Barbell', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Barbell Spiderman Rollout is a lower body movement exercise that targets your abs. You''ll also feel your lats, shoulders working to support the movement. Using a barbell provides stability for progressive overload. Leg training boosts metabolism and builds functional, real-world strength.', '103731201', '103731201-Barbell-Spiderman-Rollout_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:25.233728+00', '1. Grip a barbell with hands at the appropriate width for Barbell Spiderman Rollout. 2. Set up in the starting position for Barbell Spiderman Rollout. 3. Execute the movement with proper form, focusing on your abs. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 62, 7, 8, TRUE, TRUE, 'ab_rollout', 'Spiderman Rollout', 'plank, crunch, dead_bug', FALSE, 'barbell', FALSE, 3, 90, 4, 95, 80, 65, 95),
('14596d52-a1ba-44e1-bece-b2ee4d989766', 'Incline Triceps Extension (Cable)', 'Arms', 'Cables', '{"Triceps"}'::text[], '{"Chest","Shoulders"}'::text[], 'The Cable Incline Triceps Extension targets your triceps through a extension motion. Using an incline changes the angle of resistance for varied muscle recruitment. Cable resistance creates smooth, continuous muscle engagement. Dedicated arm training builds both strength and muscular definition.', '97371201', '97371201-Cable-Incline-Triceps-Extension-(female)_Upper-Arm.mp4', 'female', FALSE, '2025-12-03 23:26:31.931873+00', '1. Adjust the cable machine to the correct height and attachment for Cable Incline Triceps Extension. 2. Extend at the elbow until your arm is straight, squeezing the tricep. 3. Lower with control, keeping your upper arm stationary. 4. Repeat for the prescribed number of repetitions. Maintain consistent tempo throughout the set.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 93, 5, 7, FALSE, TRUE, 'tricep_extension', 'Incline Triceps Extension', 'tricep_pushdown, close_grip_bench', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('1459c01e-0bb3-4cc7-9ae4-76634eca6ed5', 'Standing Single Arm Chest Stretch', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Front Delts"}'::text[], 'Target your chest with the Standing One Arm Chest Stretch, an effective stretching movement for upper body strength. Performing this standing challenges your balance and core engagement. A versatile bodyweight movement perfect for home or gym training. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '10581201', '10581201-Standing-one-arm-chest-stretch_Chest.mp4', 'male', FALSE, '2025-12-03 23:26:21.890719+00', '1. Begin in a standing position with good posture. 2. Complete all reps on one side, then switch to the other side. 3. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, 'Standing', NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 37, 2, 6, FALSE, TRUE, 'chest_stretch', 'Standing Single Arm Chest Stretch', 'stretch_shoulder, stretch_back', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('145b5192-beae-4ff1-a5d6-0f4174198821', 'Flutter Kicks', 'Core', 'Bodyweight', '{"Lower Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build leg strength with this kicking movement focusing on your abs. You''ll also feel your hip flexors working to support the movement. A versatile bodyweight movement perfect for home or gym training. Strong legs are the foundation for athletic performance and functional fitness.', '12441201', '12441201-Flutter-Kicks-(version-3)_Hips.mp4', 'male', FALSE, '2025-12-03 23:26:27.937212+00', '1. Set up in the starting position for Flutter Kicks. 2. Execute the movement with proper form, focusing on your abs. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout. Keep your shoulders relaxed and away from your ears.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'leg_raise', 'Flutter Kicks', 'crunch, plank, v_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('14601de0-bb91-41ee-b4d9-5cc7ecbf9e8e', 'Seated Diagonal Crunch (Chair)', 'Core', 'Chair', '{"Obliques"}'::text[], '{"Hip Flexors","Abs"}'::text[], 'This crunching exercise engages your abs for improved core stability and strength. Your hip flexors work as secondary movers, adding to the training stimulus. Being seated provides stability, allowing you to focus on the working muscles. A strong core improves posture, protects your spine, and enhances all other lifts.', '104991201', '104991201-Seated-Diagonal-Crunch-on-Chair-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:28.397686+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Curl your shoulders off the floor by contracting your abs. 4. Don''t pull on your neck—focus on the abdominal contraction. 5. Lower with control, maintaining some tension. 6. Complete all reps with control before resting. Focus on maintaining proper breathing throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Seated', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 57, 5, 7, FALSE, TRUE, 'crunch', 'Seated Diagonal Crunch On Chair', 'leg_raise, plank, russian_twist, v_up', TRUE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('148afc26-bece-4fe0-88c9-883e00e76e3a', 'Leg Calf Raise (Smith Machine)', 'Legs', 'Smith Machine', '{"Calves"}'::text[], '{}'::text[], 'This raising movement focuses on your gastrocnemius and soleus. The standing position engages your core for stability. Machine exercises are great for isolating muscles and training to failure safely. Lower body strength improves everything from walking to heavy compound lifts.', '26551201', '26551201-Smith-Standing-Leg-Calf-Raise-(female)_Calf.mp4', 'female', FALSE, '2025-12-03 23:26:38.153182+00', '1. Set the Smith machine bar to the appropriate starting height for Smith Standing Leg Calf Raise. 2. Begin in a standing position with good posture. 3. Lower your heels below the platform to get a full stretch. 4. Rise up onto your toes as high as possible, squeezing your calves. 5. Lower with control and repeat. 6. Repeat for the prescribed number of repetitions. Ensure full range of motion on each rep.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 90, 5, 7, FALSE, TRUE, 'calf_raise', 'Smith Standing Leg Calf Raise', 'Standing Leg Calf Raise', FALSE, 'smith_machine', FALSE, 3, 60, 2, 80, 75, 20, 88),
('1497b66f-fbbf-4e62-9503-fb0a098e73f9', 'Kneeling Crunch (Cable)', 'Core', 'Cables', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build a stronger core with the Cable Kneeling Crunch, focusing on your abs. Your hip flexors work as secondary movers, adding to the training stimulus. The kneeling position adds a core stability challenge. Cable resistance creates smooth, continuous muscle engagement. Core strength is foundational for athletic performance and injury prevention.', '70611201', '70611201-Cable-Kneeling-Crunch-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:31.931873+00', '1. Adjust the cable machine to the correct height and attachment for Cable Kneeling Crunch. 2. Kneel on the floor (use a pad for comfort if needed). 3. Curl your shoulders off the floor by contracting your abs. 4. Don''t pull on your neck—focus on the abdominal contraction. 5. Lower with control, maintaining some tension. 6. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 80, 5, 7, FALSE, TRUE, 'crunch', 'Kneeling Crunch', 'leg_raise, plank, russian_twist, v_up', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('1499eb20-dc14-41ad-a470-6af36211f4f5', 'Arm Double Crossover', 'Shoulders', 'Bodyweight', '{"Shoulders"}'::text[], '{"Traps"}'::text[], 'Target your chest with the Arm Double Crossover, an effective movement movement for upper body strength. You''ll also feel your front delts working to support the movement. No equipment needed—your body provides all the resistance. A well-developed chest contributes to upper body strength and aesthetics.', '53651201', '53651201-Arm-Double-Crossover-(female)_Chest_.mp4', 'female', FALSE, '2025-12-03 23:26:30.54809+00', '1. Set up in the starting position for Arm Double Crossover. 2. Execute the movement with proper form, focusing on your chest. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, 'Pull', 'Isolation', 'Bilateral', NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, 'Neutral', 'Standard', 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'chest_fly', 'Arm Double Crossover', 'bench_press, incline_press, push_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('149b1150-6191-4cd4-b65b-d727acee287c', 'Outward Wrist Stretch Clasped Fingers', 'Arms', 'Bodyweight', '{"Forearms"}'::text[], '{}'::text[], 'This stretch specifically works on your wrists, promoting flexibility and reducing muscle tightness. The forearms assist throughout the movement, making this a well-rounded exercise. Flexibility work like this enhances performance and prevents stiffness.', '82461201', '82461201-Outward-Wrist-Stretch-Clasped-Fingers-(female)_Str.mp4', 'female', FALSE, '2025-12-03 23:26:35.667316+00', '1. Move into the stretch position for Outward Wrist Stretch Clasped Fingers. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'wrist_stretch', 'Outward Wrist Stretch Clasped Fingers', 'stretch_hip, stretch_back, stretch_shoulder', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('14a6d7b4-0188-4310-913c-8a5d91185d9a', 'Standing Sprint', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{"Quads","Hamstrings"}'::text[], 'Build power and athleticism with this high-intensity movement exercise that challenges your entire body. The standing position engages your core for stability. A versatile bodyweight movement perfect for home or gym training. Plyometric training builds explosive power that transfers to sports and daily activities.', '57091201', '57091201-Standing-Sprint-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:26.678791+00', '1. Stand with feet about shoulder-width apart. 2. Set up in the starting position for Standing Sprint. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'sprint', 'Standing Sprint', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('14b649ba-e0fd-4c5a-9fd0-6f0855a327ab', 'Seated Upright Twist (Chair)', 'Core', 'Chair', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'Work your side abdominals with this twisting exercise that strengthens your obliques. Your abs work as secondary movers, adding to the training stimulus. The seated position helps isolate the target muscles by removing momentum. Building core stability helps with everything from heavy deadlifts to daily activities.', '83031201', '83031201-Seated-Upright-Twists-on-a-Chair-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:24.099303+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Rotate your torso through the movement pattern for Seated Upright Twists On A Chair. 4. Control the rotation in both directions—avoid using momentum. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Seated', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 37, 5, 7, FALSE, TRUE, 'russian_twist', 'Seated Upright Twist On A Chair', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('14bd2157-6345-4af4-9864-fb87d43fbf15', 'Standing Crunch (Band)', 'Core', 'Resistance Band', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build a stronger core with the Band Standing Crunch, focusing on your abs. Your hip flexors work as secondary movers, adding to the training stimulus. The standing position engages your core for stability. The band creates increasing tension as it stretches, challenging the lockout. Core strength is foundational for athletic performance and injury prevention.', '38391201', '38391201-Band-Standing-Crunch-(female)_Waist.mp4', 'female', FALSE, '2025-12-03 23:26:30.887491+00', '1. Secure the resistance band appropriately for Band Standing Crunch. 2. Begin in a standing position with good posture. 3. Curl your shoulders off the floor by contracting your abs. 4. Don''t pull on your neck—focus on the abdominal contraction. 5. Lower with control, maintaining some tension. 6. Complete all reps with control before resting. Maintain a neutral spine throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 77, 5, 7, FALSE, TRUE, 'crunch', 'Standing Crunch', 'leg_raise, plank, russian_twist, v_up', FALSE, 'band', FALSE, 3, 60, 2, 60, 85, 90, 50),
('14c71eb7-649e-44ac-a85f-d8529acae6d6', 'Lying Supine Isometric Single Leg Hamstring Curl (Gymnastic Rings)', 'Legs', 'Gymnastic Rings', '{"Hamstrings"}'::text[], '{"Glutes"}'::text[], 'Strengthen the back of your thighs with this curling exercise. The forearms assist throughout the movement, making this a well-rounded exercise. Performing this lying down removes momentum for stricter form. Strong legs are the foundation for athletic performance and functional fitness.', '101271201', '101271201-Lying-Supine-Isometric-Single-Leg-Hamstring-Curl-.mp4', 'female', FALSE, '2025-12-03 23:26:35.38119+00', '1. Lie on your back with your body relaxed but ready. 2. Curl your heels toward your glutes by bending at the knees. 3. Squeeze your hamstrings at peak contraction. 4. Extend legs back out with control. 5. Hold the position for the prescribed time, maintaining tension. 6. Complete all reps on one side, then switch to the other side.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 48, 5, 7, FALSE, TRUE, 'leg_curl', 'Lying Supine Isometric Single Leg Hamstring Curl', 'romanian_deadlift, hip_thrust', FALSE, 'gymnastic_rings', TRUE, 3, 60, 2, 68, 85, 85, 70),
('14c8c05b-c7b7-4759-9ceb-33ec0d81716c', 'Tip Toes', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build stronger calves with this targeted movement exercise. This bodyweight exercise requires no equipment and can be done anywhere. Leg training boosts metabolism and builds functional, real-world strength.', '85991201', '85991201-Tip-Toes-(male)_Calves_.mp4', 'male', FALSE, '2025-12-03 23:26:21.995567+00', '1. Set up in the starting position for Tip Toes. 2. Execute the movement with proper form, focusing on your calves. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'calf_raise', 'Tip Toes', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('14cff221-962e-4172-b1cd-8179c4450b4e', 'Reclining Big Toe Pose With Rope', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'The Reclining Big Toe Pose With Rope provides a deep stretch for your full body, ideal for recovery and mobility work. Include this in your routine for better mobility and reduced muscle tension.', '15821201', '15821201-Reclining-Big-Toe-Pose-with-Rope_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:23.987963+00', '1. Move into the stretch position for Reclining Big Toe Pose With Rope. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 50, 2, 6, FALSE, TRUE, 'yoga', 'Reclining Big Toe Pose With Rope', 'stretch_hip, stretch_back, plank', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('14d2f86c-51ca-42fe-ba7c-3c9b5db76d39', 'Bulgarian Split Squat', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build stronger quads with this squatting movement that develops leg drive and power. Secondary activation of your glutes, hamstrings provides additional muscle engagement. No equipment needed—your body provides all the resistance. Leg training boosts metabolism and builds functional, real-world strength.', '35331201', '35331201-Bulgarian-Split-Squat_Thighs-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:23.79417+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. 4. Complete all reps with control before resting. Engage your stabilizer muscles for better control.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'split_squat', 'Bulgarian Split Squat', 'split_squat, lunge, leg_press', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('14db141a-0530-460c-96cb-5259b1dee4da', 'Step Up (Dumbbell)', 'Legs', 'Dumbbells, Step Platform', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Dumbbell Step Up is a stepping exercise that primarily loads your quadriceps. The glutes, hamstrings assist throughout the movement, making this a well-rounded exercise. Using dumbbells requires more stabilization than barbell variations. Leg training boosts metabolism and builds functional, real-world strength.', '58261201', '58261201-Dumbbell-Step-up-(VERSION-2)-(male)_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:24.203368+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Step Up. 2. Set up a box or step platform at the appropriate height. 3. Step one foot onto the elevated surface. 4. Drive through that foot to lift your body up onto the platform. 5. Step back down with control and repeat. 6. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 82, 7, 8, TRUE, TRUE, 'step_up', 'Step Up', 'lunge, split_squat, squat', TRUE, 'dumbbell', FALSE, 3, 90, 4, 92, 90, 92, 90),
('14e747f0-4b66-4843-a116-7726522c95b6', 'Table Top Bridge', 'Legs', 'Bodyweight', '{"Glutes"}'::text[], '{"Hamstrings"}'::text[], 'Build stronger glutes with this bridging movement focused on hip extension. Secondary activation of your hamstrings provides additional muscle engagement. No equipment needed—your body provides all the resistance. Lower body strength improves everything from walking to heavy compound lifts.', '48001201', '48001201-Table-Top-Bridge_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:28.71819+00', '1. Drive through your heels to lift your hips toward the ceiling. 2. Squeeze your glutes hard at the top of the movement. 3. Lower your hips back down with control. 4. Repeat for the prescribed number of repetitions. Focus on squeezing the target muscle at peak contraction.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'glute_bridge', 'Table Top Bridge', 'hip_thrust, romanian_deadlift', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('14e762a6-83c5-449f-b676-533a9be73288', 'Decline Sit Up (Decline Bench)', 'Core', 'Decline Bench', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build leg strength with this movement movement focusing on your abs. The hip flexors assist throughout the movement, making this a well-rounded exercise. Declining shifts the emphasis to hit the muscles from a different angle. Lower body strength improves everything from walking to heavy compound lifts.', '2821201', '02821201-Decline-Sit-up_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:22.644637+00', '1. Set up in the starting position for Decline Sit Up. 2. Execute the movement with proper form, focusing on your abs. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 73, 5, 7, FALSE, TRUE, 'crunch', 'Decline Sit Up', 'leg_raise, plank, russian_twist, v_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('14ed263f-68ce-43da-9366-7579e00010da', 'Corpse Pose Savasana', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'This stretch specifically works on your full body, promoting flexibility and reducing muscle tightness. Regular stretching improves flexibility, reduces injury risk, and aids recovery. Aim for full range of motion on every rep.', '58891201', '58891201-Corpse-Pose-Savasana-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:32.374165+00', '1. Move into the stretch position for Corpse Pose Savasana. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 15, 2, 6, FALSE, TRUE, 'yoga', 'Corpse Pose Savasana', 'stretch_hip, stretch_back, plank', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('14ef2dff-4000-4dc2-9324-b96c76d23c0b', 'Punch Stepback', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'A challenging plyometric exercise, the Punch Stepback (front Pov) builds reactive power and improves conditioning. Your shoulders work as secondary movers, adding to the training stimulus. Great for improving athletic performance, burning calories, and building conditioning.', '56831201', '56831201-Punch-Stepback-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:35.801913+00', '1. Set up a box or step platform at the appropriate height. 2. Set up in the starting position for Punch Stepback. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'boxing', 'Punch Stepback', 'core_exercise, shoulder_exercise, burpee', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('14ef3b62-17c3-4ae0-b8d8-14e7329c82f7', 'Standing Arms Circling', 'Shoulders', 'Bodyweight', '{"Shoulders"}'::text[], '{"Traps"}'::text[], 'Build stronger shoulders with this movement movement focusing on your delts. Performing this standing challenges your balance and core engagement. This bodyweight exercise requires no equipment and can be done anywhere. Strong shoulders improve overhead strength and support nearly all upper body movements.', '32581201', '32581201-Standing-Arms-Circling-(female)_Shoulders.mp4', 'female', FALSE, '2025-12-03 23:26:38.425788+00', '1. Stand with feet about shoulder-width apart. 2. Set up in the starting position for Standing Arms Circling. 3. Execute the movement with proper form, focusing on your delts. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'arm_exercise', 'Standing Arms Circling', 'bicep_curl, tricep_extension, hammer_curl', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('14f23d6f-d33d-42a6-b71c-9e379ea57585', 'Bent Over Lat Pulldown (Band)', 'Back', 'Resistance Band, Anchor Point', '{"Lats"}'::text[], '{"Biceps","Upper Back"}'::text[], 'The Band Bent Over Lat Pulldown is a pulling exercise that targets your latissimus dorsi for a wider back. Your biceps, upper back work as secondary movers, adding to the training stimulus. The bent over position requires core engagement to maintain a neutral spine. Resistance bands provide accommodating resistance that increases through the range of motion. Back development is crucial for pulling strength and overall upper body function.', '41441201', '41441201-Band-Bent-Over-Lat-Pulldown_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:29.837118+00', '1. Secure the resistance band appropriately for Band Bent Over Lat Pulldown. 2. Hinge at your hips, pushing them back while keeping your back flat. 3. Pull the bar/handle down toward your upper chest. 4. Drive your elbows down and back, squeezing your lats. 5. Control the weight back up without letting it yank your arms. 6. Repeat for the prescribed number of repetitions. Focus on squeezing the target muscle at peak contraction.', 'Pull Down', 'Pull', 'Compound', 'Bilateral', NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, 'Neutral', 'Standard', 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'lat_pulldown', 'Bent Over Lat Pulldown', 'pull_up, bent_over_row, cable_row, face_pull', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('1501db58-5824-4f94-9ae8-a0cd27c22980', 'Assisted Lying Bent Knee Isometric Hip Adduct (Stability Ball)', 'Core', 'Stability Ball', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Strengthen your midsection with this movement movement that works your core. Performing this lying down removes momentum for stricter form. Using a ball requires constant core engagement to maintain balance. Building core stability helps with everything from heavy deadlifts to daily activities.', '99941201', '99941201-Ball-Assisted-Lying-Bent-Knee-Isometric-Hip-Adduct.mp4', 'female', FALSE, '2025-12-03 23:26:30.685158+00', '1. Position the stability ball as needed for Assisted Lying Bent Knee Isometric Hip Adduct. 2. Lie down in the appropriate position for Assisted Lying Bent Knee Isometric Hip Adduct. 3. Hold the position for the prescribed time, maintaining tension.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 27, 7, 8, TRUE, TRUE, 'glute_exercise', 'Assisted Lying Bent Knee Isometric Hip Adduct', 'hip_thrust, lunge, squat', FALSE, 'stability_ball', TRUE, 3, 90, 4, 70, 88, 95, 65),
('150851fc-37f9-4849-a84d-6cda3012df87', 'Standing Chest Push Hip Extension Kickback', 'Legs', 'Bodyweight', '{"Glutes"}'::text[], '{"Hamstrings"}'::text[], 'Develop your posterior chain with this pushing movement that emphasizes the glutes. Secondary activation of your hamstrings provides additional muscle engagement. Performing this standing challenges your balance and core engagement. No equipment needed—your body provides all the resistance. Lower body strength improves everything from walking to heavy compound lifts.', '97761201', '97761201-Standing-Chest-Push-Hip-Extension-Kickback-(male)_.mp4', 'male', FALSE, '2025-12-03 23:26:23.79417+00', '1. Stand tall with your feet firmly planted. 2. Raise your torso by extending at the lower back/hips. 3. Lower with control, maintaining tension. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 72, 5, 7, FALSE, TRUE, 'glute_kickback', 'Standing Chest Push Hip Extension Kickback', 'hip_thrust, lunge, squat', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('150c2006-18c1-4dc3-8279-ed2b35a0b66f', 'Standing Deep Breathe And Prayer Pull', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Target your full body with the Standing Deep Breathe And Prayer Pull, an effective shoulder pulling exercise. Performing this standing challenges your balance and core engagement. No equipment needed—your body provides all the resistance. Shoulder development enhances both performance and upper body aesthetics.', '96291201', '96291201-Standing-Deep-Breathe-and-Prayer-Pull-(female)_Sho.mp4', 'female', FALSE, '2025-12-03 23:26:38.570929+00', '1. Stand tall with your feet firmly planted. 2. Set up in the starting position for Standing Deep Breathe And Prayer Pull. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout. Keep your shoulders relaxed and away from your ears. Ideal for full body strength and endurance.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 37, 7, 8, TRUE, TRUE, 'breathing', 'Standing Deep Breathe And Prayer Pull', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('151c96e6-0897-422c-a4ed-b2d0150cf715', 'Side Lying Internal Rotation - On A Bench (Dumbbell)', 'Shoulders', 'Dumbbells, Flat Bench', '{"Rotator Cuff"}'::text[], '{"Shoulders"}'::text[], 'The Dumbbell Side Lying Internal Rotation (on A Bench) is a rotation exercise that targets your rotator cuff for shoulder development. Performing this lying down removes momentum for stricter form. Using dumbbells requires more stabilization than barbell variations. Shoulder development enhances both performance and upper body aesthetics.', '69391201', '69391201-Dumbbell-Side-Lying-Internal-Rotation-(on-a-bench).mp4', 'male', FALSE, '2025-12-03 23:26:29.083517+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Side Lying Internal Rotation. 2. Lie on your side with your body aligned. 3. Rotate your torso through the movement pattern for Dumbbell Side Lying Internal Rotation. 4. Control the rotation in both directions—avoid using momentum. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 44, 7, 8, TRUE, TRUE, 'external_rotation', 'Side Lying Internal Rotation', 'squat, bench_press, deadlift', TRUE, 'dumbbell', FALSE, 3, 90, 4, 92, 90, 92, 90),
('15250894-b9e3-456a-ab75-0a75d667f9be', 'Deep Push Up Between (Dumbbell)', 'Chest', 'Dumbbells', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'This pushing exercise focuses on your pectorals for improved chest strength and development. Secondary activation of your triceps, front delts provides additional muscle engagement. Using dumbbells requires more stabilization than barbell variations. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '104551201', '104551201-Deep-Push-up-between-Dumbbells-(male)_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:28.260518+00', '1. Select a pair of dumbbells at an appropriate weight for Deep Push Up Between Dumbbells. 2. Keep your body in a straight line from head to heels throughout. 3. Lower your chest toward the floor by bending your elbows. 4. Push through your palms to return to the starting position. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 82, 7, 8, TRUE, TRUE, 'push_up', 'Deep Push Up Between', 'bench_press, chest_fly, dip', FALSE, 'dumbbell', FALSE, 3, 90, 4, 92, 90, 92, 90),
('1525d209-dd8f-48d4-b495-6aae94734f30', 'Seated Crunch - Leg Raise (Plate Loaded Machine)', 'Core', 'Machine', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Strengthen your midsection with this raising movement that works your abs. Secondary activation of your hip flexors provides additional muscle engagement. Being seated provides stability, allowing you to focus on the working muscles. The machine guides your movement path for safer, more controlled repetitions. A strong core improves posture, protects your spine, and enhances all other lifts.', '6001201', '06001201-Lever-Seated-Leg-Raise-Crunch-(plate-loaded)_Waist.mp4', 'male', FALSE, '2025-12-03 23:26:24.698781+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Seated Leg Raise Crunch. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Curl your shoulders off the floor by contracting your abs. 4. Don''t pull on your neck—focus on the abdominal contraction. 5. Lower with control, maintaining some tension. 6. Repeat for the prescribed number of repetitions. Control the movement—avoid using momentum.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 5, 7, NULL, 6, 'Seated', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 80, 5, 7, FALSE, TRUE, 'leg_raise', 'Lever Seated Leg Raise Crunch', 'crunch, plank, v_up', FALSE, 'machine', FALSE, 3, 60, 2, 80, 75, 20, 88),
('153bed45-83e5-4055-880f-3d603d0414ee', 'Pullover (Dumbbell)', 'Chest', 'Dumbbells, Flat Bench', '{"Chest"}'::text[], '{"Lats","Triceps"}'::text[], 'Build a stronger back with this pulling movement targeting your chest. You''ll also feel your lats, triceps working to support the movement. The dumbbell variation provides freedom of movement and greater range of motion. A strong back improves posture, prevents injury, and balances pressing movements.', '64841201', '64841201-Dumbbell-Pullover-(VERSION-2)-(female)_Back_.mp4', 'female', FALSE, '2025-12-03 23:26:33.034396+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Pullover. 2. With arms slightly bent, lower the weight behind your head in an arc. 3. Pull the weight back over your chest, squeezing your lats and chest. 4. Complete all reps with control before resting. Keep tension on the target muscles throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 62, 7, 8, TRUE, TRUE, 'pullover', 'Pullover', 'bicep_curl, face_pull, lat_pulldown', TRUE, 'dumbbell', FALSE, 3, 90, 4, 92, 90, 92, 90),
('153ce659-a51b-4a3b-932b-68dadebfee6a', 'Bent Over Single Arm Horizontal Row (Cable)', 'Back', 'Cables', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'The Cable Bent Over Single Arm Horizontal Row is a rowing exercise that builds thickness in your upper back. Your biceps, rear delts work as secondary movers, adding to the training stimulus. Bending over allows gravity to provide resistance in a different plane. Cable resistance creates smooth, continuous muscle engagement. Back development is crucial for pulling strength and overall upper body function.', '106661201', '106661201-Cable-Bent-Over-Single-Arm-Horizontal-Row-(male)_.mp4', 'male', FALSE, '2025-12-03 23:26:29.242428+00', '1. Adjust the cable machine to the correct height and attachment for Cable Bent Over Single Arm Horizontal Row. 2. Hinge at your hips, pushing them back while keeping your back flat. 3. Pull the weight toward your torso, leading with your elbow(s). 4. Squeeze your shoulder blades together at the peak contraction. 5. Extend back out with control, feeling the stretch in your back. 6. Complete all reps on one side, then switch to the other side. 7. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 75, 7, 8, TRUE, TRUE, 'arm_exercise', 'Bent Over Single Arm Horizontal Row', 'bent_over_row, lat_pulldown, bicep_curl', FALSE, 'cable', FALSE, 3, 90, 4, 85, 88, 30, 92),
('1542f802-165d-4986-806c-7bd860a2299e', 'Standing Hip Frontal Rotation Side Slide Arm', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'This full-body rotation exercise challenges multiple muscle groups simultaneously. The standing position engages your core for stability. A versatile bodyweight movement perfect for home or gym training. Full body exercises are time-efficient and build functional, real-world strength. Aim for full range of motion on every rep.', '60841201', '60841201-Standing-Hip-Frontal-Rotation-Side-Slide-Arm-(fema.mp4', 'female', FALSE, '2025-12-03 23:26:38.7451+00', '1. Stand tall with your feet firmly planted. 2. Rotate your torso through the movement pattern for Standing Hip Frontal Rotation Side Slide Arm. 3. Control the rotation in both directions—avoid using momentum. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'glute_exercise', 'Standing Hip Frontal Rotation Side Slide Arm', 'hip_thrust, lunge, squat', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('155a2bc5-87fa-4fc7-9222-6d3508869a72', 'Seated Overhead Reach Press', 'Shoulders', 'Bodyweight', '{"Front Delts"}'::text[], '{"Side Delts","Triceps"}'::text[], 'The Seated Overhead Reach Press is a pressing exercise that develops back strength and muscle. You''ll also feel your upper back working to support the movement. The seated position helps isolate the target muscles by removing momentum. A strong back improves posture, prevents injury, and balances pressing movements.', '89401201', '89401201-Seated-Overhead-Reach-Press-(male)_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:20.392006+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Start with the weight at shoulder level. 3. Press directly overhead until your arms are fully extended. 4. Lower back to shoulder level with control. 5. Repeat for the prescribed number of repetitions. Engage your stabilizer muscles for better control.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 72, 7, 8, TRUE, TRUE, 'shoulder_press', 'Seated Overhead Reach Press', 'lateral_raise, front_raise, rear_delt', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('1565d87f-a52b-4e76-87ae-025563c8e633', 'Elevated Plank Walkout (Step Platform)', 'Core', 'Step Platform, Chair', '{"Abs"}'::text[], '{"Shoulders","Lower Back"}'::text[], 'The Elevated Plank Walkout With A Chair is a core stabilization exercise that primarily targets your abs. Your shoulders, lower back work as secondary movers, adding to the training stimulus. A strong core improves posture, protects your spine, and enhances all other lifts.', '84261201', '84261201-Elevated-Plank-Walkout-with-a-Chair-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:29.36063+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Hold your body in a straight line from head to heels. 3. Don''t let your hips sag or pike up—engage your core and glutes. 4. Breathe steadily while maintaining the position. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 55, 7, 8, TRUE, TRUE, 'plank', 'Elevated Plank Walkout With A Chair', 'side_plank, dead_bug, hollow_hold', TRUE, 'bodyweight', TRUE, 3, 90, 4, 70, 88, 95, 65),
('15a14939-6d26-4361-9bbd-8c6f6cd2c029', 'Roll Tibialis Anterior', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build stronger calves with this targeted movement exercise. This bodyweight exercise requires no equipment and can be done anywhere. Strong legs are the foundation for athletic performance and functional fitness.', '54361201', '54361201-Roll-Tibialis-Anterior-(female)_Calves_.mp4', 'female', FALSE, '2025-12-03 23:26:36.38616+00', '1. Set up in the starting position for Roll Tibialis Anterior. 2. Execute the movement with proper form, focusing on your calves. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'foam_roll', 'Roll Tibialis Anterior', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('15b25d6c-516b-4b6d-98fa-7aaeefd8e31e', 'Kneeling Hold To Stand', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Kneeling Hold To Stand is a lower body movement exercise that targets your core. Kneeling helps eliminate lower body momentum from the movement. No equipment needed—your body provides all the resistance. Strong legs are the foundation for athletic performance and functional fitness.', '73481201', '73481201-Kneeling-Hold-to-Stand-(female)_Thighs_.mp4', 'female', FALSE, '2025-12-03 23:26:34.487002+00', '1. Kneel on the floor (use a pad for comfort if needed). 2. Hold the position for the prescribed time, maintaining tension.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 45, 7, 8, TRUE, TRUE, 'kneeling_hold', 'Kneeling Hold To Stand', 'squat, leg_extension, lunge', FALSE, 'bodyweight', TRUE, 3, 90, 4, 70, 88, 95, 65),
('15b3e596-483f-4d03-b60c-37f05bbf00b8', 'W To Y Superman', 'Back', 'Bodyweight', '{"Lower Back"}'::text[], '{"Glutes","Upper Back"}'::text[], 'The W To Y Superman is a lower body movement exercise that targets your lower back. You''ll also feel your glutes working to support the movement. A versatile bodyweight movement perfect for home or gym training. Strong legs are the foundation for athletic performance and functional fitness.', '55351201', '55351201-W-to-Y-Superman_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:24.203368+00', '1. Set up in the starting position for W To Y Superman. 2. Execute the movement with proper form, focusing on your lower back. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'back_extension', 'W To Y Superman', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('15bb074e-b472-494b-a6ac-956c0e4967bd', 'Revolved Side Angle Pose', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'The Revolved Side Angle Pose provides a deep stretch for your full body, ideal for recovery and mobility work. Flexibility work like this enhances performance and prevents stiffness.', '59001201', '59001201-Revolved-Side-Angle-Pose-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:36.38616+00', '1. Move into the stretch position for Revolved Side Angle Pose. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. 4. Switch sides and repeat for equal time.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 50, 2, 6, FALSE, TRUE, 'yoga', 'Revolved Side Angle Pose', 'stretch_hip, stretch_back, plank', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('15ce4004-e559-4972-84b4-1b32c1bfbe2d', 'Narrow Lunge With (Wall Supported)', 'Legs', 'Wall', '{"Quads","Glutes","Hamstrings"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'Build stronger quads with this rowing movement that develops leg drive and power. Your glutes, hamstrings work as secondary movers, adding to the training stimulus. Leg training boosts metabolism and builds functional, real-world strength.', '87541201', '87541201-Narrow-Lunge-with-Wall-Supported-(female)_Thighs_.mp4', 'female', FALSE, '2025-12-03 23:26:35.532804+00', '1. Position yourself at the appropriate distance from a wall. 2. Use a close/narrow grip (hands closer than shoulder-width). 3. Pull the weight toward your torso, leading with your elbow(s). 4. Squeeze your shoulder blades together at the peak contraction. 5. Extend back out with control, feeling the stretch in your back. 6. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 62, 7, 8, TRUE, TRUE, 'lunge', 'Narrow Lunge With Wall Supported', 'split_squat, step_up, squat', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('15d23d28-85a4-462e-84f8-f49f8cfa4a0d', 'Seated Knee Hug Glute Stretch', 'Legs', 'Bodyweight', '{"Glutes"}'::text[], '{"Hamstrings"}'::text[], 'Use this stretch to open up your glutes area and enhance overall flexibility. Your lower back work as secondary movers, adding to the training stimulus. Being seated provides stability, allowing you to focus on the working muscles. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '82101201', '82101201-Seated-Knee-Hug-Glute-Stretch-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:36.717157+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Move into the stretch position for Seated Knee Hug Glute Stretch. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, 'Seated', NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 42, 2, 6, FALSE, TRUE, 'glute_stretch', 'Seated Knee Hug Glute Stretch', 'stretch_hip, stretch_back', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('15d4c853-cb36-4323-8245-50127f182da8', 'Standing Side Crunch Elbow Drive', 'Core', 'Bodyweight', '{"Obliques"}'::text[], '{"Hip Flexors","Abs"}'::text[], 'The Standing Side Crunch Elbow Drive is an explosive exercise that combines cardiovascular training with dynamic crunching movements. Your abs work as secondary movers, adding to the training stimulus. The standing position engages your core for stability. This bodyweight exercise requires no equipment and can be done anywhere. Plyometric training builds explosive power that transfers to sports and daily activities.', '85841201', '85841201-Standing-Side-Crunch-Elbow-Drive-(male)_Plyometric.mp4', 'male', FALSE, '2025-12-03 23:26:27.504261+00', '1. Stand with feet about shoulder-width apart. 2. Curl your shoulders off the floor by contracting your abs. 3. Don''t pull on your neck—focus on the abdominal contraction. 4. Lower with control, maintaining some tension. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 72, 5, 7, FALSE, TRUE, 'crunch', 'Standing Side Crunch Elbow Drive', 'leg_raise, plank, russian_twist, v_up', TRUE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('15d7b5a2-1ea6-4d84-a8ee-281cc97b6524', 'Standing Curl - Close Grip (Barbell)', 'Arms', 'Barbell', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'Build bigger biceps with this curling movement that targets the front of your arms. Secondary activation of your forearms provides additional muscle engagement. Performing this standing challenges your balance and core engagement. Barbells enable bilateral loading for building raw strength. Dedicated arm training builds both strength and muscular definition.', '1061201', '01061201-Barbell-Standing-Close-Grip-Curl_Upper-Arms.mp4', 'male', FALSE, '2025-12-03 23:26:24.422129+00', '1. Grip a barbell with hands at the appropriate width for Barbell Standing Close Grip Curl. 2. Stand tall with your feet firmly planted. 3. Use a close/narrow grip (hands closer than shoulder-width). 4. Keep your elbows in a fixed position throughout the movement. 5. Curl the weight up by contracting your biceps, squeezing at the top. 6. Lower with control, resisting the weight on the way down. 7. Continue for your target rep count, maintaining good form throughout.', 'Curl', 'Pull', 'Isolation', 'Bilateral', NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, 'Underhand', 'Narrow', 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 84, 5, 7, FALSE, TRUE, 'bicep_curl', 'Standing Curl - Close Grip', 'Standing Curl - Close Grip', FALSE, 'barbell', FALSE, 3, 60, 2, 95, 80, 65, 95),
('15dd9033-a797-44f3-b826-e1354e033f95', 'Drive Front Raise (Dumbbell)', 'Shoulders', 'Dumbbells', '{"Front Delts"}'::text[], '{"Chest"}'::text[], 'The Dumbbell Drive Front Raise is a raising exercise that targets your front delts for shoulder development. The dumbbell variation provides freedom of movement and greater range of motion. Shoulder development enhances both performance and upper body aesthetics.', '86501201', '86501201-Dumbbell-Drive-Front-Raise-(male)_Shoulders_.mp4', 'male', FALSE, '2025-12-03 23:26:29.242428+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Drive Front Raise. 2. Raise the weight in front of you to shoulder height. 3. Lower with control, maintaining tension throughout. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 82, 5, 7, FALSE, TRUE, 'front_raise', 'Drive Front Raise', 'shoulder_press, lateral_raise, rear_delt_fly', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('15e9432d-959b-4398-98d1-87175bccf993', 'Standing Slingshots (Kettlebell)', 'Shoulders', 'Kettlebell', '{"Shoulders"}'::text[], '{"Traps"}'::text[], 'Target your delts with the Kettlebell Standing Slingshots, an effective shoulder movement exercise. Performing this standing challenges your balance and core engagement. The kettlebell grip position adds a unique training stimulus. Shoulder development enhances both performance and upper body aesthetics.', '45341201', '45341201-Kettlebell-Standing-Slingshots-(female)_Shoulders_.mp4', 'female', FALSE, '2025-12-03 23:26:34.196858+00', '1. Select an appropriately weighted kettlebell for Kettlebell Standing Slingshots. 2. Stand tall with your feet firmly planted. 3. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 60, 7, 8, TRUE, TRUE, 'boxing', 'Standing Slingshots', 'squat, bench_press, deadlift', FALSE, 'kettlebell', FALSE, 3, 90, 4, 75, 88, 88, 78),
('15e9f782-862a-4575-9fa4-a9ddd27bba3a', 'Reeves Deadlift (Barbell)', 'Back', 'Barbell', '{"Lower Back"}'::text[], '{"Glutes","Hamstrings","Traps"}'::text[], 'The Barbell Reeves Deadlift is a lower body hip hinge exercise that targets your hamstrings/glutes. You''ll also feel your glutes, lower back working to support the movement. The barbell allows you to handle heavier loads for maximum strength gains. Leg training boosts metabolism and builds functional, real-world strength.', '41161201', '41161201-Barbell-Reeves-Deadlift-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:23.689343+00', '1. Grip a barbell with hands at the appropriate width for Barbell Reeves Deadlift. 2. Hinge at hips and bend knees to grip the weight. 3. Drive through your heels, extending hips and knees to stand. 4. Lower by reversing the movement with control. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 3, 6, NULL, 10, NULL, TRUE, NULL, 'Strength', 97, 7, 9, TRUE, FALSE, 'deadlift', 'Reeves Deadlift', 'romanian_deadlift, hip_thrust, leg_curl', TRUE, 'barbell', FALSE, 4, 120, 6, 95, 80, 65, 95),
('15f92e57-b2c4-40a6-810d-75660de166fc', 'Back Crossover Foot Tap', 'Full Body', 'Bodyweight', '{"Shoulders"}'::text[], '{"Biceps","Triceps","Core"}'::text[], 'A challenging plyometric exercise, the Back Crossover Foot Tap builds reactive power and improves conditioning. The front delts assist throughout the movement, making this a well-rounded exercise. A versatile bodyweight movement perfect for home or gym training. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '77581201', '77581201-Back-Crossover-Foot-Tap-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:30.54809+00', '1. Set up in the starting position for Back Crossover Foot Tap. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'chest_fly', 'Back Crossover Foot Tap', 'bench_press, incline_press, push_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('1605fc66-36f0-4b1c-9d3f-63018004563b', 'Seated Single Arm External Rotation (Dumbbell)', 'Shoulders', 'Dumbbells, Flat Bench', '{"Rotator Cuff"}'::text[], '{"Shoulders"}'::text[], 'Target your rotator cuff with the Dumbbell Seated Single Arm External Rotation, an effective shoulder rotation exercise. The seated position helps isolate the target muscles by removing momentum. Dumbbells allow each arm to work independently, helping correct imbalances. Strong shoulders improve overhead strength and support nearly all upper body movements.', '105991201', '105991201-Dumbbell-Seated-Single-Arm-External-Rotation-(mal.mp4', 'male', FALSE, '2025-12-03 23:26:23.466497+00', '1. Select an appropriate weight dumbbell and hold it in one hand. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Rotate your torso through the movement pattern for Dumbbell Seated Single Arm External Rotation. 4. Control the rotation in both directions—avoid using momentum. 5. Complete all reps on one side, then switch to the other side. 6. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 8, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 59, 7, 8, TRUE, TRUE, 'external_rotation', 'Seated Single Arm External Rotation', 'squat, bench_press, deadlift', TRUE, 'dumbbell', FALSE, 3, 90, 4, 92, 90, 92, 90),
('160e621f-9fb9-4209-89b5-5623acb9a490', 'Prone Incline Hammer Curl (Band)', 'Arms', 'Resistance Band, Incline Bench', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'The Band Prone Incline Hammer Curl is a curling exercise that isolates your biceps. Your forearms work as secondary movers, adding to the training stimulus. Performing this lying down removes momentum for stricter form. The band creates increasing tension as it stretches, challenging the lockout. Arm strength supports grip, pulling, and pushing in compound movements.', '68681201', '68681201-Band-Prone-Incline-Hammer-Curl_Upper-Arms_.mp4', 'male', FALSE, '2025-12-03 23:26:21.249384+00', '1. Secure the resistance band appropriately for Band Prone Incline Hammer Curl. 2. Lie face down (prone position) for Band Prone Incline Hammer Curl. 3. Use a hammer/neutral grip with palms facing each other throughout. 4. Keep your elbows in a fixed position throughout the movement. 5. Curl the weight up by contracting your biceps, squeezing at the top. 6. Lower with control, resisting the weight on the way down. 7. Repeat for the prescribed number of repetitions.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 88, 5, 7, FALSE, TRUE, 'incline_press', 'Prone Incline Hammer Curl', 'bench_press, shoulder_press, chest_fly', FALSE, 'band', FALSE, 3, 60, 2, 60, 85, 90, 50),
('162e25c5-2456-41ef-a6e0-ccfe01eabf0f', 'Standing Rear Delt Row - Rope (Cable)', 'Shoulders', 'Cables', '{"Rear Delts"}'::text[], '{"Upper Back","Traps"}'::text[], 'The Cable Standing Rear Delt Row (with Rope) is a rowing exercise that targets your rear delts for shoulder development. The upper back assist throughout the movement, making this a well-rounded exercise. The standing position engages your core for stability. The cable setup allows you to adjust the angle of resistance. Strong shoulders improve overhead strength and support nearly all upper body movements.', '2331201', '02331201-Cable-Standing-Rear-Delt-Row-(with-rope)_Shoulder_.mp4', 'male', FALSE, '2025-12-03 23:26:26.39056+00', '1. Adjust the cable machine to the correct height and attachment for Cable Standing Rear Delt Row. 2. Begin in a standing position with good posture. 3. Pull the weight toward your torso, leading with your elbow(s). 4. Squeeze your shoulder blades together at the peak contraction. 5. Extend back out with control, feeling the stretch in your back. 6. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 74, 7, 8, TRUE, TRUE, 'rear_delt', 'Standing Rear Delt Row', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'cable', FALSE, 3, 90, 4, 85, 88, 30, 92),
('1636dd09-a809-4779-a724-45e0316f7701', 'Pull Apart (Resistance Band)', 'Shoulders', 'Resistance Band, Anchor Point', '{"Shoulders"}'::text[], '{"Traps"}'::text[], 'Target your delts with the Resistance Band Pull Apart, an effective shoulder pulling exercise. Bands are joint-friendly and portable, perfect for any training environment. Shoulder development enhances both performance and upper body aesthetics.', '45681201', '45681201-Resistance-Band-Pull-Apart_Shoulders_.mp4', 'male', FALSE, '2025-12-03 23:26:21.249384+00', '1. Secure the resistance band appropriately for Resistance Band Pull Apart. 2. Set up in the starting position for Resistance Band Pull Apart. 3. Execute the movement with proper form, focusing on your delts. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 55, 7, 8, TRUE, TRUE, 'pull_apart', 'Pull Apart', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('1657137c-5ac4-453e-8fa2-86c34f28bafd', 'Calf Raise Wall Sit (Wall)', 'Legs', 'Wall', '{"Calves"}'::text[], '{}'::text[], 'Build stronger calves with this targeted raising exercise. Leg training boosts metabolism and builds functional, real-world strength. Quality repetitions are more important than quantity.', '85351201', '85351201-Bodyweight-Calf-Raise-Wall-Sit-(male)_Calves_.mp4', 'male', FALSE, '2025-12-03 23:26:29.36063+00', '1. Position yourself at the appropriate distance from a wall. 2. Lower your heels below the platform to get a full stretch. 3. Rise up onto your toes as high as possible, squeezing your calves. 4. Lower with control and repeat. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 80, 5, 7, FALSE, TRUE, 'calf_raise', 'Calf Raise Wall Sit', 'standing_calf_raise, seated_calf_raise, tibialis_raise', FALSE, 'bodyweight', TRUE, 3, 60, 2, 70, 88, 95, 65),
('16603cd0-ddc3-4c25-98c3-48d694551fb7', 'Forward Fold And Rock', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Use this stretch to open up your hamstrings area and enhance overall flexibility. Secondary activation of your lower back, calves provides additional muscle engagement. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '79141201', '79141201-Forward-Fold-and-Rock-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:33.640031+00', '1. Move into the stretch position for Forward Fold And Rock. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. Keep the movement smooth and controlled.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'hamstring_stretch', 'Forward Fold And Rock', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('16627a10-9644-45f2-92d5-29ee5180b56e', 'Double Strict Press (Kettlebell)', 'Shoulders', 'Kettlebell', '{"Front Delts"}'::text[], '{"Side Delts","Triceps"}'::text[], 'Build stronger shoulders with this pressing movement focusing on your delts. The kettlebell''s offset center of mass increases the stability challenge. Shoulder development enhances both performance and upper body aesthetics.', '98431201', '98431201-Kettlebell-Double-Strict-Press_Shoulders_.mp4', 'male', FALSE, '2025-12-03 23:26:22.536005+00', '1. Position two kettlebells for Kettlebell Double Strict Press. 2. Start with the weight at shoulder level. 3. Press directly overhead until your arms are fully extended. 4. Lower back to shoulder level with control. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 78, 7, 8, TRUE, TRUE, 'shoulder_press', 'Double Strict Press', 'lateral_raise, front_raise, rear_delt', FALSE, 'kettlebell', FALSE, 3, 90, 4, 75, 88, 88, 78),
('166759ac-49be-40d7-871b-80f6863d507c', 'Warrior Pose II Virabhadrasana II', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Hip Flexors","Core"}'::text[], 'The Warrior Pose II Virabhadrasana II is a flexibility exercise that targets your full body, helping to release tension and improve range of motion. Secondary activation of your hips, shoulders, quads provides additional muscle engagement. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '9631201', '09631201-Warrior-Pose-II-Virabhadrasana-II-(female)_Stretch.mp4', 'female', FALSE, '2025-12-03 23:26:39.91585+00', '1. Move into the stretch position for Warrior Pose II Virabhadrasana II. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 15, 2, 6, FALSE, TRUE, 'yoga', 'Warrior Pose II Virabhadrasana II', 'stretch_hip, stretch_back, plank', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('1677a896-b679-4165-9e85-a74e17c5aded', 'Static Lunge (Dumbbell)', 'Legs', 'Dumbbells', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This lunging movement emphasizes your quadriceps for stronger, more powerful legs. Secondary activation of your glutes, hamstrings provides additional muscle engagement. Using dumbbells requires more stabilization than barbell variations. Lower body strength improves everything from walking to heavy compound lifts.', '57891201', '57891201-Dumbbell-Static-Lunge-(female)_Thighs_.mp4', 'female', FALSE, '2025-12-03 23:26:33.298565+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Static Lunge. 2. Step forward into a lunge until both knees are at about 90 degrees. 3. Push through your front/working leg to return to the starting position. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 82, 7, 8, TRUE, TRUE, 'lunge', 'Static Lunge', 'split_squat, step_up, squat', TRUE, 'dumbbell', TRUE, 3, 90, 4, 92, 90, 92, 90),
('168de0fe-3e92-46c4-8ae8-90d7e3d16b7a', 'Horizontal Pallof Press Twist (Band)', 'Core', 'Resistance Band, Anchor Point', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'Work your side abdominals with this pressing exercise that strengthens your obliques. The abs assist throughout the movement, making this a well-rounded exercise. Bands are joint-friendly and portable, perfect for any training environment. Building core stability helps with everything from heavy deadlifts to daily activities.', '107271201', '107271201-Band-Horizontal-Pallof-Press-Twist_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:22.536005+00', '1. Secure the resistance band appropriately for Band Horizontal Pallof Press Twist. 2. Execute the pressing motion for Band Horizontal Pallof Press Twist, extending through the target muscles. 3. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 75, 5, 7, FALSE, TRUE, 'pallof_press', 'Horizontal Pallof Press Twist', 'woodchop, plank, dead_bug', FALSE, 'band', FALSE, 3, 60, 2, 60, 85, 90, 50),
('168f9631-d116-4a44-b23b-b68fbc819413', 'Lying Leg Extenstion', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{}'::text[], 'This extension exercise engages your abs for improved core stability and strength. Performing this lying down removes momentum for stricter form. No equipment needed—your body provides all the resistance. Building core stability helps with everything from heavy deadlifts to daily activities.', '71281201', '71281201-Lying-Leg-Extension-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:35.250398+00', '1. Lie down in the appropriate position for Lying Leg Extension. 2. Extend your legs until straight, squeezing your quads at the top. 3. Lower with control back to the starting position. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, FALSE, NULL, 'Strength', 80, 5, 7, FALSE, TRUE, 'leg_extension', 'Lying Leg Extension', 'squat, leg_press, lunge', TRUE, 'bodyweight', FALSE, 3, 60, 2, 80, 75, 20, 88),
('16907dce-c3af-4d28-8f89-3c9c3ce6874b', 'Backward Run', 'Full Body', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Backward Run is an explosive exercise that combines cardiovascular training with dynamic movement movements. This bodyweight exercise requires no equipment and can be done anywhere. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '74571201', '74571201-Backward-Run-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:25.341124+00', '1. Set up in the starting position for Backward Run. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'back_exercise', 'Backward Run', 'cycling, rowing_cardio, jump_rope', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('1692f021-eacd-496f-bf46-ba75b3e7f03a', 'Kneeling Prayer Lat Stretch (Stability Ball)', 'Back', 'Stability Ball', '{"Lats"}'::text[], '{"Lower Back"}'::text[], 'Designed to lengthen your lats, the Kneeling Prayer Lat Stretch (stability Ball) helps improve mobility and prevent stiffness. You''ll also feel your shoulders working to support the movement. Kneeling helps eliminate lower body momentum from the movement. The stability ball adds an instability challenge that activates more stabilizer muscles. Include this in your routine for better mobility and reduced muscle tension.', '101311201', '101311201-Exercise-Ball-Kneeling-Prayer-Lat-Stretch-(female.mp4', 'female', FALSE, '2025-12-03 23:26:33.505723+00', '1. Position the stability ball as needed for Kneeling Prayer Lat Stretch. 2. Kneel on the floor (use a pad for comfort if needed). 3. Move into the stretch position for Kneeling Prayer Lat Stretch. 4. Ease into the stretch until you feel gentle tension (not pain). 5. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 17, 2, 6, FALSE, TRUE, 'lat_stretch', 'Kneeling Prayer Lat Stretch', 'stretch_hip, stretch_back', FALSE, 'stability_ball', TRUE, 1, 30, 2, 70, 88, 95, 65),
('169f5b33-a058-4f4e-9ee6-64861bf0c579', 'Single Arm Curl (Cable)', 'Arms', 'Cables', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'Build bigger biceps with this curling movement that targets the front of your arms. Your forearms work as secondary movers, adding to the training stimulus. Cable resistance creates smooth, continuous muscle engagement. Arm strength supports grip, pulling, and pushing in compound movements.', '25811201', '25811201-Cable-One-Arm-Curl-(female)_Upper-Arms.mp4', 'female', FALSE, '2025-12-03 23:26:31.931873+00', '1. Adjust the cable machine to the correct height and attachment for Cable One Arm Curl. 2. Keep your elbows in a fixed position throughout the movement. 3. Curl the weight up by contracting your biceps, squeezing at the top. 4. Lower with control, resisting the weight on the way down. 5. Complete all reps on one side, then switch to the other side. 6. Continue for your target rep count, maintaining good form throughout.', 'Curl', 'Pull', NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 75, 5, 7, FALSE, TRUE, 'bicep_curl', 'Single Arm Curl', 'hammer_curl, preacher_curl, cable_curl', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('16a2fdbb-b073-4c07-8c1d-35fa3ded5b10', 'Criss Cross Stepback Hops', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Calves"}'::text[], 'A challenging plyometric exercise, the Criss Cross Stepback Hops builds reactive power and improves conditioning. Your quads work as secondary movers, adding to the training stimulus. Great for improving athletic performance, burning calories, and building conditioning.', '71941201', '71941201-Criss-Cross-Stepback-Hops-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:32.501166+00', '1. Set up a box or step platform at the appropriate height. 2. Set up in the starting position for Criss Cross Stepback Hops. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 50, 9, 8, TRUE, TRUE, 'boxing', 'Criss Cross Stepback Hops', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('16a8210d-d5e6-437f-9397-982ecbb6e3a9', 'Seated Hip Abduction (Resistance Band)', 'Legs', 'Resistance Band', '{"Glutes"}'::text[], '{"Hip Abductors"}'::text[], 'Build leg strength with this movement movement focusing on your hip abductors. The glutes assist throughout the movement, making this a well-rounded exercise. Being seated provides stability, allowing you to focus on the working muscles. Resistance bands provide accommodating resistance that increases through the range of motion. Leg training boosts metabolism and builds functional, real-world strength.', '67841201', '67841201-Resistance-Band-Seated-Hip-Abduction-(VERSION-2)-(.mp4', 'female', FALSE, '2025-12-03 23:26:36.128549+00', '1. Secure the resistance band appropriately for Resistance Band Seated Hip Abduction. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 57, 7, 8, TRUE, TRUE, 'hip_abduction', 'Seated Hip Abduction', 'hip_adduction, glute_bridge, clamshell', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('16b455b0-5a92-41a1-809f-702ac2a07992', 'Starfish Crunch', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Starfish Crunch is a core crunching exercise that primarily targets your abs. You''ll also feel your hip flexors working to support the movement. A versatile bodyweight movement perfect for home or gym training. Core strength is foundational for athletic performance and injury prevention.', '28881201', '28881201-Starfish-Crunch-(beginner)-(female).mp4', 'female', FALSE, '2025-12-03 23:26:39.21093+00', '1. Curl your shoulders off the floor by contracting your abs. 2. Don''t pull on your neck—focus on the abdominal contraction. 3. Lower with control, maintaining some tension. 4. Complete all reps with control before resting. Focus on squeezing the target muscle at peak contraction. Works well for abs activation.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'crunch', 'Starfish Crunch', 'leg_raise, plank, russian_twist, v_up', TRUE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('16b6090b-c604-4eb5-b4ef-8565bf97b5d0', 'Jack Hammer Pushdown (Cable)', 'Arms', 'Cables', '{"Triceps"}'::text[], '{"Chest","Shoulders"}'::text[], 'Build stronger triceps with this pushing exercise for bigger arms. Cable resistance creates smooth, continuous muscle engagement. Arm strength supports grip, pulling, and pushing in compound movements.', '88191201', '88191201-Cable-Jack-Hammer-Pushdown-(male)_Upper-Arms_.mp4', 'male', FALSE, '2025-12-03 23:26:26.678791+00', '1. Adjust the cable machine to the correct height and attachment for Cable Jack Hammer Pushdown. 2. Use a hammer/neutral grip with palms facing each other throughout. 3. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 60, 5, 7, FALSE, TRUE, 'tricep_pushdown', 'Jack Hammer Pushdown', 'tricep_extension, close_grip_bench, dip', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('16c070d9-6c90-4b50-aa60-7d8c0ca3593c', 'Crocodile Yoga Pose', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'The Crocodile Yoga Pose provides a deep stretch for your full body, ideal for recovery and mobility work. Flexibility work like this enhances performance and prevents stiffness.', '43721201', '43721201-Crocodile-Yoga-Pose_Stretching_.mp4', 'male', FALSE, '2025-12-03 23:26:21.452942+00', '1. Move into the stretch position for Crocodile Yoga Pose. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 15, 2, 6, FALSE, TRUE, 'yoga', 'Crocodile Yoga Pose', 'stretch_hip, stretch_back, plank', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('16c5acac-a75a-4ae1-9deb-81db33ca14ca', 'Squat To Kickback', 'Legs', 'Bodyweight', '{"Quads","Glutes"}'::text[], '{"Rear Delts"}'::text[], 'The Squat To Kickback is a squatting exercise that primarily loads your quadriceps. Your hamstrings work as secondary movers, adding to the training stimulus. This bodyweight exercise requires no equipment and can be done anywhere. Lower body strength improves everything from walking to heavy compound lifts.', '105451201', '105451201-Squat-to-Kickback-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:21.109351+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. 4. Repeat for the prescribed number of repetitions. Start with lighter weight to perfect your form.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 85, 5, 7, FALSE, TRUE, 'tricep_kickback', 'Squat To Kickback', 'leg_press, leg_extension, leg_curl, lunge, front_squat, hack_squat', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('16cb9d79-fc96-4ce0-be67-fedb9b6bd21b', 'Jumping Pistol Squat', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build power and athleticism with this high-intensity squatting exercise that challenges your entire body. You''ll also feel your glutes working to support the movement. A versatile bodyweight movement perfect for home or gym training. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '41691201', '41691201-Jumping-Pistol-Squat_Plyometric_.mp4', 'male', FALSE, '2025-12-03 23:26:24.941834+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Explode upward from the bottom, jumping as high as possible. 4. Land softly with bent knees and immediately descend into the next rep. 5. Repeat for the prescribed number of repetitions. Keep tension on the target muscles throughout.', 'Squat', NULL, NULL, NULL, NULL, 4, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 85, 9, 8, TRUE, TRUE, 'pistol_squat', 'Jumping Pistol Squat', 'squat, bench_press, deadlift', TRUE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('16cdf24e-16e6-4c04-af76-8ce5a64593c6', 'Standing Drag Curl (Dumbbell)', 'Arms', 'Dumbbells', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'Build bigger biceps with this curling movement that targets the front of your arms. Secondary activation of your forearms provides additional muscle engagement. The standing position engages your core for stability. Using dumbbells requires more stabilization than barbell variations. Arm strength supports grip, pulling, and pushing in compound movements.', '54491201', '54491201-Dumbbell-Standing-Drag-Curl-(VERSION-2)_Upper-Arms.mp4', 'male', FALSE, '2025-12-03 23:26:23.172397+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Standing Drag Curl. 2. Stand tall with your feet firmly planted. 3. Keep your elbows in a fixed position throughout the movement. 4. Curl the weight up by contracting your biceps, squeezing at the top. 5. Lower with control, resisting the weight on the way down. 6. Complete all reps with control before resting.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 84, 5, 7, FALSE, TRUE, 'bicep_curl', 'Standing Drag Curl', 'hammer_curl, preacher_curl, cable_curl', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('16db2226-4221-4d4c-b3a5-daa96fefaa80', 'Switching Shoulder Rotation Stretch', 'Shoulders', 'Bodyweight', '{"Rotator Cuff"}'::text[], '{"Shoulders"}'::text[], 'Target your shoulders with this rotation stretch that helps restore range of motion. Include this in your routine for better mobility and reduced muscle tension.', '90611201', '90611201-Switching-Shoulder-Rotation-Stretch-(female)_Shoul.mp4', 'female', FALSE, '2025-12-03 23:26:39.623429+00', '1. Rotate your torso through the movement pattern for Switching Shoulder Rotation Stretch. 2. Control the rotation in both directions—avoid using momentum. 3. Move into the stretch position for Switching Shoulder Rotation Stretch. 4. Ease into the stretch until you feel gentle tension (not pain). 5. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'stretch_general', 'Switching Shoulder Rotation Stretch', 'stretch_chest, stretch_tricep, stretch_lat', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('16e00d56-4706-410d-9abd-bba6d0512962', 'Lying Pressdown - Skull Crusher - Reverse Grip (Band)', 'Arms', 'Resistance Band', '{"Triceps"}'::text[], '{"Chest","Shoulders"}'::text[], 'The Band Lying Reverse Grip Pressdown (skull Crusher) targets your triceps through a pressing motion. Performing this lying down removes momentum for stricter form. Resistance bands provide accommodating resistance that increases through the range of motion. Dedicated arm training builds both strength and muscular definition.', '41421201', '41421201-Band-Lying-Reverse-Grip-Pressdown-(Skull-Crusher)_.mp4', 'male', FALSE, '2025-12-03 23:26:26.271124+00', '1. Secure the resistance band appropriately for Band Lying Reverse Grip Pressdown. 2. Lie down in the appropriate position for Band Lying Reverse Grip Pressdown. 3. Use a reverse grip (opposite of the standard grip for this exercise). 4. Execute the pressing motion for Band Lying Reverse Grip Pressdown, extending through the target muscles. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 67, 7, 8, TRUE, TRUE, 'tricep_extension', 'Lying Pressdown - Reverse Grip', 'Lying Pressdown - Reverse Grip', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('16e13b8e-6ed8-42c2-8594-05f5a31e0ad3', 'Seated Reverse Butterfly (Resistance Band, Chair)', 'Chest', 'Resistance Band, Chair', '{"Chest"}'::text[], '{"Front Delts"}'::text[], 'Build a stronger chest with this flying movement that develops pressing power. Your front delts work as secondary movers, adding to the training stimulus. The seated position helps isolate the target muscles by removing momentum. Bands are joint-friendly and portable, perfect for any training environment. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '92081201', '92081201-Resistance-Band-Sitting-Reverse-Butterfly-on-a-Cha.mp4', 'female', FALSE, '2025-12-03 23:26:36.266593+00', '1. Secure the resistance band appropriately for Resistance Band Seated Reverse Butterfly On A Chair. 2. Position yourself with a sturdy chair for support or as part of the movement. 3. Sit with your back supported, core engaged, feet flat on the floor. 4. With a slight bend in your elbows, move the weight in a wide arc. 5. Squeeze your chest muscles at the center/top of the movement. 6. Return with control, feeling the stretch at the bottom. 7. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 50, 5, 7, FALSE, TRUE, 'groin_stretch', 'Seated Reverse Butterfly On A Chair', 'shoulder_press, lateral_raise, face_pull, bent_over_row', FALSE, 'band', FALSE, 3, 60, 2, 60, 85, 90, 50),
('16e45122-eac4-4e8e-b7e5-f993959fcfca', 'Stiff Leg Deadlift On Bench (Barbell)', 'Legs', 'Barbell', '{"Hamstrings"}'::text[], '{"Glutes","Lower Back"}'::text[], 'The Barbell Stiff Leg Deadlift On Bench is a lower body hip hinge exercise that targets your hamstrings/glutes. Secondary activation of your glutes, lower back provides additional muscle engagement. The barbell allows you to handle heavier loads for maximum strength gains. Lower body strength improves everything from walking to heavy compound lifts.', '15421201', '15421201-Barbell-Stiff-Leg-Deadlift-on-Bench_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:25.123298+00', '1. Load a barbell and set it on a bench rack at the appropriate height. 2. Push your hips back, lowering the weight along your legs with a flat back. 3. Lower until you feel a stretch in your hamstrings. 4. Drive hips forward to stand, squeezing glutes at the top. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 3, 6, NULL, 10, NULL, TRUE, NULL, 'Strength', 97, 7, 9, TRUE, FALSE, 'romanian_deadlift', 'Stiff Leg Deadlift On Bench', 'deadlift, leg_curl, hip_thrust', TRUE, 'barbell', FALSE, 4, 120, 6, 95, 80, 65, 95),
('16e4a7e4-25e9-4e04-bdb7-0d0f08f3fb9e', 'Russian Twist Shoulder Press S - Close Grip (Dumbbell)', 'Shoulders', 'Dumbbells', '{"Shoulders"}'::text[], '{"Side Delts","Triceps"}'::text[], 'Target your delts with the Dumbbell Russian Twist Close Grip Shoulder Press S, an effective shoulder pressing exercise. Secondary activation of your triceps provides additional muscle engagement. Dumbbells allow each arm to work independently, helping correct imbalances. Strong shoulders improve overhead strength and support nearly all upper body movements.', '46251201', '46251201-Dumbbell-Russian-Twist-Close-Grip-Shoulder-Press-S.mp4', 'male', FALSE, '2025-12-03 23:26:27.263406+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Russian Twist Close Grip Shoulder Press S. 2. Use a close/narrow grip (hands closer than shoulder-width). 3. Start with the weight at shoulder level. 4. Press directly overhead until your arms are fully extended. 5. Lower back to shoulder level with control. 6. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 82, 7, 8, TRUE, TRUE, 'shoulder_press', 'Russian Twist Close Grip Shoulder Press S', 'Russian Twist Shoulder Press S - Close Grip', FALSE, 'dumbbell', FALSE, 3, 90, 4, 92, 90, 92, 90),
('16ea031a-a8df-4d9a-b79f-30c016b8db49', 'Lateral Elbow Plank Walk', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Shoulders","Lower Back"}'::text[], 'The Lateral Elbow Plank Walk is a core stabilization exercise that primarily targets your abs. The shoulders, lower back assist throughout the movement, making this a well-rounded exercise. No equipment needed—your body provides all the resistance. Core strength is foundational for athletic performance and injury prevention.', '66611201', '66611201-Lateral-Elbow-Plank-Walk-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:23.466497+00', '1. Hold your body in a straight line from head to heels. 2. Don''t let your hips sag or pike up—engage your core and glutes. 3. Breathe steadily while maintaining the position. 4. Complete all reps with control before resting. Start with lighter weight to perfect your form.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'plank', 'Lateral Elbow Plank Walk', 'side_plank, dead_bug, hollow_hold', TRUE, 'bodyweight', TRUE, 3, 90, 4, 70, 88, 95, 65),
('171fa98d-8c11-411f-8b9f-b5da7fcd68db', 'Rear Delt Row (TRX)', 'Shoulders', 'TRX', '{"Rear Delts"}'::text[], '{"Upper Back","Traps"}'::text[], 'Build stronger shoulders with this rowing movement focusing on your rear delts. The upper back assist throughout the movement, making this a well-rounded exercise. Suspension training adds instability, increasing core activation throughout. Shoulder development enhances both performance and upper body aesthetics.', '95031201', '95031201-Suspender-Rear-Delt-Row-(male)_Shoulders_.mp4', 'male', FALSE, '2025-12-03 23:26:20.667107+00', '1. Adjust the TRX/suspension straps to the appropriate length for Suspender Rear Delt Row. 2. Pull the weight toward your torso, leading with your elbow(s). 3. Squeeze your shoulder blades together at the peak contraction. 4. Extend back out with control, feeling the stretch in your back. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 60, 7, 8, TRUE, TRUE, 'rear_delt', 'Suspender Rear Delt Row', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'trx', FALSE, 3, 90, 4, 68, 85, 85, 70),
('171fcd11-212e-4805-b0a8-be8a0e0ba581', 'Front Rack Lunge (Barbell)', 'Legs', 'Barbell', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build stronger quads with this lunging movement that develops leg drive and power. You''ll also feel your glutes, hamstrings working to support the movement. The barbell allows you to handle heavier loads for maximum strength gains. Lower body strength improves everything from walking to heavy compound lifts.', '57171201', '57171201-Barbell-Front-Rack-Lunge-(female)_Thighs_.mp4', 'female', FALSE, '2025-12-03 23:26:31.013316+00', '1. Set up a barbell in a rack at the appropriate height for Barbell Front Rack Lunge. 2. Step forward into a lunge until both knees are at about 90 degrees. 3. Push through your front/working leg to return to the starting position. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 82, 7, 8, TRUE, TRUE, 'lunge', 'Front Rack Lunge', 'split_squat, step_up, squat', FALSE, 'barbell', FALSE, 3, 90, 4, 95, 80, 65, 95),
('17234080-e92b-4595-87b0-274d5e5e68bf', 'Half Kneeling Lift (Cable)', 'Chest', 'Cables', '{"Chest"}'::text[], '{}'::text[], 'The Cable Half Kneeling Lift is a movement exercise that targets your chest muscles. The kneeling position adds a core stability challenge. Cable resistance creates smooth, continuous muscle engagement. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '69571201', '69571201-Cable-Half-Kneeling-Lift-(male)_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:25.233728+00', '1. Adjust the cable machine to the correct height and attachment for Cable Half Kneeling Lift. 2. Get into a half-kneeling position (one knee down, opposite foot forward). 3. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 60, 7, 8, TRUE, TRUE, 'woodchop', 'Half Kneeling Lift', 'squat, leg_extension, lunge', FALSE, 'cable', FALSE, 3, 90, 4, 85, 88, 30, 92),
('17323a7d-1a72-487f-9413-28b0903b1b85', 'Butt Kicks', 'Legs', 'Bodyweight', '{"Glutes","Hamstrings"}'::text[], '{"Calves"}'::text[], 'Build your aerobic capacity with this steady-state cardio movement. Your hamstrings work as secondary movers, adding to the training stimulus. Cardiovascular exercise improves heart health, endurance, and helps manage weight.', '30371201', '30371201-Butt-Kicks-(male)_Cardio.mp4', 'male', FALSE, '2025-12-03 23:26:21.890719+00', '1. Set up in the starting position for Butt Kicks. 2. Execute the movement with proper form, focusing on your cardio. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions. Exhale during the exertion phase of the movement.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'glute_kickback', 'Butt Kicks', 'high_knees, jumping_jack, running', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('17389291-b9e2-4fb6-9e96-3eb204889e89', 'Split Squat Heel Raise', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Split Squat Heel Raise is a squatting exercise that primarily loads your quadriceps. Secondary activation of your glutes, hamstrings provides additional muscle engagement. This bodyweight exercise requires no equipment and can be done anywhere. Leg training boosts metabolism and builds functional, real-world strength.', '89601201', '89601201-Split-Squat-Heel-Raise-(male)_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:27.504261+00', '1. Raise the weight in the prescribed direction for Split Squat Heel Raise. 2. Lower with control, maintaining tension throughout. 3. Repeat for the prescribed number of repetitions.', 'Squat', NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 85, 5, 7, FALSE, TRUE, 'split_squat', 'Split Squat Heel Raise', 'lunge, bulgarian_split_squat, squat', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('1742bf29-fb61-4fc3-9e4d-62126a1d8991', 'Side Step Arm Circle', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'A challenging plyometric exercise, the Side Step Arm Circle builds reactive power and improves conditioning. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '85181201', '85181201-Side-Step-Arm-Circle-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:37.303932+00', '1. Set up a box or step platform at the appropriate height. 2. Set up in the starting position for Side Step Arm Circle. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'arm_exercise', 'Side Step Arm Circle', 'high_knees, butt_kicks, jumping_jack', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('174416da-c3a8-4fb9-a5c5-35c7d7a4b822', 'Goblet Squat Side Shuffle (Dumbbell)', 'Legs', 'Dumbbells', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build power and athleticism with this high-intensity squatting exercise that challenges your entire body. Your glutes, hamstrings work as secondary movers, adding to the training stimulus. Dumbbells allow each arm to work independently, helping correct imbalances. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '79961201', '79961201-Dumbbell-Goblet-Squat-Side-Shuffle-(male)_Plyometr.mp4', 'male', FALSE, '2025-12-03 23:26:21.732034+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Goblet Squat Side Shuffle. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Repeat for the prescribed number of repetitions.', 'Squat', NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 97, 9, 8, TRUE, TRUE, 'goblet_squat', 'Goblet Squat Side Shuffle', 'squat, front_squat, lunge', TRUE, 'dumbbell', FALSE, 3, 60, 4, 92, 90, 92, 90),
('175cd1d1-a241-467e-bff1-356343e0bfb1', 'Weighted Lying Knee Raise (Dumbbell)', 'Core', 'Dumbbells, Flat Bench', '{"Lower Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Weighted Dumbbell Lying Knee Raise is a lower body raising exercise that targets your abs. You''ll also feel your hip flexors working to support the movement. The lying position provides back support and helps isolate the target muscles. The dumbbell variation provides freedom of movement and greater range of motion. Strong legs are the foundation for athletic performance and functional fitness.', '88731201', '88731201-Weighted-Dumbbell-Lying-Knee-Raise-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:23.987963+00', '1. Select a pair of dumbbells at an appropriate weight for Weighted Dumbbell Lying Knee Raise. 2. Lie down in the appropriate position for Weighted Dumbbell Lying Knee Raise. 3. Raise the weight in the prescribed direction for Weighted Dumbbell Lying Knee Raise. 4. Lower with control, maintaining tension throughout. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 82, 5, 7, FALSE, TRUE, 'leg_raise', 'Weighted Lying Knee Raise', 'Weighted Lying Knee Raise', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('176d5e9e-0f11-414a-a92f-24dbbb683196', 'Side Squat (Dumbbell)', 'Legs', 'Dumbbells', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Target the front of your thighs with this squatting exercise for quad development. You''ll also feel your glutes, hamstrings working to support the movement. Dumbbells allow each arm to work independently, helping correct imbalances. Lower body strength improves everything from walking to heavy compound lifts.', '47541201', '47541201-Dumbbell-Side-Squat_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:23.172397+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Side Squat. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Complete all reps with control before resting.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 9, NULL, TRUE, NULL, 'Strength', 97, 7, 9, TRUE, FALSE, 'squat', 'Side Squat', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'dumbbell', FALSE, 4, 120, 5, 92, 90, 92, 90),
('1775191a-a2bb-4ad9-91d7-9f5b2cb56c6d', 'Incline Row (Band)', 'Back', 'Resistance Band, Incline Bench, Anchor Point', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'The Band Incline Row is a rowing exercise that builds thickness in your upper back. Secondary activation of your biceps, rear delts provides additional muscle engagement. The incline angle shifts emphasis toward the upper portion of the target muscles. The band creates increasing tension as it stretches, challenging the lockout. Back development is crucial for pulling strength and overall upper body function.', '68481201', '68481201-Band-Incline-Row_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:27.384461+00', '1. Secure the resistance band appropriately for Band Incline Row. 2. Pull the weight toward your torso, leading with your elbow(s). 3. Squeeze your shoulder blades together at the peak contraction. 4. Extend back out with control, feeling the stretch in your back. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 78, 7, 8, TRUE, TRUE, 'dumbbell_row', 'Incline Row', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('17bffa7f-ecd2-4e6d-8936-c2deb458547c', 'Protraction Plank', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Shoulders","Lower Back"}'::text[], 'The Protraction Plank is a core stabilization exercise that primarily targets your abs. You''ll also feel your shoulders, lower back working to support the movement. No equipment needed—your body provides all the resistance. A strong core improves posture, protects your spine, and enhances all other lifts.', '71851201', '71851201-Protraction-Plank-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:26.39056+00', '1. Hold your body in a straight line from head to heels. 2. Don''t let your hips sag or pike up—engage your core and glutes. 3. Breathe steadily while maintaining the position. 4. Complete all reps with control before resting. Focus on squeezing the target muscle at peak contraction. Beneficial for overall core development.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'plank', 'Protraction Plank', 'side_plank, dead_bug, hollow_hold', TRUE, 'bodyweight', TRUE, 3, 90, 4, 70, 88, 95, 65),
('17d4f15a-e283-48d2-8e5f-d86fcc6a138d', 'Concentration Curl (Resistance Band)', 'Arms', 'Resistance Band', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'Build bigger biceps with this curling movement that targets the front of your arms. Your forearms work as secondary movers, adding to the training stimulus. Bands are joint-friendly and portable, perfect for any training environment. Dedicated arm training builds both strength and muscular definition.', '91351201', '91351201-Resistance-Band-Concentration-Curl-(female)_Upper-.mp4', 'female', FALSE, '2025-12-03 23:26:35.936279+00', '1. Secure the resistance band appropriately for Resistance Band Concentration Curl. 2. Keep your elbows in a fixed position throughout the movement. 3. Curl the weight up by contracting your biceps, squeezing at the top. 4. Lower with control, resisting the weight on the way down. 5. Continue for your target rep count, maintaining good form throughout.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 85, 5, 7, FALSE, TRUE, 'concentration_curl', 'Concentration Curl', 'tricep_pushdown, tricep_extension, bicep_curl, hammer_curl', FALSE, 'band', FALSE, 3, 60, 2, 60, 85, 90, 50),
('17d82310-cc48-4f52-95d7-c1c6da5debc3', 'Shoulder External Rotation In Supp (Resistance Band)', 'Shoulders', 'Resistance Band, Anchor Point', '{"Rotator Cuff"}'::text[], '{"Shoulders"}'::text[], 'Target your rotator cuff with the Resistance Band Shoulder External Rotation In Supp, an effective shoulder rotation exercise. The band creates increasing tension as it stretches, challenging the lockout. Strong shoulders improve overhead strength and support nearly all upper body movements.', '91931201', '91931201-Resistance-Band-Shoulder-External-Rotation-in-Supp.mp4', 'female', FALSE, '2025-12-03 23:26:36.128549+00', '1. Secure the resistance band appropriately for Resistance Band Shoulder External Rotation In Supp. 2. Rotate your torso through the movement pattern for Resistance Band Shoulder External Rotation In Supp. 3. Control the rotation in both directions—avoid using momentum. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 45, 7, 8, TRUE, TRUE, 'external_rotation', 'Shoulder External Rotation In Supp', 'squat, bench_press, deadlift', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('17decae8-abeb-4e17-a386-4d6f283d1289', 'Lying Russian Twist', 'Core', 'Bodyweight', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'This twisting movement focuses on your obliques for a complete core workout. Secondary activation of your abs provides additional muscle engagement. Performing this lying down removes momentum for stricter form. This bodyweight exercise requires no equipment and can be done anywhere. Core strength is foundational for athletic performance and injury prevention.', '82271201', '82271201-Lying-Russian-Twist-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:35.250398+00', '1. Lie down in the appropriate position for Lying Russian Twist. 2. Rotate your torso through the movement pattern for Lying Russian Twist. 3. Control the rotation in both directions—avoid using momentum. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 50, 5, 7, FALSE, TRUE, 'russian_twist', 'Lying Russian Twist', 'crunch, plank, leg_raise, wood_chop', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65);
INSERT INTO _exercise_staging (id, name, category, equipment, primary_muscles, secondary_muscles, description, video_code, video_filename, gender, is_custom, created_at, steps_to_perform, movement_pattern, force_type, movement_type, laterality, plane_of_motion, difficulty_level, complexity_score, strength_rating, hypertrophy_rating, power_rating, endurance_rating, body_position, bench_angle, grip_type, grip_width, optimal_rep_range_min, optimal_rep_range_max, placement_in_workout, fatigability, popularity_score, home_gym_friendly, instructions, workout_type, practicality_score, fat_loss_rating, general_fitness_rating, is_compound, supersetable, exercise_family, base_exercise_name, complementary_families, is_equipment_primary, equipment_category, duration_based, recommended_sets, rest_seconds, muscles_worked_count, priority_build_muscle, priority_get_lean, priority_home, priority_gym) VALUES
('17e1a515-6c59-4753-8dde-9abd796ec598', 'High Plank Hip Tap', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Shoulders","Lower Back"}'::text[], 'Build a stronger core with the High Plank Hip Tap, focusing on your abs. The shoulders, lower back assist throughout the movement, making this a well-rounded exercise. A versatile bodyweight movement perfect for home or gym training. A strong core improves posture, protects your spine, and enhances all other lifts.', '80191201', '80191201-High-Plank-Hip-Tap-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:28.851102+00', '1. Hold your body in a straight line from head to heels. 2. Don''t let your hips sag or pike up—engage your core and glutes. 3. Breathe steadily while maintaining the position. 4. Complete all reps with control before resting. Ensure full range of motion on each rep. Works well for abs activation.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'plank', 'High Plank Hip Tap', 'side_plank, dead_bug, hollow_hold', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('17f3f62d-a8b2-4b67-9cba-8083675e6d4a', '3 Sec Sumo Squat', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Inner Thighs","Hamstrings"}'::text[], 'The 3 Sec Sumo Squat is a squatting exercise that primarily loads your quadriceps. Secondary activation of your glutes, hamstrings provides additional muscle engagement. This bodyweight exercise requires no equipment and can be done anywhere. Lower body strength improves everything from walking to heavy compound lifts.', '73501201', '73501201-3-Sec-Sumo-Squat-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:30.292204+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. 4. Complete all reps with control before resting. Keep the movement smooth and controlled. Perfect for targeting your quads.', 'Squat', NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'squat', '3 Sec Sumo Squat', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('18070c70-36c0-4592-91a3-1c9ded4b158f', 'Stiff Leg Good Morning (Barbell)', 'Back', 'Barbell', '{"Lower Back"}'::text[], '{"Hamstrings","Glutes"}'::text[], 'The Barbell Stiff Leg Good Morning targets your hamstrings through a controlled movement motion. Secondary activation of your glutes, lower back provides additional muscle engagement. The barbell allows you to handle heavier loads for maximum strength gains. Lower body strength improves everything from walking to heavy compound lifts.', '1151201', '01151201-Barbell-Stiff-Leg-Good-Morning_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:27.67144+00', '1. Grip a barbell with hands at the appropriate width for Barbell Stiff Leg Good Morning. 2. Set up in the starting position for Barbell Stiff Leg Good Morning. 3. Execute the movement with proper form, focusing on your hamstrings. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 62, 7, 8, TRUE, TRUE, 'back_extension', 'Stiff Leg Good Morning', 'romanian_deadlift, back_extension, hip_thrust', TRUE, 'barbell', FALSE, 3, 90, 4, 95, 80, 65, 95),
('18144326-046c-4c5d-ab6b-fc688db06a44', 'Upper Crunch (Band)', 'Core', 'Resistance Band', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'This crunching exercise engages your abs for improved core stability and strength. The hip flexors assist throughout the movement, making this a well-rounded exercise. The band creates increasing tension as it stretches, challenging the lockout. A strong core improves posture, protects your spine, and enhances all other lifts.', '70371201', '70371201-Band-Upper-Crunch-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:31.013316+00', '1. Secure the resistance band appropriately for Band Upper Crunch. 2. Curl your shoulders off the floor by contracting your abs. 3. Don''t pull on your neck—focus on the abdominal contraction. 4. Lower with control, maintaining some tension. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 75, 5, 7, FALSE, TRUE, 'crunch', 'Upper Crunch', 'leg_raise, plank, russian_twist, v_up', FALSE, 'band', FALSE, 3, 60, 2, 60, 85, 90, 50),
('18154fe1-ecbd-4e7b-83ee-85bdd00fa21a', 'Weighted Bag Spin', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Weighted Bag Spin is a core movement exercise that primarily targets your abs. This bodyweight exercise requires no equipment and can be done anywhere. Building core stability helps with everything from heavy deadlifts to daily activities.', '65061201', '65061201-Weighted-Bag-Spin_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:21.890719+00', '1. Set up in the starting position for Weighted Bag Spin. 2. Execute the movement with proper form, focusing on your abs. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'spin', 'Weighted Bag Spin', 'running, elliptical, rowing_cardio', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('1820bcfa-bfec-4e8d-b396-ffe751b5614c', 'Seated External Rotation (Chair)', 'Shoulders', 'Chair', '{"Rotator Cuff"}'::text[], '{"Shoulders"}'::text[], 'The Seated External Rotation On A Chair is a rotation exercise that develops back strength and muscle. The seated position helps isolate the target muscles by removing momentum. A strong back improves posture, prevents injury, and balances pressing movements.', '93001201', '93001201-Sitting-External-Rotation-on-a-Chair-(female)_Back.mp4', 'female', FALSE, '2025-12-03 23:26:37.628647+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Rotate your torso through the movement pattern for Seated External Rotation On A Chair. 4. Control the rotation in both directions—avoid using momentum. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 35, 7, 8, TRUE, TRUE, 'external_rotation', 'Seated External Rotation On A Chair', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('18225b6f-d10b-4c90-811d-a489caa38d7d', 'Calf Raise - Seated (Smith Machine)', 'Legs', 'Smith Machine, Flat Bench', '{Calves}'::text[], '{Soleus}'::text[], 'This raising movement focuses on your gastrocnemius and soleus. Being seated provides stability, allowing you to focus on the working muscles. Machine exercises are great for isolating muscles and training to failure safely. Strong legs are the foundation for athletic performance and functional fitness.', '43701201', '43701201-Smith-Seated-Calf-Raise_Calves_.mp4', 'male', FALSE, '2025-12-03 23:26:22.938497+00', '1. Set the Smith machine bar to the appropriate starting height for Smith Seated Calf Raise. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Lower your heels below the platform to get a full stretch. 4. Rise up onto your toes as high as possible, squeezing your calves. 5. Lower with control and repeat. 6. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Seated', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 90, 5, 7, FALSE, TRUE, 'calf_raise', 'Smith Seated Calf Raise', 'Seated Calf Raise', FALSE, 'barbell', FALSE, 3, 60, 2, 80, 75, 20, 88),
('1835d701-c0a4-4e5d-aa75-5c70bd3e3593', 'Incline Y Raise (Dumbbell)', 'Shoulders', 'Dumbbells, Incline Bench', '{"Rear Delts"}'::text[], '{"Upper Back","Rotator Cuff"}'::text[], 'Build stronger shoulders with this raising movement focusing on your delts. Secondary activation of your upper back provides additional muscle engagement. The incline angle shifts emphasis toward the upper portion of the target muscles. Dumbbells allow each arm to work independently, helping correct imbalances. Strong shoulders improve overhead strength and support nearly all upper body movements.', '80771201', '80771201-Dumbbell-Incline-Y-Raise-(female)_Shoulders_.mp4', 'female', FALSE, '2025-12-03 23:26:32.914483+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Incline Y Raise. 2. Raise the weight in the prescribed direction for Dumbbell Incline Y Raise. 3. Lower with control, maintaining tension throughout. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 85, 5, 7, FALSE, TRUE, 'lateral_raise', 'Incline Y Raise', 'shoulder_press, front_raise, rear_delt', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('18361452-7592-4aed-962a-055f5d1b6ce0', 'Power Sled Pull Row (Sled)', 'Back', 'Sled', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'This rowing exercise strengthens the muscles between your shoulder blades. The biceps, rear delts assist throughout the movement, making this a well-rounded exercise. A strong back improves posture, prevents injury, and balances pressing movements.', '25631201', '25631201-Power-Sled-Pull-Row-(female)_Back_.mp4', 'female', FALSE, '2025-12-03 23:26:35.801913+00', '1. Pull the weight toward your torso, leading with your elbow(s). 2. Squeeze your shoulder blades together at the peak contraction. 3. Extend back out with control, feeling the stretch in your back. 4. Perform the concentric (lifting) phase explosively with maximum effort. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'general_exercise', 'Power Sled Pull Row', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('1837cdb6-0ba3-481b-94ce-3db8411651c9', 'Triceps Dip (Dip Bars)', 'Arms', 'Dip Bars', '{"Quads"}'::text[], '{"Chest","Shoulders"}'::text[], 'Build stronger triceps with this dipping exercise for bigger arms. You''ll also feel your triceps, front delts working to support the movement. No equipment needed—your body provides all the resistance. Dedicated arm training builds both strength and muscular definition.', '31151201', '31151201-Triceps-Dip-(female)_Upper-Arms.mp4', 'female', FALSE, '2025-12-03 23:26:39.79101+00', '1. Lower your body by bending your elbows to about 90 degrees. 2. Push back up until your arms are fully extended. 3. Continue for your target rep count, maintaining good form throughout. Keep your core engaged for stability.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'dip', 'Triceps Dip', 'bench_press, tricep_pushdown, push_up', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('184a0adf-191b-4c61-afa4-43360c397ffb', 'Chair Squat (Smith Machine)', 'Legs', 'Smith Machine, Chair', '{Quadriceps}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Smith Chair Squat is a squatting exercise that primarily loads your quadriceps. Your glutes, hamstrings work as secondary movers, adding to the training stimulus. The machine guides your movement path for safer, more controlled repetitions. Leg training boosts metabolism and builds functional, real-world strength.', '26171201', '26171201-Smith-Chair-Squat-(female)_Thighs.mp4', 'female', FALSE, '2025-12-03 23:26:37.99429+00', '1. Set the Smith machine bar to the appropriate starting height for Smith Chair Squat. 2. Position yourself with a sturdy chair for support or as part of the movement. 3. Push your hips back and bend your knees to lower your body. 4. Keep your chest up and knees tracking over your toes. 5. Drive through your heels to stand back up, squeezing your glutes at the top. 6. Repeat for the prescribed number of repetitions.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 9, NULL, FALSE, NULL, 'Strength', 78, 7, 9, TRUE, FALSE, 'squat', 'Smith Chair Squat', 'Chair Squat', FALSE, 'smith_machine', FALSE, 4, 120, 5, 80, 75, 20, 88),
('185a6fa0-90f4-4c56-ab43-f8af51636581', 'Bent Over Hip Extension (Band)', 'Legs', 'Resistance Band', '{"Glutes"}'::text[], '{"Hamstrings"}'::text[], 'Develop your posterior chain with this extension movement that emphasizes the glutes. The hamstrings assist throughout the movement, making this a well-rounded exercise. The bent over position requires core engagement to maintain a neutral spine. The band creates increasing tension as it stretches, challenging the lockout. Lower body strength improves everything from walking to heavy compound lifts.', '9801201', '09801201-Band-bent-over-hip-extension-(female)_Hips.mp4', 'female', FALSE, '2025-12-03 23:26:30.685158+00', '1. Secure the resistance band appropriately for Band Bent Over Hip Extension. 2. Hinge at your hips, pushing them back while keeping your back flat. 3. Extend through the target joint(s) for Band Bent Over Hip Extension. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 75, 5, 7, FALSE, TRUE, 'glute_kickback', 'Bent Over Hip Extension', 'hip_thrust, lunge, squat', FALSE, 'band', FALSE, 3, 60, 2, 60, 85, 90, 50),
('1864b2c9-65f8-41d6-81ca-9286ed9543f8', 'Sphinx Pose Opening', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'The Sphinx Pose Opening is a flexibility exercise that targets your full body, helping to release tension and improve range of motion. Flexibility work like this enhances performance and prevents stiffness.', '89621201', '89621201-Sphinx-Pose-Opening-(male)_Stretching_.mp4', 'male', FALSE, '2025-12-03 23:26:26.39056+00', '1. Move into the stretch position for Sphinx Pose Opening. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. Maintain a neutral spine throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 50, 2, 6, FALSE, TRUE, 'back_stretch', 'Sphinx Pose Opening', 'stretch_hip, stretch_back, plank', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('18652b1d-19a5-459b-b105-759c0dc234bc', 'Seated Hyght Fly (Dumbbell)', 'Shoulders', 'Dumbbells, Flat Bench', '{"Shoulders"}'::text[], '{"Traps"}'::text[], 'Build stronger shoulders with this flying movement focusing on your delts. Your front delts work as secondary movers, adding to the training stimulus. The seated position helps isolate the target muscles by removing momentum. Using dumbbells requires more stabilization than barbell variations. Shoulder development enhances both performance and upper body aesthetics.', '105131201', '105131201-Dumbbell-Seated-Hyght-Fly_Shoulders_.mp4', 'male', FALSE, '2025-12-03 23:26:26.93819+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Seated Hyght Fly. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. With a slight bend in your elbows, move the weight in a wide arc. 4. Squeeze your chest muscles at the center/top of the movement. 5. Return with control, feeling the stretch at the bottom. 6. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Seated', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 84, 5, 7, FALSE, TRUE, 'chest_fly', 'Seated Hyght Fly', 'bench_press, incline_press, push_up', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('18784a35-a02d-4cfd-b37f-85c7e828c6d1', 'Standing Back Rotation Squeeze', 'Shoulders', 'Bodyweight', '{"Rotator Cuff"}'::text[], '{"Shoulders"}'::text[], 'Target your delts with the Standing Back Rotation Squeeze, an effective shoulder rotation exercise. Performing this standing challenges your balance and core engagement. A versatile bodyweight movement perfect for home or gym training. Strong shoulders improve overhead strength and support nearly all upper body movements.', '85871201', '85871201-Standing-Back-Rotation-Squeeze-(female)_Shoulders_.mp4', 'female', FALSE, '2025-12-03 23:26:38.425788+00', '1. Begin in a standing position with good posture. 2. Rotate your torso through the movement pattern for Standing Back Rotation Squeeze. 3. Control the rotation in both directions—avoid using momentum. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'back_exercise', 'Standing Back Rotation Squeeze', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('1883515c-2c86-4462-8939-ebf01eb96527', 'Chair Squat To Toe Stand (Chair)', 'Legs', 'Chair', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Target the front of your thighs with this squatting exercise for quad development. You''ll also feel your glutes, hamstrings working to support the movement. Leg training boosts metabolism and builds functional, real-world strength. This is a great exercise for all fitness levels with proper scaling.', '89531201', '89531201-Chair-Squat-to-Toe-Stand-(male)_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:29.483269+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Complete all reps with control before resting. Focus on squeezing the target muscle at peak contraction.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'squat', 'Chair Squat To Toe Stand', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('188b6bcf-abf4-40db-a766-c767c73bdf1b', 'Single Arm Lat Pulldown (Cable)', 'Back', 'Cables', '{"Lats"}'::text[], '{"Biceps","Upper Back"}'::text[], 'Build lat width and pulling strength with this pulling movement. The biceps, upper back assist throughout the movement, making this a well-rounded exercise. Cables provide constant tension throughout the full range of motion. A strong back improves posture, prevents injury, and balances pressing movements.', '35961201', '35961201-Cable-One-Arm-Lat-Pulldown-(female)_back-FIX_.mp4', 'female', FALSE, '2025-12-03 23:26:31.931873+00', '1. Adjust the cable machine to the correct height and attachment for Cable One Arm Lat Pulldown. 2. Pull the bar/handle down toward your upper chest. 3. Drive your elbows down and back, squeezing your lats. 4. Control the weight back up without letting it yank your arms. 5. Complete all reps on one side, then switch to the other side. 6. Continue for your target rep count, maintaining good form throughout. Engage your stabilizer muscles for better control.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'lat_pulldown', 'Single Arm Lat Pulldown', 'pull_up, bent_over_row, cable_row, face_pull', TRUE, 'cable', FALSE, 3, 90, 4, 85, 88, 30, 92),
('1890a859-ac09-4e9a-951b-fac2c44b8fe9', 'Leg Drop Pulse', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build a stronger core with the Leg Drop Pulse, focusing on your abs. No equipment needed—your body provides all the resistance. A strong core improves posture, protects your spine, and enhances all other lifts.', '63301201', '63301201-Leg-Drop-Pulse-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:34.603963+00', '1. At the bottom or top, pulse up and down in small movements before completing the rep. 2. Set up in the starting position for Leg Drop Pulse. 3. Execute the movement with proper form, focusing on your abs. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'pulse', 'Leg Drop Pulse', 'squat, lunge, leg_press', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('1897c217-a6bd-4c03-975e-6ad1cf782cf5', 'Marching Kick On Spot', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Marching Kick On Spot (front Pov) is a cardiovascular exercise that improves endurance and heart health. Your hip flexors work as secondary movers, adding to the training stimulus. Cardiovascular exercise improves heart health, endurance, and helps manage weight.', '96411201', '96411201-Marching-Kick-On-Spot-(front-POV)-(male)_Cardio_.mp4', 'male', FALSE, '2025-12-03 23:26:21.608253+00', '1. Set up in the starting position for Marching Kick On Spot. 2. Execute the movement with proper form, focusing on your cardio. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions. Focus on squeezing the target muscle at peak contraction.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 2, 2, NULL, 10, NULL, NULL, NULL, NULL, 1, 1, NULL, 3, NULL, TRUE, NULL, 'Cardio', 50, 9, 8, FALSE, TRUE, 'marching', 'Marching Kick On Spot', 'high_knees, butt_kicks, jumping_jack', FALSE, 'bodyweight', TRUE, 1, 60, 4, 70, 88, 95, 65),
('189860c4-5410-4ef5-b45e-9f5fcc6e2435', 'Pullover (Stability Ball, Kettlebell)', 'Chest', 'Kettlebell, Stability Ball, Flat Bench', '{"Chest"}'::text[], '{"Lats","Triceps"}'::text[], 'Build a stronger back with this pulling movement targeting your chest. The lats, triceps assist throughout the movement, making this a well-rounded exercise. The kettlebell grip position adds a unique training stimulus. Back development is crucial for pulling strength and overall upper body function.', '83231201', '83231201-Kettlebell-Pullover-on-Stability-Ball-(male)_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:24.941834+00', '1. Select an appropriately weighted kettlebell for Kettlebell Pullover On Stability Ball. 2. With arms slightly bent, lower the weight behind your head in an arc. 3. Pull the weight back over your chest, squeezing your lats and chest. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'pullover', 'Pullover On Stability Ball', 'bicep_curl, face_pull, lat_pulldown', FALSE, 'kettlebell', FALSE, 3, 90, 4, 75, 88, 88, 78),
('18a39bde-ea7e-4955-83a2-5752c77483d7', 'Push Up Jack', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'Build a stronger chest with this pushing movement that develops pressing power. Your triceps, front delts work as secondary movers, adding to the training stimulus. This bodyweight exercise requires no equipment and can be done anywhere. A well-developed chest contributes to upper body strength and aesthetics. This is a great exercise for all fitness levels with proper scaling.', '106811201', '106811201-Push-Up-Jack-(female)_Chest_.mp4', 'female', FALSE, '2025-12-03 23:26:35.936279+00', '1. Keep your body in a straight line from head to heels throughout. 2. Lower your chest toward the floor by bending your elbows. 3. Push through your palms to return to the starting position. 4. Repeat for the prescribed number of repetitions. Start with lighter weight to perfect your form. A solid choice for chest day.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 70, 9, 8, TRUE, TRUE, 'push_up', 'Push Up Jack', 'bench_press, chest_fly, dip', TRUE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('18a58873-a557-45e4-a55b-fefb07e87e46', 'Box Squat (Barbell)', 'Legs', 'Barbell, Plyo Box', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Target the front of your thighs with this squatting exercise for quad development. Your glutes, hamstrings work as secondary movers, adding to the training stimulus. Barbells enable bilateral loading for building raw strength. Leg training boosts metabolism and builds functional, real-world strength.', '107201201', '107201201-Barbell-Box-Squat-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:31.013316+00', '1. Set up a barbell in a rack at the appropriate height for Barbell Box Squat. 2. Set up a box or step platform at the appropriate height. 3. Push your hips back and bend your knees to lower your body. 4. Keep your chest up and knees tracking over your toes. 5. Drive through your heels to stand back up, squeezing your glutes at the top. 6. Complete all reps with control before resting.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 9, NULL, TRUE, NULL, 'Strength', 97, 7, 9, TRUE, FALSE, 'squat', 'Box Squat', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'barbell', FALSE, 4, 120, 5, 95, 80, 65, 95),
('18a73e09-0da6-4afe-a9e0-82b4f281cbca', 'Standing Prone Lateral Raise (Dumbbell)', 'Shoulders', 'Dumbbells', '{"Side Delts"}'::text[], '{"Traps"}'::text[], 'Target your lateral delts with the Dumbbell Standing Prone Lateral Raise, an effective shoulder raising exercise. Performing this standing challenges your balance and core engagement. Dumbbells allow each arm to work independently, helping correct imbalances. Strong shoulders improve overhead strength and support nearly all upper body movements.', '83351201', '83351201-Dumbbell-Standing-Prone-Lateral-Raise-(male)_Shoul.mp4', 'male', FALSE, '2025-12-03 23:26:21.995567+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Standing Prone Lateral Raise. 2. Stand tall with your feet firmly planted. 3. Raise your arms out to the sides until parallel to the floor. 4. Lower with control, maintaining tension throughout. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 94, 5, 7, FALSE, TRUE, 'lateral_raise', 'Standing Prone Lateral Raise', 'shoulder_press, front_raise, rear_delt', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('18acba66-9ce3-4741-85a7-01829c0533cd', 'Bouncing Shift Sky Reach', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'A challenging plyometric exercise, the Bodyweight Bouncing Shift Sky Reach builds reactive power and improves conditioning. Secondary activation of your shoulders provides additional muscle engagement. A versatile bodyweight movement perfect for home or gym training. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '93841201', '93841201-Bodyweight-Bouncing-Shift-Sky-Reach-(female)_Plyom.mp4', 'female', FALSE, '2025-12-03 23:26:31.347577+00', '1. Set up in the starting position for Bodyweight Bouncing Shift Sky Reach. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'shoulder_stretch', 'Bouncing Shift Sky Reach', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('18c0d6a7-beba-4826-ab51-149cdb961342', 'Open Up (Chair)', 'Legs', 'Chair', '{"Hip Flexors"}'::text[], '{"Glutes"}'::text[], 'Build leg strength with this movement movement focusing on your hip flexors. You''ll also feel your glutes working to support the movement. Strong legs are the foundation for athletic performance and functional fitness.', '76641201', '76641201-Open-Up-on-a-Chair-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:35.667316+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Set up in the starting position for Open Up On A Chair. 3. Execute the movement with proper form, focusing on your hip flexors. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 35, 7, 8, TRUE, TRUE, 'dynamic_warmup', 'Open Up On A Chair', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('18cfa633-92b0-47e3-8995-0adcc06861c7', 'Half Kneeling Pallof Press (Cable)', 'Core', 'Cables', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'This pressing exercise engages your abs for improved core stability and strength. The kneeling position adds a core stability challenge. The cable setup allows you to adjust the angle of resistance. A strong core improves posture, protects your spine, and enhances all other lifts.', '104411201', '104411201-Cable-Half-Kneeling-Pallof-Press-(female)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:23.689343+00', '1. Adjust the cable machine to the correct height and attachment for Cable Half Kneeling Pallof Press. 2. Get into a half-kneeling position (one knee down, opposite foot forward). 3. Execute the pressing motion for Cable Half Kneeling Pallof Press, extending through the target muscles. 4. Continue for your target rep count, maintaining good form throughout. Keep your shoulders relaxed and away from your ears.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 80, 7, 8, TRUE, TRUE, 'pallof_press', 'Half Kneeling Pallof Press', 'woodchop, plank, dead_bug', FALSE, 'cable', FALSE, 3, 90, 4, 85, 88, 30, 92),
('18d9f06f-b1ef-4499-a4fe-725d1fea8578', 'Single Arm Front Raise (Cable)', 'Shoulders', 'Cables', '{"Front Delts"}'::text[], '{"Chest"}'::text[], 'Build stronger shoulders with this raising movement focusing on your front delts. Cables provide constant tension throughout the full range of motion. Strong shoulders improve overhead strength and support nearly all upper body movements.', '82941201', '82941201-Cable-One-Arm-Front-Raise-(male)_Shoulders_.mp4', 'male', FALSE, '2025-12-03 23:26:27.805708+00', '1. Adjust the cable machine to the correct height and attachment for Cable One Arm Front Raise. 2. Raise the weight in front of you to shoulder height. 3. Lower with control, maintaining tension throughout. 4. Complete all reps on one side, then switch to the other side. 5. Complete all reps with control before resting. Control the movement—avoid using momentum.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 75, 5, 7, FALSE, TRUE, 'front_raise', 'Single Arm Front Raise', 'shoulder_press, lateral_raise, rear_delt_fly', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('18dd92c4-0487-4112-84be-c91ff82622da', 'Russian Twist (beginner Level)', 'Core', 'Bodyweight', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'Work your side abdominals with this twisting exercise that strengthens your obliques. Your abs work as secondary movers, adding to the training stimulus. No equipment needed—your body provides all the resistance. Building core stability helps with everything from heavy deadlifts to daily activities.', '69671201', '69671201-Russian-Twist-(beginner-level)-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:36.581585+00', '1. Rotate your torso through the movement pattern for Russian Twist. 2. Control the rotation in both directions—avoid using momentum. 3. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 50, 5, 7, FALSE, TRUE, 'russian_twist', 'Russian Twist', 'crunch, plank, leg_raise, wood_chop', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('18e4dacf-fd90-4397-b8eb-8bcc9fec57bf', 'Seated Lower Back Stretch', 'Back', 'Bodyweight', '{"Lats"}'::text[], '{"Lower Back"}'::text[], 'Designed to lengthen your back, the Seated Lower Back Stretch helps improve mobility and prevent stiffness. Being seated provides stability, allowing you to focus on the working muscles. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '43051201', '43051201-Seated-Lower-Back-Stretch-(female)_Back.mp4', 'female', FALSE, '2025-12-03 23:26:36.717157+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Move into the stretch position for Seated Lower Back Stretch. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. Keep the movement smooth and controlled.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, 'Seated', NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 42, 2, 6, FALSE, TRUE, 'back_stretch', 'Seated Lower Back Stretch', 'stretch_hip, stretch_hamstring, stretch_shoulder', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('18eaebac-b65f-478d-a997-44fce1edb464', 'Ring Chin Up - Neutral Grip (Gymnastic Rings)', 'Back', 'Gymnastic Rings', '{"Lats"}'::text[], '{"Biceps","Upper Back"}'::text[], 'This movement exercise emphasizes your lats for improved back development. The biceps assist throughout the movement, making this a well-rounded exercise. Back development is crucial for pulling strength and overall upper body function.', '80081201', '80081201-Ring-Neutral-Grip-Chin-Up-(male)_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:30.292204+00', '1. Use a neutral grip with palms facing each other. 2. Pull yourself up, focusing on bicep and lat engagement. 3. Raise until chin is over the bar, lower with full control. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 4, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 58, 7, 8, TRUE, TRUE, 'pull_up', 'Ring Chin Up - Neutral Grip', 'Ring Chin Up - Neutral Grip', TRUE, 'gymnastic_rings', FALSE, 3, 90, 4, 68, 85, 85, 70),
('18ecb792-7afd-4677-b039-ba6d29373898', 'Single Leg Forward Bend', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Single Leg Forward Bend is a flexibility exercise that targets your hamstrings, helping to release tension and improve range of motion. You''ll also feel your lower back, calves working to support the movement. Include this in your routine for better mobility and reduced muscle tension.', '85321201', '85321201-Single-Leg-Forward-Bend-(male)_Stretching_.mp4', 'male', FALSE, '2025-12-03 23:26:27.504261+00', '1. Move into the stretch position for Single Leg Forward Bend. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. 4. Switch sides and repeat for equal time. 5. Complete all reps on one side, then switch to the other side.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 45, 7, 8, TRUE, TRUE, 'leg_exercise', 'Single Leg Forward Bend', 'squat, lunge, leg_press', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('18fbdc73-335e-407f-8ba4-9fc92c6cd6b3', 'Standing Hip Extension To Leg Lift', 'Legs', 'Bodyweight', '{"Glutes"}'::text[], '{"Hamstrings"}'::text[], 'Build stronger glutes with this extension movement focused on hip extension. The hamstrings assist throughout the movement, making this a well-rounded exercise. Performing this standing challenges your balance and core engagement. This bodyweight exercise requires no equipment and can be done anywhere. Lower body strength improves everything from walking to heavy compound lifts.', '90731201', '90731201-Standing-Hip-Extension-to-Leg-Lift-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:38.7451+00', '1. Stand with feet about shoulder-width apart. 2. Extend your legs until straight, squeezing your quads at the top. 3. Lower with control back to the starting position. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 72, 5, 7, FALSE, TRUE, 'glute_kickback', 'Standing Hip Extension To Leg Lift', 'crunch, plank, russian_twist, hanging_knee_raise', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('18fc5b38-df2f-4fe3-af9c-6fd8c3e8685f', 'Seated Under Ankle Tap (Wall) - Alternating', 'Full Body', 'Wall', '{"Glutes","Hamstrings","Quads"}'::text[], '{"Abs"}'::text[], 'This dynamic movement movement gets your heart rate up while developing explosive strength. Great for improving athletic performance, burning calories, and building conditioning.', '87661201', '87661201-Alternate-Ankle-Tap-Under-Sit-agains-Wall-(female).mp4', 'female', FALSE, '2025-12-03 23:26:30.412523+00', '1. Position yourself at the appropriate distance from a wall. 2. Alternate between sides/arms/legs with each repetition. 3. Continue for your target rep count, maintaining good form throughout. Engage your stabilizer muscles for better control.', 'Hold', 'Static', 'Compound', 'Bilateral (Alternating)', NULL, 2, NULL, 7, 7, NULL, 5, 'Seated (Against Wall)', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 42, 7, 8, TRUE, TRUE, 'general_exercise', 'Seated Under Ankle Tap - Alternating', 'high_knees, butt_kicks, jumping_jack', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('1909f811-8328-404f-9dc1-f68797652cec', 'Sprinter Lunge - Alternating', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This lunging movement emphasizes your quadriceps for stronger, more powerful legs. Your glutes, hamstrings work as secondary movers, adding to the training stimulus. No equipment needed—your body provides all the resistance. Leg training boosts metabolism and builds functional, real-world strength.', '70951201', '70951201-Alternate-Sprinter-Lunge-(female)_Thighs_.mp4', 'female', FALSE, '2025-12-03 23:26:30.412523+00', '1. Step forward into a lunge until both knees are at about 90 degrees. 2. Push through your front/working leg to return to the starting position. 3. Continue for your target rep count, maintaining good form throughout. Focus on the mind-muscle connection. Include this in your legs training.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'sprint', 'Sprinter Lunge - Alternating', 'squat, split_squat, step_up, leg_press', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('19132dfe-4c4e-422f-a102-1caab22a60d0', 'Diamond Push Up (Against Wall)', 'Chest', 'Wall', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'This pushing movement isolates your triceps for improved arm development. Your chest work as secondary movers, adding to the training stimulus. Arm strength supports grip, pulling, and pushing in compound movements.', '69221201', '69221201-Diamond-Push-up-against-wall-(male)_Upper-Arms_.mp4', 'male', FALSE, '2025-12-03 23:26:26.271124+00', '1. Position yourself at the appropriate distance from a wall. 2. Keep your body in a straight line from head to heels throughout. 3. Lower your chest toward the floor by bending your elbows. 4. Push through your palms to return to the starting position. 5. Complete all reps with control before resting. Exhale during the exertion phase of the movement.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 62, 7, 8, TRUE, TRUE, 'push_up', 'Diamond Push Up Against Wall', 'bench_press, chest_fly, dip', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('191b28d5-bf9e-4bf0-83fa-ab70fdde7883', 'Walking Side And Sky Reach', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'A challenging plyometric exercise, the Walking Side And Sky Reach builds reactive power and improves conditioning. This bodyweight exercise requires no equipment and can be done anywhere. Great for improving athletic performance, burning calories, and building conditioning.', '93831201', '93831201-Walking-Side-and-Sky-Reach-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:39.91585+00', '1. Set up in the starting position for Walking Side And Sky Reach. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 2, 2, NULL, 10, NULL, NULL, NULL, NULL, 1, 1, NULL, 3, NULL, TRUE, NULL, 'Cardio', 50, 9, 8, FALSE, TRUE, 'shoulder_stretch', 'Walking Side And Sky Reach', 'squat, bench_press, deadlift', FALSE, 'bodyweight', TRUE, 1, 60, 4, 70, 88, 95, 65),
('193336c8-9700-44eb-81ed-03498a26f7e3', 'Lying Single To Double Toe Tap', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Lying Single To Double Toe Tap is a core movement exercise that primarily targets your abs. Performing this lying down removes momentum for stricter form. No equipment needed—your body provides all the resistance. A strong core improves posture, protects your spine, and enhances all other lifts.', '74971201', '74971201-Lying-Single-to-Double-Toe-Tap-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:22.123147+00', '1. Lie down in the appropriate position for Lying Single To Double Toe Tap. 2. Set up in the starting position for Lying Single To Double Toe Tap. 3. Execute the movement with proper form, focusing on your abs. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Lying Single To Double Toe Tap', 'high_knees, butt_kicks, jumping_jack', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('193587bc-b3b6-4347-ae11-c6f95168c7c1', 'Chinese Plank', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Shoulders","Lower Back"}'::text[], 'Build a stronger core with the Chinese Plank, focusing on your abs. Secondary activation of your shoulders, lower back provides additional muscle engagement. No equipment needed—your body provides all the resistance. Core strength is foundational for athletic performance and injury prevention.', '86101201', '86101201-Chinese-Plank-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:22.536005+00', '1. Hold your body in a straight line from head to heels. 2. Don''t let your hips sag or pike up—engage your core and glutes. 3. Breathe steadily while maintaining the position. 4. Continue for your target rep count, maintaining good form throughout. Focus on the mind-muscle connection.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'plank', 'Chinese Plank', 'side_plank, dead_bug, hollow_hold', TRUE, 'bodyweight', TRUE, 3, 90, 4, 70, 88, 95, 65),
('19371fcc-4b86-4b96-a828-9f928189e4f3', 'Side Twist From Squat (Plate)', 'Legs', 'Weight Plate', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This dynamic squatting movement gets your heart rate up while developing explosive strength. The abs assist throughout the movement, making this a well-rounded exercise. No equipment needed—your body provides all the resistance. Plyometric training builds explosive power that transfers to sports and daily activities.', '83441201', '83441201-Weighted-Plate-Side-Twist-from-Squat-(male)_Plyome.mp4', 'male', FALSE, '2025-12-03 23:26:25.991486+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. 4. Continue for your target rep count, maintaining good form throughout. Ensure full range of motion on each rep.', 'Squat', NULL, NULL, NULL, NULL, 4, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 85, 5, 7, FALSE, TRUE, 'squat', 'Weighted Plate Side Twist From Squat', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'plate', FALSE, 3, 60, 2, 70, 88, 95, 65),
('194b4656-3135-4378-88ec-1aff72305f39', 'Lateral Step Up (Smith Machine)', 'Legs', 'Smith Machine, Step Platform', '{Quadriceps}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This stepping movement emphasizes your quadriceps for stronger, more powerful legs. The glutes, hamstrings assist throughout the movement, making this a well-rounded exercise. The fixed path allows you to focus purely on muscular effort. Strong legs are the foundation for athletic performance and functional fitness.', '8841201', '08841201-Smith-Lateral-Step-Up-(female)_Thighs_.mp4', 'female', FALSE, '2025-12-03 23:26:37.99429+00', '1. Set the Smith machine bar to the appropriate starting height for Smith Lateral Step Up. 2. Set up a box or step platform at the appropriate height. 3. Step one foot onto the elevated surface. 4. Drive through that foot to lift your body up onto the platform. 5. Step back down with control and repeat. 6. Continue for your target rep count, maintaining good form throughout. Exhale during the exertion phase of the movement.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 78, 7, 8, TRUE, TRUE, 'step_up', 'Smith Lateral Step Up', 'Lateral Step Up', FALSE, 'smith_machine', FALSE, 3, 90, 4, 80, 75, 20, 88),
('195fa85c-f589-4744-aedb-52081a131fd9', 'Pullover (Dumbbell)', 'Chest', 'Dumbbells, Flat Bench', '{"Chest"}'::text[], '{"Lats","Triceps"}'::text[], 'The Dumbbell Pullover is a pulling exercise that targets your chest muscles. You''ll also feel your lats, triceps working to support the movement. Dumbbells allow each arm to work independently, helping correct imbalances. A well-developed chest contributes to upper body strength and aesthetics.', '3751201', '03751201-Dumbbell-Pullover_Chest.mp4', 'male', FALSE, '2025-12-03 23:26:27.384461+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Pullover. 2. With arms slightly bent, lower the weight behind your head in an arc. 3. Pull the weight back over your chest, squeezing your lats and chest. 4. Complete all reps with control before resting. Control the movement—avoid using momentum.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 62, 7, 8, TRUE, TRUE, 'pullover', 'Pullover', 'bicep_curl, face_pull, lat_pulldown', TRUE, 'dumbbell', FALSE, 3, 90, 4, 92, 90, 92, 90),
('19669a0e-f382-46b0-b46a-f547d07e4d7f', 'Standing Chest Reach', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Shoulders"}'::text[], 'Designed to lengthen your chest, the Standing Chest Reach helps improve mobility and prevent stiffness. The shoulders assist throughout the movement, making this a well-rounded exercise. Performing this standing challenges your balance and core engagement. Flexibility work like this enhances performance and prevents stiffness.', '72931201', '72931201-Standing-Chest-Reach-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:38.570929+00', '1. Stand tall with your feet firmly planted. 2. Move into the stretch position for Standing Chest Reach. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'chest_exercise', 'Standing Chest Reach', 'bench_press, chest_fly, push_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('1993a96f-023d-4f53-beeb-e658619146bd', 'Straight Leg Sit Up', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'This movement exercise engages your abs for improved core stability and strength. Your hip flexors work as secondary movers, adding to the training stimulus. No equipment needed—your body provides all the resistance. Core strength is foundational for athletic performance and injury prevention.', '50001201', '50001201-Straight-Leg-Sit-Up-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:39.340041+00', '1. Set up in the starting position for Straight Leg Sit Up. 2. Execute the movement with proper form, focusing on your abs. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'romanian_deadlift', 'Straight Leg Sit Up', 'deadlift, leg_curl, hip_thrust', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('1997a4de-1e57-4fe9-99fb-098608265e8c', 'Inchworm And Mountain Climbers', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors","Shoulders"}'::text[], 'Build power and athleticism with this high-intensity climbing exercise that challenges your entire body. You''ll also feel your hip flexors, shoulders working to support the movement. This bodyweight exercise requires no equipment and can be done anywhere. Plyometric training builds explosive power that transfers to sports and daily activities.', '55981201', '55981201-Inchworm-and-Mountain-Climbers-(Male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:29.242428+00', '1. From plank position, drive one knee toward your chest. 2. Quickly switch legs, bringing the other knee forward. 3. Continue alternating at a quick pace while maintaining plank form. 4. Repeat for the prescribed number of repetitions. Don''t rush—quality over quantity. Include this in your plyometrics training.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 50, 9, 8, TRUE, TRUE, 'mountain_climber', 'Inchworm And Mountain Climbers', 'burpee, plank, high_knees', TRUE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('199e8a01-38b7-45e3-abdd-eea9a9958b01', 'Side Lying Lateral Raise (Dumbbell)', 'Shoulders', 'Dumbbells, Flat Bench', '{"Side Delts"}'::text[], '{"Traps"}'::text[], 'This raising exercise works your lateral delts for improved shoulder strength and aesthetics. The lying position provides back support and helps isolate the target muscles. Dumbbells allow each arm to work independently, helping correct imbalances. Strong shoulders improve overhead strength and support nearly all upper body movements.', '85311201', '85311201-Dumbbell-Side-Lying-Lateral-Raise-(male)_Shoulders.mp4', 'male', FALSE, '2025-12-03 23:26:28.260518+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Side Lying Lateral Raise. 2. Lie on your side with your body aligned. 3. Raise your arms out to the sides until parallel to the floor. 4. Lower with control, maintaining tension throughout. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 92, 5, 7, FALSE, TRUE, 'lateral_raise', 'Side Lying Lateral Raise', 'shoulder_press, front_raise, rear_delt', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('19b36196-3c01-460e-a564-baf1407b11a7', 'Seated Wide Lat Pulldown (Machine, Cable)', 'Back', 'Cables', '{"Lats"}'::text[], '{"Biceps","Upper Back"}'::text[], 'This pulling exercise emphasizes your lats for improved back development. You''ll also feel your biceps, upper back working to support the movement. Being seated provides stability, allowing you to focus on the working muscles. The fixed path allows you to focus purely on muscular effort. A strong back improves posture, prevents injury, and balances pressing movements.', '86461201', '86461201-Lever-Seated-Wide-Lat-Pulldown-(male)_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:20.982555+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Seated Wide Lat Pulldown. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Use a wide grip (wider than shoulder-width) for this variation. 4. Pull the bar/handle down toward your upper chest. 5. Drive your elbows down and back, squeezing your lats. 6. Control the weight back up without letting it yank your arms. 7. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 8, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 90, 7, 8, TRUE, TRUE, 'lat_pulldown', 'Lever Seated Wide Lat Pulldown', 'pull_up, bent_over_row, cable_row, face_pull', TRUE, 'cable', FALSE, 3, 90, 4, 85, 88, 30, 92),
('19c2f4c0-70e8-4300-9e39-c04fcf3c9ee7', 'Thoracic Bridge', 'Back', 'Bodyweight', '{"Upper Back"}'::text[], '{"Obliques"}'::text[], 'The Thoracic Bridge provides a deep stretch for your thoracic spine, ideal for recovery and mobility work. You''ll also feel your shoulders working to support the movement. Flexibility work like this enhances performance and prevents stiffness.', '45531201', '45531201-Thoracic-Bridge_Stretching.mp4', 'male', FALSE, '2025-12-03 23:26:24.307972+00', '1. Drive through your heels to lift your hips toward the ceiling. 2. Squeeze your glutes hard at the top of the movement. 3. Lower your hips back down with control. Don''t rush—quality over quantity.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'spinal_stretch', 'Thoracic Bridge', 'hip_thrust, romanian_deadlift, leg_curl', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('19cad9b9-f22c-4356-8dfe-f9aa66180ef0', 'Side Lunge (TRX)', 'Legs', 'TRX', '{"Quads"}'::text[], '{"Glutes","Inner Thighs"}'::text[], 'The Suspender Side Lunge is a lunging exercise that primarily loads your quadriceps. Secondary activation of your glutes, hamstrings provides additional muscle engagement. The TRX allows you to adjust difficulty by changing your body angle. Lower body strength improves everything from walking to heavy compound lifts.', '11321201', '11321201-Suspender-Side-Lunge-(female)_Thighs_.mp4', 'female', FALSE, '2025-12-03 23:26:39.472701+00', '1. Adjust the TRX/suspension straps to the appropriate length for Suspender Side Lunge. 2. Step to the side, bending that knee while keeping the other leg straight. 3. Push through your front/working leg to return to the starting position. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 60, 7, 8, TRUE, TRUE, 'side_bend', 'Suspender Side Lunge', 'squat, bench_press, deadlift', FALSE, 'trx', FALSE, 3, 90, 4, 68, 85, 85, 70),
('19cb8fa8-e8b0-44a2-944a-aacfe655debf', 'Standing Face Pull (Cable)', 'Shoulders', 'Cables', '{"Rear Delts"}'::text[], '{"Upper Back","Rotator Cuff"}'::text[], 'The Cable Standing Face Pull is a pulling exercise that targets your delts for shoulder development. You''ll also feel your upper back, rotator cuff working to support the movement. The standing position engages your core for stability. Cables provide constant tension throughout the full range of motion. Shoulder development enhances both performance and upper body aesthetics.', '56091201', '56091201-Cable-Standing-Face-Pull_Shoulders_.mp4', 'male', FALSE, '2025-12-03 23:26:29.483269+00', '1. Adjust the cable machine to the correct height and attachment for Cable Standing Face Pull. 2. Stand with feet about shoulder-width apart. 3. Pull the rope toward your face, separating your hands as you pull. 4. Squeeze your rear delts and upper back at peak contraction. 5. Return with control, maintaining cable tension. 6. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 92, 7, 8, TRUE, TRUE, 'face_pull', 'Standing Face Pull', 'rear_delt_fly, bent_over_row, lateral_raise', TRUE, 'cable', FALSE, 3, 90, 4, 85, 88, 30, 92),
('19d886c2-8577-46d7-b8ba-f945b4bc76d3', 'Rotational Deadlift (Kettlebell)', 'Back', 'Kettlebell', '{"Lower Back"}'::text[], '{"Glutes","Hamstrings","Traps"}'::text[], 'The Kettlebell Rotational Deadlift is a lower body hip hinge exercise that targets your hamstrings/glutes. Secondary activation of your glutes, lower back provides additional muscle engagement. The kettlebell''s offset center of mass increases the stability challenge. Lower body strength improves everything from walking to heavy compound lifts.', '58861201', '58861201-Kettlebell-Rotational-Deadlift-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:22.938497+00', '1. Select an appropriately weighted kettlebell for Kettlebell Rotational Deadlift. 2. Hinge at hips and bend knees to grip the weight. 3. Drive through your heels, extending hips and knees to stand. 4. Lower by reversing the movement with control. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'woodchop', 'Rotational Deadlift', 'romanian_deadlift, leg_curl, back_extension, hip_thrust, good_morning', FALSE, 'kettlebell', FALSE, 3, 90, 4, 75, 88, 88, 78),
('19e39531-95ef-4a6a-a75f-18e27d31e2ac', 'Bicycle Crunch (Band) - Alternating', 'Core', 'Resistance Band', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build a stronger core with the Band Bicycle Crunch, focusing on your abs. Your abs work as secondary movers, adding to the training stimulus. Bands are joint-friendly and portable, perfect for any training environment. A strong core improves posture, protects your spine, and enhances all other lifts.', '9721201', '09721201-Band-bicycle-crunch_Waist.mp4', 'male', FALSE, '2025-12-03 23:26:25.87243+00', '1. Secure the resistance band appropriately for Band Bicycle Crunch. 2. Bring one knee toward chest while extending the other leg. 3. Rotate to bring opposite elbow toward the bent knee. 4. Alternate sides in a pedaling motion. 5. Continue for your target rep count, maintaining good form throughout. Focus on the mind-muscle connection.', 'Trunk Flexion', 'Pull', 'Compound', 'Bilateral', NULL, 2, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'cycling', 'Bicycle Crunch - Alternating', 'Alternating Bicycle Crunch', FALSE, 'bodyweight', FALSE, 3, 60, 2, 60, 85, 90, 50),
('19e4f838-d6b5-4759-b4e8-672c321dccdb', 'Standing Military Press - Without Rack (Barbell)', 'Shoulders', 'Barbell', '{"Front Delts"}'::text[], '{"Side Delts","Triceps"}'::text[], 'Build stronger shoulders with this pressing movement focusing on your delts. Secondary activation of your triceps provides additional muscle engagement. The standing position engages your core for stability. The barbell allows you to handle heavier loads for maximum strength gains. Shoulder development enhances both performance and upper body aesthetics.', '70051201', '70051201-Barbell-Standing-Military-Press-(without-rack)-(fe.mp4', 'female', FALSE, '2025-12-03 23:26:31.133197+00', '1. Set up a barbell in a rack at the appropriate height for Barbell Standing Military Press. 2. Begin in a standing position with good posture. 3. Start with the weight at shoulder level. 4. Press directly overhead until your arms are fully extended. 5. Lower back to shoulder level with control. 6. Continue for your target rep count, maintaining good form throughout.', NULL, 'Push', 'Compound', 'Bilateral', NULL, 3, NULL, 10, 10, NULL, 4, 'Standing', NULL, 'Overhand', 'Standard', 5, 8, NULL, 8, NULL, FALSE, NULL, 'Strength', 91, 7, 9, TRUE, FALSE, 'shoulder_press', 'Standing Military Press', 'lateral_raise, front_raise, rear_delt', TRUE, 'barbell', FALSE, 4, 120, 4, 95, 80, 65, 95),
('19ee6076-9054-4fa9-8c7b-260ad606380a', 'Push Up (Medicine Ball)', 'Chest', 'Medicine Ball', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'The Push Up Medicine Ball is a pushing exercise that targets your chest muscles. The triceps, front delts assist throughout the movement, making this a well-rounded exercise. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '6631201', '06631201-Push-Up-Medicine-Ball_Chest-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:23.288245+00', '1. Hold a medicine ball at the appropriate position for Push Up Medicine Ball. 2. Keep your body in a straight line from head to heels throughout. 3. Lower your chest toward the floor by bending your elbows. 4. Push through your palms to return to the starting position. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'push_up', 'Push Up Medicine Ball', 'bench_press, chest_fly, dip', TRUE, 'medicine_ball', FALSE, 3, 90, 4, 70, 88, 95, 65),
('19fa88b4-38d5-4104-9449-cdaa760607f2', 'Dead Hang - Alternating', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'The Alternating Dead Hang is a flexibility exercise that targets your full body, helping to release tension and improve range of motion. Flexibility work like this enhances performance and prevents stiffness.', '104381201', '104381201-Alternating-Dead-Hang-(male)_Stretching_.mp4', 'male', FALSE, '2025-12-03 23:26:26.93819+00', '1. Move into the stretch position for Alternating Dead Hang. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. 4. Alternate between sides/arms/legs with each repetition.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Dead Hang - Alternating', 'pull_up, lat_pulldown, grip_training', FALSE, 'bodyweight', TRUE, 3, 90, 4, 70, 88, 95, 65),
('1a042f0f-60dc-49c3-8387-ceaa54e0dc0c', 'Arm Swing Side Step', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Elevate your training with this swinging exercise that develops speed, power, and coordination. Secondary activation of your quads provides additional muscle engagement. Great for improving athletic performance, burning calories, and building conditioning. Works well as both a primary exercise or accessory movement.', '58491201', '58491201-Arm-Swing-Side-Step-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:30.54809+00', '1. Set up a box or step platform at the appropriate height. 2. Hinge at your hips, letting the weight swing back between your legs. 3. Explosively drive hips forward, propelling the weight forward/up. 4. Let gravity bring it back as you hinge for the next rep. 5. Complete all reps with control before resting. Focus on squeezing the target muscle at peak contraction.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'arm_exercise', 'Arm Swing Side Step', 'high_knees, butt_kicks, jumping_jack', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('1a05d6ac-4365-4980-a323-82bc36f01c04', 'Jab Cross Left Hook Cross (combo)', 'Full Body', 'Bodyweight', '{"Shoulders"}'::text[], '{"Biceps","Triceps","Core"}'::text[], 'A challenging plyometric exercise, the Jab Cross Left Hook Cross (combo) builds reactive power and improves conditioning. Secondary activation of your shoulders, core provides additional muscle engagement. No equipment needed—your body provides all the resistance. Great for improving athletic performance, burning calories, and building conditioning.', '104401201', '104401201-Jab-Cross-Left-Hook-Cross-(combo)_Boxing.mp4', 'male', FALSE, '2025-12-03 23:26:25.737494+00', '1. Set up in the starting position for Jab Cross Left Hook Cross. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'boxing', 'Jab Cross Left Hook Cross', 'core_exercise, shoulder_exercise, burpee', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('1a066c86-9431-43c1-88ff-1e331aef8d81', 'Lunge Twist (Barbell)', 'Legs', 'Barbell', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Target the front of your thighs with this lunging exercise for quad development. You''ll also feel your abs working to support the movement. Using a barbell provides stability for progressive overload. Strong legs are the foundation for athletic performance and functional fitness.', '73631201', '73631201-Barbell-Lunge-Twist-(male)_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:26.507873+00', '1. Grip a barbell with hands at the appropriate width for Barbell Lunge Twist. 2. Step forward into a lunge until both knees are at about 90 degrees. 3. Push through your front/working leg to return to the starting position. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 82, 7, 8, TRUE, TRUE, 'lunge', 'Lunge Twist', 'split_squat, step_up, squat', FALSE, 'barbell', FALSE, 3, 90, 4, 95, 80, 65, 95),
('1a1b1001-bc1f-4a56-8dde-e94b5db6e504', 'Side To Side Punches', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{"Shoulders"}'::text[], 'Build power and athleticism with this high-intensity movement exercise that challenges your entire body. Secondary activation of your shoulders provides additional muscle engagement. This bodyweight exercise requires no equipment and can be done anywhere. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '81771201', '81771201-Side-to-Side-Punches-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:23.79417+00', '1. Set up in the starting position for Side To Side Punches. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions. Control the movement—avoid using momentum.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'boxing', 'Side To Side Punches', 'core_exercise, shoulder_exercise, burpee', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('1a2113e7-cdd7-4f1c-8c1a-00125a2e8012', 'Lying Leg Crossover', 'Core', 'Bodyweight', '{"Abs","Obliques"}'::text[], '{"Front Delts"}'::text[], 'Build leg strength with this movement movement focusing on your chest. You''ll also feel your front delts working to support the movement. The lying position provides back support and helps isolate the target muscles. A versatile bodyweight movement perfect for home or gym training. Leg training boosts metabolism and builds functional, real-world strength.', '89311201', '89311201-Lying-Leg-Crossover-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:35.250398+00', '1. Lie down in the appropriate position for Lying Leg Crossover. 2. Set up in the starting position for Lying Leg Crossover. 3. Execute the movement with proper form, focusing on your chest. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'chest_fly', 'Lying Leg Crossover', 'bench_press, incline_press, push_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('1a26f4bc-d5e2-49fe-aa11-059e02ae045c', 'Swing Back Knee Drives', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'This dynamic swinging movement gets your heart rate up while developing explosive strength. This bodyweight exercise requires no equipment and can be done anywhere. Great for improving athletic performance, burning calories, and building conditioning.', '60861201', '60861201-Swing-Back-Knee-Drives-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:39.623429+00', '1. Hinge at your hips, letting the weight swing back between your legs. 2. Explosively drive hips forward, propelling the weight forward/up. 3. Let gravity bring it back as you hinge for the next rep. 4. Continue for your target rep count, maintaining good form throughout. Engage your stabilizer muscles for better control.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'knee_drive', 'Swing Back Knee Drives', 'butt_kicks, jumping_jack, mountain_climber', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('1a2f36d1-8001-4ed8-8bfb-37c3b824b7fe', 'Lat Pulldown - Wide Grip (Cable)', 'Back', 'Cables', '{"Lats"}'::text[], '{"Biceps","Upper Back"}'::text[], 'This pulling exercise emphasizes your lats for improved back development. You''ll also feel your biceps, upper back working to support the movement. The cable setup allows you to adjust the angle of resistance. A strong back improves posture, prevents injury, and balances pressing movements. Focus on controlled form throughout each repetition.', '22911201', '22911201-Cable-Wide-Grip-Lat-Pulldown-(female)_Back.mp4', 'female', FALSE, '2025-12-03 23:26:32.166461+00', '1. Adjust the cable machine to the correct height and attachment for Cable Wide Grip Lat Pulldown. 2. Use a wide grip (wider than shoulder-width) for this variation. 3. Pull the bar/handle down toward your upper chest. 4. Drive your elbows down and back, squeezing your lats. 5. Control the weight back up without letting it yank your arms. 6. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 90, 7, 8, TRUE, TRUE, 'lat_pulldown', 'Lat Pulldown - Wide Grip', 'Lat Pulldown - Wide Grip', TRUE, 'cable', FALSE, 3, 90, 4, 85, 88, 30, 92),
('1a523c2d-950a-42de-bc23-96910626ed66', 'Seated Hamstring Stretch (Chair)', 'Legs', 'Gymnastic Rings, Chair', '{"Hamstrings"}'::text[], '{"Glutes"}'::text[], 'Target your hamstrings with this stretching stretch that helps restore range of motion. Your lower back work as secondary movers, adding to the training stimulus. The seated position helps isolate the target muscles by removing momentum. Flexibility work like this enhances performance and prevents stiffness.', '104651201', '104651201-Seated-Hamstring-Stretch-on-a-Chair-(VERSION-2)-(.mp4', 'male', FALSE, '2025-12-03 23:26:29.61214+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Move into the stretch position for Seated Hamstring Stretch On A Chair(. 4. Ease into the stretch until you feel gentle tension (not pain). 5. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, 'Seated', NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 15, 2, 6, FALSE, TRUE, 'hamstring_stretch', 'Seated Hamstring Stretch On A Chair(', 'stretch_hip, stretch_calf, stretch_back', FALSE, 'gymnastic_rings', TRUE, 1, 30, 2, 68, 85, 85, 70),
('1a5c7794-1b5b-4956-acd6-c74a7499fa70', 'Ring Rocky Pull Up Pulldown (Gymnastic Rings)', 'Back', 'Gymnastic Rings', '{"Lats"}'::text[], '{"Biceps","Upper Back"}'::text[], 'This pulling exercise emphasizes your lats for improved back development. Secondary activation of your biceps, upper back provides additional muscle engagement. A strong back improves posture, prevents injury, and balances pressing movements.', '106621201', '106621201-Ring-Rocky-Pull-Up-Pulldown_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:28.52454+00', '1. Pull yourself up by driving your elbows down and back. 2. Continue until your chin clears the bar, then lower with control to a full hang. 3. Complete all reps with control before resting. Exhale during the exertion phase of the movement.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 58, 7, 8, TRUE, TRUE, 'lat_pulldown', 'Ring Rocky Pull Up Pulldown', 'pull_up, bent_over_row, cable_row, face_pull', FALSE, 'gymnastic_rings', FALSE, 3, 90, 4, 68, 85, 85, 70),
('1a69cd00-a16b-485a-9cdc-d2e13536d0ff', 'Figure 4 Sinal Rotation', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Figure 4 Sinal Rotation is a flexibility exercise that targets your glutes, helping to release tension and improve range of motion. Secondary activation of your hips provides additional muscle engagement. Flexibility work like this enhances performance and prevents stiffness.', '85401201', '85401201-Figure-4-Sinal-Rotation-(male)_Stretching_.mp4', 'male', FALSE, '2025-12-03 23:26:28.71819+00', '1. Rotate your torso through the movement pattern for Figure 4 Sinal Rotation. 2. Control the rotation in both directions—avoid using momentum. 3. Move into the stretch position for Figure 4 Sinal Rotation. 4. Ease into the stretch until you feel gentle tension (not pain). 5. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Figure 4 Sinal Rotation', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('1a6a877e-f914-40a5-a2ae-1db22c17336e', 'Single Arm Squat (Kettlebell)', 'Legs', 'Kettlebell', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This squatting movement emphasizes your quadriceps for stronger, more powerful legs. The glutes, hamstrings assist throughout the movement, making this a well-rounded exercise. The kettlebell''s offset center of mass increases the stability challenge. Strong legs are the foundation for athletic performance and functional fitness.', '98401201', '98401201-Kettlebell-Single-Arm-Squat-(Bilateral)-(male)_Thi.mp4', 'male', FALSE, '2025-12-03 23:26:23.288245+00', '1. Select an appropriately weighted kettlebell for Kettlebell Single Arm Squat. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Complete all reps on one side, then switch to the other side. 6. Complete all reps with control before resting.', 'Squat', NULL, NULL, NULL, NULL, 4, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 88, 7, 8, TRUE, TRUE, 'squat', 'Single Arm Squat', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'kettlebell', FALSE, 3, 90, 4, 75, 88, 88, 78),
('1a6c13aa-46d0-41a9-9d7a-cdaadb33fef7', 'Standing Double Prayer Push And Circle Draw', 'Shoulders', 'Bodyweight', '{"Shoulders"}'::text[], '{"Traps"}'::text[], 'Build stronger shoulders with this pushing movement focusing on your delts. The standing position engages your core for stability. This bodyweight exercise requires no equipment and can be done anywhere. Strong shoulders improve overhead strength and support nearly all upper body movements.', '94351201', '94351201-Standing-Double-Prayer-Push-and-Circle-Draw-(femal.mp4', 'female', FALSE, '2025-12-03 23:26:38.570929+00', '1. Stand with feet about shoulder-width apart. 2. Set up in the starting position for Standing Double Prayer Push And Circle Draw. 3. Execute the movement with proper form, focusing on your delts. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 37, 7, 8, TRUE, TRUE, 'boxing', 'Standing Double Prayer Push And Circle Draw', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('1a73a2ab-a275-412a-8783-256248a13697', 'Lying Triceps Extension On Floor (Dumbbell)', 'Arms', 'Dumbbells', '{"Triceps"}'::text[], '{"Chest","Shoulders"}'::text[], 'The Dumbbell Lying Triceps Extension On Floor targets your triceps through a extension motion. Performing this lying down removes momentum for stricter form. The dumbbell variation provides freedom of movement and greater range of motion. Dedicated arm training builds both strength and muscular definition.', '27381201', '27381201-Dumbbell-Lying-Triceps-Extension-on-Floor-(female).mp4', 'female', FALSE, '2025-12-03 23:26:32.914483+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Lying Triceps Extension On Floor. 2. Position yourself on the floor for Dumbbell Lying Triceps Extension On Floor. 3. Lie down in the appropriate position for Dumbbell Lying Triceps Extension On Floor. 4. Extend at the elbow until your arm is straight, squeezing the tricep. 5. Lower with control, keeping your upper arm stationary. 6. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 87, 5, 7, FALSE, TRUE, 'tricep_extension', 'Lying Triceps Extension On Floor', 'tricep_pushdown, close_grip_bench', FALSE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('1a88e3aa-1dd4-4fe1-ac92-e605f7b183b8', 'Side Neck Stretch', 'Neck', 'Bodyweight', '{"Neck"}'::text[], '{"Traps"}'::text[], 'This stretch specifically works on your neck, promoting flexibility and reducing muscle tightness. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '7131201', '07131201-Side-Neck-Stretch_Neck-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:22.755209+00', '1. Move into the stretch position for Side Neck Stretch. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. 4. Switch sides and repeat for equal time. Maintain a neutral spine throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'neck_stretch', 'Side Neck Stretch', 'stretch_hip, stretch_back', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('1a8ad9b4-0548-48b2-9629-2d5a30008d97', 'Standing Shoulder Extrernal Rotati (Resistance Band)', 'Full Body', 'Resistance Band', '{"Full Body"}'::text[], '{}'::text[], 'The Resistance Band Standing Shoulder Extrernal Rotati is a compound movement exercise that engages your entire body. The standing position engages your core for stability. Resistance bands provide accommodating resistance that increases through the range of motion. Full body exercises are time-efficient and build functional, real-world strength.', '83611201', '83611201-Resistance-Band-Standing-Shoulder-Extrernal-Rotati.mp4', 'male', FALSE, '2025-12-03 23:26:29.483269+00', '1. Secure the resistance band appropriately for Resistance Band Standing Shoulder Extrernal Rotati. 2. Begin in a standing position with good posture. 3. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 47, 7, 8, TRUE, TRUE, 'shoulder_exercise', 'Standing Shoulder Extrernal Rotati', 'lateral_raise, shoulder_press, front_raise', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('1a8ede7c-3cde-4887-9c0e-722abaa7025f', 'Zottman Preacher Curl (Dumbbell)', 'Arms', 'Dumbbells, Preacher Bench', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'This curling exercise focuses on your biceps for improved arm size and strength. You''ll also feel your forearms working to support the movement. Using dumbbells requires more stabilization than barbell variations. Dedicated arm training builds both strength and muscular definition.', '70731201', '70731201-Dumbbell-Zottman-Preacher-Curl-(female)_Upper-Arms.mp4', 'female', FALSE, '2025-12-03 23:26:33.298565+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Zottman Preacher Curl. 2. Keep your elbows in a fixed position throughout the movement. 3. Curl the weight up by contracting your biceps, squeezing at the top. 4. Lower with control, resisting the weight on the way down. 5. Complete all reps with control before resting. Focus on the mind-muscle connection.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 35, 5, 7, FALSE, TRUE, 'preacher_curl', 'Zottman Preacher Curl', 'tricep_pushdown, tricep_extension, bicep_curl, hammer_curl', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('1a908559-805d-42a4-baa9-9306e9ee4d51', 'Good Morning Squat', 'Legs', 'Bodyweight', '{"Hamstrings","Glutes"}'::text[], '{}'::text[], 'Target the front of your thighs with this squatting exercise for quad development. You''ll also feel your glutes, lower back working to support the movement. No equipment needed—your body provides all the resistance. Strong legs are the foundation for athletic performance and functional fitness.', '45471201', '45471201-Good-Morning-Squat_Hips.mp4', 'male', FALSE, '2025-12-03 23:26:20.982555+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. 4. Complete all reps with control before resting. Maintain a neutral spine throughout.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'back_extension', 'Good Morning Squat', 'leg_press, leg_extension, leg_curl, lunge, front_squat, hack_squat', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('1a90dce9-61a5-4d11-b513-397c385843d9', 'Kneeling Cat Cow', 'Back', 'Bodyweight', '{"Lats"}'::text[], '{"Lower Back"}'::text[], 'Use this stretch to open up your spine area and enhance overall flexibility. Secondary activation of your core provides additional muscle engagement. The kneeling position adds a core stability challenge. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '79161201', '79161201-Kneeling-Cat-Cow-(VERSION-2)-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:34.322534+00', '1. Kneel on the floor (use a pad for comfort if needed). 2. Move into the stretch position for Kneeling Cat Cow. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 15, 2, 6, FALSE, TRUE, 'back_stretch', 'Kneeling Cat Cow', 'stretch_hip, stretch_back, plank', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('1aa7710d-f2be-4845-8c51-5b64b11d595b', 'Knee Raise Torso Twist Punch', 'Core', 'Bodyweight', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'This dynamic raising movement gets your heart rate up while developing explosive strength. Secondary activation of your hip flexors provides additional muscle engagement. A versatile bodyweight movement perfect for home or gym training. Plyometric training builds explosive power that transfers to sports and daily activities.', '67821201', '67821201-Knee-Raise-Torso-Twist-Punch-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:34.322534+00', '1. Raise the weight in the prescribed direction for Knee Raise Torso Twist Punch. 2. Lower with control, maintaining tension throughout. 3. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'russian_twist', 'Knee Raise Torso Twist Punch', 'butt_kicks, jumping_jack, mountain_climber', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('1aaa4d2b-daa4-416a-8375-8931df11c226', 'Kneeling Shoulder External Rotation (Cable)', 'Shoulders', 'Cables', '{"Rotator Cuff"}'::text[], '{"Shoulders"}'::text[], 'The Cable Kneeling Shoulder External Rotation is a rotation exercise that develops back strength and muscle. The kneeling position adds a core stability challenge. The cable setup allows you to adjust the angle of resistance. A strong back improves posture, prevents injury, and balances pressing movements.', '67551201', '67551201-Cable-Kneeling-Shoulder-External-Rotation-(male)_B.mp4', 'male', FALSE, '2025-12-03 23:26:27.504261+00', '1. Adjust the cable machine to the correct height and attachment for Cable Kneeling Shoulder External Rotation. 2. Kneel on the floor (use a pad for comfort if needed). 3. Rotate your torso through the movement pattern for Cable Kneeling Shoulder External Rotation. 4. Control the rotation in both directions—avoid using momentum. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 60, 7, 8, TRUE, TRUE, 'external_rotation', 'Kneeling Shoulder External Rotation', 'squat, bench_press, deadlift', FALSE, 'cable', FALSE, 3, 90, 4, 85, 88, 30, 92),
('1ab4acaf-f1d8-40f5-82b6-247ca20420af', 'Reverse Curl (Band)', 'Arms', 'Resistance Band', '{"Forearms"}'::text[], '{"Biceps"}'::text[], 'This curling exercise focuses on your biceps for improved arm size and strength. You''ll also feel your biceps working to support the movement. The band creates increasing tension as it stretches, challenging the lockout. Dedicated arm training builds both strength and muscular definition.', '9171201', '09171201-Band-Reverse-Curl-(female)_Forearms_.mp4', 'female', FALSE, '2025-12-03 23:26:30.887491+00', '1. Secure the resistance band appropriately for Band Reverse Curl. 2. Keep your elbows in a fixed position throughout the movement. 3. Curl the weight up by contracting your biceps, squeezing at the top. 4. Lower with control, resisting the weight on the way down. 5. Complete all reps with control before resting.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 75, 5, 7, FALSE, TRUE, 'bicep_curl', 'Reverse Curl', 'hammer_curl, preacher_curl, cable_curl', FALSE, 'band', FALSE, 3, 60, 2, 60, 85, 90, 50),
('1acb93cc-a992-446c-8e09-3978cd21b88e', 'L Sit Kick Out', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'This kicking exercise engages your abs for improved core stability and strength. A versatile bodyweight movement perfect for home or gym training. Building core stability helps with everything from heavy deadlifts to daily activities.', '78231201', '78231201-L-Sit-Kick-Out-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:23.586683+00', '1. Set up in the starting position for L Sit Kick Out. 2. Execute the movement with proper form, focusing on your abs. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 5, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'L Sit Kick Out', 'hip_flexor, lunge, dynamic_warmup', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('1ae088fc-f0c0-49ef-bdc0-4ba91dc1adcd', 'Stagged Stance Romanian Deadlift (Plate)', 'Legs', 'Weight Plate', '{"Hamstrings"}'::text[], '{"Glutes","Lower Back"}'::text[], 'The Weighted Plate Stagged Stance Romanian Deadlift targets your hamstrings through a controlled hip hinge motion. You''ll also feel your glutes, lower back working to support the movement. This bodyweight exercise requires no equipment and can be done anywhere. Lower body strength improves everything from walking to heavy compound lifts.', '88231201', '88231201-Weighted-Plate-Stagged-Stance-Romanian-Deadlift-(f.mp4', 'female', FALSE, '2025-12-03 23:26:40.037451+00', '1. Push your hips back, lowering the weight along your legs with a flat back. 2. Lower until you feel a stretch in your hamstrings. 3. Drive hips forward to stand, squeezing glutes at the top. 4. Repeat for the prescribed number of repetitions. Keep your core engaged for stability.', NULL, NULL, NULL, NULL, NULL, 4, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'romanian_deadlift', 'Weighted Plate Stagged Stance Romanian Deadlift', 'deadlift, leg_curl, hip_thrust', FALSE, 'plate', FALSE, 3, 90, 4, 70, 88, 95, 65),
('1ae181ed-fa0c-4d73-bfb6-bd206e8fa4d2', 'Inverted Row Arm Twist (TRX)', 'Back', 'TRX', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'This rowing exercise strengthens the muscles between your shoulder blades. Secondary activation of your biceps provides additional muscle engagement. Suspension training adds instability, increasing core activation throughout. Back development is crucial for pulling strength and overall upper body function.', '65251201', '65251201-Suspender-Inverted-Row-Arm-Twist-(female)_Back_.mp4', 'female', FALSE, '2025-12-03 23:26:39.472701+00', '1. Adjust the TRX/suspension straps to the appropriate length for Suspender Inverted Row Arm Twist. 2. Pull the weight toward your torso, leading with your elbow(s). 3. Squeeze your shoulder blades together at the peak contraction. 4. Extend back out with control, feeling the stretch in your back. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 60, 7, 8, TRUE, TRUE, 'russian_twist', 'Suspender Inverted Row Arm Twist', 'bicep_curl, tricep_extension, hammer_curl', FALSE, 'trx', FALSE, 3, 90, 4, 68, 85, 85, 70),
('1ae7b1d0-4caa-4c2d-ae31-ff20026eb0d5', 'Deep Dip', 'Chest', 'Bodyweight', '{"Lower Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'Build stronger triceps with this dipping exercise for bigger arms. The triceps, front delts assist throughout the movement, making this a well-rounded exercise. A versatile bodyweight movement perfect for home or gym training. Arm strength supports grip, pulling, and pushing in compound movements.', '106431201', '106431201-Deep-Dip-(male)_Upper-Arms_.mp4', 'male', FALSE, '2025-12-03 23:26:23.056255+00', '1. Lower your body by bending your elbows to about 90 degrees. 2. Push back up until your arms are fully extended. 3. Continue for your target rep count, maintaining good form throughout. Exhale during the exertion phase of the movement.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'dip', 'Deep Dip', 'bench_press, tricep_pushdown, push_up', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('1aed7a9a-ec7f-40b7-a10c-3d0193b6c099', 'Hip Adduction (Machine)', 'Legs', 'Machine', '{"Inner Thighs"}'::text[], '{}'::text[], 'The Lever Seated Hip Adduction is a lower body movement exercise that targets your adductors. The seated position helps isolate the target muscles by removing momentum. Machine exercises are great for isolating muscles and training to failure safely. Leg training boosts metabolism and builds functional, real-world strength.', '25521201', '25521201-Lever-Seated-Hip-Adduction-(VERSION-2)-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:34.855778+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Seated Hip Adduction. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Repeat for the prescribed number of repetitions. Start with lighter weight to perfect your form.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 60, 7, 8, TRUE, TRUE, 'hip_adduction', 'Lever Seated Hip Adduction', 'hip_abduction, squat, lunge', TRUE, 'machine', FALSE, 3, 90, 4, 80, 75, 20, 88),
('1b012dec-e32c-4c78-bd7e-08b2ad5898b5', 'Backward Abdominal Stretch', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Strengthen your midsection with this stretching movement that works your abs. A versatile bodyweight movement perfect for home or gym training. Building core stability helps with everything from heavy deadlifts to daily activities.', '42701201', '42701201-Backward-Abdominal-Stretch-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:30.685158+00', '1. Set up in the starting position for Backward Abdominal Stretch. 2. Execute the movement with proper form, focusing on your abs. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'stretch_general', 'Backward Abdominal Stretch', 'stretch_hip, stretch_hamstring, stretch_shoulder', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('1b21512f-bc7f-42cd-a2f2-ce5527a64f72', 'Hang Power Clean (Dumbbell)', 'Full Body', 'Dumbbells', '{"Full Body"}'::text[], '{"Quads","Glutes","Traps"}'::text[], 'Develop functional strength with the Dumbbell Hang Power Clean, a comprehensive movement exercise. The quads, glutes, traps assist throughout the movement, making this a well-rounded exercise. Dumbbells allow each arm to work independently, helping correct imbalances. Full body exercises are time-efficient and build functional, real-world strength.', '47391201', '47391201-Dumbbell-Hang-Power-Clean_Weightlifting_.mp4', 'male', FALSE, '2025-12-03 23:26:27.263406+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Hang Power Clean. 2. Explosively pull the weight upward from the starting position. 3. Pull yourself under the weight and catch it at shoulder level. 4. Stand to complete the lift, then lower with control. 5. Perform the concentric (lifting) phase explosively with maximum effort. 6. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 5, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 3, 6, NULL, 9, NULL, TRUE, NULL, 'Strength', 62, 7, 9, TRUE, FALSE, 'clean', 'Hang Power Clean', 'clean, hang_clean, deadlift', TRUE, 'dumbbell', FALSE, 4, 120, 6, 92, 90, 92, 90),
('1b245332-0f7a-430d-b6f5-1d9f7159c528', 'Chair Squat (Machine)', 'Legs', 'Lever Machine', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Lever Chair Squat is a squatting exercise that primarily loads your quadriceps. The glutes, hamstrings assist throughout the movement, making this a well-rounded exercise. Machine exercises are great for isolating muscles and training to failure safely. Strong legs are the foundation for athletic performance and functional fitness.', '10381201', '10381201-Lever-Chair-Squat_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:24.099303+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Chair Squat. 2. Position yourself with a sturdy chair for support or as part of the movement. 3. Push your hips back and bend your knees to lower your body. 4. Keep your chest up and knees tracking over your toes. 5. Drive through your heels to stand back up, squeezing your glutes at the top. 6. Repeat for the prescribed number of repetitions.', 'Squat', NULL, NULL, NULL, NULL, 1, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 9, NULL, FALSE, NULL, 'Strength', 78, 7, 9, TRUE, FALSE, 'squat', 'Lever Chair Squat', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'machine', FALSE, 4, 120, 5, 80, 75, 20, 88),
('1b2501f5-d0c9-4e8e-9ded-66a1454bd3d8', 'Seated Side Bend Shoulder Stretch', 'Shoulders', 'Bodyweight', '{"Shoulders"}'::text[], '{"Traps"}'::text[], 'This stretch specifically works on your shoulders, promoting flexibility and reducing muscle tightness. You''ll also feel your upper back working to support the movement. The seated position helps isolate the target muscles by removing momentum. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '82391201', '82391201-Seated-Side-Bend-Shoulder-Stretch-(female)_Stretch.mp4', 'female', FALSE, '2025-12-03 23:26:36.848698+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Move into the stretch position for Seated Side Bend Shoulder Stretch. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. 5. Switch sides and repeat for equal time.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, 'Seated', NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 42, 2, 6, FALSE, TRUE, 'shoulder_stretch', 'Seated Side Bend Shoulder Stretch', 'stretch_chest, stretch_tricep, stretch_lat', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('1b32e3dc-373e-4b15-8a26-f749207145de', 'Seated Single Leg Extension (Cable)', 'Legs', 'Cables', '{"Quads"}'::text[], '{}'::text[], 'Build stronger quads with this extension movement that develops leg drive and power. The seated position helps isolate the target muscles by removing momentum. Cables provide constant tension throughout the full range of motion. Strong legs are the foundation for athletic performance and functional fitness.', '78101201', '78101201-Cable-Seated-Single-Leg-Extension-(female)_Thighs_.mp4', 'female', FALSE, '2025-12-03 23:26:32.054831+00', '1. Adjust the cable machine to the correct height and attachment for Cable Seated Single Leg Extension. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Extend your legs until straight, squeezing your quads at the top. 4. Lower with control back to the starting position. 5. Complete all reps on one side, then switch to the other side. 6. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 5, 7, NULL, 6, 'Seated', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 87, 5, 7, FALSE, TRUE, 'leg_extension', 'Seated Single Leg Extension', 'squat, leg_press, lunge', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('1b349471-43a2-42e3-89a0-246fe6d19fde', 'Crunch Heel Touch', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build a stronger core with the Crunch Heel Touch, focusing on your abs. Your abs work as secondary movers, adding to the training stimulus. No equipment needed—your body provides all the resistance. A strong core improves posture, protects your spine, and enhances all other lifts.', '104121201', '104121201-Crunch-Heel-Touch-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:26.146796+00', '1. Curl your shoulders off the floor by contracting your abs. 2. Don''t pull on your neck—focus on the abdominal contraction. 3. Lower with control, maintaining some tension. 4. Continue for your target rep count, maintaining good form throughout. Focus on squeezing the target muscle at peak contraction. Perfect for targeting your abs.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'crunch', 'Crunch Heel Touch', 'leg_raise, plank, russian_twist, v_up', TRUE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('1b36cccf-7259-48a8-b9f8-4fd24d82778f', 'Front Kick In Place - Alternating', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Build power and athleticism with this high-intensity kicking exercise that challenges your entire body. A versatile bodyweight movement perfect for home or gym training. Plyometric training builds explosive power that transfers to sports and daily activities. Perfect for including in both strength and hypertrophy programs.', '47131201', '47131201-Alternate-Front-Kick-in-Place_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:24.577164+00', '1. Alternate between sides/arms/legs with each repetition. 2. Set up in the starting position for Alternate Front Kick In Place. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Front Kick In Place - Alternating', 'hip_flexor, lunge, dynamic_warmup', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('1b3f6f44-7d0e-4efa-911b-dffc2c628810', 'Seated Shoulder Press And Hip Abduction On A Padd', 'Shoulders', 'Bodyweight', '{"Shoulders"}'::text[], '{"Side Delts","Triceps"}'::text[], 'Build stronger shoulders with this pressing movement focusing on your delts. The triceps assist throughout the movement, making this a well-rounded exercise. Being seated provides stability, allowing you to focus on the working muscles. Strong shoulders improve overhead strength and support nearly all upper body movements.', '55581201', '55581201-Sitting-Shoulder-Press-and-Hip-Abduction-on-a-padd.mp4', 'male', FALSE, '2025-12-03 23:26:23.172397+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Start with the weight at shoulder level. 3. Press directly overhead until your arms are fully extended. 4. Lower back to shoulder level with control. 5. Repeat for the prescribed number of repetitions. Exhale during the exertion phase of the movement.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 80, 7, 8, TRUE, TRUE, 'shoulder_press', 'Seated Shoulder Press And Hip Abduction On A Padd', 'lateral_raise, front_raise, rear_delt', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('1b4f100f-02cd-48e0-9f8e-3eaf1e8e1533', 'Standing Calf Raise (On A Staircase)', 'Legs', 'Bodyweight', '{"Calves"}'::text[], '{}'::text[], 'Build stronger calves with this targeted raising exercise. Performing this standing challenges your balance and core engagement. A versatile bodyweight movement perfect for home or gym training. Lower body strength improves everything from walking to heavy compound lifts.', '80961201', '80961201-Standing-Calf-Raise-(On-a-staircase)-(female)_Calv.mp4', 'female', FALSE, '2025-12-03 23:26:38.425788+00', '1. Stand tall with your feet firmly planted. 2. Lower your heels below the platform to get a full stretch. 3. Rise up onto your toes as high as possible, squeezing your calves. 4. Lower with control and repeat. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 82, 5, 7, FALSE, TRUE, 'calf_raise', 'Standing Calf Raise', 'calf_raise, seated_calf_raise', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('1b5fd646-c943-4b79-98df-7d2954dcc5d3', 'Front Plank With Leg Lift', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Shoulders","Lower Back"}'::text[], 'Build leg strength with this stabilization movement focusing on your abs. The shoulders, lower back assist throughout the movement, making this a well-rounded exercise. No equipment needed—your body provides all the resistance. Lower body strength improves everything from walking to heavy compound lifts.', '35011201', '35011201-Front-Plank-with-Leg-Lift-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:27.805708+00', '1. Hold your body in a straight line from head to heels. 2. Don''t let your hips sag or pike up—engage your core and glutes. 3. Breathe steadily while maintaining the position. 4. Complete all reps with control before resting. Exhale during the exertion phase of the movement.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'plank', 'Front Plank With Leg Lift', 'side_plank, dead_bug, hollow_hold', TRUE, 'bodyweight', TRUE, 3, 90, 4, 70, 88, 95, 65),
('1b682cd2-d144-467a-8474-63ad0e1f3673', 'Standing Upright Row (EZ Bar)', 'Shoulders', 'EZ Bar', '{"Side Delts"}'::text[], '{"Traps","Front Delts"}'::text[], 'This rowing exercise works your delts for improved shoulder strength and aesthetics. You''ll also feel your traps working to support the movement. Performing this standing challenges your balance and core engagement. Strong shoulders improve overhead strength and support nearly all upper body movements.', '71141201', '71141201-EZ-Bar-Standing-Upright-Row-(female)_Shoulders_.mp4', 'female', FALSE, '2025-12-03 23:26:33.505723+00', '1. Grip the EZ bar on the angled portions for a comfortable wrist position. 2. Begin in a standing position with good posture. 3. Pull the weight straight up along your body, leading with your elbows. 4. Raise until elbows reach shoulder height, then lower with control. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 10, 10, NULL, 4, 'Standing', NULL, NULL, NULL, 5, 8, NULL, 8, NULL, TRUE, NULL, 'Strength', 72, 7, 9, TRUE, FALSE, 'upright_row', 'EZ Bar Standing Upright Row', 'lateral_raise, shoulder_press, shrug', FALSE, 'ez_bar', FALSE, 4, 120, 4, 95, 80, 65, 95),
('1b743f95-bb04-4a53-a465-315461f7bef7', 'Lying Extension - Across Face (Dumbbell)', 'Arms', 'Dumbbells, Flat Bench', '{"Triceps"}'::text[], '{"Chest","Shoulders"}'::text[], 'The Dumbbell Lying Extension (across Face) is an arm extension exercise targeting your core. The lying position provides back support and helps isolate the target muscles. Dumbbells allow each arm to work independently, helping correct imbalances. Arm strength supports grip, pulling, and pushing in compound movements.', '25861201', '25861201-Dumbbell-Lying-Extension-(across-face)-(female)_Up.mp4', 'female', FALSE, '2025-12-03 23:26:32.914483+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Lying Extension. 2. Lie down in the appropriate position for Dumbbell Lying Extension. 3. Extend through the target joint(s) for Dumbbell Lying Extension. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 74, 5, 7, FALSE, TRUE, 'boxing', 'Lying Extension', 'squat, bench_press, deadlift', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('1b7b291e-3651-4cb9-bff8-f8a41109abc8', 'Flexion Leg Sit Up (Straight Arm)', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Strengthen your midsection with this flexion movement that works your abs. Secondary activation of your hip flexors provides additional muscle engagement. No equipment needed—your body provides all the resistance. Core strength is foundational for athletic performance and injury prevention.', '4571201', '04571201-Flexion-Leg-Sit-up-(straight-arm)_waist.mp4', 'male', FALSE, '2025-12-03 23:26:30.099411+00', '1. Set up in the starting position for Flexion Leg Sit Up. 2. Execute the movement with proper form, focusing on your abs. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'crunch', 'Flexion Leg Sit Up', 'leg_raise, plank, russian_twist, v_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('1b85d840-666f-4355-bb50-fd3650cf28dd', 'Kneeling Single Kickback', 'Legs', 'Bodyweight', '{"Glutes","Hamstrings"}'::text[], '{"Rear Delts"}'::text[], 'The Kneeling Single Kickback is a hip-dominant kicking exercise that targets your glutes. You''ll also feel your hamstrings working to support the movement. Kneeling helps eliminate lower body momentum from the movement. A versatile bodyweight movement perfect for home or gym training. Leg training boosts metabolism and builds functional, real-world strength.', '64831201', '64831201-Kneeling-Single-Kickback-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:34.487002+00', '1. Kneel on the floor (use a pad for comfort if needed). 2. Keep your upper arm stationary and extend your forearm back. 3. Squeeze at full extension, then return with control. 4. Repeat for the prescribed number of repetitions. Keep your core engaged for stability.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 50, 5, 7, FALSE, TRUE, 'tricep_kickback', 'Kneeling Single Kickback', 'squat, leg_extension, lunge', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('1b8ddade-6712-41f5-a145-12e0b101ce31', 'Seated Knee Slap (Chair)', 'Core', 'Chair', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Seated Knee Slap On Chair is a lower body movement exercise that targets your core. The seated position helps isolate the target muscles by removing momentum. Lower body strength improves everything from walking to heavy compound lifts.', '105071201', '105071201-Seated-Knee-Slap-on-Chair-(male)_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:29.083517+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Complete all reps with control before resting. Keep your shoulders relaxed and away from your ears. Works well for core activation.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 37, 7, 8, TRUE, TRUE, 'general_exercise', 'Seated Knee Slap On Chair', 'squat, leg_extension, lunge', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('1b99f9ae-11b5-4763-bcac-be346d2506a3', 'Incline Reverse Push Up', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Front Delts","Triceps"}'::text[], 'The Incline Reverse Push Up is an arm pushing exercise targeting your chest. Secondary activation of your triceps, front delts provides additional muscle engagement. Using an incline changes the angle of resistance for varied muscle recruitment. Arm strength supports grip, pulling, and pushing in compound movements.', '64971201', '64971201-Incline-Reverse-Push-up_Upper-Arms_.mp4', 'male', FALSE, '2025-12-03 23:26:20.982555+00', '1. Keep your body in a straight line from head to heels throughout. 2. Lower your chest toward the floor by bending your elbows. 3. Push through your palms to return to the starting position. 4. Continue for your target rep count, maintaining good form throughout. Keep the movement smooth and controlled.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 73, 7, 8, TRUE, TRUE, 'push_up', 'Incline Reverse Push Up', 'bench_press, chest_fly, dip', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('1b9f8b92-c327-4a6c-a125-49b29a596be6', 'Butt Bridge', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Butt Bridge is a core bridging exercise that primarily targets your abs. Secondary activation of your hamstrings provides additional muscle engagement. A versatile bodyweight movement perfect for home or gym training. A strong core improves posture, protects your spine, and enhances all other lifts.', '1451201', '01451201-Butt-Bridge-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:31.723232+00', '1. Drive through your heels to lift your hips toward the ceiling. 2. Squeeze your glutes hard at the top of the movement. 3. Lower your hips back down with control. 4. Complete all reps with control before resting. Keep tension on the target muscles throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'glute_bridge', 'Butt Bridge', 'hip_thrust, romanian_deadlift', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('1ba2dc8a-3677-46e2-b4a9-cd3ddd5ae127', 'Seated Shoulder Flexor Depresor Retractor Stretch Bent Knee', 'Shoulders', 'Bodyweight', '{"Shoulders"}'::text[], '{"Traps"}'::text[], 'Build stronger shoulders with this stretching movement focusing on your delts. The seated position helps isolate the target muscles by removing momentum. Strong shoulders improve overhead strength and support nearly all upper body movements.', '46761201', '46761201-Seated-Shoulder-Flexor-Depresor-Retractor-Stretch-Bent-Knee-(female)_Shoulders.mp4', 'female', FALSE, '2025-12-03 23:26:36.848698+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Set up in the starting position for Seated Shoulder Flexor Depresor Retractor Stretch Bent Knee. 3. Execute the movement with proper form, focusing on your delts. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, 'Seated', NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 32, 2, 6, FALSE, TRUE, 'stretch_general', 'Seated Shoulder Flexor Depresor Retractor Stretch Bent Knee', 'stretch_chest, stretch_tricep, stretch_lat', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('1ba4bdb0-ecbf-431e-8100-acda4f4775da', 'Single Arm Thruster (Kettlebell)', 'Full Body', 'Kettlebell', '{"Full Body"}'::text[], '{"Quads","Shoulders"}'::text[], 'Develop functional strength with the Kettlebell One Arm Thruster, a comprehensive thrusting exercise. You''ll also feel your quads, shoulders working to support the movement. The kettlebell''s offset center of mass increases the stability challenge. Compound movements like this develop coordination, power, and overall fitness.', '45411201', '45411201-Kettlebell-One-Arm-Thruster_Weightlifting_.mp4', 'male', FALSE, '2025-12-03 23:26:23.689343+00', '1. Select an appropriately weighted kettlebell for Kettlebell One Arm Thruster. 2. Drive through your heels to lift your hips toward the ceiling. 3. Squeeze your glutes hard at the top of the movement. 4. Lower your hips back down with control. 5. Complete all reps on one side, then switch to the other side. 6. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 4, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 53, 7, 8, TRUE, TRUE, 'thruster', 'Single Arm Thruster', 'front_squat, shoulder_press, clean', FALSE, 'kettlebell', FALSE, 3, 90, 4, 75, 88, 88, 78),
('1bb09553-ea98-4ff7-b10b-9526ceb0ea18', 'Sphinx Lookback', 'Back', 'Bodyweight', '{"Upper Back"}'::text[], '{"Shoulders"}'::text[], 'Use this stretch to open up your back area and enhance overall flexibility. Secondary activation of your shoulders provides additional muscle engagement. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '81571201', '81571201-Sphinx-Lookback-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:38.153182+00', '1. Move into the stretch position for Sphinx Lookback. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'back_stretch', 'Sphinx Lookback', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65);
INSERT INTO _exercise_staging (id, name, category, equipment, primary_muscles, secondary_muscles, description, video_code, video_filename, gender, is_custom, created_at, steps_to_perform, movement_pattern, force_type, movement_type, laterality, plane_of_motion, difficulty_level, complexity_score, strength_rating, hypertrophy_rating, power_rating, endurance_rating, body_position, bench_angle, grip_type, grip_width, optimal_rep_range_min, optimal_rep_range_max, placement_in_workout, fatigability, popularity_score, home_gym_friendly, instructions, workout_type, practicality_score, fat_loss_rating, general_fitness_rating, is_compound, supersetable, exercise_family, base_exercise_name, complementary_families, is_equipment_primary, equipment_category, duration_based, recommended_sets, rest_seconds, muscles_worked_count, priority_build_muscle, priority_get_lean, priority_home, priority_gym) VALUES
('1bb68a00-61e8-4079-9fd7-64f16a79947f', 'Reverse Lunge High Knee', 'Legs', 'Bodyweight', '{"Glutes"}'::text[], '{"Quads","Hamstrings"}'::text[], 'This lunging movement emphasizes your quadriceps for stronger, more powerful legs. The hip flexors assist throughout the movement, making this a well-rounded exercise. No equipment needed—your body provides all the resistance. Leg training boosts metabolism and builds functional, real-world strength.', '73731201', '73731201-Reverse-Lunge-High-Knee-(male)_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:27.937212+00', '1. Step backward, lowering your back knee toward the floor. 2. Push through your front/working leg to return to the starting position. 3. Complete all reps with control before resting. Maintain a neutral spine throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 70, 9, 8, TRUE, TRUE, 'lunge', 'Reverse Lunge High Knee', 'split_squat, step_up, squat', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('1bbba2bb-b539-42a0-b52a-5084dcd87f43', 'Pendlay Row (Cable)', 'Back', 'Cables', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'This rowing exercise strengthens the muscles between your shoulder blades. Your biceps, rear delts work as secondary movers, adding to the training stimulus. Cables provide constant tension throughout the full range of motion. A strong back improves posture, prevents injury, and balances pressing movements.', '105771201', '105771201-Cable-Pendlay-Row_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:28.968567+00', '1. Adjust the cable machine to the correct height and attachment for Cable Pendlay Row. 2. Pull the weight toward your torso, leading with your elbow(s). 3. Squeeze your shoulder blades together at the peak contraction. 4. Extend back out with control, feeling the stretch in your back. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 35, 7, 8, TRUE, TRUE, 'bent_over_row', 'Pendlay Row', 'cable_row, dumbbell_row, t_bar_row, lat_pulldown', FALSE, 'cable', FALSE, 3, 90, 4, 85, 88, 30, 92),
('1bd4f8ad-b6e7-4a6b-bb03-a05d0829670a', 'Decline Bench Press (Barbell)', 'Chest', 'Barbell, Decline Bench', '{"Chest","Lower Chest"}'::text[], '{"Front Delts","Triceps"}'::text[], 'The Barbell Decline Bench Press is a pressing exercise that targets your chest muscles. The triceps, front delts assist throughout the movement, making this a well-rounded exercise. The decline position targets the lower portion of the muscles more intensely. The barbell allows you to handle heavier loads for maximum strength gains. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '331201', '00331201-Barbell-Decline-Bench-Press_Chest-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:29.61214+00', '1. Load a barbell and set it on a bench rack at the appropriate height. 2. Lower the weight toward your chest with control. 3. Press the weight up until your arms are extended (don''t lock elbows). 4. Continue for your target rep count, maintaining good form throughout. Exhale during the exertion phase of the movement. Great for building strength in your chest.', 'Press', 'Push', 'Compound', 'Bilateral', NULL, 3, NULL, 10, 10, NULL, 4, 'Lying (Decline)', NULL, 'Overhand (pronated)', 'Slightly wider than shoulder-width', 5, 8, NULL, 8, NULL, FALSE, NULL, 'Strength', 100, 7, 9, TRUE, FALSE, 'decline_press', 'Decline Bench Press', 'bench_press, incline_bench_press, chest_fly, dip', TRUE, 'barbell', FALSE, 4, 120, 4, 95, 80, 65, 95),
('1c0844b7-f837-42fa-a60a-6bae2175e892', 'Weighted Single Leg Hip Thrust', 'Legs', 'Bodyweight', '{"Glutes"}'::text[], '{"Hamstrings","Core"}'::text[], 'This thrusting exercise isolates your glutes for improved hip strength and power. Your hamstrings work as secondary movers, adding to the training stimulus. A versatile bodyweight movement perfect for home or gym training. Leg training boosts metabolism and builds functional, real-world strength.', '10621201', '10621201-Weighted-One-Leg-Hip-Thrust_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:23.466497+00', '1. Drive through your heels to lift your hips toward the ceiling. 2. Squeeze your glutes hard at the top of the movement. 3. Lower your hips back down with control. 4. Complete all reps on one side, then switch to the other side. 5. Complete all reps with control before resting. Control the movement—avoid using momentum.', NULL, NULL, NULL, NULL, NULL, 5, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 65, 7, 8, TRUE, TRUE, 'hip_thrust', 'Weighted Single Leg Hip Thrust', 'glute_bridge, romanian_deadlift, leg_curl', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('1c1146fa-21d4-4b31-a35d-10db76bc93cd', 'Thruster (Band)', 'Full Body', 'Resistance Band', '{"Full Body"}'::text[], '{"Quads","Shoulders"}'::text[], 'The Band Thruster is a lower body thrusting exercise that targets your full body. The quads, shoulders assist throughout the movement, making this a well-rounded exercise. Resistance bands provide accommodating resistance that increases through the range of motion. Leg training boosts metabolism and builds functional, real-world strength.', '29711201', '29711201-Band-Thruster-(female)_Thighs_.mp4', 'female', FALSE, '2025-12-03 23:26:31.013316+00', '1. Secure the resistance band appropriately for Band Thruster. 2. Drive through your heels to lift your hips toward the ceiling. 3. Squeeze your glutes hard at the top of the movement. 4. Lower your hips back down with control. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 55, 7, 8, TRUE, TRUE, 'thruster', 'Thruster', 'front_squat, shoulder_press, clean', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('1c22b0b6-f25d-45b5-a728-791c0e5f83c9', 'Butt Kick Jump', 'Legs', 'Bodyweight', '{"Glutes","Hamstrings"}'::text[], '{"Calves"}'::text[], 'The Butt Kick Jump is an explosive exercise that combines cardiovascular training with dynamic kicking movements. Secondary activation of your hamstrings provides additional muscle engagement. No equipment needed—your body provides all the resistance. Great for improving athletic performance, burning calories, and building conditioning.', '78471201', '78471201-Butt-Kick-Jump-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:28.260518+00', '1. Set up in the starting position for Butt Kick Jump. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 50, 9, 8, TRUE, TRUE, 'glute_kickback', 'Butt Kick Jump', 'high_knees, jumping_jack, running', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('1c274bdb-1215-427e-8962-0cd8129e4bc2', 'Straight Arm Pullover (Dumbbell)', 'Chest', 'Dumbbells, Flat Bench', '{"Chest"}'::text[], '{"Lats","Triceps"}'::text[], 'This pulling exercise focuses on your pectorals for improved chest strength and development. Secondary activation of your lats, triceps provides additional muscle engagement. The dumbbell variation provides freedom of movement and greater range of motion. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '4331201', '04331201-Dumbbell-Straight-Arm-Pullover_Chest.mp4', 'male', FALSE, '2025-12-03 23:26:29.36063+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Straight Arm Pullover. 2. With arms slightly bent, lower the weight behind your head in an arc. 3. Pull the weight back over your chest, squeezing your lats and chest. 4. Continue for your target rep count, maintaining good form throughout. Exhale during the exertion phase of the movement.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 62, 7, 8, TRUE, TRUE, 'pullover', 'Straight Arm Pullover', 'bicep_curl, face_pull, lat_pulldown', TRUE, 'dumbbell', FALSE, 3, 90, 4, 92, 90, 92, 90),
('1c2fe1bc-e033-4e5a-a98e-d7d95f15564a', 'Big Turn Back Stretch', 'Back', 'Bodyweight', '{"Lats"}'::text[], '{"Lower Back"}'::text[], 'The Big Turn Back Stretch is a stretching exercise that targets your chest muscles. A versatile bodyweight movement perfect for home or gym training. A well-developed chest contributes to upper body strength and aesthetics.', '65401201', '65401201-Big-Turn-Back-Stretch-(female)_Chest_.mp4', 'female', FALSE, '2025-12-03 23:26:31.347577+00', '1. Set up in the starting position for Big Turn Back Stretch. 2. Execute the movement with proper form, focusing on your chest. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'back_stretch', 'Big Turn Back Stretch', 'stretch_hip, stretch_hamstring, stretch_shoulder', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('1c55362a-48d7-4202-be47-a3a7b57c760a', 'Seated Shrug (Chair)', 'Back', 'Chair', '{"Traps"}'::text[], '{"Upper Back"}'::text[], 'The Seated Shrug On A Chair is a shrugging exercise that develops back strength and muscle. The seated position helps isolate the target muscles by removing momentum. A strong back improves posture, prevents injury, and balances pressing movements.', '90991201', '90991201-Sitting-Shrug-on-a-Chair-(female)_Back_.mp4', 'female', FALSE, '2025-12-03 23:26:37.877283+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Shrug your shoulders straight up toward your ears. 4. Hold briefly at the top, then lower with control. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 55, 5, 7, FALSE, TRUE, 'shrug', 'Seated Shrug On A Chair', 'deadlift, bent_over_row, face_pull', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('1c6160d4-2917-4f7b-bb72-df377aebd8b0', 'Prone Incline Curl (Dumbbell)', 'Arms', 'Dumbbells, Incline Bench', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'Build bigger biceps with this curling movement that targets the front of your arms. Secondary activation of your forearms provides additional muscle engagement. The lying position provides back support and helps isolate the target muscles. Dumbbells allow each arm to work independently, helping correct imbalances. Arm strength supports grip, pulling, and pushing in compound movements.', '3741201', '03741201-Dumbbell-Prone-Incline-Curl_Upper-Arms-FIX2_.mp4', 'male', FALSE, '2025-12-03 23:26:23.586683+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Prone Incline Curl. 2. Lie face down (prone position) for Dumbbell Prone Incline Curl. 3. Keep your elbows in a fixed position throughout the movement. 4. Curl the weight up by contracting your biceps, squeezing at the top. 5. Lower with control, resisting the weight on the way down. 6. Continue for your target rep count, maintaining good form throughout.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 95, 5, 7, FALSE, TRUE, 'incline_curl', 'Prone Incline Curl', 'bicep_curl, hammer_curl, preacher_curl', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('1c66c20e-5c5a-40ef-b94a-475ae45199fd', 'Side Plank - Beginner', 'Core', 'Bodyweight', '{"Core","Abs"}'::text[], '{"Shoulders"}'::text[], 'Strengthen your midsection with this stabilization movement that works your abs. Your shoulders, lower back work as secondary movers, adding to the training stimulus. This bodyweight exercise requires no equipment and can be done anywhere. Core strength is foundational for athletic performance and injury prevention.', '28991201', '28991201-Side-Plank-(beginner)-(female)_Waist-FIX_.mp4', 'female', FALSE, '2025-12-03 23:26:37.179953+00', '1. Hold your body in a straight line from head to heels. 2. Don''t let your hips sag or pike up—engage your core and glutes. 3. Breathe steadily while maintaining the position. 4. Repeat for the prescribed number of repetitions. Don''t rush—quality over quantity. Beneficial for overall core development.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'side_plank', 'Side Plank', 'plank, russian_twist, woodchop', FALSE, 'bodyweight', TRUE, 3, 90, 4, 70, 88, 95, 65),
('1c67d946-59fc-4373-be34-db13af9779cd', 'Preacher Curl (Machine)', 'Arms', 'Machine', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'Build bigger biceps with this curling movement that targets the front of your arms. Your forearms work as secondary movers, adding to the training stimulus. Machine exercises are great for isolating muscles and training to failure safely. Dedicated arm training builds both strength and muscular definition.', '28191201', '28191201-Lever-Preacher-Curl-(VERSION-2)-(female)_Upper-Arms.mp4', 'female', FALSE, '2025-12-03 23:26:34.724336+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Preacher Curl. 2. Keep your elbows in a fixed position throughout the movement. 3. Curl the weight up by contracting your biceps, squeezing at the top. 4. Lower with control, resisting the weight on the way down. 5. Continue for your target rep count, maintaining good form throughout. Start with lighter weight to perfect your form.', 'Curl', 'Pull', NULL, NULL, NULL, 1, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, FALSE, NULL, 'Strength', 88, 5, 7, FALSE, TRUE, 'preacher_curl', 'Lever Preacher Curl', 'tricep_pushdown, tricep_extension, bicep_curl, hammer_curl', FALSE, 'machine', FALSE, 3, 60, 2, 80, 75, 20, 88),
('1c686e3b-0818-4cbb-9097-af422d0cff76', 'Standing Crossover Crunch', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'A challenging plyometric exercise, the Standing Crossover Crunch builds reactive power and improves conditioning. The front delts assist throughout the movement, making this a well-rounded exercise. Performing this standing challenges your balance and core engagement. This bodyweight exercise requires no equipment and can be done anywhere. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '77561201', '77561201-Standing-Crossover-Crunch-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:38.570929+00', '1. Stand tall with your feet firmly planted. 2. Curl your shoulders off the floor by contracting your abs. 3. Don''t pull on your neck—focus on the abdominal contraction. 4. Lower with control, maintaining some tension. 5. Repeat for the prescribed number of repetitions. Engage your stabilizer muscles for better control.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 72, 5, 7, FALSE, TRUE, 'chest_fly', 'Standing Crossover Crunch', 'bench_press, incline_press, push_up', TRUE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('1c6f6ed4-7142-4968-94a5-734695c775bc', 'Elevated Cycling (Stationary Bike)', 'Core', 'Stationary Bike, Step Platform', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Strengthen your midsection with this movement movement that works your abs. No equipment needed—your body provides all the resistance. A strong core improves posture, protects your spine, and enhances all other lifts. This variation is excellent for building mind-muscle connection.', '56791201', '56791201-Elevated-Cycling-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:27.805708+00', '1. Set up in the starting position for Elevated Cycling. 2. Execute the movement with proper form, focusing on your abs. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 2, 2, NULL, 10, NULL, NULL, NULL, NULL, 1, 1, NULL, 3, NULL, TRUE, NULL, 'Cardio', 50, 9, 8, FALSE, TRUE, 'cycling', 'Elevated Cycling', 'running, elliptical, rowing_cardio', FALSE, 'bodyweight', TRUE, 1, 60, 4, 70, 88, 95, 65),
('1c72aa13-3c4e-4c25-a376-c116e233a47a', 'Ring Tuck Planche (Gymnastic Rings)', 'Core', 'Gymnastic Rings', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'This movement exercise focuses on your pectorals for improved chest strength and development. Your triceps, front delts, core work as secondary movers, adding to the training stimulus. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '75111201', '75111201-Ring-Tuck-Planche-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:23.689343+00', '1. Set up in the starting position for Ring Tuck Planche. 2. Execute the movement with proper form, focusing on your chest. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 5, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 5, 7, 8, TRUE, TRUE, 'planche', 'Ring Tuck Planche', 'squat, bench_press, deadlift', FALSE, 'gymnastic_rings', FALSE, 3, 90, 4, 68, 85, 85, 70),
('1c8019e4-05c6-4d7b-9556-a148bc5c5110', 'Squat And Knee', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'A challenging plyometric exercise, the Squat And Knee builds reactive power and improves conditioning. You''ll also feel your glutes, hamstrings working to support the movement. No equipment needed—your body provides all the resistance. Great for improving athletic performance, burning calories, and building conditioning.', '56781201', '56781201-Squat-and-Knee-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:30.292204+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. 4. Continue for your target rep count, maintaining good form throughout. Control the movement—avoid using momentum. This variation specifically emphasizes the quads.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'squat', 'Squat And Knee', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('1ca1e741-a274-42fb-81cb-866d406b56f5', 'Standing Triceps Stretch (Against Wall)', 'Arms', 'Wall', '{"Triceps"}'::text[], '{"Chest","Shoulders"}'::text[], 'The Standing Triceps Stretch Against Wall is a flexibility exercise that targets your triceps, helping to release tension and improve range of motion. Your shoulders work as secondary movers, adding to the training stimulus. Performing this standing challenges your balance and core engagement. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '98201201', '98201201-Standing-Triceps-Stretch-against-Wall-(male)_Stret.mp4', 'male', FALSE, '2025-12-03 23:26:24.941834+00', '1. Position yourself at the appropriate distance from a wall. 2. Stand with feet about shoulder-width apart. 3. Move into the stretch position for Standing Triceps Stretch Against Wall. 4. Ease into the stretch until you feel gentle tension (not pain). 5. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, 'Standing', NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 34, 2, 6, FALSE, TRUE, 'stretch_general', 'Standing Triceps Stretch Against Wall', 'bicep_curl, dip', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('1ca4d457-739d-42bb-a9b3-8fb2b744e03f', 'Seated Shoulder Rotation', 'Shoulders', 'Bodyweight', '{"Rotator Cuff"}'::text[], '{"Shoulders"}'::text[], 'Designed to lengthen your shoulders, the Seated Shoulder Rotation helps improve mobility and prevent stiffness. Secondary activation of your upper back provides additional muscle engagement. Being seated provides stability, allowing you to focus on the working muscles. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '81261201', '81261201-Seated-Shoulder-Rotation-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:36.848698+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Rotate your torso through the movement pattern for Seated Shoulder Rotation. 3. Control the rotation in both directions—avoid using momentum.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'shoulder_exercise', 'Seated Shoulder Rotation', 'lateral_raise, shoulder_press, front_raise', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('1cac351f-744c-413f-b9c3-3cc5b5c81a67', 'Deep Push Up', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'This pushing exercise focuses on your pectorals for improved chest strength and development. Your triceps, front delts work as secondary movers, adding to the training stimulus. This bodyweight exercise requires no equipment and can be done anywhere. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '12741201', '12741201-Deep-Push-Up_Chest-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:22.247914+00', '1. Keep your body in a straight line from head to heels throughout. 2. Lower your chest toward the floor by bending your elbows. 3. Push through your palms to return to the starting position. 4. Complete all reps with control before resting. Focus on squeezing the target muscle at peak contraction. An effective movement for your chest routine.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'push_up', 'Deep Push Up', 'bench_press, chest_fly, dip', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('1cb34bc9-b586-4b25-aa6f-0ca7fcf4d4b3', 'Standing Single Chest Stretch (Against Wall)', 'Chest', 'Wall', '{"Chest"}'::text[], '{"Front Delts"}'::text[], 'Use this stretch to open up your chest area and enhance overall flexibility. Secondary activation of your shoulders provides additional muscle engagement. Performing this standing challenges your balance and core engagement. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '81201201', '81201201-Standing-Single-Chest-Stretch-against-Wall-(female.mp4', 'female', FALSE, '2025-12-03 23:26:38.992671+00', '1. Position yourself at the appropriate distance from a wall. 2. Stand tall with your feet firmly planted. 3. Move into the stretch position for Standing Single Chest Stretch Against Wall. 4. Ease into the stretch until you feel gentle tension (not pain). 5. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. 6. Switch sides and repeat for equal time.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, 'Standing', NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 34, 2, 6, FALSE, TRUE, 'chest_stretch', 'Standing Single Chest Stretch Against Wall', 'stretch_shoulder, stretch_back', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('1cc18ca3-7c21-40c0-b13f-fc9086697e93', 'High Pull (Smith Machine)', 'Shoulders', 'Smith Machine', '{"Shoulders"}'::text[], '{"Traps"}'::text[], 'This pulling exercise works your delts for improved shoulder strength and aesthetics. Machine exercises are great for isolating muscles and training to failure safely. Strong shoulders improve overhead strength and support nearly all upper body movements.', '93911201', '93911201-Smith-High-Pull-(male)_Shoulders_.mp4', 'male', FALSE, '2025-12-03 23:26:29.61214+00', '1. Set the Smith machine bar to the appropriate starting height for Smith High Pull. 2. Set up in the starting position for Smith High Pull. 3. Execute the movement with proper form, focusing on your delts. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 58, 7, 8, TRUE, TRUE, 'upright_row', 'Smith High Pull', 'High Pull', FALSE, 'smith_machine', FALSE, 3, 90, 4, 80, 75, 20, 88),
('1cc5a9b9-b6ae-410a-a017-3dc39ec1aaed', 'Seated Twist (Straight Arm)', 'Core', 'Bodyweight', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'Build rotational power and define your waistline with the Seated Twist (straight Arm). Secondary activation of your abs provides additional muscle engagement. Being seated provides stability, allowing you to focus on the working muscles. A strong core improves posture, protects your spine, and enhances all other lifts.', '6951201', '06951201-Seated-Twist-(straight-arm)_Waist.mp4', 'female', FALSE, '2025-12-03 23:26:36.848698+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Rotate your torso through the movement pattern for Seated Twist. 3. Control the rotation in both directions—avoid using momentum. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Seated', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 52, 5, 7, FALSE, TRUE, 'russian_twist', 'Seated Twist', 'bicep_curl, tricep_extension, hammer_curl', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('1cc69b66-6a2f-40cd-8f60-f644826b9654', 'Side Push Neck Stretch', 'Neck', 'Bodyweight', '{"Neck"}'::text[], '{"Traps"}'::text[], 'Designed to lengthen your neck, the Side Push Neck Stretch helps improve mobility and prevent stiffness. Include this in your routine for better mobility and reduced muscle tension.', '7161201', '07161201-Side-Push-Neck-Stretch_Neck_.mp4', 'male', FALSE, '2025-12-03 23:26:24.698781+00', '1. Move into the stretch position for Side Push Neck Stretch. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. 4. Switch sides and repeat for equal time.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'neck_stretch', 'Side Push Neck Stretch', 'stretch_hip, stretch_back', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('1cd5cf37-d93d-4949-8f1a-695142c82286', 'Incline Leg Hip Raise (leg Straight)', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build a stronger core with the Incline Leg Hip Raise (leg Straight), focusing on your abs. The incline angle shifts emphasis toward the upper portion of the target muscles. A strong core improves posture, protects your spine, and enhances all other lifts.', '27031201', '27031201-Incline-Leg-Hip-Raise-(leg-straight)-(female)_waist.mp4', 'female', FALSE, '2025-12-03 23:26:34.073704+00', '1. Set up in the starting position for Incline Leg Hip Raise. 2. Execute the movement with proper form, focusing on your abs. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 73, 5, 7, FALSE, TRUE, 'leg_exercise', 'Incline Leg Hip Raise', 'crunch, plank, russian_twist, hanging_knee_raise', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('1ce4570e-db2b-4d6c-ac1e-75a5e536402b', 'Pullover With Bench Press (Barbell)', 'Chest', 'Barbell, Flat Bench', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'This pressing exercise focuses on your pectorals for improved chest strength and development. Secondary activation of your triceps, front delts provides additional muscle engagement. Barbells enable bilateral loading for building raw strength. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '79331201', '79331201-Barbell-Pullover-with-Bench-Press-(male)_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:30.099411+00', '1. Load a barbell and set it on a bench rack at the appropriate height. 2. Lower the weight toward your chest with control. 3. Press the weight up until your arms are extended (don''t lock elbows). 4. Complete all reps with control before resting. Maintain consistent tempo throughout the set.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 8, NULL, TRUE, NULL, 'Strength', 97, 7, 9, TRUE, FALSE, 'bench_press', 'Pullover With Bench Press', 'incline_press, decline_press, chest_fly, push_up, dip', TRUE, 'barbell', FALSE, 4, 120, 4, 95, 80, 65, 95),
('1cef4b55-08ff-4280-8933-0ff19424f6c6', 'Roll Middle Back Lying On Floor', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build a stronger back with this movement movement targeting your core. Performing this lying down removes momentum for stricter form. No equipment needed—your body provides all the resistance. Back development is crucial for pulling strength and overall upper body function. Can be modified for beginners or progressed for advanced athletes.', '54211201', '54211201-Roll-Middle-Back-Lying-on-Floor-(female)_Back_.mp4', 'female', FALSE, '2025-12-03 23:26:36.38616+00', '1. Position yourself on the floor for Roll Middle Back Lying On Floor. 2. Lie down in the appropriate position for Roll Middle Back Lying On Floor. 3. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 45, 7, 8, TRUE, TRUE, 'back_exercise', 'Roll Middle Back Lying On Floor', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('1cfa6047-db82-4e3b-a1c5-8f2fdb1609d5', 'Mountain Climber (Against Wall)', 'Core', 'Wall', '{"Abs"}'::text[], '{"Hip Flexors","Shoulders"}'::text[], 'This cardio exercise keeps your heart rate elevated for improved cardiovascular fitness. Your hip flexors, shoulders work as secondary movers, adding to the training stimulus. Regular cardio training builds the aerobic base for better overall fitness.', '74451201', '74451201-Mountain-Climber-against-Wall-(male)_Cardio_.mp4', 'male', FALSE, '2025-12-03 23:26:28.52454+00', '1. Position yourself at the appropriate distance from a wall. 2. From plank position, drive one knee toward your chest. 3. Quickly switch legs, bringing the other knee forward. 4. Continue alternating at a quick pace while maintaining plank form. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 42, 9, 8, TRUE, TRUE, 'mountain_climber', 'Mountain Climber Against Wall', 'burpee, plank, high_knees', TRUE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('1d102f2e-53ad-49e6-8e74-36f95dc431bc', 'Standing Ab Twist', 'Core', 'Bodyweight', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'Work your side abdominals with this twisting exercise that strengthens your obliques. Secondary activation of your abs provides additional muscle engagement. Performing this standing challenges your balance and core engagement. A versatile bodyweight movement perfect for home or gym training. Core strength is foundational for athletic performance and injury prevention.', '50851201', '50851201-Standing-Ab-Twist-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:38.285955+00', '1. Stand with feet about shoulder-width apart. 2. Rotate your torso through the movement pattern for Standing Ab Twist. 3. Control the rotation in both directions—avoid using momentum. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 52, 5, 7, FALSE, TRUE, 'russian_twist', 'Standing Ab Twist', 'plank, crunch, leg_raise', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('1d1abf36-6f1e-4e25-a632-817b92b8f480', 'Assisted Lying Bent Knee Hip Adduction (Stability Ball)', 'Legs', 'Stability Ball', '{"Inner Thighs"}'::text[], '{}'::text[], 'The Assisted Lying Bent Knee Hip Adduction (stability Ball) is a lower body movement exercise that targets your adductors. Performing this lying down removes momentum for stricter form. Using a ball requires constant core engagement to maintain balance. Lower body strength improves everything from walking to heavy compound lifts.', '99741201', '99741201-Ball-Assisted-Lying-Bent-Knee-Hip-Adduction-(femal.mp4', 'female', FALSE, '2025-12-03 23:26:30.685158+00', '1. Position the stability ball as needed for Assisted Lying Bent Knee Hip Adduction. 2. Lie down in the appropriate position for Assisted Lying Bent Knee Hip Adduction. 3. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 32, 7, 8, TRUE, TRUE, 'hip_adduction', 'Assisted Lying Bent Knee Hip Adduction', 'hip_abduction, squat, lunge', FALSE, 'stability_ball', FALSE, 3, 90, 4, 70, 88, 95, 65),
('1d33d636-051f-4204-ba74-233f9e06a6f9', 'Seated Knee Slide', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'This stretch specifically works on your full body, promoting flexibility and reducing muscle tightness. The seated position helps isolate the target muscles by removing momentum. Flexibility work like this enhances performance and prevents stiffness.', '72901201', '72901201-Seated-Knee-Slide-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:36.717157+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Move into the stretch position for Seated Knee Slide. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'general_exercise', 'Seated Knee Slide', 'squat, leg_extension, lunge', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('1d4a767b-e436-49cf-bb79-a95dd53cc339', 'Push Up Pull', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'The Push Up Pull is a pulling exercise that targets your chest muscles. Secondary activation of your triceps, front delts provides additional muscle engagement. No equipment needed—your body provides all the resistance. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '65371201', '65371201-Push-up-Pull-(male)_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:26.39056+00', '1. Keep your body in a straight line from head to heels throughout. 2. Lower your chest toward the floor by bending your elbows. 3. Push through your palms to return to the starting position. 4. Repeat for the prescribed number of repetitions. Keep your shoulders relaxed and away from your ears.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'push_up', 'Push Up Pull', 'bench_press, chest_fly, dip', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('1d4b448a-f421-4634-83ec-4bf1e7ef4f92', 'Preacher Curl (Dumbbell)', 'Arms', 'Dumbbells, Preacher Bench', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'The Dumbbell Preacher Curl is a curling exercise that isolates your biceps. Your forearms work as secondary movers, adding to the training stimulus. The dumbbell variation provides freedom of movement and greater range of motion. Dedicated arm training builds both strength and muscular definition.', '3721201', '03721201-Dumbbell-Preacher-Curl_Upper-Arms.mp4', 'male', FALSE, '2025-12-03 23:26:21.249384+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Preacher Curl. 2. Keep your elbows in a fixed position throughout the movement. 3. Curl the weight up by contracting your biceps, squeezing at the top. 4. Lower with control, resisting the weight on the way down. 5. Repeat for the prescribed number of repetitions.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 92, 5, 7, FALSE, TRUE, 'preacher_curl', 'Preacher Curl', 'tricep_pushdown, tricep_extension, bicep_curl, hammer_curl', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('1d504f29-2354-494a-b64d-dc2fc0ae7192', 'Walking (Machine)', 'Legs', 'Machine', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Enhance your stamina and burn calories with this effective cardio movement. Machine exercises are great for isolating muscles and training to failure safely. Regular cardio training builds the aerobic base for better overall fitness.', '96871201', '96871201-Lever-Walking-(female)_Cardio_.mp4', 'female', FALSE, '2025-12-03 23:26:34.855778+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Walking. 2. Set up in the starting position for Lever Walking. 3. Execute the movement with proper form, focusing on your cardio. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 2, 2, NULL, 10, NULL, NULL, NULL, NULL, 1, 1, NULL, 3, NULL, FALSE, NULL, 'Cardio', 58, 9, 8, FALSE, TRUE, 'walking', 'Lever Walking', 'squat, bench_press, deadlift', FALSE, 'machine', TRUE, 1, 60, 4, 80, 75, 20, 88),
('1d507df8-11c5-4039-871b-dd945a950517', 'Quadruped Shoulder Cars', 'Shoulders', 'Bodyweight', '{"Shoulders"}'::text[], '{"Traps"}'::text[], 'The Quadruped Shoulder Cars provides a deep stretch for your shoulders, ideal for recovery and mobility work. You''ll also feel your upper back working to support the movement. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '82531201', '82531201-Quadruped-Shoulder-CARs-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:35.936279+00', '1. Move into the stretch position for Quadruped Shoulder Cars. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. Engage your stabilizer muscles for better control.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'bird_dog', 'Quadruped Shoulder Cars', 'lateral_raise, shoulder_press, front_raise', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('1d512c24-ac2a-44bc-8433-87e3800b4fca', 'Bridge (On Knees)', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Strengthen your midsection with this bridging movement that works your abs. You''ll also feel your hamstrings working to support the movement. This bodyweight exercise requires no equipment and can be done anywhere. A strong core improves posture, protects your spine, and enhances all other lifts.', '1421201', '01421201-Bridge-(on-knees)-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:31.723232+00', '1. Drive through your heels to lift your hips toward the ceiling. 2. Squeeze your glutes hard at the top of the movement. 3. Lower your hips back down with control. 4. Repeat for the prescribed number of repetitions. Maintain a neutral spine throughout. Great for building strength in your abs.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Bridge', 'hip_thrust, romanian_deadlift, leg_curl', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('1d52095c-0786-4bda-b54b-29f6020ab23b', 'Ab Twist Toe Tap', 'Core', 'Bodyweight', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'Work your side abdominals with this twisting exercise that strengthens your obliques. Your abs work as secondary movers, adding to the training stimulus. A versatile bodyweight movement perfect for home or gym training. A strong core improves posture, protects your spine, and enhances all other lifts.', '87861201', '87861201-Ab-Twist-Toe-Tap-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:27.504261+00', '1. Rotate your torso through the movement pattern for Ab Twist Toe Tap. 2. Control the rotation in both directions—avoid using momentum. 3. Complete all reps with control before resting. Focus on the mind-muscle connection.', 'Trunk Rotation + Hip Flexion (Toe Tap)', 'Static', 'Compound', 'Bilateral', NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 50, 5, 7, FALSE, TRUE, 'russian_twist', 'Ab Twist Toe Tap', 'high_knees, butt_kicks, jumping_jack', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('1d67434c-f62d-4955-81e5-0b0310927b36', 'Seated Calf Stretch', 'Legs', 'Bodyweight', '{"Calves"}'::text[], '{}'::text[], 'Build stronger calves with this targeted stretching exercise. The seated position helps isolate the target muscles by removing momentum. Lower body strength improves everything from walking to heavy compound lifts.', '43041201', '43041201-Seated-Calf-Stretch-(female)_Calves.mp4', 'female', FALSE, '2025-12-03 23:26:36.717157+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Set up in the starting position for Seated Calf Stretch. 3. Execute the movement with proper form, focusing on your calves. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout. Keep your shoulders relaxed and away from your ears.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, 'Seated', NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 42, 2, 6, FALSE, TRUE, 'calf_stretch', 'Seated Calf Stretch', 'stretch_hip, stretch_back', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('1d6b1586-d3e3-4d9b-ab44-0d5a70f9d61a', 'Standing Foot Muscles Activation', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Build leg strength with this movement movement focusing on your full body. Performing this standing challenges your balance and core engagement. This bodyweight exercise requires no equipment and can be done anywhere. Leg training boosts metabolism and builds functional, real-world strength.', '67751201', '67751201-Standing-Foot-Muscles-Activation-(female)_Feet_.mp4', 'female', FALSE, '2025-12-03 23:26:38.570929+00', '1. Begin in a standing position with good posture. 2. Set up in the starting position for Standing Foot Muscles Activation. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'dynamic_warmup', 'Standing Foot Muscles Activation', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('1d6b66d6-fb4b-46d7-8ddd-065483166225', 'Tight Rope Walk', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Tight Rope Walk is an explosive exercise that combines cardiovascular training with dynamic stepping movements. Plyometric training builds explosive power that transfers to sports and daily activities.', '59771201', '59771201-Tight-Rope-Walk-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:21.995567+00', '1. Set up in the starting position for Tight Rope Walk. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'walking', 'Tight Rope Walk', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('1d701afc-d5f1-4d8b-9b1f-15395197ffe8', 'Lunge (Dumbbell)', 'Legs', 'Dumbbells', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Target the front of your thighs with this lunging exercise for quad development. Your glutes, hamstrings work as secondary movers, adding to the training stimulus. Dumbbells allow each arm to work independently, helping correct imbalances. Strong legs are the foundation for athletic performance and functional fitness. Aim for full range of motion on every rep.', '3361201', '03361201-Dumbbell-Lunge_Hips-FIX3_.mp4', 'male', FALSE, '2025-12-03 23:26:23.466497+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Lunge. 2. Step forward into a lunge until both knees are at about 90 degrees. 3. Push through your front/working leg to return to the starting position. 4. Complete all reps with control before resting. Exhale during the exertion phase of the movement.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 82, 7, 8, TRUE, TRUE, 'lunge', 'Lunge', 'split_squat, step_up, squat', TRUE, 'dumbbell', FALSE, 3, 90, 4, 92, 90, 92, 90),
('1d72a88b-6b1f-48b4-831a-76837048b34f', 'Standing Romanian Deadlift', 'Legs', 'Bodyweight', '{"Hamstrings"}'::text[], '{"Glutes","Lower Back"}'::text[], 'Build leg strength with this hip hinge movement focusing on your hamstrings/glutes. Your glutes, lower back work as secondary movers, adding to the training stimulus. The standing position engages your core for stability. No equipment needed—your body provides all the resistance. Lower body strength improves everything from walking to heavy compound lifts.', '66511201', '66511201-Bodyweight-Standing-Romanian-Deadlift-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:26.507873+00', '1. Begin in a standing position with good posture. 2. Push your hips back, lowering the weight along your legs with a flat back. 3. Lower until you feel a stretch in your hamstrings. 4. Drive hips forward to stand, squeezing glutes at the top. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 87, 7, 8, TRUE, TRUE, 'romanian_deadlift', 'Standing Romanian Deadlift', 'deadlift, leg_curl, hip_thrust', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('1d7ae386-c7ff-4efd-87d0-ebb099ad327c', 'Quick Feet In Out Run', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{"Glutes","Hamstrings","Quads"}'::text[], 'The Quick Feet In Out Run is a cardiovascular exercise that improves endurance and heart health. Regular cardio training builds the aerobic base for better overall fitness.', '107471201', '107471201-Quick-Feet-In-Out-Run-(female)_Cardio_.mp4', 'female', FALSE, '2025-12-03 23:26:35.936279+00', '1. Set up in the starting position for Quick Feet In Out Run. 2. Execute the movement with proper form, focusing on your cardio. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Quick Feet In Out Run', 'cycling, rowing_cardio, jump_rope', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('1d950101-7493-44b9-9952-18341f78a615', 'Incline Shrug (Kettlebell)', 'Back', 'Kettlebell', '{"Traps"}'::text[], '{"Upper Back"}'::text[], 'The Kettlebell Incline Shrug is a shrugging exercise that develops back strength and muscle. Using an incline changes the angle of resistance for varied muscle recruitment. The kettlebell''s offset center of mass increases the stability challenge. Back development is crucial for pulling strength and overall upper body function.', '68251201', '68251201-Kettlebell-Incline-Shrug_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:28.079801+00', '1. Select an appropriately weighted kettlebell for Kettlebell Incline Shrug. 2. Shrug your shoulders straight up toward your ears. 3. Hold briefly at the top, then lower with control. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 81, 5, 7, FALSE, TRUE, 'shrug', 'Incline Shrug', 'deadlift, bent_over_row, face_pull', FALSE, 'kettlebell', FALSE, 3, 60, 2, 75, 88, 88, 78),
('1daa5f54-de51-4a68-acda-f99cdb5d5332', 'Elliptical Machine - Walking (Elliptical)', 'Legs', 'Elliptical', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This cardio exercise keeps your heart rate elevated for improved cardiovascular fitness. Machine exercises are great for isolating muscles and training to failure safely. Regular cardio training builds the aerobic base for better overall fitness.', '42591201', '42591201-Walking-on-Elliptical-Machine-(VERSION-7)-(female).mp4', 'female', FALSE, '2025-12-03 23:26:39.91585+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Walking On Elliptical Machine. 2. Set up in the starting position for Walking On Elliptical Machine. 3. Execute the movement with proper form, focusing on your cardio. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 2, 2, NULL, 10, NULL, NULL, NULL, NULL, 1, 1, NULL, 3, NULL, FALSE, NULL, 'Cardio', 58, 9, 8, FALSE, TRUE, 'elliptical', 'Walking On Elliptical', 'squat, bench_press, deadlift', FALSE, 'machine', TRUE, 1, 60, 4, 80, 75, 20, 88),
('1daa82d6-c634-4a75-bc14-531c915c86cf', 'Crab Walk', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Crab Walk is an explosive exercise that combines cardiovascular training with dynamic stepping movements. This bodyweight exercise requires no equipment and can be done anywhere. Plyometric training builds explosive power that transfers to sports and daily activities.', '75791201', '75791201-Crab-Walk-(VERSION-2)-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:27.384461+00', '1. Set up in the starting position for Crab Walk. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'walking', 'Crab Walk', 'plank, crunch, leg_raise', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('1dbb7ac5-aa6d-4598-8585-c0fd4c87cea8', 'Spine Rolling', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Spine Rolling is a core movement exercise that primarily targets your abs. This bodyweight exercise requires no equipment and can be done anywhere. A strong core improves posture, protects your spine, and enhances all other lifts.', '85261201', '85261201-Spine-Rolling-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:21.452942+00', '1. Set up in the starting position for Spine Rolling. 2. Execute the movement with proper form, focusing on your abs. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'cycling', 'Spine Rolling', 'running, elliptical, rowing_cardio', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('1dc20b00-18a8-4834-8b93-e7f197a19e9a', 'Lying Punches', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Shoulders"}'::text[], 'Target your chest with the Lying Punches, an effective movement movement for upper body strength. You''ll also feel your shoulders working to support the movement. The lying position provides back support and helps isolate the target muscles. A versatile bodyweight movement perfect for home or gym training. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '82901201', '82901201-Lying-Punches-(male)_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:26.808474+00', '1. Lie down in the appropriate position for Lying Punches. 2. Set up in the starting position for Lying Punches. 3. Execute the movement with proper form, focusing on your chest. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'boxing', 'Lying Punches', 'core_exercise, shoulder_exercise, burpee', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('1df00dc2-076a-40e1-b832-d617b633ccb9', 'Kneeling Leg Lift Crossover - Alternating', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Front Delts"}'::text[], 'The Kneeling Alternating Leg Lift Crossover is a lower body movement exercise that targets your chest. The front delts assist throughout the movement, making this a well-rounded exercise. Kneeling helps eliminate lower body momentum from the movement. No equipment needed—your body provides all the resistance. Lower body strength improves everything from walking to heavy compound lifts.', '97131201', '97131201-Kneeling-Alternating-Leg-Lift-Crossover-(female)_H.mp4', 'female', FALSE, '2025-12-03 23:26:34.322534+00', '1. Kneel on the floor (use a pad for comfort if needed). 2. Alternate between sides/arms/legs with each repetition. 3. Repeat for the prescribed number of repetitions. Keep tension on the target muscles throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'chest_fly', 'Kneeling Leg Lift Crossover - Alternating', 'bench_press, incline_press, push_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('1e2b16bb-68ed-4f3d-8449-04753afede2b', 'Single Leg Glute Bridge (Dumbbell)', 'Legs', 'Dumbbells', '{"Glutes"}'::text[], '{"Hamstrings"}'::text[], 'The Dumbbell Single Leg Glute Bridge is a hip-dominant bridging exercise that targets your glutes. Your hamstrings work as secondary movers, adding to the training stimulus. Dumbbells allow each arm to work independently, helping correct imbalances. Leg training boosts metabolism and builds functional, real-world strength.', '57551201', '57551201-Dumbbell-Single-Leg-Glute-Bridge-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:33.168801+00', '1. Select an appropriate weight dumbbell and hold it in one hand. 2. Drive through your heels to lift your hips toward the ceiling. 3. Squeeze your glutes hard at the top of the movement. 4. Lower your hips back down with control. 5. Complete all reps on one side, then switch to the other side. 6. Repeat for the prescribed number of repetitions. Start with lighter weight to perfect your form.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 77, 7, 8, TRUE, TRUE, 'glute_bridge', 'Single Leg Glute Bridge', 'hip_thrust, romanian_deadlift', FALSE, 'dumbbell', FALSE, 3, 90, 4, 92, 90, 92, 90),
('1e404bc9-2e36-4147-89bf-8c59137561b7', 'Criss Cross Jack', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{"Shoulders","Core"}'::text[], 'This dynamic movement movement gets your heart rate up while developing explosive strength. Secondary activation of your shoulders, core provides additional muscle engagement. A versatile bodyweight movement perfect for home or gym training. Plyometric training builds explosive power that transfers to sports and daily activities.', '47111201', '47111201-Criss-Cross-Jack_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:27.805708+00', '1. Set up in the starting position for Criss Cross Jack. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 50, 9, 8, TRUE, TRUE, 'boxing', 'Criss Cross Jack', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('1e52d429-4e3e-4959-8ef2-29eb30bd601e', 'Ring Weighted Pronated Grip Inverted Row (Gymnastic Rings)', 'Back', 'Gymnastic Rings', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'This rowing exercise strengthens the muscles between your shoulder blades. The biceps assist throughout the movement, making this a well-rounded exercise. Back development is crucial for pulling strength and overall upper body function.', '77721201', '77721201-Ring-Weighted-Pronated-Grip-Inverted-Row_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:24.831811+00', '1. Use an overhand (pronated) grip with palms facing down/away. 2. Pull the weight toward your torso, leading with your elbow(s). 3. Squeeze your shoulder blades together at the peak contraction. 4. Extend back out with control, feeling the stretch in your back. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 4, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 58, 7, 8, TRUE, TRUE, 'general_exercise', 'Ring Weighted Pronated Grip Inverted Row', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'gymnastic_rings', FALSE, 3, 90, 4, 68, 85, 85, 70),
('1e54d46e-9ec3-4c4a-980b-b40a143025ef', 'Ring Single Arm Pull Up (Gymnastic Rings)', 'Back', 'Gymnastic Rings', '{"Lats"}'::text[], '{"Biceps","Upper Back"}'::text[], 'The Ring One Arm Pull Up is a pulling exercise that targets your latissimus dorsi for a wider back. You''ll also feel your biceps, upper back working to support the movement. Back development is crucial for pulling strength and overall upper body function.', '75171201', '75171201-Ring-One-Arm-Pull-Up-(male)_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:20.392006+00', '1. Pull yourself up by driving your elbows down and back. 2. Continue until your chin clears the bar, then lower with control to a full hang. 3. Complete all reps on one side, then switch to the other side. 4. Repeat for the prescribed number of repetitions. Focus on squeezing the target muscle at peak contraction.', NULL, NULL, NULL, NULL, NULL, 5, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 5, 7, 8, TRUE, TRUE, 'pull_up', 'Ring Single Arm Pull Up', 'lat_pulldown, bent_over_row, bicep_curl', TRUE, 'gymnastic_rings', FALSE, 3, 90, 4, 68, 85, 85, 70),
('1e54e153-46a0-48f3-a47f-04b94b0b7a9a', 'Seated Inversion Foot (Resistance Band)', 'Core', 'Resistance Band', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Resistance Band Seated Inversion Foot is a lower body movement exercise that targets your core. Being seated provides stability, allowing you to focus on the working muscles. Resistance bands provide accommodating resistance that increases through the range of motion. Lower body strength improves everything from walking to heavy compound lifts.', '86121201', '86121201-Resistance-Band-Seated-Inversion-Foot-(male)_Calve.mp4', 'male', FALSE, '2025-12-03 23:26:24.698781+00', '1. Secure the resistance band appropriately for Resistance Band Seated Inversion Foot. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 57, 7, 8, TRUE, TRUE, 'general_exercise', 'Seated Inversion Foot', 'squat, bench_press, deadlift', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('1e5e78fd-33d9-4cc5-b2f0-b7d72b30d65d', 'External Shoulder Rotation Stretch', 'Shoulders', 'Bodyweight', '{"Rotator Cuff"}'::text[], '{"Shoulders"}'::text[], 'Target your shoulders with this rotation stretch that helps restore range of motion. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '19901201', '19901201-External-Shoulder-Rotation-Stretch-(female)_Should.mp4', 'female', FALSE, '2025-12-03 23:26:33.505723+00', '1. Rotate your torso through the movement pattern for External Shoulder Rotation Stretch. 2. Control the rotation in both directions—avoid using momentum. 3. Move into the stretch position for External Shoulder Rotation Stretch. 4. Ease into the stretch until you feel gentle tension (not pain). 5. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'stretch_general', 'External Shoulder Rotation Stretch', 'squat, bench_press, deadlift', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('1e63e85a-fc07-4473-a553-b4134b2d7ed5', 'Incline Chest Press (Machine)', 'Chest', 'Machine', '{"Chest"}'::text[], '{"Front Delts","Triceps"}'::text[], 'Target your chest with the Lever Stack Seated Incline Chest Press, an effective pressing movement for upper body strength. Your triceps, front delts work as secondary movers, adding to the training stimulus. The seated position helps isolate the target muscles by removing momentum. The fixed path allows you to focus purely on muscular effort. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '106691201', '106691201-Lever-Stack-Seated-Incline-Chest-Press-(male)_Che.mp4', 'male', FALSE, '2025-12-03 23:26:20.667107+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Stack Seated Incline Chest Press. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Lower the weight toward your chest with control. 4. Press the weight up until your arms are extended (don''t lock elbows). 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 83, 7, 8, TRUE, TRUE, 'incline_press', 'Lever Stack Seated Incline Chest Press', 'bench_press, shoulder_press, chest_fly', FALSE, 'machine', FALSE, 3, 90, 4, 80, 75, 20, 88),
('1e6f673e-3983-48a4-9b8c-c752e12ead28', 'Landmine Single Arm Bent Over Row (Landmine)', 'Back', 'Landmine Attachment, Barbell', '{"Back","Lats"}'::text[], '{"Biceps","Rear Delts"}'::text[], 'This rowing exercise strengthens the muscles between your shoulder blades. You''ll also feel your biceps, lats working to support the movement. The bent over position requires core engagement to maintain a neutral spine. Back development is crucial for pulling strength and overall upper body function.', '40381201', '40381201-Landmine-One-Arm-Bent-Over-Row_Back-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:25.123298+00', '1. Hinge at your hips, pushing them back while keeping your back flat. 2. Pull the weight toward your torso, leading with your elbow(s). 3. Squeeze your shoulder blades together at the peak contraction. 4. Extend back out with control, feeling the stretch in your back. 5. Complete all reps on one side, then switch to the other side. 6. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 4, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 8, NULL, TRUE, NULL, 'Strength', 65, 7, 9, TRUE, FALSE, 'bent_over_row', 'Landmine Single Arm Bent Over Row', 'cable_row, dumbbell_row, t_bar_row, lat_pulldown', FALSE, 'barbell', FALSE, 4, 120, 4, 95, 80, 65, 95),
('1e79afda-e9b5-4713-a247-1bf2b2530ff7', 'Pec Deck Fly (Machine)', 'Chest', 'Machine', '{"Chest"}'::text[], '{"Front Delts"}'::text[], 'Build a stronger chest with this flying movement that develops pressing power. The fixed path allows you to focus purely on muscular effort. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '24271201', '24271201-Lever-Pec-Deck-Fly-(female)_Chest.mp4', 'female', FALSE, '2025-12-03 23:26:34.724336+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Pec Deck Fly. 2. With a slight bend in your elbows, move the weight in a wide arc. 3. Squeeze your chest muscles at the center/top of the movement. 4. Return with control, feeling the stretch at the bottom. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, FALSE, NULL, 'Strength', 78, 5, 7, FALSE, TRUE, 'chest_fly', 'Lever Pec Deck Fly', 'bench_press, incline_press, push_up', FALSE, 'machine', FALSE, 3, 60, 2, 80, 75, 20, 88),
('1e8c498c-c417-4292-bec6-8e676a27d7d7', 'March Sit (Against Wall)', 'Legs', 'Wall', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build leg strength with this movement movement focusing on your full body. The hip flexors assist throughout the movement, making this a well-rounded exercise. Lower body strength improves everything from walking to heavy compound lifts.', '6241201', '06241201-March-Sit-(wall)_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:21.732034+00', '1. Position yourself at the appropriate distance from a wall. 2. Set up in the starting position for March Sit. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 42, 7, 8, TRUE, TRUE, 'marching', 'March Sit', 'high_knees, butt_kicks, jumping_jack', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('1eab908c-8c08-461e-9509-bb2de61cc1d4', 'Side Bend (Dumbbell)', 'Core', 'Dumbbells', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'Build a stronger core with the Dumbbell Side Bend, focusing on your abs. Secondary activation of your abs provides additional muscle engagement. Using dumbbells requires more stabilization than barbell variations. Building core stability helps with everything from heavy deadlifts to daily activities.', '25971201', '25971201-Dumbbell-Side-Bend-(female)_Waist.mp4', 'female', FALSE, '2025-12-03 23:26:33.168801+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Side Bend. 2. Set up in the starting position for Dumbbell Side Bend. 3. Execute the movement with proper form, focusing on your abs. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 62, 7, 8, TRUE, TRUE, 'side_bend', 'Side Bend', 'russian_twist, woodchop, oblique_crunch', TRUE, 'dumbbell', FALSE, 3, 90, 4, 92, 90, 92, 90),
('1eae0bac-9ea3-49d1-a3d2-24640b46d4dc', 'Split Squat (Dumbbell)', 'Legs', 'Dumbbells', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Dumbbell Split Squat is a squatting exercise that primarily loads your quadriceps. You''ll also feel your glutes, hamstrings working to support the movement. The dumbbell variation provides freedom of movement and greater range of motion. Lower body strength improves everything from walking to heavy compound lifts.', '29591201', '29591201-Dumbbell-Split-Squat-(female)_Thighs_.mp4', 'female', FALSE, '2025-12-03 23:26:33.168801+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Split Squat. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Repeat for the prescribed number of repetitions.', 'Squat', NULL, NULL, NULL, NULL, 2, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 9, NULL, TRUE, NULL, 'Strength', 97, 7, 9, TRUE, FALSE, 'split_squat', 'Split Squat', 'lunge, bulgarian_split_squat, squat', TRUE, 'dumbbell', FALSE, 4, 120, 5, 92, 90, 92, 90),
('1eb32386-bb61-47f8-bbd7-efb30f88d203', 'Single Arm Lateral Raise (Cable)', 'Shoulders', 'Cables', '{"Side Delts"}'::text[], '{"Traps"}'::text[], 'Target your lateral delts with the Cable One Arm Lateral Raise, an effective shoulder raising exercise. Cables provide constant tension throughout the full range of motion. Shoulder development enhances both performance and upper body aesthetics.', '22311201', '22311201-Cable-One-Arm-Lateral-Raise-(female)_Shoulders.mp4', 'female', FALSE, '2025-12-03 23:26:31.931873+00', '1. Adjust the cable machine to the correct height and attachment for Cable One Arm Lateral Raise. 2. Raise your arms out to the sides until parallel to the floor. 3. Lower with control, maintaining tension throughout. 4. Complete all reps on one side, then switch to the other side. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 85, 5, 7, FALSE, TRUE, 'lateral_raise', 'Single Arm Lateral Raise', 'shoulder_press, front_raise, rear_delt', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('1eb35c4a-6702-490c-8223-370e1aacbd69', 'Box Drop 2 Foot Land', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'This dynamic movement movement gets your heart rate up while developing explosive strength. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '90681201', '90681201-Box-Drop-2-Foot-Land-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:24.698781+00', '1. Set up a box or step platform at the appropriate height. 2. Set up in the starting position for Box Drop 2 Foot Land. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'box_jump', 'Box Drop 2 Foot Land', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('1ed77dfc-52be-45a3-bea2-27b466bea100', 'Overhead Bicep Curl - Single Arm (Band)', 'Arms', 'Resistance Band', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'Build bigger biceps with this curling movement that targets the front of your arms. Your forearms work as secondary movers, adding to the training stimulus. The band creates increasing tension as it stretches, challenging the lockout. Arm strength supports grip, pulling, and pushing in compound movements.', '9861201', '09861201-Band-One-Arm-Overhead-Biceps-Curl_Upper-Arms_.mp4', 'male', FALSE, '2025-12-03 23:26:23.172397+00', '1. Secure the resistance band appropriately for Band One Arm Overhead Biceps Curl. 2. Keep your elbows in a fixed position throughout the movement. 3. Curl the weight up by contracting your biceps, squeezing at the top. 4. Lower with control, resisting the weight on the way down. 5. Complete all reps on one side, then switch to the other side. 6. Continue for your target rep count, maintaining good form throughout.', 'Curl', 'Pull', 'Compound', 'Unilateral', NULL, 3, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 80, 5, 7, FALSE, TRUE, 'bicep_curl', 'Single Arm Overhead Bicep Curl', 'hammer_curl, preacher_curl, cable_curl', FALSE, 'band', FALSE, 3, 60, 2, 60, 85, 90, 50),
('1eea7c99-79f9-413e-b2a0-8703e60334e6', 'Leg Press (Plate Loaded Machine)', 'Legs', 'Machine', '{"Glutes"}'::text[], '{"Hamstrings"}'::text[], 'Develop your posterior chain with this pressing movement that emphasizes the glutes. Secondary activation of your glutes provides additional muscle engagement. Lower body strength improves everything from walking to heavy compound lifts.', '75931201', '75931201-Sled-Glute-Dominant-Leg-Press-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:20.667107+00', '1. Position your feet on the platform and release the safety. 2. Lower the weight by bending your knees, then press back up powerfully. 3. Continue for your target rep count, maintaining good form throughout. Exhale during the exertion phase of the movement.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 8, NULL, FALSE, NULL, 'Strength', 80, 7, 9, TRUE, FALSE, 'leg_press', 'Sled Glute Dominant Leg Press', 'squat, hack_squat, lunge', TRUE, 'machine', FALSE, 4, 120, 4, 80, 75, 20, 88),
('1eea9fd1-a2f9-40dd-8fae-e49d0f35e37f', 'Side Lying Clam And Kick', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build leg strength with this kicking movement focusing on your glute med/abductors. Performing this lying down removes momentum for stricter form. No equipment needed—your body provides all the resistance. Leg training boosts metabolism and builds functional, real-world strength.', '66521201', '66521201-Side-Lying-Clam-and-Kick-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:22.123147+00', '1. Lie on your side with your body aligned. 2. Set up in the starting position for Side Lying Clam And Kick. 3. Execute the movement with proper form, focusing on your glute med/abductors. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout. Start with lighter weight to perfect your form.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'hip_abduction', 'Side Lying Clam And Kick', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('1f11aea3-5d18-4912-8855-4896eaf9526c', 'Wide Hand Push Up', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'This pushing exercise focuses on your pectorals for improved chest strength and development. Your triceps, front delts work as secondary movers, adding to the training stimulus. No equipment needed—your body provides all the resistance. Chest strength improves pushing power for sports, daily tasks, and other lifts. A staple exercise that belongs in most training programs.', '13111201', '13111201-Wide-Hand-Push-up_Chest.mp4', 'male', FALSE, '2025-12-03 23:26:22.247914+00', '1. Keep your body in a straight line from head to heels throughout. 2. Lower your chest toward the floor by bending your elbows. 3. Push through your palms to return to the starting position. 4. Continue for your target rep count, maintaining good form throughout. Ensure full range of motion on each rep. Include this in your chest training.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'push_up', 'Wide Hand Push Up', 'bench_press, chest_fly, dip', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('1f15295e-e161-4780-ba57-bcef37229f6c', 'Preacher Hammer Curl (Dumbbell)', 'Arms', 'Dumbbells', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'This curling exercise focuses on your biceps for improved arm size and strength. The forearms assist throughout the movement, making this a well-rounded exercise. Using dumbbells requires more stabilization than barbell variations. Arm strength supports grip, pulling, and pushing in compound movements. Can be modified for beginners or progressed for advanced athletes.', '69981201', '69981201-Dumbbell-Peacher-Hammer-Curl-(female)_Forearms_.mp4', 'female', FALSE, '2025-12-03 23:26:33.034396+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Peacher Hammer Curl. 2. Use a hammer/neutral grip with palms facing each other throughout. 3. Keep your elbows in a fixed position throughout the movement. 4. Curl the weight up by contracting your biceps, squeezing at the top. 5. Lower with control, resisting the weight on the way down. 6. Complete all reps with control before resting. Start with lighter weight to perfect your form.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 92, 5, 7, FALSE, TRUE, 'hammer_curl', 'Peacher Hammer Curl', 'bicep_curl, preacher_curl', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('1f2e3bdb-6350-477e-943c-573048b2265b', 'Leg Raise Dragon Flag', 'Core', 'Bodyweight', '{"Lower Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Strengthen your midsection with this raising movement that works your abs. Secondary activation of your hip flexors provides additional muscle engagement. This bodyweight exercise requires no equipment and can be done anywhere. Building core stability helps with everything from heavy deadlifts to daily activities.', '107111201', '107111201-Leg-Raise-Dragon-Flag-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:34.603963+00', '1. Keeping legs mostly straight, raise them toward the ceiling. 2. Lower with control, stopping just before touching down. 3. Complete all reps with control before resting. Focus on squeezing the target muscle at peak contraction. Works well for abs activation.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 5, 5, 7, FALSE, TRUE, 'leg_raise', 'Leg Raise Dragon Flag', 'crunch, plank, v_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('1f364865-580b-496c-a266-f819bb5dd7bf', 'Dancer Bend', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Elevate your training with this movement exercise that develops speed, power, and coordination. A versatile bodyweight movement perfect for home or gym training. Great for improving athletic performance, burning calories, and building conditioning. Maintain proper breathing - exhale during the effort phase.', '63841201', '63841201-Dancer-Bend-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:32.501166+00', '1. Set up in the starting position for Dancer Bend. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Dancer Bend', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('1f47bc09-d066-4082-99ff-d80c6c959b17', 'Standing Front Backhand Tap And Behind Backhand Ta', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'The Standing Front Backhand Tap And Behind Backhand Ta is an explosive exercise that combines cardiovascular training with dynamic movement movements. The standing position engages your core for stability. A versatile bodyweight movement perfect for home or gym training. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '95411201', '95411201-Standing-Front-Backhand-Tap-And-Behind-Backhand-Ta.mp4', 'female', FALSE, '2025-12-03 23:26:38.570929+00', '1. Begin in a standing position with good posture. 2. Set up in the starting position for Standing Front Backhand Tap And Behind Backhand Ta. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'back_exercise', 'Standing Front Backhand Tap And Behind Backhand Ta', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('1f4b428c-7705-4a40-8e13-fec3ab235a86', 'Clean Grip Front Squat (Barbell)', 'Legs', 'Barbell', '{"Quads","Glutes","Core"}'::text[], '{}'::text[], 'Target the front of your thighs with this squatting exercise for quad development. The glutes, hamstrings assist throughout the movement, making this a well-rounded exercise. Using a barbell provides stability for progressive overload. Lower body strength improves everything from walking to heavy compound lifts. Perfect for including in both strength and hypertrophy programs.', '291201', '00291201-Barbell-Clean-grip-Front-Squat_Thighs-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:21.732034+00', '1. Set up a barbell in a rack at the appropriate height for Barbell Clean Grip Front Squat. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Continue for your target rep count, maintaining good form throughout.', 'Squat', 'Push', 'Compound', 'Bilateral', NULL, 4, NULL, 10, 10, NULL, 4, 'Standing', NULL, 'Overhand (Pronated)', 'Standard (Just outside shoulders)', 3, 6, NULL, 9, NULL, TRUE, NULL, 'Strength', 97, 7, 9, TRUE, FALSE, 'front_squat', 'Clean Grip Front Squat', 'squat, leg_press, leg_extension, goblet_squat', TRUE, 'barbell', FALSE, 4, 120, 6, 95, 80, 65, 95),
('1f661150-5581-4d54-bed6-3c8b000439fd', 'Half Squat Torso Punches', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This squatting exercise engages your abs for improved core stability and strength. Your glutes, hamstrings work as secondary movers, adding to the training stimulus. This bodyweight exercise requires no equipment and can be done anywhere. Building core stability helps with everything from heavy deadlifts to daily activities.', '59551201', '59551201-Half-Squat-Torso-Punches-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:33.960339+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. 4. Continue for your target rep count, maintaining good form throughout. Exhale during the exertion phase of the movement. Ideal for abs strength and endurance.', 'Squat', NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'squat', 'Half Squat Torso Punches', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('1f8b2078-b158-4ffa-884e-cf7256e2d7fb', 'Standing Side Crunch And Raise - Alternating', 'Core', 'Bodyweight', '{"Obliques"}'::text[], '{"Hip Flexors","Abs"}'::text[], 'Build power and athleticism with this high-intensity raising exercise that challenges your entire body. The abs assist throughout the movement, making this a well-rounded exercise. The standing position engages your core for stability. No equipment needed—your body provides all the resistance. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '89111201', '89111201-Standing-Alternate-Side-Crunch-and-Raise-(male)_Pl.mp4', 'male', FALSE, '2025-12-03 23:26:20.392006+00', '1. Stand with feet about shoulder-width apart. 2. Raise your arms out to the sides until parallel to the floor. 3. Lower with control, maintaining tension throughout. 4. Alternate between sides/arms/legs with each repetition. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 72, 5, 7, FALSE, TRUE, 'crunch', 'Standing Side Crunch And Raise - Alternating', 'leg_raise, plank, russian_twist, v_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('1f963f03-ddbd-4b7a-bc17-193aef056495', 'Crunch With Leg Lift', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Strengthen your midsection with this crunching movement that works your abs. You''ll also feel your hip flexors working to support the movement. A versatile bodyweight movement perfect for home or gym training. Building core stability helps with everything from heavy deadlifts to daily activities.', '40951201', '40951201-Crunch-with-Leg-Lift-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:24.203368+00', '1. Curl your shoulders off the floor by contracting your abs. 2. Don''t pull on your neck—focus on the abdominal contraction. 3. Lower with control, maintaining some tension. 4. Complete all reps with control before resting. Maintain a neutral spine throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'crunch', 'Crunch With Leg Lift', 'leg_raise, plank, russian_twist, v_up', TRUE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('1fa5d5ab-55ee-4be0-b57b-7aa1eaebfc90', 'Seated Row (Cable)', 'Back', 'Cables', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'This rowing exercise strengthens the muscles between your shoulder blades. Secondary activation of your biceps, lats provides additional muscle engagement. The seated position helps isolate the target muscles by removing momentum. The cable setup allows you to adjust the angle of resistance. Back development is crucial for pulling strength and overall upper body function.', '70801201', '70801201-Cable-Seated-Row-(female)_Back_.mp4', 'female', FALSE, '2025-12-03 23:26:32.054831+00', '1. Adjust the cable machine to the correct height and attachment for Cable Seated Row. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Pull the weight toward your torso, leading with your elbow(s). 4. Squeeze your shoulder blades together at the peak contraction. 5. Extend back out with control, feeling the stretch in your back. 6. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 8, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 92, 7, 8, TRUE, TRUE, 'cable_row', 'Seated Row', 'bent_over_row, lat_pulldown, face_pull', TRUE, 'cable', FALSE, 3, 90, 4, 85, 88, 30, 92),
('1fad2a60-062a-4b14-8bd4-0226f2b29158', 'Kneeling Hip Flexor Lift', 'Legs', 'Bodyweight', '{"Hip Flexors"}'::text[], '{}'::text[], 'Use this stretch to open up your hip flexors area and enhance overall flexibility. Kneeling helps eliminate lower body momentum from the movement. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '81471201', '81471201-Kneeling-Hip-Flexor-Lift-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:34.322534+00', '1. Kneel on the floor (use a pad for comfort if needed). 2. Move into the stretch position for Kneeling Hip Flexor Lift. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'hip_stretch', 'Kneeling Hip Flexor Lift', 'hip_thrust, lunge, squat', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('1fadb9d3-462d-4dda-b7bc-ced6018ba18a', 'Military Press (Plate Loaded Machine)', 'Shoulders', 'Machine', '{"Front Delts"}'::text[], '{"Side Delts","Triceps"}'::text[], 'This pressing exercise works your delts for improved shoulder strength and aesthetics. The triceps assist throughout the movement, making this a well-rounded exercise. The machine guides your movement path for safer, more controlled repetitions. Shoulder development enhances both performance and upper body aesthetics.', '31011201', '31011201-Lever-Military-Press-(plate-loaded)-(female)_shoulder.mp4', 'female', FALSE, '2025-12-03 23:26:34.724336+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Military Press. 2. Start with the weight at shoulder level. 3. Press directly overhead until your arms are fully extended. 4. Lower back to shoulder level with control. 5. Continue for your target rep count, maintaining good form throughout. Maintain consistent tempo throughout the set.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 8, NULL, FALSE, NULL, 'Strength', 93, 7, 9, TRUE, FALSE, 'shoulder_press', 'Lever Military Press', 'lateral_raise, front_raise, rear_delt', FALSE, 'machine', FALSE, 4, 120, 4, 80, 75, 20, 88),
('1fc122da-edab-4e63-aa12-24895132b01a', '45 Degree Side Bend', 'Core', 'Bodyweight', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'This movement exercise engages your abs for improved core stability and strength. The abs assist throughout the movement, making this a well-rounded exercise. This bodyweight exercise requires no equipment and can be done anywhere. A strong core improves posture, protects your spine, and enhances all other lifts.', '21201', '00021201-45-degree-Side-Bend_Waist-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:27.937212+00', '1. Set up in the starting position for 45 Degree Side Bend. 2. Execute the movement with proper form, focusing on your abs. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'side_bend', '45 Degree Side Bend', 'russian_twist, woodchop, oblique_crunch', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('1fcbf4fe-e57e-43e3-9b25-d651ea91b16a', 'Assisted Chin Up - Neutral Grip (Resistance Band)', 'Back', 'Resistance Band, Pull-Up Bar', '{"Lats"}'::text[], '{"Biceps","Upper Back"}'::text[], 'The Resistance Band Assisted Neutral Grip Chin Up is a movement exercise that targets your latissimus dorsi for a wider back. You''ll also feel your biceps working to support the movement. The band creates increasing tension as it stretches, challenging the lockout. A strong back improves posture, prevents injury, and balances pressing movements.', '81651201', '81651201-Resistance-Band-Assisted-Neutral-Grip-Chin-Up-(mal.mp4', 'male', FALSE, '2025-12-03 23:26:21.249384+00', '1. Secure the resistance band appropriately for Resistance Band Assisted Neutral Grip Chin Up. 2. Use a neutral grip with palms facing each other. 3. Pull yourself up, focusing on bicep and lat engagement. 4. Raise until chin is over the bar, lower with full control. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 75, 7, 8, TRUE, TRUE, 'pull_up', 'Assisted Chin Up - Neutral Grip', 'Assisted Chin Up - Neutral Grip', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('1fdba65a-22ce-4dcb-8ca8-438eb53ac19a', 'Weighted Pull Up (Pull-Up Bar)', 'Back', 'Pull-Up Bar', '{"Lats"}'::text[], '{"Biceps","Upper Back"}'::text[], 'This pulling exercise emphasizes your lats for improved back development. Secondary activation of your biceps, upper back provides additional muscle engagement. No equipment needed—your body provides all the resistance. Back development is crucial for pulling strength and overall upper body function.', '8411201', '08411201-Weighted-Pull-Up_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:24.831811+00', '1. Pull yourself up by driving your elbows down and back. 2. Continue until your chin clears the bar, then lower with control to a full hang. 3. Complete all reps with control before resting. Keep tension on the target muscles throughout. Perfect for targeting your lats.', NULL, NULL, NULL, NULL, NULL, 4, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'pull_up', 'Weighted Pull Up', 'lat_pulldown, bent_over_row, bicep_curl', TRUE, 'pull_up_bar', FALSE, 3, 90, 4, 70, 88, 95, 65),
('1fdc48a5-f9a7-4d58-b06d-a889fddd4f37', 'Seated Stepjack Front Raise (Chair)', 'Shoulders', 'Chair', '{"Front Delts"}'::text[], '{"Chest"}'::text[], 'A challenging plyometric exercise, the Seated Stepjack Front Raise On A Chair builds reactive power and improves conditioning. Being seated provides stability, allowing you to focus on the working muscles. Plyometric training builds explosive power that transfers to sports and daily activities.', '90811201', '90811201-Sitting-Stepjack-Front-Raise-on-a-Chair-(female)_P.mp4', 'female', FALSE, '2025-12-03 23:26:37.877283+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Set up a box or step platform at the appropriate height. 3. Sit with your back supported, core engaged, feet flat on the floor. 4. Raise the weight in front of you to shoulder height. 5. Lower with control, maintaining tension throughout. 6. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 55, 9, 8, TRUE, TRUE, 'front_raise', 'Seated Stepjack Front Raise On A Chair', 'shoulder_press, lateral_raise, rear_delt_fly', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('1fe006da-cdbe-4999-88a1-2efad0f6998b', 'Power Clean (Dumbbell)', 'Full Body', 'Dumbbells', '{"Full Body"}'::text[], '{"Quads","Glutes","Traps"}'::text[], 'The Dumbbell Power Clean is a compound movement exercise that engages your entire body. The quads, glutes, traps assist throughout the movement, making this a well-rounded exercise. Dumbbells allow each arm to work independently, helping correct imbalances. Full body exercises are time-efficient and build functional, real-world strength.', '48891201', '48891201-Dumbbell-Power-Clean_Weightlifting_.mp4', 'male', FALSE, '2025-12-03 23:26:29.36063+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Power Clean. 2. Explosively pull the weight upward from the starting position. 3. Pull yourself under the weight and catch it at shoulder level. 4. Stand to complete the lift, then lower with control. 5. Perform the concentric (lifting) phase explosively with maximum effort. 6. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 5, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 3, 6, NULL, 9, NULL, TRUE, NULL, 'Strength', 62, 7, 9, TRUE, FALSE, 'clean', 'Power Clean', 'clean, hang_clean, deadlift', TRUE, 'dumbbell', FALSE, 4, 120, 6, 92, 90, 92, 90),
('1feb4a17-8aab-47a4-8d29-18a95bc980d7', 'Rainbow Switching Toe Tap', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Build power and athleticism with this high-intensity movement exercise that challenges your entire body. This bodyweight exercise requires no equipment and can be done anywhere. Great for improving athletic performance, burning calories, and building conditioning. Control the negative portion for maximum muscle engagement.', '80281201', '80281201-Rainbow-Switching-Toe-Tap-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:29.083517+00', '1. Set up in the starting position for Rainbow Switching Toe Tap. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Rainbow Switching Toe Tap', 'high_knees, butt_kicks, jumping_jack', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('20095a73-b763-453d-ba38-fa647bb9507a', 'Rear Lunge (Smith Machine)', 'Legs', 'Smith Machine', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Target the front of your thighs with this lunging exercise for quad development. Secondary activation of your glutes, hamstrings provides additional muscle engagement. The machine guides your movement path for safer, more controlled repetitions. Strong legs are the foundation for athletic performance and functional fitness.', '58251201', '58251201-Smith-Rear-Lunge-(version-2)-(male)_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:28.71819+00', '1. Set the Smith machine bar to the appropriate starting height for Smith Rear Lunge. 2. Step forward into a lunge until both knees are at about 90 degrees. 3. Push through your front/working leg to return to the starting position. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 78, 7, 8, TRUE, TRUE, 'lunge', 'Smith Rear Lunge', 'Rear Lunge', FALSE, 'smith_machine', FALSE, 3, 90, 4, 80, 75, 20, 88),
('20176394-95d4-43d6-a4eb-393f49cef75b', 'Side Step Swing', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Elevate your training with this swinging exercise that develops speed, power, and coordination. Secondary activation of your quads provides additional muscle engagement. Great for improving athletic performance, burning calories, and building conditioning. A staple exercise that belongs in most training programs.', '57701201', '57701201-Side-Step-Swing-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:37.303932+00', '1. Set up a box or step platform at the appropriate height. 2. Hinge at your hips, letting the weight swing back between your legs. 3. Explosively drive hips forward, propelling the weight forward/up. 4. Let gravity bring it back as you hinge for the next rep. 5. Complete all reps with control before resting. Keep your shoulders relaxed and away from your ears.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Side Step Swing', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('20181a91-1b29-4b2f-a659-2f863254e9f2', 'Standing Calf Stretch (Against Wall)', 'Legs', 'Wall', '{"Calves"}'::text[], '{}'::text[], 'This stretch specifically works on your calves, promoting flexibility and reducing muscle tightness. Performing this standing challenges your balance and core engagement. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '84431201', '84431201-Standing-Calf-Stretch-against-Wall-(female)_Stretc.mp4', 'female', FALSE, '2025-12-03 23:26:38.570929+00', '1. Position yourself at the appropriate distance from a wall. 2. Stand with feet about shoulder-width apart. 3. Move into the stretch position for Standing Calf Stretch Against Wall. 4. Ease into the stretch until you feel gentle tension (not pain). 5. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, 'Standing', NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 34, 2, 6, FALSE, TRUE, 'calf_stretch', 'Standing Calf Stretch Against Wall', 'stretch_hip, stretch_back', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('201b918a-ff34-4cac-abe8-878634d30ff5', 'Seated Knee Raise Leg Raise (Chair)', 'Core', 'Chair', '{"Lower Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build a stronger core with the Seated Knee Raise Leg Raise On A Chair, focusing on your abs. You''ll also feel your hip flexors working to support the movement. Being seated provides stability, allowing you to focus on the working muscles. Building core stability helps with everything from heavy deadlifts to daily activities.', '83041201', '83041201-Seated-Knee-Raise-Leg-Raise-on-a-Chair-(male)_Wais.mp4', 'male', FALSE, '2025-12-03 23:26:29.36063+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Keeping legs mostly straight, raise them toward the ceiling. 4. Lower with control, stopping just before touching down. 5. Continue for your target rep count, maintaining good form throughout. Focus on the mind-muscle connection.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Seated', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 57, 5, 7, FALSE, TRUE, 'leg_raise', 'Seated Knee Raise Leg Raise On A Chair', 'crunch, plank, v_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('2020d0d2-1fae-44f3-b267-f02e3164feb4', 'Standing Ankle Dorsi Flexion (Against Wall)', 'Core', 'Wall', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Strengthen your midsection with this flexion movement that works your core. Performing this standing challenges your balance and core engagement. Building core stability helps with everything from heavy deadlifts to daily activities.', '100011201', '100011201-Standing-Ankle-Dorsi-Flexion-against-Wall-(female.mp4', 'female', FALSE, '2025-12-03 23:26:38.285955+00', '1. Position yourself at the appropriate distance from a wall. 2. Stand with feet about shoulder-width apart. 3. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 44, 7, 8, TRUE, TRUE, 'general_exercise', 'Standing Ankle Dorsi Flexion Against Wall', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('20264d42-8dcd-4278-a032-1b74b1dafa38', 'Hammer Grip Incline Bench Two Arm Row (Band)', 'Back', 'Resistance Band, Incline Bench, Anchor Point', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'This rowing exercise strengthens the muscles between your shoulder blades. The biceps, rear delts assist throughout the movement, making this a well-rounded exercise. The incline angle shifts emphasis toward the upper portion of the target muscles. The band creates increasing tension as it stretches, challenging the lockout. Back development is crucial for pulling strength and overall upper body function.', '68671201', '68671201-Band-Hammer-Grip-Incline-Bench-Two-Arm-Row_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:21.452942+00', '1. Secure the resistance band appropriately for Band Hammer Grip Incline Bench Two Arm Row. 2. Set the bench to an incline angle (30-45 degrees). 3. Use a hammer/neutral grip with palms facing each other throughout. 4. Pull the weight toward your torso, leading with your elbow(s). 5. Squeeze your shoulder blades together at the peak contraction. 6. Extend back out with control, feeling the stretch in your back. 7. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 78, 7, 8, TRUE, TRUE, 'incline_press', 'Hammer Grip Incline Bench Two Arm Row', 'bench_press, shoulder_press, chest_fly', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('2026fc86-2295-4cf0-8385-d0814ac3d9c9', 'Seated Row - Neutral Grip (Plate Loaded Machine)', 'Back', 'Machine', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'This rowing exercise strengthens the muscles between your shoulder blades. Secondary activation of your biceps, lats provides additional muscle engagement. Being seated provides stability, allowing you to focus on the working muscles. The machine guides your movement path for safer, more controlled repetitions. Back development is crucial for pulling strength and overall upper body function.', '5881201', '05881201-Lever-Neutral-Grip-Seated-Row-(plate-loaded)_Back-.mp4', 'male', FALSE, '2025-12-03 23:26:24.203368+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Neutral Grip Seated Row. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Use a neutral grip with palms facing each other. 4. Pull the weight toward your torso, leading with your elbow(s). 5. Squeeze your shoulder blades together at the peak contraction. 6. Extend back out with control, feeling the stretch in your back. 7. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 10, 10, NULL, 4, 'Seated', NULL, NULL, NULL, 5, 8, NULL, 8, NULL, FALSE, NULL, 'Strength', 90, 7, 9, TRUE, FALSE, 'cable_row', 'Lever Seated Row - Neutral Grip', 'Lever Seated Row - Neutral Grip', TRUE, 'machine', FALSE, 4, 120, 4, 80, 75, 20, 88),
('2032b260-27d3-472b-afbf-a38be3a5accc', 'V Up (Dumbbell)', 'Core', 'Dumbbells', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Dumbbell V Up is a core movement exercise that primarily targets your abs. You''ll also feel your hip flexors working to support the movement. Using dumbbells requires more stabilization than barbell variations. A strong core improves posture, protects your spine, and enhances all other lifts.', '42501201', '42501201-Dumbbell-V-up-(VERSION-2)_Waist.mp4', 'male', FALSE, '2025-12-03 23:26:24.203368+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell V Up. 2. Set up in the starting position for Dumbbell V Up. 3. Execute the movement with proper form, focusing on your abs. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 62, 7, 8, TRUE, TRUE, 'v_up', 'V Up', 'squat, bench_press, deadlift', TRUE, 'dumbbell', FALSE, 3, 90, 4, 92, 90, 92, 90),
('2038ebdd-d31d-49b4-bc0b-af0af78c8073', 'Narrow Lunge With (Wall Supported)', 'Legs', 'Wall', '{"Quads","Glutes","Hamstrings"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'This rowing movement emphasizes your quadriceps for stronger, more powerful legs. The glutes, hamstrings assist throughout the movement, making this a well-rounded exercise. Leg training boosts metabolism and builds functional, real-world strength.', '89881201', '89881201-Narrow-Lunge-with-Wall-Supported-(male)_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:29.837118+00', '1. Position yourself at the appropriate distance from a wall. 2. Use a close/narrow grip (hands closer than shoulder-width). 3. Pull the weight toward your torso, leading with your elbow(s). 4. Squeeze your shoulder blades together at the peak contraction. 5. Extend back out with control, feeling the stretch in your back. 6. Continue for your target rep count, maintaining good form throughout. Don''t rush—quality over quantity.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 62, 7, 8, TRUE, TRUE, 'lunge', 'Narrow Lunge With Wall Supported', 'split_squat, step_up, squat', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('204ebba4-0ae0-4611-af74-914e4e719409', 'Bicep Curl - Neutral Grip (Cable)', 'Arms', 'Cables', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'This curling exercise focuses on your biceps for improved arm size and strength. Your forearms work as secondary movers, adding to the training stimulus. Cables provide constant tension throughout the full range of motion. Dedicated arm training builds both strength and muscular definition.', '69911201', '69911201-Cable-Neutral-Grip-Biceps-Curl_Upper-Arms_.mp4', 'male', FALSE, '2025-12-03 23:26:20.847006+00', '1. Adjust the cable machine to the correct height and attachment for Cable Neutral Grip Biceps Curl. 2. Use a neutral grip with palms facing each other. 3. Keep your elbows in a fixed position throughout the movement. 4. Curl the weight up by contracting your biceps, squeezing at the top. 5. Lower with control, resisting the weight on the way down. 6. Complete all reps with control before resting.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 90, 5, 7, FALSE, TRUE, 'bicep_curl', 'Bicep Curl - Neutral Grip', 'Bicep Curl - Neutral Grip', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('204fb462-e547-4ad6-bf2b-510f61136a62', 'Deep Lunge Dorsi Flexion', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Designed to lengthen your quads, the Deep Lunge Dorsi Flexion helps improve mobility and prevent stiffness. You''ll also feel your glutes, hamstrings working to support the movement. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '83761201', '83761201-Deep-Lunge-Dorsi-Flexion-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:32.501166+00', '1. Step forward into a lunge until both knees are at about 90 degrees. 2. Push through your front/working leg to return to the starting position. 3. Move into the stretch position for Deep Lunge Dorsi Flexion. 4. Ease into the stretch until you feel gentle tension (not pain). 5. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'lunge', 'Deep Lunge Dorsi Flexion', 'split_squat, step_up, squat', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('20644cb5-b6cb-4a4e-8a7b-73780d340046', 'Stand Spread Leg Forward Fold', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This stretch specifically works on your hamstrings, promoting flexibility and reducing muscle tightness. Your lower back, calves work as secondary movers, adding to the training stimulus. Include this in your routine for better mobility and reduced muscle tension.', '9601201', '09601201-Stand-Spread-Leg-Forward-Fold-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:38.285955+00', '1. Move into the stretch position for Stand Spread Leg Forward Fold. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'hamstring_stretch', 'Stand Spread Leg Forward Fold', 'squat, lunge, leg_press', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('20781373-95a8-4e8f-ad44-69af13134886', 'Seated Pull Up (Pull-Up Bar)', 'Back', 'Pull-Up Bar', '{"Lats"}'::text[], '{"Biceps","Upper Back"}'::text[], 'The Seated Pull Up is a pulling exercise that targets your latissimus dorsi for a wider back. Your biceps, upper back work as secondary movers, adding to the training stimulus. Being seated provides stability, allowing you to focus on the working muscles. A strong back improves posture, prevents injury, and balances pressing movements.', '47851201', '47851201-Seated-Pull-up_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:29.61214+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Pull yourself up by driving your elbows down and back. 3. Continue until your chin clears the bar, then lower with control to a full hang. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 72, 7, 8, TRUE, TRUE, 'pull_up', 'Seated Pull Up', 'lat_pulldown, bent_over_row, bicep_curl', TRUE, 'pull_up_bar', FALSE, 3, 90, 4, 70, 88, 95, 65),
('2082f795-5817-4912-b9ee-6a6db6fb4a7d', 'Standing Archer Side Step', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build power and athleticism with this high-intensity stepping exercise that challenges your entire body. The quads assist throughout the movement, making this a well-rounded exercise. Performing this standing challenges your balance and core engagement. Plyometric training builds explosive power that transfers to sports and daily activities.', '85241201', '85241201-Standing-Archer-Side-Step-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:38.425788+00', '1. Set up a box or step platform at the appropriate height. 2. Stand with feet about shoulder-width apart. 3. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'general_exercise', 'Standing Archer Side Step', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('20966b3c-9ef4-431d-a5da-c9970c3dc8ef', 'Wide Push Up (Against Wall)', 'Chest', 'Wall', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'This pushing exercise focuses on your pectorals for improved chest strength and development. The triceps, front delts assist throughout the movement, making this a well-rounded exercise. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '27401201', '27401201-Wide-Push-up-(wall)-(female)_Chest_.mp4', 'female', FALSE, '2025-12-03 23:26:40.037451+00', '1. Position yourself at the appropriate distance from a wall. 2. Keep your body in a straight line from head to heels throughout. 3. Lower your chest toward the floor by bending your elbows. 4. Push through your palms to return to the starting position. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 62, 7, 8, TRUE, TRUE, 'push_up', 'Wide Push Up', 'bench_press, chest_fly, dip', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('20a9d302-b2f0-4796-81ee-266d88681f4e', 'Strict Curl (Barbell)', 'Arms', 'Barbell', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'This curling exercise focuses on your biceps for improved arm size and strength. Your forearms work as secondary movers, adding to the training stimulus. Using a barbell provides stability for progressive overload. Arm strength supports grip, pulling, and pushing in compound movements.', '56691201', '56691201-Barbell-Srtict-Curl_Upper-Arms_.mp4', 'male', FALSE, '2025-12-03 23:26:21.995567+00', '1. Grip a barbell with hands at the appropriate width for Barbell Strict Curl. 2. Keep your elbows in a fixed position throughout the movement. 3. Curl the weight up by contracting your biceps, squeezing at the top. 4. Lower with control, resisting the weight on the way down. 5. Complete all reps with control before resting.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 82, 5, 7, FALSE, TRUE, 'bicep_curl', 'Strict Curl', 'hammer_curl, preacher_curl, cable_curl', FALSE, 'barbell', FALSE, 3, 60, 2, 95, 80, 65, 95),
('20abe7c3-8571-4b76-902b-b119997526df', 'High Row - Overhand Grip (Band)', 'Back', 'Resistance Band, Anchor Point', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'The Band Narrow Grip High Row is a rowing exercise that builds thickness in your upper back. Secondary activation of your biceps, rear delts provides additional muscle engagement. Bands are joint-friendly and portable, perfect for any training environment. A strong back improves posture, prevents injury, and balances pressing movements.', '41481201', '41481201-Band-Narrow-Grip-High-Row-(VERSION-2)_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:27.263406+00', '1. Secure the resistance band appropriately for Band Narrow Grip High Row. 2. Use a close/narrow grip (hands closer than shoulder-width). 3. Pull the weight toward your torso, leading with your elbow(s). 4. Squeeze your shoulder blades together at the peak contraction. 5. Extend back out with control, feeling the stretch in your back. 6. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 75, 7, 8, TRUE, TRUE, 'close_grip_bench', 'High Row - Narrow Grip', 'High Row - Narrow Grip', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50);
INSERT INTO _exercise_staging (id, name, category, equipment, primary_muscles, secondary_muscles, description, video_code, video_filename, gender, is_custom, created_at, steps_to_perform, movement_pattern, force_type, movement_type, laterality, plane_of_motion, difficulty_level, complexity_score, strength_rating, hypertrophy_rating, power_rating, endurance_rating, body_position, bench_angle, grip_type, grip_width, optimal_rep_range_min, optimal_rep_range_max, placement_in_workout, fatigability, popularity_score, home_gym_friendly, instructions, workout_type, practicality_score, fat_loss_rating, general_fitness_rating, is_compound, supersetable, exercise_family, base_exercise_name, complementary_families, is_equipment_primary, equipment_category, duration_based, recommended_sets, rest_seconds, muscles_worked_count, priority_build_muscle, priority_get_lean, priority_home, priority_gym) VALUES
('20bdd5aa-dc69-43a6-aa8e-945f9bd16a70', 'Lying Hip Straight Leg Raise', 'Core', 'Bodyweight', '{"Lower Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build leg strength with this raising movement focusing on your abs. Secondary activation of your hip flexors provides additional muscle engagement. The lying position provides back support and helps isolate the target muscles. No equipment needed—your body provides all the resistance. Leg training boosts metabolism and builds functional, real-world strength.', '6191201', '06191201-Lying-Hip-Straight-Leg-Raise-(female)_Hips.mp4', 'female', FALSE, '2025-12-03 23:26:35.250398+00', '1. Lie down in the appropriate position for Lying Hip Straight Leg Raise. 2. Keeping legs mostly straight, raise them toward the ceiling. 3. Lower with control, stopping just before touching down. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'romanian_deadlift', 'Lying Hip Straight Leg Raise', 'deadlift, leg_curl, hip_thrust', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('20c2ae7e-3772-477d-825f-52040237e3a8', 'Side Bend Arm Tuck', 'Core', 'Bodyweight', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'This dynamic movement movement gets your heart rate up while developing explosive strength. The abs assist throughout the movement, making this a well-rounded exercise. No equipment needed—your body provides all the resistance. Plyometric training builds explosive power that transfers to sports and daily activities.', '73561201', '73561201-Side-Bend-Arm-Tuck-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:36.985772+00', '1. Set up in the starting position for Side Bend Arm Tuck. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'side_bend', 'Side Bend Arm Tuck', 'russian_twist, woodchop, oblique_crunch', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('20c5cbee-a7b0-434f-8085-45182eceee74', 'Side Lying Single Leg Kick', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Target the front of your thighs with this kicking exercise for quad development. Secondary activation of your hip flexors provides additional muscle engagement. Performing this lying down removes momentum for stricter form. This bodyweight exercise requires no equipment and can be done anywhere. Leg training boosts metabolism and builds functional, real-world strength.', '87531201', '87531201-Side-Lying-Single-Leg-Kick-female)_Thighs_.mp4', 'female', FALSE, '2025-12-03 23:26:37.179953+00', '1. Lie on your side with your body aligned. 2. Complete all reps on one side, then switch to the other side. 3. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 45, 7, 8, TRUE, TRUE, 'leg_exercise', 'Side Lying Single Leg Kick Female)', 'hip_flexor, lunge, dynamic_warmup', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('20d2f8bf-0154-417c-8eab-623ff2c18e1b', 'Decline Sit Up (Dumbbell)', 'Core', 'Dumbbells, Decline Bench', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'This movement exercise engages your abs for improved core stability and strength. Your hip flexors work as secondary movers, adding to the training stimulus. Declining shifts the emphasis to hit the muscles from a different angle. Using dumbbells requires more stabilization than barbell variations. Core strength is foundational for athletic performance and injury prevention.', '47351201', '47351201-Dumbbell-Decline-Sit-up_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:27.384461+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Decline Sit Up. 2. Set up in the starting position for Dumbbell Decline Sit Up. 3. Execute the movement with proper form, focusing on your abs. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', 'Sit Up', NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 85, 5, 7, FALSE, TRUE, 'crunch', 'Decline Sit Up', 'leg_raise, plank, russian_twist, v_up', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('20d6fd1e-6f90-4a1a-a827-b32f12c83b28', 'Weighted Seated Tuck Crunch On Floor', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Weighted Seated Tuck Crunch On Floor is a core crunching exercise that primarily targets your abs. The hip flexors assist throughout the movement, making this a well-rounded exercise. Being seated provides stability, allowing you to focus on the working muscles. A strong core improves posture, protects your spine, and enhances all other lifts.', '46231201', '46231201-Weighted-Seated-Tuck-Crunch-on-Floor_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:27.937212+00', '1. Position yourself on the floor for Weighted Seated Tuck Crunch On Floor. 2. Sit on the floor with your legs positioned as required. 3. Curl your shoulders off the floor by contracting your abs. 4. Don''t pull on your neck—focus on the abdominal contraction. 5. Lower with control, maintaining some tension. 6. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, 'Seated', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 67, 5, 7, FALSE, TRUE, 'crunch', 'Weighted Seated Tuck Crunch On Floor', 'leg_raise, plank, russian_twist, v_up', TRUE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('20dc7db1-2c4c-469c-a318-a5c0f2214acf', 'Side Floor Tap Plank', 'Core', 'Bodyweight', '{"Core","Abs"}'::text[], '{"Shoulders"}'::text[], 'This stabilization exercise engages your abs for improved core stability and strength. The shoulders, lower back assist throughout the movement, making this a well-rounded exercise. A versatile bodyweight movement perfect for home or gym training. A strong core improves posture, protects your spine, and enhances all other lifts. This is a great exercise for all fitness levels with proper scaling.', '83991201', '83991201-Side-Floor-Tap-Plank-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:22.536005+00', '1. Position yourself on the floor for Side Floor Tap Plank. 2. Hold your body in a straight line from head to heels. 3. Don''t let your hips sag or pike up—engage your core and glutes. 4. Breathe steadily while maintaining the position. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 65, 7, 8, TRUE, TRUE, 'plank', 'Side Floor Tap Plank', 'side_plank, dead_bug, hollow_hold', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('20dfa375-d95d-4305-b285-a58177bf8155', 'Prone Thoracic Rotation', 'Back', 'Bodyweight', '{"Upper Back"}'::text[], '{"Obliques"}'::text[], 'The Prone Thoracic Rotation provides a deep stretch for your thoracic spine, ideal for recovery and mobility work. The shoulders assist throughout the movement, making this a well-rounded exercise. Performing this lying down removes momentum for stricter form. Flexibility work like this enhances performance and prevents stiffness.', '79111201', '79111201-Prone-Thoracic-Rotation-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:35.801913+00', '1. Lie face down (prone position) for Prone Thoracic Rotation. 2. Rotate your torso through the movement pattern for Prone Thoracic Rotation. 3. Control the rotation in both directions—avoid using momentum.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'spinal_stretch', 'Prone Thoracic Rotation', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('20f604d2-0d9d-415d-9181-4a37d2c6c381', 'Assisted Weighted Push Up', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'Build a stronger chest with this pushing movement that develops pressing power. Your triceps, front delts work as secondary movers, adding to the training stimulus. This bodyweight exercise requires no equipment and can be done anywhere. A well-developed chest contributes to upper body strength and aesthetics. Control the negative portion for maximum muscle engagement.', '11721201', '11721201-Assisted-Weighted-Push-up_Chest.mp4', 'male', FALSE, '2025-12-03 23:26:23.79417+00', '1. Keep your body in a straight line from head to heels throughout. 2. Lower your chest toward the floor by bending your elbows. 3. Push through your palms to return to the starting position. 4. Complete all reps with control before resting. Focus on the mind-muscle connection. Ideal for chest strength and endurance.', NULL, NULL, NULL, NULL, NULL, 4, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'push_up', 'Assisted Weighted Push Up', 'bench_press, chest_fly, dip', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('20fac688-b445-4c87-8812-f79c3b8d15d4', 'Single Arm Bent Over Row (Dumbbell)', 'Back', 'Dumbbells', '{"Back","Lats"}'::text[], '{"Biceps","Rear Delts"}'::text[], 'Target your delts with the Dumbbell One Arm Bent Over Row, an effective shoulder rowing exercise. The biceps, lats assist throughout the movement, making this a well-rounded exercise. The bent over position requires core engagement to maintain a neutral spine. Using dumbbells requires more stabilization than barbell variations. Shoulder development enhances both performance and upper body aesthetics.', '23931201', '23931201-Dumbbell-One-Arm-Bent-over-Row-(female)_Shoulders.mp4', 'female', FALSE, '2025-12-03 23:26:32.914483+00', '1. Select an appropriate weight dumbbell and hold it in one hand. 2. Hinge at your hips, pushing them back while keeping your back flat. 3. Pull the weight toward your torso, leading with your elbow(s). 4. Squeeze your shoulder blades together at the peak contraction. 5. Extend back out with control, feeling the stretch in your back. 6. Complete all reps on one side, then switch to the other side. 7. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 8, NULL, TRUE, NULL, 'Strength', 77, 7, 9, TRUE, FALSE, 'bent_over_row', 'Single Arm Bent Over Row', 'cable_row, dumbbell_row, t_bar_row, lat_pulldown', TRUE, 'dumbbell', FALSE, 4, 120, 4, 92, 90, 92, 90),
('210f1171-1955-421d-9b8f-b5fcd204b6e7', 'Single Leg Stretch (Bent Knee)', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This stretch specifically works on your full body, promoting flexibility and reducing muscle tightness. Regular stretching improves flexibility, reduces injury risk, and aids recovery. Quality repetitions are more important than quantity.', '43091201', '43091201-Single-Leg-Stretch-(bent-knee)-(male)_Pilates-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:24.422129+00', '1. Move into the stretch position for Single Leg Stretch. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. 4. Switch sides and repeat for equal time. 5. Complete all reps on one side, then switch to the other side. Engage your stabilizer muscles for better control. This exercise is excellent for full body development.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 35, 2, 6, FALSE, TRUE, 'stretch_general', 'Single Leg Stretch', 'stretch_hip, stretch_back, stretch_shoulder', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('211eb982-8d92-4537-bb74-27eed45eeda7', 'Front Plank With Arm And Leg Lift', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Shoulders","Lower Back"}'::text[], 'The Front Plank With Arm And Leg Lift is a core stabilization exercise that primarily targets your abs. Secondary activation of your shoulders, lower back provides additional muscle engagement. This bodyweight exercise requires no equipment and can be done anywhere. A strong core improves posture, protects your spine, and enhances all other lifts.', '28961201', '28961201-Front-Plank-with-Arm-and-Leg-Lift-(female)_Waist-F.mp4', 'female', FALSE, '2025-12-03 23:26:33.640031+00', '1. Hold your body in a straight line from head to heels. 2. Don''t let your hips sag or pike up—engage your core and glutes. 3. Breathe steadily while maintaining the position. 4. Complete all reps with control before resting. Don''t rush—quality over quantity. A solid choice for core day.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'plank', 'Front Plank With Arm And Leg Lift', 'side_plank, dead_bug, hollow_hold', TRUE, 'bodyweight', TRUE, 3, 90, 4, 70, 88, 95, 65),
('2124e93f-fe67-434a-be1d-b94b1bab423b', 'Pin Chest Press (Barbell)', 'Chest', 'Barbell', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'Target your chest with the Barbell Pin Chest Press, an effective pressing movement for upper body strength. Secondary activation of your triceps, front delts provides additional muscle engagement. Barbells enable bilateral loading for building raw strength. A well-developed chest contributes to upper body strength and aesthetics.', '56601201', '56601201-Barbell-Pin-Chest-Press_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:20.847006+00', '1. Grip a barbell with hands at the appropriate width for Barbell Pin Chest Press. 2. Lower the weight toward your chest with control. 3. Press the weight up until your arms are extended (don''t lock elbows). 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 82, 7, 8, TRUE, TRUE, 'bench_press', 'Pin Chest Press', 'incline_press, decline_press, chest_fly, push_up, dip', TRUE, 'barbell', FALSE, 3, 90, 4, 95, 80, 65, 95),
('21265dc3-28e9-4f0c-9596-2b885457b095', 'Seated Leg Extension - Thigh Constraint (Machine)', 'Legs', 'Machine', '{"Quads"}'::text[], '{}'::text[], 'The Lever Seated Leg Extension is a extension exercise that primarily loads your quadriceps. Being seated provides stability, allowing you to focus on the working muscles. The machine guides your movement path for safer, more controlled repetitions. Lower body strength improves everything from walking to heavy compound lifts.', '71081201', '71081201-Lever-Seated-Leg-Extension-(VERSION-2)_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:29.971345+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Seated Leg Extension. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Extend your legs until straight, squeezing your quads at the top. 4. Lower with control back to the starting position. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 5, 7, NULL, 6, 'Seated', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, FALSE, NULL, 'Strength', 90, 5, 7, FALSE, TRUE, 'leg_extension', 'Lever Seated Leg Extension', 'squat, leg_press, lunge', TRUE, 'machine', FALSE, 3, 60, 2, 80, 75, 20, 88),
('2132d0aa-7971-439e-a34f-092b33454939', 'Wide Bench Press (Barbell)', 'Chest', 'Barbell, Flat Bench', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'The Barbell Wide Bench Press is a pressing exercise that targets your chest muscles. You''ll also feel your triceps, front delts working to support the movement. The barbell allows you to handle heavier loads for maximum strength gains. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '70691201', '70691201-Barbell-Wide-Bench-Press-(female)_Chest_.mp4', 'female', FALSE, '2025-12-03 23:26:31.133197+00', '1. Load a barbell and set it on a bench rack at the appropriate height. 2. Use a wide grip (wider than shoulder-width) for this variation. 3. Lower the weight toward your chest with control. 4. Press the weight up until your arms are extended (don''t lock elbows). 5. Repeat for the prescribed number of repetitions. Start with lighter weight to perfect your form.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 8, NULL, TRUE, NULL, 'Strength', 97, 7, 9, TRUE, FALSE, 'bench_press', 'Wide Bench Press', 'incline_press, decline_press, chest_fly, push_up, dip', TRUE, 'barbell', FALSE, 4, 120, 4, 95, 80, 65, 95),
('21363fe0-e60d-4ae6-966d-36ec7914c461', 'Hip Thrust (Resistance Band)', 'Legs', 'Resistance Band', '{"Glutes"}'::text[], '{"Hamstrings","Core"}'::text[], 'Build stronger glutes with this thrusting movement focused on hip extension. You''ll also feel your hamstrings working to support the movement. Bands are joint-friendly and portable, perfect for any training environment. Lower body strength improves everything from walking to heavy compound lifts.', '76831201', '76831201-Resistance-Band-Hip-Thrust-(VERSION-2)-(female)_Hi.mp4', 'female', FALSE, '2025-12-03 23:26:36.128549+00', '1. Secure the resistance band appropriately for Resistance Band Hip Thrust. 2. Drive through your heels to lift your hips toward the ceiling. 3. Squeeze your glutes hard at the top of the movement. 4. Lower your hips back down with control. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 75, 7, 8, TRUE, TRUE, 'hip_thrust', 'Hip Thrust', 'glute_bridge, romanian_deadlift, leg_curl', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('2137da36-03fb-4309-a12e-a0763fb92487', 'Curl Press Extension (Barbell)', 'Arms', 'Barbell', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'Build stronger triceps with this pressing exercise for bigger arms. Secondary activation of your forearms provides additional muscle engagement. The barbell allows you to handle heavier loads for maximum strength gains. Dedicated arm training builds both strength and muscular definition.', '58831201', '58831201-Barbell-Curl-Press-Extension-(male)_Upper-Arms_.mp4', 'male', FALSE, '2025-12-03 23:26:28.52454+00', '1. Grip a barbell with hands at the appropriate width for Barbell Curl Press Extension. 2. Execute the pressing motion for Barbell Curl Press Extension, extending through the target muscles. 3. Continue for your target rep count, maintaining good form throughout.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 82, 5, 7, FALSE, TRUE, 'general_exercise', 'Curl Press Extension', 'tricep_pushdown, tricep_extension, hammer_curl, preacher_curl', FALSE, 'barbell', FALSE, 3, 60, 2, 95, 80, 65, 95),
('213bb8b9-edf6-48f3-9061-a9df782059fd', 'Standing Military Press (Barbell)', 'Shoulders', 'Barbell', '{"Front Delts"}'::text[], '{"Side Delts","Triceps"}'::text[], 'This pressing exercise works your delts for improved shoulder strength and aesthetics. Secondary activation of your triceps provides additional muscle engagement. Performing this standing challenges your balance and core engagement. Using a barbell provides stability for progressive overload. Strong shoulders improve overhead strength and support nearly all upper body movements.', '11621201', '11621201-Barbell-Standing-Military-Press_Shoulders-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:23.987963+00', '1. Grip a barbell with hands at the appropriate width for Barbell Standing Military Press. 2. Stand with feet about shoulder-width apart. 3. Start with the weight at shoulder level. 4. Press directly overhead until your arms are fully extended. 5. Lower back to shoulder level with control. 6. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 10, 10, NULL, 4, 'Standing', NULL, NULL, NULL, 5, 8, NULL, 8, NULL, TRUE, NULL, 'Strength', 99, 7, 9, TRUE, FALSE, 'shoulder_press', 'Standing Military Press', 'lateral_raise, front_raise, rear_delt', TRUE, 'barbell', FALSE, 4, 120, 4, 95, 80, 65, 95),
('213d5bda-b8db-4f1e-b11c-a4ed81f3e348', 'Double Heel Lift Sit (Against Wall)', 'Legs', 'Wall', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build stronger calves with this targeted movement exercise. Leg training boosts metabolism and builds functional, real-world strength.', '87681201', '87681201-Double-Heel-Lift-Sit-agains-Wall-(female)_Calves_.mp4', 'female', FALSE, '2025-12-03 23:26:32.624497+00', '1. Position yourself at the appropriate distance from a wall. 2. Set up in the starting position for Double Heel Lift Sit Against Wall. 3. Execute the movement with proper form, focusing on your calves. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 42, 7, 8, TRUE, TRUE, 'general_exercise', 'Double Heel Lift Sit Against Wall', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('213f661c-1725-4375-8d23-4143363193ab', 'Knee Raise Side Reach', 'Core', 'Bodyweight', '{"Lower Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build power and athleticism with this high-intensity raising exercise that challenges your entire body. You''ll also feel your hip flexors working to support the movement. No equipment needed—your body provides all the resistance. Plyometric training builds explosive power that transfers to sports and daily activities.', '97851201', '97851201-Knee-Raise-Side-Reach-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:34.322534+00', '1. Raise your arms out to the sides until parallel to the floor. 2. Lower with control, maintaining tension throughout. 3. Complete all reps with control before resting. Focus on squeezing the target muscle at peak contraction. Great for building strength in your full body.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'leg_raise', 'Knee Raise Side Reach', 'crunch, plank, v_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('21411675-1b5f-4923-a3c6-97971e2e816f', 'Box Jump', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Calves"}'::text[], 'The Jump Box is an explosive exercise that combines cardiovascular training with dynamic jumping movements. Secondary activation of your quads, calves provides additional muscle engagement. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '71591201', '71591201-Jump-Box-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:34.196858+00', '1. Set up a box or step platform at the appropriate height. 2. Set up in the starting position for Jump Box. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions. Keep tension on the target muscles throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 50, 9, 8, TRUE, TRUE, 'general_exercise', 'Jump Box', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('216b64e3-69ae-4f5f-ba26-549fa244f9da', 'Shrug (Smith Machine)', 'Back', 'Smith Machine', '{"Traps"}'::text[], '{"Upper Back"}'::text[], 'Build a stronger back with this shrugging movement targeting your traps. Machine exercises are great for isolating muscles and training to failure safely. A strong back improves posture, prevents injury, and balances pressing movements.', '70501201', '70501201-Smith-Shrug-(female)_Back_.mp4', 'female', FALSE, '2025-12-03 23:26:38.153182+00', '1. Set the Smith machine bar to the appropriate starting height for Smith Shrug. 2. Shrug your shoulders straight up toward your ears. 3. Hold briefly at the top, then lower with control. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, FALSE, NULL, 'Strength', 78, 5, 7, FALSE, TRUE, 'shrug', 'Smith Shrug', 'Shrug', FALSE, 'smith_machine', FALSE, 3, 60, 2, 80, 75, 20, 88),
('21701fee-ecc0-45a6-ac12-9d145957e98e', 'Standing Pulsing Elbow Lift', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{}'::text[], 'Build a stronger chest with this movement movement that develops pressing power. The standing position engages your core for stability. No equipment needed—your body provides all the resistance. A well-developed chest contributes to upper body strength and aesthetics.', '94301201', '94301201-Standing-Pulsing-Elbow-Lift-(female)_Chest_.mp4', 'female', FALSE, '2025-12-03 23:26:38.870314+00', '1. Stand with feet about shoulder-width apart. 2. Set up in the starting position for Standing Pulsing Elbow Lift. 3. Execute the movement with proper form, focusing on your chest. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'pulse', 'Standing Pulsing Elbow Lift', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('217dbc33-f8ad-4c94-8d8c-f6256c5700ce', 'Concentration Extension - On Knee (Cable)', 'Arms', 'Cables', '{"Triceps"}'::text[], '{"Chest","Shoulders"}'::text[], 'The Cable Concentration Extension (on Knee) targets your triceps through a extension motion. Cables provide constant tension throughout the full range of motion. Dedicated arm training builds both strength and muscular definition.', '30431201', '30431201-Cable-Concentration-Extension-(on-knee)-(female)_U.mp4', 'female', FALSE, '2025-12-03 23:26:31.723232+00', '1. Adjust the cable machine to the correct height and attachment for Cable Concentration Extension. 2. Extend through the target joint(s) for Cable Concentration Extension. 3. Repeat for the prescribed number of repetitions. Don''t rush—quality over quantity.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 72, 5, 7, FALSE, TRUE, 'general_exercise', 'Concentration Extension', 'squat, leg_extension, lunge', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('217f756e-024e-4033-94a2-b94c0dc3b0a1', 'Lying Floor Quarter Twisting Crunch', 'Core', 'Bodyweight', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'This crunching movement focuses on your obliques for a complete core workout. Your hip flexors work as secondary movers, adding to the training stimulus. The lying position provides back support and helps isolate the target muscles. A versatile bodyweight movement perfect for home or gym training. A strong core improves posture, protects your spine, and enhances all other lifts.', '92961201', '92961201-Lying-Floor-Quarter-Twisting-Crunch-(female)_Waist.mp4', 'female', FALSE, '2025-12-03 23:26:35.133808+00', '1. Position yourself on the floor for Lying Floor Quarter Twisting Crunch. 2. Lie down in the appropriate position for Lying Floor Quarter Twisting Crunch. 3. Curl your shoulders off the floor by contracting your abs. 4. Don''t pull on your neck—focus on the abdominal contraction. 5. Lower with control, maintaining some tension. 6. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 57, 5, 7, FALSE, TRUE, 'crunch', 'Lying Floor Quarter Twisting Crunch', 'leg_raise, plank, russian_twist, v_up', TRUE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('2189c9ae-8b0f-4e54-8e57-4408a5cf2b99', 'Rack Pull (Smith Machine)', 'Back', 'Smith Machine', '{"Upper Back"}'::text[], '{"Lats","Biceps"}'::text[], 'Strengthen the back of your thighs with this pulling exercise. You''ll also feel your glutes, lower back working to support the movement. The fixed path allows you to focus purely on muscular effort. Leg training boosts metabolism and builds functional, real-world strength.', '41711201', '41711201-Smith-Rack-Pull_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:28.397686+00', '1. Set the Smith machine bar to the appropriate starting height for Smith Rack Pull. 2. Set up in the starting position for Smith Rack Pull. 3. Execute the movement with proper form, focusing on your hamstrings. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 58, 7, 8, TRUE, TRUE, 'general_exercise', 'Smith Rack Pull', 'Rack Pull', FALSE, 'smith_machine', FALSE, 3, 90, 4, 80, 75, 20, 88),
('218db375-f91c-4ba4-af65-07b4ef580e95', 'Overhead Triceps Extension - Rope Attachment (Cable)', 'Arms', 'Cables', '{"Quads"}'::text[], '{"Shoulders"}'::text[], 'The Cable Overhead Triceps Extension (rope Attachment) targets your triceps through a extension motion. Cables provide constant tension throughout the full range of motion. Dedicated arm training builds both strength and muscular definition.', '1941201', '01941201-Cable-Overhead-Triceps-Extension-(rope-attachment)_Upper-Arms-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:24.422129+00', '1. Adjust the cable machine to the correct height and attachment for Cable Overhead Triceps Extension. 2. Extend at the elbow until your arm is straight, squeezing the tricep. 3. Lower with control, keeping your upper arm stationary. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 72, 5, 7, FALSE, TRUE, 'tricep_extension', 'Overhead Triceps Extension', 'tricep_pushdown, close_grip_bench', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('218e48db-6116-4b41-b722-fa7f73131ac0', 'Lateral Step Up (Smith Machine)', 'Legs', 'Smith Machine, Step Platform', '{Quadriceps}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Target the front of your thighs with this stepping exercise for quad development. Secondary activation of your glutes, hamstrings provides additional muscle engagement. Machine exercises are great for isolating muscles and training to failure safely. Strong legs are the foundation for athletic performance and functional fitness.', '58241201', '58241201-Smith-Lateral-Step-Up-(male)_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:29.242428+00', '1. Set the Smith machine bar to the appropriate starting height for Smith Lateral Step Up. 2. Set up a box or step platform at the appropriate height. 3. Step one foot onto the elevated surface. 4. Drive through that foot to lift your body up onto the platform. 5. Step back down with control and repeat. 6. Continue for your target rep count, maintaining good form throughout. Maintain consistent tempo throughout the set.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 78, 7, 8, TRUE, TRUE, 'step_up', 'Smith Lateral Step Up', 'Lateral Step Up', FALSE, 'smith_machine', FALSE, 3, 90, 4, 80, 75, 20, 88),
('21962f17-c91b-41f6-8d8d-ff1cc82da23a', 'Stepback Side Bend', 'Core', 'Bodyweight', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'A challenging plyometric exercise, the Stepback Side Bend builds reactive power and improves conditioning. You''ll also feel your abs working to support the movement. Plyometric training builds explosive power that transfers to sports and daily activities.', '74861201', '74861201-Stepback-Side-Bend-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:39.21093+00', '1. Set up a box or step platform at the appropriate height. 2. Set up in the starting position for Stepback Side Bend. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'side_bend', 'Stepback Side Bend', 'russian_twist, woodchop, oblique_crunch', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('21b01531-27c6-4790-b9ec-678261710882', 'Kneeling Scapular Push Up', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'The Kneeling Scapular Push Up is a pushing exercise that develops back strength and muscle. The triceps, front delts assist throughout the movement, making this a well-rounded exercise. The kneeling position adds a core stability challenge. No equipment needed—your body provides all the resistance. Back development is crucial for pulling strength and overall upper body function.', '41171201', '41171201-Kneeling-Scapular-Push-Up-(male)_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:24.203368+00', '1. Kneel on the floor (use a pad for comfort if needed). 2. Keep your body in a straight line from head to heels throughout. 3. Lower your chest toward the floor by bending your elbows. 4. Push through your palms to return to the starting position. 5. Repeat for the prescribed number of repetitions. Exhale during the exertion phase of the movement.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'push_up', 'Kneeling Scapular Push Up', 'bench_press, chest_fly, dip', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('21b8171a-69e6-443a-891e-20f03eada74a', 'Push Up', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'This pushing exercise focuses on your pectorals for improved chest strength and development. Secondary activation of your triceps, front delts provides additional muscle engagement. A versatile bodyweight movement perfect for home or gym training. Chest strength improves pushing power for sports, daily tasks, and other lifts. Perfect for including in both strength and hypertrophy programs.', '6651201', '06651201-Push-up-(female)_Chest.mp4', 'female', FALSE, '2025-12-03 23:26:35.801913+00', '1. Keep your body in a straight line from head to heels throughout. 2. Lower your chest toward the floor by bending your elbows. 3. Push through your palms to return to the starting position. 4. Continue for your target rep count, maintaining good form throughout. Maintain a neutral spine throughout. A solid choice for chest day.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'push_up', 'Push Up', 'bench_press, chest_fly, dip', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('21cb7583-e6d6-40a7-ac3b-97ae70329f4e', 'Lying Vertical Scissors On Floor', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build leg strength with this movement movement focusing on your core. Performing this lying down removes momentum for stricter form. This bodyweight exercise requires no equipment and can be done anywhere. Lower body strength improves everything from walking to heavy compound lifts.', '55081201', '55081201-Lying-Vertical-Scissors-on-Floor_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:23.466497+00', '1. Position yourself on the floor for Lying Vertical Scissors On Floor. 2. Lie down in the appropriate position for Lying Vertical Scissors On Floor. 3. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 45, 7, 8, TRUE, TRUE, 'general_exercise', 'Lying Vertical Scissors On Floor', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('21d9e016-b46d-4619-9fd5-66eb5779228d', 'Standing Viking Press (Machine)', 'Shoulders', 'Machine', '{"Front Delts"}'::text[], '{"Side Delts","Triceps"}'::text[], 'Target your delts with the Lever Standing Viking Press, an effective shoulder pressing exercise. The standing position engages your core for stability. The machine guides your movement path for safer, more controlled repetitions. Shoulder development enhances both performance and upper body aesthetics.', '88501201', '88501201-Lever-Standing-Viking-Press-(male)_Shoulders_.mp4', 'male', FALSE, '2025-12-03 23:26:26.271124+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Standing Viking Press. 2. Stand tall with your feet firmly planted. 3. Start with the weight at shoulder level. 4. Press directly overhead until your arms are fully extended. 5. Lower back to shoulder level with control. 6. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 80, 7, 8, TRUE, TRUE, 'general_exercise', 'Lever Standing Viking Press', 'lateral_raise, front_raise, rear_delt_fly, upright_row', FALSE, 'machine', FALSE, 3, 90, 4, 80, 75, 20, 88),
('21de2136-52f7-4d6a-8a9a-1ed147ecf36c', 'Star Reach Side Leg Lift', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'The Star Reach Side Leg Lift is an explosive exercise that combines cardiovascular training with dynamic movement movements. This bodyweight exercise requires no equipment and can be done anywhere. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '78431201', '78431201-Star-Reach-Side-Leg-Lift-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:39.21093+00', '1. Set up in the starting position for Star Reach Side Leg Lift. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'leg_exercise', 'Star Reach Side Leg Lift', 'crunch, plank, russian_twist, hanging_knee_raise', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('21ea5346-0d89-43c0-a735-c77d735483e3', 'Shrug (Dumbbell)', 'Back', 'Dumbbells', '{"Traps"}'::text[], '{"Upper Back"}'::text[], 'The Dumbbell Shrug is a shrugging exercise that develops back strength and muscle. Using dumbbells requires more stabilization than barbell variations. Back development is crucial for pulling strength and overall upper body function.', '25961201', '25961201-Dumbbell-Shrug-(female)_Back.mp4', 'female', FALSE, '2025-12-03 23:26:33.168801+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Shrug. 2. Shrug your shoulders straight up toward your ears. 3. Hold briefly at the top, then lower with control. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 82, 5, 7, FALSE, TRUE, 'shrug', 'Shrug', 'deadlift, bent_over_row, face_pull', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('2213f364-f9e3-4cd7-a28b-ce3f453a9db9', 'Shoulder External Rotation Test', 'Shoulders', 'Bodyweight', '{"Rotator Cuff"}'::text[], '{"Shoulders"}'::text[], 'Target your shoulders with this rotation stretch that helps restore range of motion. The upper back assist throughout the movement, making this a well-rounded exercise. Include this in your routine for better mobility and reduced muscle tension.', '67901201', '67901201-Shoulder-External-Rotation-Test-(female)_Stretchin.mp4', 'female', FALSE, '2025-12-03 23:26:36.848698+00', '1. Rotate your torso through the movement pattern for Shoulder External Rotation Test. 2. Control the rotation in both directions—avoid using momentum. 3. Move into the stretch position for Shoulder External Rotation Test. 4. Ease into the stretch until you feel gentle tension (not pain). 5. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'external_rotation', 'Shoulder External Rotation Test', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('221b6fe6-4da4-4ba2-b5b6-0842944deb15', 'Single Leg Thrust', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build stronger glutes with this thrusting movement focused on hip extension. No equipment needed—your body provides all the resistance. Lower body strength improves everything from walking to heavy compound lifts.', '57741201', '57741201-Single-Leg-Thrusts-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:37.628647+00', '1. Drive through your heels to lift your hips toward the ceiling. 2. Squeeze your glutes hard at the top of the movement. 3. Lower your hips back down with control. 4. Complete all reps on one side, then switch to the other side. 5. Repeat for the prescribed number of repetitions. Keep tension on the target muscles throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 45, 7, 8, TRUE, TRUE, 'leg_exercise', 'Single Leg Thrust', 'squat, lunge, leg_press', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('2220d1b6-7569-4196-a729-7777cd18ce6b', 'Ring Back Roll To Support (Gymnastic Rings)', 'Full Body', 'Gymnastic Rings', '{"Full Body"}'::text[], '{}'::text[], 'Build power and athleticism with this high-intensity movement exercise that challenges your entire body. Great for improving athletic performance, burning calories, and building conditioning. Can be modified for beginners or progressed for advanced athletes.', '76171201', '76171201-Ring-Back-Roll-to-Support-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:26.271124+00', '1. Set up in the starting position for Ring Back Roll To Support. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 38, 7, 8, TRUE, TRUE, 'back_exercise', 'Ring Back Roll To Support', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'gymnastic_rings', FALSE, 3, 90, 4, 68, 85, 85, 70),
('2222369f-e10b-460c-9832-632c8765bc28', 'Side Plank Raise', 'Core', 'Bodyweight', '{"Core","Abs"}'::text[], '{"Shoulders"}'::text[], 'Strengthen your midsection with this raising movement that works your abs. You''ll also feel your shoulders, lower back working to support the movement. A versatile bodyweight movement perfect for home or gym training. A strong core improves posture, protects your spine, and enhances all other lifts.', '77531201', '77531201-Side-Plank-Raise-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:23.466497+00', '1. Raise your arms out to the sides until parallel to the floor. 2. Lower with control, maintaining tension throughout. 3. Complete all reps with control before resting. Keep the movement smooth and controlled.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'side_plank', 'Side Plank Raise', 'shoulder_press, front_raise, rear_delt_fly, upright_row', FALSE, 'bodyweight', TRUE, 3, 60, 2, 70, 88, 95, 65),
('2226af4a-cac4-4d97-b482-ecca53cf799e', 'Over Bench Neutral Wrist Curl (Dumbbell)', 'Arms', 'Dumbbells', '{"Forearms"}'::text[], '{}'::text[], 'Build grip strength and forearm size with this curling exercise. Your forearms work as secondary movers, adding to the training stimulus. Dumbbells allow each arm to work independently, helping correct imbalances. Arm strength supports grip, pulling, and pushing in compound movements. This variation is excellent for building mind-muscle connection.', '3651201', '03651201-Dumbbell-Over-Bench-Neutral-Wrist-Curl_Forearms_.mp4', 'male', FALSE, '2025-12-03 23:26:22.247914+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Over Bench Neutral Wrist Curl. 2. Keep your elbows in a fixed position throughout the movement. 3. Curl the weight up by contracting your biceps, squeezing at the top. 4. Lower with control, resisting the weight on the way down. 5. Continue for your target rep count, maintaining good form throughout.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 82, 5, 7, FALSE, TRUE, 'wrist_curl', 'Over Bench Neutral Wrist Curl', 'tricep_pushdown, tricep_extension, hammer_curl, preacher_curl', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('22300a58-d4ce-40e3-9a69-09117ed1e8d2', 'Kneeling Leg Half Circle (Resistance Band)', 'Shoulders', 'Resistance Band', '{"Shoulders"}'::text[], '{"Traps"}'::text[], 'Build stronger shoulders with this movement movement focusing on your delts. Kneeling helps eliminate lower body momentum from the movement. Resistance bands provide accommodating resistance that increases through the range of motion. Strong shoulders improve overhead strength and support nearly all upper body movements.', '72091201', '72091201-Resistance-Band-Kneeling-Leg-Half-Circle-(female)_.mp4', 'female', FALSE, '2025-12-03 23:26:36.128549+00', '1. Secure the resistance band appropriately for Resistance Band Kneeling Leg Half Circle. 2. Get into a half-kneeling position (one knee down, opposite foot forward). 3. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 55, 7, 8, TRUE, TRUE, 'leg_exercise', 'Kneeling Leg Half Circle', 'squat, leg_extension, lunge', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('22367063-c114-417d-89cd-30c088d3a6fa', 'Standing Wrist Rotation', 'Arms', 'Bodyweight', '{"Forearms"}'::text[], '{}'::text[], 'Build grip strength and forearm size with this rotation exercise. Performing this standing challenges your balance and core engagement. A versatile bodyweight movement perfect for home or gym training. Dedicated arm training builds both strength and muscular definition.', '95561201', '95561201-Standing-Wrist-Rotation-(female)_Forearms_.mp4', 'female', FALSE, '2025-12-03 23:26:39.21093+00', '1. Stand tall with your feet firmly planted. 2. Rotate your torso through the movement pattern for Standing Wrist Rotation. 3. Control the rotation in both directions—avoid using momentum. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 52, 5, 7, FALSE, TRUE, 'wrist_stretch', 'Standing Wrist Rotation', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('2252c01d-013d-4d24-911e-126aa2c27e81', 'Standing Hands Torsion (Plate)', 'Full Body', 'Weight Plate', '{"Full Body"}'::text[], '{}'::text[], 'The Weighted Plate Standing Hands Torsion is an arm movement exercise targeting your full body. The standing position engages your core for stability. No equipment needed—your body provides all the resistance. Dedicated arm training builds both strength and muscular definition.', '70551201', '70551201-Weighted-Plate-Standing-Hands-Torsion-(male)_Forea.mp4', 'male', FALSE, '2025-12-03 23:26:22.417605+00', '1. Stand with feet about shoulder-width apart. 2. Set up in the starting position for Weighted Plate Standing Hands Torsion. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'back_exercise', 'Weighted Plate Standing Hands Torsion', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'plate', FALSE, 3, 90, 4, 70, 88, 95, 65),
('225ab4fc-8ed8-43d3-a792-decba4ed16b0', 'Diagonal Claps Woodchopper', 'Core', 'Bodyweight', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'The Diagonal Claps Woodchopper is an explosive exercise that combines cardiovascular training with dynamic movement movements. A versatile bodyweight movement perfect for home or gym training. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '79461201', '79461201-Diagonal-Claps-Woodchopper-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:32.501166+00', '1. Set up in the starting position for Diagonal Claps Woodchopper. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 50, 9, 8, TRUE, TRUE, 'woodchop', 'Diagonal Claps Woodchopper', 'russian_twist, pallof_press, cable_crunch', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('225ffa34-ac73-4912-b3c4-bcda962991fd', 'Chest Dip (Dip Bars)', 'Chest', 'Dip Bars', '{"Lower Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'This dipping exercise focuses on your pectorals for improved chest strength and development. You''ll also feel your triceps, front delts working to support the movement. No equipment needed—your body provides all the resistance. A well-developed chest contributes to upper body strength and aesthetics.', '35991201', '35991201-Chest-Dip-(female)_Chest.mp4', 'female', FALSE, '2025-12-03 23:26:32.166461+00', '1. Lower your body by bending your elbows to about 90 degrees. 2. Push back up until your arms are fully extended. 3. Continue for your target rep count, maintaining good form throughout. Exhale during the exertion phase of the movement. A solid choice for chest day.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'dip', 'Chest Dip', 'bench_press, tricep_pushdown, push_up', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('2261b15d-90b0-49c3-8e07-70a66f5f2b0d', 'Standing Hip Frontal Rotation Prayer Arms', 'Legs', 'Bodyweight', '{"Hips"}'::text[], '{"Glutes","Hip Flexors"}'::text[], 'Build total body strength and coordination with this multi-joint rotation movement. Performing this standing challenges your balance and core engagement. A versatile bodyweight movement perfect for home or gym training. Full body exercises are time-efficient and build functional, real-world strength. Start with lighter weight to master the movement pattern.', '80341201', '80341201-Standing-Hip-Frontal-Rotation-Prayer-Arms-(female).mp4', 'female', FALSE, '2025-12-03 23:26:38.7451+00', '1. Begin in a standing position with good posture. 2. Rotate your torso through the movement pattern for Standing Hip Frontal Rotation Prayer Arms. 3. Control the rotation in both directions—avoid using momentum. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 37, 7, 8, TRUE, TRUE, 'glute_exercise', 'Standing Hip Frontal Rotation Prayer Arms', 'hip_thrust, lunge, squat', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('22684a9e-513e-47a3-92ab-30a2b975287d', 'Side Plank Scissors', 'Core', 'Bodyweight', '{"Core","Abs"}'::text[], '{"Shoulders"}'::text[], 'Strengthen your midsection with this stabilization movement that works your abs. The shoulders, lower back assist throughout the movement, making this a well-rounded exercise. No equipment needed—your body provides all the resistance. A strong core improves posture, protects your spine, and enhances all other lifts.', '64361201', '64361201-Side-Plank-Scissors-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:37.179953+00', '1. Hold your body in a straight line from head to heels. 2. Don''t let your hips sag or pike up—engage your core and glutes. 3. Breathe steadily while maintaining the position. 4. Complete all reps with control before resting. Focus on the mind-muscle connection. Perfect for targeting your abs.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'side_plank', 'Side Plank Scissors', 'plank, russian_twist, woodchop', FALSE, 'bodyweight', TRUE, 3, 90, 4, 70, 88, 95, 65),
('226c43b8-592f-4e68-be05-a2a9f2964c4c', 'Low Bar Squat (Smith Machine)', 'Legs', 'Smith Machine', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Target the front of your thighs with this squatting exercise for quad development. The glutes, hamstrings assist throughout the movement, making this a well-rounded exercise. The fixed path allows you to focus purely on muscular effort. Strong legs are the foundation for athletic performance and functional fitness. Excellent for pre-exhausting the target muscle before compound lifts.', '57601201', '57601201-Smith-Low-Bar-Squat-(female)_Thighs_.mp4', 'female', FALSE, '2025-12-03 23:26:38.153182+00', '1. Set the Smith machine bar to the appropriate starting height for Smith Low Bar Squat. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Complete all reps with control before resting.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 9, NULL, FALSE, NULL, 'Strength', 93, 7, 9, TRUE, FALSE, 'squat', 'Smith Low Bar Squat', 'Low Bar Squat', FALSE, 'smith_machine', FALSE, 4, 120, 5, 80, 75, 20, 88),
('226f6b1c-b560-4e81-95e9-cda86562cce4', 'Side Plank Raise', 'Core', 'Bodyweight', '{"Core","Abs"}'::text[], '{"Shoulders"}'::text[], 'Strengthen your midsection with this raising movement that works your abs. The shoulders, lower back assist throughout the movement, making this a well-rounded exercise. A versatile bodyweight movement perfect for home or gym training. A strong core improves posture, protects your spine, and enhances all other lifts.', '78291201', '78291201-Side-Plank-Raise-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:37.179953+00', '1. Raise your arms out to the sides until parallel to the floor. 2. Lower with control, maintaining tension throughout. 3. Repeat for the prescribed number of repetitions. Focus on squeezing the target muscle at peak contraction.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'side_plank', 'Side Plank Raise', 'shoulder_press, front_raise, rear_delt_fly, upright_row', FALSE, 'bodyweight', TRUE, 3, 60, 2, 70, 88, 95, 65),
('227f6d00-9a3e-4dbf-ae83-14912f0711b7', 'Pulse Squat', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Target the front of your thighs with this squatting exercise for quad development. Your glutes, hamstrings work as secondary movers, adding to the training stimulus. No equipment needed—your body provides all the resistance. Leg training boosts metabolism and builds functional, real-world strength.', '46541201', '46541201-Bodyweight-Pulse-Squat-(female)_Thighs.mp4', 'female', FALSE, '2025-12-03 23:26:31.475486+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. 4. At the bottom or top, pulse up and down in small movements before completing the rep. 5. Continue for your target rep count, maintaining good form throughout. Keep your shoulders relaxed and away from your ears.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'squat', 'Pulse Squat', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('227f960b-758e-4414-a517-bd60751a61dd', 'Lying Legs Extension Abduction', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Lying Legs Extension Abduction is a lower body extension exercise that targets your glute med/abductors. Performing this lying down removes momentum for stricter form. This bodyweight exercise requires no equipment and can be done anywhere. Strong legs are the foundation for athletic performance and functional fitness.', '95211201', '95211201-Lying-Legs-Extension-Abduction-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:35.250398+00', '1. Lie down in the appropriate position for Lying Legs Extension Abduction. 2. Extend your legs until straight, squeezing your quads at the top. 3. Lower with control back to the starting position. 4. Repeat for the prescribed number of repetitions. Exhale during the exertion phase of the movement.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'hip_abduction', 'Lying Legs Extension Abduction', 'leg_curl, squat, leg_press, lunge', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('22938f34-cf8c-4b28-af2a-bebfca7cdbad', 'Standing Calf Raise (Kettlebell)', 'Legs', 'Kettlebell', '{"Calves"}'::text[], '{}'::text[], 'Build stronger calves with this targeted raising exercise. The standing position engages your core for stability. The kettlebell grip position adds a unique training stimulus. Leg training boosts metabolism and builds functional, real-world strength.', '58541201', '58541201-Kettlebell-Standing-Calf-Raise_Calves_.mp4', 'male', FALSE, '2025-12-03 23:26:23.987963+00', '1. Select an appropriately weighted kettlebell for Kettlebell Standing Calf Raise. 2. Stand tall with your feet firmly planted. 3. Lower your heels below the platform to get a full stretch. 4. Rise up onto your toes as high as possible, squeezing your calves. 5. Lower with control and repeat. 6. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 90, 5, 7, FALSE, TRUE, 'calf_raise', 'Standing Calf Raise', 'calf_raise, seated_calf_raise', FALSE, 'kettlebell', FALSE, 3, 60, 2, 75, 88, 88, 78),
('2296a651-10f9-47fc-ba8b-a04d594411b9', 'Standing Single Leg Front Back Side To Side Toe T', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Develop functional strength with the Standing Single Leg Front Back Side To Side Toe T, a comprehensive movement exercise. Performing this standing challenges your balance and core engagement. This bodyweight exercise requires no equipment and can be done anywhere. Full body exercises are time-efficient and build functional, real-world strength.', '107481201', '107481201-Standing-Single-Leg-Front-Back-Side-to-Side-Toe-T.mp4', 'female', FALSE, '2025-12-03 23:26:38.992671+00', '1. Stand tall with your feet firmly planted. 2. Complete all reps on one side, then switch to the other side. 3. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 47, 7, 8, TRUE, TRUE, 'back_exercise', 'Standing Single Leg Front Back Side To Side Toe T', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('22974e87-bd70-41bf-a26e-243992d27997', 'Standing Front To Lateral Raise (Dumbbell)', 'Shoulders', 'Dumbbells', '{"Side Delts"}'::text[], '{"Traps"}'::text[], 'The Dumbbell Standing Front To Lateral Raise is a raising exercise that targets your lateral delts for shoulder development. The standing position engages your core for stability. Dumbbells allow each arm to work independently, helping correct imbalances. Strong shoulders improve overhead strength and support nearly all upper body movements.', '73611201', '73611201-Dumbbell-Standing-Front-to-Lateral-Raise_Shoulders.mp4', 'male', FALSE, '2025-12-03 23:26:28.260518+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Standing Front To Lateral Raise. 2. Begin in a standing position with good posture. 3. Raise your arms out to the sides until parallel to the floor. 4. Lower with control, maintaining tension throughout. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 94, 5, 7, FALSE, TRUE, 'lateral_raise', 'Standing Front To Lateral Raise', 'shoulder_press, front_raise, rear_delt', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('2297f5e1-6f40-41e3-b410-6d53895cd699', 'Seated Knee Extension (Chair) - Alternating', 'Legs', 'Chair', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This extension movement emphasizes your quadriceps for stronger, more powerful legs. The seated position helps isolate the target muscles by removing momentum. Strong legs are the foundation for athletic performance and functional fitness.', '87441201', '87441201-Seated-Alternate-Knee-Extension-on-Chair-(male)_Th.mp4', 'male', FALSE, '2025-12-03 23:26:23.288245+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Extend through the target joint(s) for Seated Alternate Knee Extension On Chair. 4. Alternate between sides/arms/legs with each repetition. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Seated', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 57, 5, 7, FALSE, TRUE, 'leg_extension', 'Seated Knee Extension On Chair - Alternating', 'squat, leg_press, lunge', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('22a16049-6670-44dc-9a6f-b04a621d90c5', 'Upper Body Dead Bug (Resistance Band)', 'Core', 'Resistance Band', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'This movement exercise engages your abs for improved core stability and strength. Your hip flexors work as secondary movers, adding to the training stimulus. Resistance bands provide accommodating resistance that increases through the range of motion. Building core stability helps with everything from heavy deadlifts to daily activities.', '35121201', '35121201-Resistance-Band-Upper-Body-Dead-Bug_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:27.805708+00', '1. Secure the resistance band appropriately for Resistance Band Upper Body Dead Bug. 2. Set up in the starting position for Resistance Band Upper Body Dead Bug. 3. Execute the movement with proper form, focusing on your abs. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 55, 7, 8, TRUE, TRUE, 'dead_bug', 'Upper Body Dead Bug', 'plank, bird_dog, hollow_hold', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('22a844ef-29eb-4f89-911c-497960fac12e', 'Sumo Deadlift (Smith Machine)', 'Legs', 'Smith Machine', '{"Glutes"}'::text[], '{"Quads","Lower Back","Inner Thighs"}'::text[], 'The Smith Sumo Deadlift is a lower body hip hinge exercise that targets your hamstrings/glutes. Your glutes, lower back work as secondary movers, adding to the training stimulus. The fixed path allows you to focus purely on muscular effort. Strong legs are the foundation for athletic performance and functional fitness.', '65571201', '65571201-Smith-Sumo-Deadlift-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:38.153182+00', '1. Set the Smith machine bar to the appropriate starting height for Smith Sumo Deadlift. 2. Hinge at hips and bend knees to grip the weight. 3. Drive through your heels, extending hips and knees to stand. 4. Lower by reversing the movement with control. 5. Repeat for the prescribed number of repetitions. Keep your core engaged for stability.', NULL, NULL, NULL, NULL, NULL, 4, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 3, 6, NULL, 10, NULL, FALSE, NULL, 'Strength', 93, 7, 9, TRUE, FALSE, 'deadlift', 'Smith Sumo Deadlift', 'Sumo Deadlift', FALSE, 'smith_machine', FALSE, 4, 120, 6, 80, 75, 20, 88),
('22ade6a6-728b-4848-836b-6e280e9e9ff7', 'Abduction Squat (Machine)', 'Legs', 'Machine', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build leg strength with this squatting movement focusing on your glute med/abductors. You''ll also feel your glutes, hamstrings working to support the movement. The machine guides your movement path for safer, more controlled repetitions. Strong legs are the foundation for athletic performance and functional fitness.', '27461201', '27461201-Lever-Abduction-Squat-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:34.724336+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Abduction Squat. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Continue for your target rep count, maintaining good form throughout.', 'Squat', NULL, NULL, NULL, NULL, 1, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 9, NULL, FALSE, NULL, 'Strength', 93, 7, 9, TRUE, FALSE, 'hip_abduction', 'Lever Abduction Squat', 'leg_press, leg_extension, leg_curl, lunge, front_squat, hack_squat', FALSE, 'machine', FALSE, 4, 120, 5, 80, 75, 20, 88),
('22bdedb2-9a60-4ff4-b406-214c1fbcf1d7', 'Roll Peroneal Side Lying On Floor', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build stronger calves with this targeted movement exercise. The lying position provides back support and helps isolate the target muscles. No equipment needed—your body provides all the resistance. Lower body strength improves everything from walking to heavy compound lifts.', '54401201', '54401201-Roll-Peroneal-Side-Lying-on-Floor-(female)_Calves_.mp4', 'female', FALSE, '2025-12-03 23:26:36.38616+00', '1. Position yourself on the floor for Roll Peroneal Side Lying On Floor. 2. Lie on your side with your body aligned. 3. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 45, 7, 8, TRUE, TRUE, 'general_exercise', 'Roll Peroneal Side Lying On Floor', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('22c4f6c5-6f33-48ee-9cca-c44703c6d344', 'Standing Cat Cow Stretch', 'Back', 'Bodyweight', '{"Lats"}'::text[], '{"Lower Back"}'::text[], 'Target your spine with this stretching stretch that helps restore range of motion. The core assist throughout the movement, making this a well-rounded exercise. Performing this standing challenges your balance and core engagement. Include this in your routine for better mobility and reduced muscle tension.', '85121201', '85121201-Standing-Cat-Cow-Stretch-(male)_Stretching_.mp4', 'male', FALSE, '2025-12-03 23:26:25.123298+00', '1. Begin in a standing position with good posture. 2. Move into the stretch position for Standing Cat Cow Stretch. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, 'Standing', NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 15, 2, 6, FALSE, TRUE, 'back_stretch', 'Standing Cat Cow Stretch', 'stretch_hip, stretch_back, plank', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('22c5a96e-869e-4258-a5ab-8c96205947b4', 'Wrist Curl (Band)', 'Arms', 'Resistance Band', '{"Forearms"}'::text[], '{}'::text[], 'Build grip strength and forearm size with this curling exercise. You''ll also feel your forearms working to support the movement. The band creates increasing tension as it stretches, challenging the lockout. Arm strength supports grip, pulling, and pushing in compound movements.', '10161201', '10161201-Band-Wrist-Curl_Forearms_.mp4', 'male', FALSE, '2025-12-03 23:26:25.123298+00', '1. Secure the resistance band appropriately for Band Wrist Curl. 2. Keep your elbows in a fixed position throughout the movement. 3. Curl the weight up by contracting your biceps, squeezing at the top. 4. Lower with control, resisting the weight on the way down. 5. Continue for your target rep count, maintaining good form throughout.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 75, 5, 7, FALSE, TRUE, 'wrist_curl', 'Wrist Curl', 'tricep_pushdown, tricep_extension, hammer_curl, preacher_curl', FALSE, 'band', FALSE, 3, 60, 2, 60, 85, 90, 50),
('22c6f336-9d24-4ffb-869f-9d47bdd6bf6b', 'Rear Delt Raise (Dumbbell)', 'Shoulders', 'Dumbbells', '{"Rear Delts"}'::text[], '{"Upper Back","Traps"}'::text[], 'The Dumbbell Rear Delt Raise is a raising exercise that targets your rear delts for shoulder development. Your upper back work as secondary movers, adding to the training stimulus. The dumbbell variation provides freedom of movement and greater range of motion. Strong shoulders improve overhead strength and support nearly all upper body movements.', '22921201', '22921201-Dumbbell-Rear-Delt-Raise_Shoulders.mp4', 'male', FALSE, '2025-12-03 23:26:29.971345+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Rear Delt Raise. 2. Raise your arms out to the sides and back, focusing on rear delts. 3. Lower with control, maintaining tension throughout. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 82, 5, 7, FALSE, TRUE, 'rear_delt', 'Rear Delt Raise', 'shoulder_press, lateral_raise, face_pull, bent_over_row', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('22d7fac7-aaa3-4373-9fe5-9a7874086751', 'Side Bridge (TRX)', 'Core', 'TRX', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Strengthen your midsection with this bridging movement that works your abs. You''ll also feel your hamstrings working to support the movement. Suspension training adds instability, increasing core activation throughout. Building core stability helps with everything from heavy deadlifts to daily activities.', '10981201', '10981201-Suspender-Side-Bridge-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:39.472701+00', '1. Adjust the TRX/suspension straps to the appropriate length for Suspender Side Bridge. 2. Drive through your heels to lift your hips toward the ceiling. 3. Squeeze your glutes hard at the top of the movement. 4. Lower your hips back down with control. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 40, 7, 8, TRUE, TRUE, 'side_bend', 'Suspender Side Bridge', 'hip_thrust, romanian_deadlift, leg_curl', TRUE, 'trx', FALSE, 3, 90, 4, 68, 85, 85, 70),
('22f33bf4-49e2-4fc4-b8b8-a2694f78a4d9', 'Upright Row (Dumbbell)', 'Shoulders', 'Dumbbells', '{"Side Delts"}'::text[], '{"Traps","Front Delts"}'::text[], 'Build stronger shoulders with this rowing movement focusing on your delts. Your traps work as secondary movers, adding to the training stimulus. Dumbbells allow each arm to work independently, helping correct imbalances. Strong shoulders improve overhead strength and support nearly all upper body movements.', '34311201', '34311201-Dumbbell-Upright-Row-(female)_Shoulder.mp4', 'female', FALSE, '2025-12-03 23:26:33.298565+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Upright Row. 2. Pull the weight straight up along your body, leading with your elbows. 3. Raise until elbows reach shoulder height, then lower with control. 4. Repeat for the prescribed number of repetitions. Ensure full range of motion on each rep.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 8, NULL, TRUE, NULL, 'Strength', 82, 7, 9, TRUE, FALSE, 'upright_row', 'Upright Row', 'lateral_raise, shoulder_press, shrug', TRUE, 'dumbbell', FALSE, 4, 120, 4, 92, 90, 92, 90),
('22f51805-979a-4ac3-aa9b-e6ae76bea58c', 'Bench Press - Wide Grip (Smith Machine)', 'Chest', 'Smith Machine, Flat Bench', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'Target your chest with the Smith Wide Grip Bench Press, an effective pressing movement for upper body strength. Secondary activation of your triceps, front delts provides additional muscle engagement. The fixed path allows you to focus purely on muscular effort. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '13081201', '13081201-Smith-Wide-Grip-Bench-Press_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:26.507873+00', '1. Set the Smith machine bar to the appropriate starting height for Smith Wide Grip Bench Press. 2. Use a wide grip (wider than shoulder-width) for this variation. 3. Lower the weight toward your chest with control. 4. Press the weight up until your arms are extended (don''t lock elbows). 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 8, NULL, FALSE, NULL, 'Strength', 93, 7, 9, TRUE, FALSE, 'bench_press', 'Smith Bench Press - Wide Grip', 'Bench Press - Wide Grip', FALSE, 'smith_machine', FALSE, 4, 120, 4, 80, 75, 20, 88),
('23059efb-ecae-40d0-8c4f-e487ee2b1678', 'Elbow To Knee', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Strengthen your midsection with this movement movement that works your abs. No equipment needed—your body provides all the resistance. A strong core improves posture, protects your spine, and enhances all other lifts. Focus on controlled form throughout each repetition.', '4431201', '04431201-Elbow-To-Knee-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:21.732034+00', '1. Set up in the starting position for Elbow To Knee. 2. Execute the movement with proper form, focusing on your abs. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Elbow To Knee', 'squat, leg_extension, lunge', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('23091be9-ea54-4791-9492-0e97e7d42591', 'Standing Balance Hip Abduction Pulse', 'Legs', 'Bodyweight', '{"Glutes"}'::text[], '{"Hip Abductors"}'::text[], 'The Standing Balance Hip Abduction Pulse is a lower body movement exercise that targets your glute med/abductors. The glutes assist throughout the movement, making this a well-rounded exercise. Performing this standing challenges your balance and core engagement. A versatile bodyweight movement perfect for home or gym training. Lower body strength improves everything from walking to heavy compound lifts.', '81151201', '81151201-Standing-Balance-Hip-Abduction-Pulse-(female)_Hips.mp4', 'female', FALSE, '2025-12-03 23:26:38.425788+00', '1. Stand with feet about shoulder-width apart. 2. At the bottom or top, pulse up and down in small movements before completing the rep. 3. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'hip_abduction', 'Standing Balance Hip Abduction Pulse', 'hip_adduction, glute_bridge, clamshell', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('231cc3e8-a22f-46f9-ad81-0eb109cb8c84', 'Wrist Flexor Stretch', 'Arms', 'Bodyweight', '{"Forearms"}'::text[], '{}'::text[], 'Build grip strength and forearm size with this stretching exercise. No equipment needed—your body provides all the resistance. Dedicated arm training builds both strength and muscular definition.', '18501201', '18501201-Wrist-Flexor-Stretch-(female)_Forearms_.mp4', 'female', FALSE, '2025-12-03 23:26:40.146812+00', '1. Set up in the starting position for Wrist Flexor Stretch. 2. Execute the movement with proper form, focusing on your forearms. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'wrist_stretch', 'Wrist Flexor Stretch', 'stretch_hip, stretch_back, stretch_shoulder', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('231ce272-7186-4a99-bca6-8b1c97357485', 'Posterior Tibialis Stretch', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This stretching movement focuses on your gastrocnemius and soleus. No equipment needed—your body provides all the resistance. Lower body strength improves everything from walking to heavy compound lifts. A staple exercise that belongs in most training programs.', '13891201', '13891201-Posterior-Tibialis-Stretch_Calves_.mp4', 'male', FALSE, '2025-12-03 23:26:23.288245+00', '1. Set up in the starting position for Posterior Tibialis Stretch. 2. Execute the movement with proper form, focusing on your calves. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'stretch_general', 'Posterior Tibialis Stretch', 'stretch_hip, stretch_back, stretch_shoulder', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('231e7f0d-fe4e-43f3-8963-f31e2d80744b', 'Bent Arm Lateral Raise (Dumbbell)', 'Shoulders', 'Dumbbells', '{"Side Delts"}'::text[], '{"Traps"}'::text[], 'Build stronger shoulders with this raising movement focusing on your lateral delts. The dumbbell variation provides freedom of movement and greater range of motion. Shoulder development enhances both performance and upper body aesthetics.', '56351201', '56351201-Dumbbell-Bent-Arm-Lateral-Raise-(male)_Shoulders_.mp4', 'male', FALSE, '2025-12-03 23:26:30.292204+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Bent Arm Lateral Raise. 2. Raise your arms out to the sides until parallel to the floor. 3. Lower with control, maintaining tension throughout. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 92, 5, 7, FALSE, TRUE, 'lateral_raise', 'Bent Arm Lateral Raise', 'shoulder_press, front_raise, rear_delt', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('233b3c5d-de81-4734-a3b1-455a6658e586', 'Swing Torso Twist', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{"Abs"}'::text[], 'The Swing Torso Twist is an explosive exercise that combines cardiovascular training with dynamic twisting movements. You''ll also feel your abs working to support the movement. A versatile bodyweight movement perfect for home or gym training. Great for improving athletic performance, burning calories, and building conditioning.', '76711201', '76711201-Swing-Torso-Twist-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:22.536005+00', '1. Rotate your torso through the movement pattern for Swing Torso Twist. 2. Control the rotation in both directions—avoid using momentum. 3. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 50, 5, 7, FALSE, TRUE, 'russian_twist', 'Swing Torso Twist', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('234fa377-0343-4bd9-8071-c56dd2dc0b09', 'Reverse Dip', 'Chest', 'Bodyweight', '{"Lower Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'This dipping movement isolates your triceps for improved arm development. Your triceps, front delts work as secondary movers, adding to the training stimulus. No equipment needed—your body provides all the resistance. Dedicated arm training builds both strength and muscular definition.', '43021201', '43021201-Reverse-Dip-(female)_Upper-Arms.mp4', 'female', FALSE, '2025-12-03 23:26:36.266593+00', '1. Lower your body by bending your elbows to about 90 degrees. 2. Push back up until your arms are fully extended. 3. Complete all reps with control before resting. Keep your core engaged for stability.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'dip', 'Reverse Dip', 'bench_press, tricep_pushdown, push_up', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('23519a1a-a917-4484-ba05-f1d764e7d24c', 'Standing Single Arm Face Pull (Cable)', 'Shoulders', 'Cables', '{"Rear Delts"}'::text[], '{"Upper Back","Rotator Cuff"}'::text[], 'The Cable Standing One Arm Face Pull is a pulling exercise that targets your delts for shoulder development. The upper back, rotator cuff assist throughout the movement, making this a well-rounded exercise. Performing this standing challenges your balance and core engagement. Cables provide constant tension throughout the full range of motion. Strong shoulders improve overhead strength and support nearly all upper body movements.', '55241201', '55241201-Cable-Standing-One-Arm-Face-Pull_Shoulders_.mp4', 'male', FALSE, '2025-12-03 23:26:21.995567+00', '1. Adjust the cable machine to the correct height and attachment for Cable Standing One Arm Face Pull. 2. Stand with feet about shoulder-width apart. 3. Pull the rope toward your face, separating your hands as you pull. 4. Squeeze your rear delts and upper back at peak contraction. 5. Return with control, maintaining cable tension. 6. Complete all reps on one side, then switch to the other side. 7. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 8, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 87, 7, 8, TRUE, TRUE, 'face_pull', 'Standing Single Arm Face Pull', 'rear_delt_fly, bent_over_row, lateral_raise', TRUE, 'cable', FALSE, 3, 90, 4, 85, 88, 30, 92),
('23531ba8-6811-4ec4-8c1b-e455f3811f9a', 'Lying Hamstring Sciatic Nerve Mobilization (Gymnastic Rings)', 'Core', 'Gymnastic Rings', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Lying Hamstring Sciatic Nerve Mobilization is a core movement exercise that primarily targets your core. Performing this lying down removes momentum for stricter form. Building core stability helps with everything from heavy deadlifts to daily activities.', '83811201', '83811201-Lying-Hamstring-Sciatic-Nerve-Mobilization-(female.mp4', 'female', FALSE, '2025-12-03 23:26:35.133808+00', '1. Lie down in the appropriate position for Lying Hamstring Sciatic Nerve Mobilization. 2. Set up in the starting position for Lying Hamstring Sciatic Nerve Mobilization. 3. Execute the movement with proper form, focusing on your core. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 1, 1, NULL, 3, 'Lying', NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 26, 2, 6, FALSE, TRUE, 'mobility', 'Lying Hamstring Sciatic Nerve Mobilization', 'squat, lunge, leg_press', FALSE, 'gymnastic_rings', TRUE, 1, 30, 2, 68, 85, 85, 70),
('2365ca06-b853-48b8-8e34-b8093e054d45', 'Bear Push Up', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'The Bear Push Up is a pushing exercise that targets your chest muscles. You''ll also feel your triceps, front delts working to support the movement. A versatile bodyweight movement perfect for home or gym training. A well-developed chest contributes to upper body strength and aesthetics.', '75271201', '75271201-Bear-Push-Up-(male)_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:28.71819+00', '1. Keep your body in a straight line from head to heels throughout. 2. Lower your chest toward the floor by bending your elbows. 3. Push through your palms to return to the starting position. 4. Repeat for the prescribed number of repetitions. Don''t rush—quality over quantity. Perfect for targeting your chest.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'push_up', 'Bear Push Up', 'bench_press, chest_fly, dip', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('23670e58-dace-4966-b24e-540ca88ee291', 'Glute Bridge Single Leg (Chair)', 'Legs', 'Chair', '{"Glutes"}'::text[], '{"Hamstrings"}'::text[], 'The Glute Bridge Single Leg With Chair is a hip-dominant bridging exercise that targets your glutes. Your hamstrings work as secondary movers, adding to the training stimulus. Strong legs are the foundation for athletic performance and functional fitness.', '78811201', '78811201-Glute-Bridge-Single-Leg-with-Chair-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:33.778367+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Drive through your heels to lift your hips toward the ceiling. 3. Squeeze your glutes hard at the top of the movement. 4. Lower your hips back down with control. 5. Complete all reps on one side, then switch to the other side. 6. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'glute_bridge', 'Glute Bridge Single Leg With Chair', 'hip_thrust, romanian_deadlift', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('236802d3-d756-44a2-accc-7f577291f07e', 'Seated Swimmer (Chair)', 'Shoulders', 'Chair', '{"Shoulders"}'::text[], '{"Traps"}'::text[], 'Build stronger shoulders with this movement movement focusing on your delts. The seated position helps isolate the target muscles by removing momentum. Shoulder development enhances both performance and upper body aesthetics.', '81971201', '81971201-Sitting-Swimmer-on-a-Chair-(male)_Shoulders_.mp4', 'male', FALSE, '2025-12-03 23:26:22.247914+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Complete all reps with control before resting. Focus on the mind-muscle connection.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 35, 7, 8, TRUE, TRUE, 'swimming', 'Seated Swimmer On A Chair', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('23793d32-4a90-4963-ad65-cf9c50aba6c8', 'Single Arm Lat Pulldown - Neutral Grip (Cable)', 'Back', 'Cables', '{"Lats"}'::text[], '{"Biceps","Upper Back"}'::text[], 'The Cable One Arm Neutral Grip Lat Pulldown is a pulling exercise that targets your latissimus dorsi for a wider back. Your biceps, upper back work as secondary movers, adding to the training stimulus. The cable setup allows you to adjust the angle of resistance. A strong back improves posture, prevents injury, and balances pressing movements.', '106531201', '106531201-Cable-One-Arm-Neutral-grip-Lat-Pulldown_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:28.52454+00', '1. Adjust the cable machine to the correct height and attachment for Cable One Arm Neutral Grip Lat Pulldown. 2. Use a neutral grip with palms facing each other. 3. Pull the bar/handle down toward your upper chest. 4. Drive your elbows down and back, squeezing your lats. 5. Control the weight back up without letting it yank your arms. 6. Complete all reps on one side, then switch to the other side. 7. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'lat_pulldown', 'Single Arm Lat Pulldown - Neutral Grip', 'One Arm Lat Pulldown - Neutral Grip', TRUE, 'cable', FALSE, 3, 90, 4, 85, 88, 30, 92),
('237c41f4-0d61-470a-b71b-35fa04266b6c', 'Lying Arms Slide', 'Shoulders', 'Bodyweight', '{"Shoulders"}'::text[], '{"Traps"}'::text[], 'This movement exercise works your delts for improved shoulder strength and aesthetics. Performing this lying down removes momentum for stricter form. No equipment needed—your body provides all the resistance. Strong shoulders improve overhead strength and support nearly all upper body movements.', '90121201', '90121201-Lying-Arms-Slide-(male)_Shoulders_.mp4', 'male', FALSE, '2025-12-03 23:26:25.991486+00', '1. Lie down in the appropriate position for Lying Arms Slide. 2. Set up in the starting position for Lying Arms Slide. 3. Execute the movement with proper form, focusing on your delts. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'arm_exercise', 'Lying Arms Slide', 'bicep_curl, tricep_extension, hammer_curl', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('238eda67-5889-4856-b8f8-ebbad1942ce7', 'Lying Hamstring Curl (Dumbbell)', 'Legs', 'Dumbbells, Gymnastic Rings, Flat Bench', '{"Hamstrings"}'::text[], '{"Glutes"}'::text[], 'This curling movement works your hamstrings for balanced leg development. The forearms assist throughout the movement, making this a well-rounded exercise. Performing this lying down removes momentum for stricter form. Using dumbbells requires more stabilization than barbell variations. Strong legs are the foundation for athletic performance and functional fitness.', '57321201', '57321201-Dumbbell-Lying-Hamstring-Curl-(female)_Thighs_.mp4', 'female', FALSE, '2025-12-03 23:26:32.914483+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Lying Hamstring Curl. 2. Lie down in the appropriate position for Dumbbell Lying Hamstring Curl. 3. Keep your elbows in a fixed position throughout the movement. 4. Curl the weight up by contracting your biceps, squeezing at the top. 5. Lower with control, resisting the weight on the way down. 6. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'leg_curl', 'Lying Hamstring Curl', 'romanian_deadlift, hip_thrust', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('2395a9ee-daef-4d5e-a62f-06ca3589d683', 'Seated Lumbar Extension Flexion (Stability Ball)', 'Core', 'Stability Ball', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'This extension exercise engages your core for improved core stability and strength. The seated position helps isolate the target muscles by removing momentum. The stability ball adds an instability challenge that activates more stabilizer muscles. Core strength is foundational for athletic performance and injury prevention.', '84711201', '84711201-Seated-Lumbar-Extension-Flexion-on-Stability-Ball-.mp4', 'female', FALSE, '2025-12-03 23:26:36.717157+00', '1. Position the stability ball as needed for Seated Lumbar Extension Flexion. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Extend through the target joint(s) for Seated Lumbar Extension Flexion. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Seated', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 64, 5, 7, FALSE, TRUE, 'general_exercise', 'Seated Lumbar Extension Flexion', 'plank, crunch, leg_raise', FALSE, 'stability_ball', FALSE, 3, 60, 2, 70, 88, 95, 65),
('23a53438-03e3-4f43-b577-6e53b9c62dfc', 'PVC Overhead Squat', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This squatting movement emphasizes your quadriceps for stronger, more powerful legs. Your glutes, hamstrings work as secondary movers, adding to the training stimulus. Leg training boosts metabolism and builds functional, real-world strength. Can be modified for beginners or progressed for advanced athletes.', '46061201', '46061201-PVC-Overhead-Squat_Thighs.mp4', 'male', FALSE, '2025-12-03 23:26:26.39056+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. 4. Continue for your target rep count, maintaining good form throughout. Keep the movement smooth and controlled. This variation specifically emphasizes the quads.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'squat', 'PVC Overhead Squat', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('23a57604-4370-49a1-ac23-aedfa5294362', 'One Side Archer Push Up', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'Build a stronger chest with this pushing movement that develops pressing power. Secondary activation of your triceps, front delts provides additional muscle engagement. A versatile bodyweight movement perfect for home or gym training. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '41531201', '41531201-One-Side-Archer-Push-up_Chest.mp4', 'male', FALSE, '2025-12-03 23:26:22.938497+00', '1. Keep your body in a straight line from head to heels throughout. 2. Lower your chest toward the floor by bending your elbows. 3. Push through your palms to return to the starting position. 4. Repeat for the prescribed number of repetitions. Ensure full range of motion on each rep.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'push_up', 'One Side Archer Push Up', 'bench_press, chest_fly, dip', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('23b44c07-13ad-4bb9-8944-04edf43fb10b', 'Diagonal Lunge', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build power and athleticism with this high-intensity lunging exercise that challenges your entire body. The glutes, hamstrings assist throughout the movement, making this a well-rounded exercise. A versatile bodyweight movement perfect for home or gym training. Plyometric training builds explosive power that transfers to sports and daily activities.', '45521201', '45521201-Diagonal-Lunge_Plyometrics.mp4', 'male', FALSE, '2025-12-03 23:26:23.987963+00', '1. Step forward into a lunge until both knees are at about 90 degrees. 2. Push through your front/working leg to return to the starting position. 3. Complete all reps with control before resting. Ensure full range of motion on each rep.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'lunge', 'Diagonal Lunge', 'split_squat, step_up, squat', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('23c444fb-e668-420a-b305-5d237e324132', 'Spine (lumbar) Flexion', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Strengthen your midsection with this flexion movement that works your abs. No equipment needed—your body provides all the resistance. Core strength is foundational for athletic performance and injury prevention.', '88401201', '88401201-Spine-(Lumbar)---Flexion-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:38.153182+00', '1. Set up in the starting position for SpineFlexion. 2. Execute the movement with proper form, focusing on your abs. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'cycling', 'Spine Flexion', 'Spine Flexion', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('23e0f9ca-d39e-4f39-aecf-a91755746952', 'Side Plank', 'Core', 'Bodyweight', '{"Core","Abs"}'::text[], '{"Shoulders"}'::text[], 'The Side Plank is a core stabilization exercise that primarily targets your abs. Your shoulders, lower back work as secondary movers, adding to the training stimulus. A versatile bodyweight movement perfect for home or gym training. A strong core improves posture, protects your spine, and enhances all other lifts.', '7151201', '07151201-Side-Plank-(male)_Waist-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:21.452942+00', '1. Hold your body in a straight line from head to heels. 2. Don''t let your hips sag or pike up—engage your core and glutes. 3. Breathe steadily while maintaining the position. 4. Repeat for the prescribed number of repetitions. Exhale during the exertion phase of the movement.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'side_plank', 'Side Plank', 'plank, russian_twist, woodchop', FALSE, 'bodyweight', TRUE, 3, 90, 4, 70, 88, 95, 65),
('23e1719b-917b-4f68-8a58-564de1537c44', 'Seated Dynamic Jabs (Chair)', 'Core', 'Chair', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build power and athleticism with this high-intensity movement exercise that challenges your entire body. The shoulders, core assist throughout the movement, making this a well-rounded exercise. Being seated provides stability, allowing you to focus on the working muscles. Plyometric training builds explosive power that transfers to sports and daily activities.', '104841201', '104841201-Seated-Dynamic-Jabs-on-Chair-(male)_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:23.987963+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Repeat for the prescribed number of repetitions. Focus on maintaining proper breathing throughout. Include this in your plyometrics training.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 37, 7, 8, TRUE, TRUE, 'boxing', 'Seated Dynamic Jabs On Chair', 'core_exercise, shoulder_exercise, burpee', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('23e41428-de70-4442-84e5-4f456691ebd4', 'Hip Abduction (Machine)', 'Legs', 'Machine', '{"Glutes"}'::text[], '{"Hip Abductors"}'::text[], 'The Lever Seated Hip Abduction is a lower body movement exercise that targets your glute med/abductors. Your glutes work as secondary movers, adding to the training stimulus. The seated position helps isolate the target muscles by removing momentum. The fixed path allows you to focus purely on muscular effort. Strong legs are the foundation for athletic performance and functional fitness.', '18691201', '18691201-Lever-Seated-Hip-Abduction-(Version-2)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:27.145158+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Seated Hip Abduction. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Complete all reps with control before resting. Maintain a neutral spine throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 60, 7, 8, TRUE, TRUE, 'hip_abduction', 'Lever Seated Hip Abduction', 'hip_adduction, glute_bridge, clamshell', TRUE, 'machine', FALSE, 3, 90, 4, 80, 75, 20, 88),
('23ef2873-a66d-4149-89e6-45901c5b48ff', 'Front And Back Neck Stretch', 'Neck', 'Bodyweight', '{"Neck"}'::text[], '{"Traps"}'::text[], 'The Front And Back Neck Stretch is a flexibility exercise that targets your neck, helping to release tension and improve range of motion. Flexibility work like this enhances performance and prevents stiffness.', '4621201', '04621201-Front-and-Back-Neck-Stretch_Neck_.mp4', 'male', FALSE, '2025-12-03 23:26:20.392006+00', '1. Move into the stretch position for Front And Back Neck Stretch. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'neck_stretch', 'Front And Back Neck Stretch', 'stretch_hip, stretch_hamstring, stretch_shoulder', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('23ef8812-aecb-4244-a4ef-f77aab2f73a5', 'Russian Twist With Legs Off Floor (Dumbbell)', 'Core', 'Dumbbells', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'Build rotational power and define your waistline with the Dumbbell Russian Twist With Legs Floor Off (versio. The abs assist throughout the movement, making this a well-rounded exercise. Using dumbbells requires more stabilization than barbell variations. Core strength is foundational for athletic performance and injury prevention.', '80481201', '80481201-Dumbbell-Russian-Twist-with-Legs-Floor-Off-(VERSIO.mp4', 'female', FALSE, '2025-12-03 23:26:33.034396+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Russian Twist With Legs Floor Off (versio. 2. Position yourself on the floor for Dumbbell Russian Twist With Legs Floor Off (versio. 3. Rotate your torso through the movement pattern for Dumbbell Russian Twist With Legs Floor Off (versio. 4. Control the rotation in both directions—avoid using momentum. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 39, 5, 7, FALSE, TRUE, 'russian_twist', 'Russian Twist With Legs Floor Off', 'crunch, plank, leg_raise, wood_chop', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('23f38a50-f496-4396-9b61-7c7295aa1dbf', 'Lying Knee Flexion And Extension (Stability Ball)', 'Core', 'Stability Ball', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Strengthen your midsection with this extension movement that works your core. Performing this lying down removes momentum for stricter form. The stability ball adds an instability challenge that activates more stabilizer muscles. Core strength is foundational for athletic performance and injury prevention.', '100611201', '100611201-Lying-Knee-Flexion-and-Extension-on-Exercise-Ball.mp4', 'female', FALSE, '2025-12-03 23:26:35.250398+00', '1. Position the stability ball as needed for Lying Knee Flexion And Extension. 2. Lie down in the appropriate position for Lying Knee Flexion And Extension. 3. Extend through the target joint(s) for Lying Knee Flexion And Extension. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 62, 5, 7, FALSE, TRUE, 'general_exercise', 'Lying Knee Flexion And Extension', 'squat, leg_extension, lunge', FALSE, 'stability_ball', FALSE, 3, 60, 2, 70, 88, 95, 65),
('23f708ce-9a90-475b-8c13-47c7d80d17e8', 'Seated Legs Extended To Butterfly Stretch', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Seated Legs Extended To Butterfly Stretch provides a deep stretch for your adductors, ideal for recovery and mobility work. You''ll also feel your hips working to support the movement. The seated position helps isolate the target muscles by removing momentum. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '95321201', '95321201-Sitting-Legs-Extended-to-Butterfly-Stretch-(female.mp4', 'female', FALSE, '2025-12-03 23:26:37.756436+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. With a slight bend in your elbows, move the weight in a wide arc. 3. Squeeze your chest muscles at the center/top of the movement. 4. Return with control, feeling the stretch at the bottom. Keep tension on the target muscles throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 60, 2, 6, FALSE, TRUE, 'groin_stretch', 'Seated Legs Extended To Butterfly Stretch', 'stretch_hip, stretch_back, stretch_shoulder', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('23faa70a-8861-4fda-944d-1375dcb53a95', 'Side Step Tip Toes', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build power and athleticism with this high-intensity stepping exercise that challenges your entire body. You''ll also feel your quads working to support the movement. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '77041201', '77041201-Side-Step-Tip-Toes-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:37.303932+00', '1. Set up a box or step platform at the appropriate height. 2. Set up in the starting position for Side Step Tip Toes. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'calf_raise', 'Side Step Tip Toes', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('23fc6394-3bf0-46a1-8422-d97da309ebc1', 'Arms Stretch On A Support', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'The Arms Stretch On A Support provides a deep stretch for your full body, ideal for recovery and mobility work. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '18171201', '18171201-Arms-Stretch-On-a-Support_Upper-Arms_.mp4', 'male', FALSE, '2025-12-03 23:26:22.644637+00', '1. Move into the stretch position for Arms Stretch On A Support. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'stretch_general', 'Arms Stretch On A Support', 'stretch_hip, stretch_back, stretch_shoulder', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('240883ec-b2bb-47a1-b49b-fa64051938ea', 'Lying Shoulder Flexion Extension', 'Shoulders', 'Bodyweight', '{"Shoulders"}'::text[], '{"Traps"}'::text[], 'The Lying Shoulder Flexion Extension is a extension exercise that targets your delts for shoulder development. The lying position provides back support and helps isolate the target muscles. No equipment needed—your body provides all the resistance. Shoulder development enhances both performance and upper body aesthetics.', '72921201', '72921201-Lying-Shoulder-Flexion-Extension-(female)_Shoulder.mp4', 'female', FALSE, '2025-12-03 23:26:35.38119+00', '1. Lie down in the appropriate position for Lying Shoulder Flexion Extension. 2. Extend through the target joint(s) for Lying Shoulder Flexion Extension. 3. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'shoulder_exercise', 'Lying Shoulder Flexion Extension', 'lateral_raise, shoulder_press, front_raise', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('2411472d-70c9-4a32-aba1-685ccb2e7ee3', 'Pull Up - Wide Grip (Pull-Up Bar)', 'Back', 'Pull-Up Bar', '{"Lats","Upper Back"}'::text[], '{"Biceps","Rear Delts"}'::text[], 'This pulling exercise emphasizes your lats for improved back development. The biceps, upper back assist throughout the movement, making this a well-rounded exercise. This bodyweight exercise requires no equipment and can be done anywhere. Back development is crucial for pulling strength and overall upper body function. Progress gradually by increasing resistance over time.', '36271201', '36271201-Wide-Grip-Pull-Up-(female)_Back.mp4', 'female', FALSE, '2025-12-03 23:26:40.037451+00', '1. Use a wide grip (wider than shoulder-width) for this variation. 2. Pull yourself up by driving your elbows down and back. 3. Continue until your chin clears the bar, then lower with control to a full hang. 4. Complete all reps with control before resting. Don''t rush—quality over quantity.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'pullup', 'Pull Up - Wide Grip', 'Pull Up - Wide Grip', TRUE, 'pull_up_bar', FALSE, 3, 90, 4, 70, 88, 95, 65),
('24199b11-c336-4049-937d-1fd7d46e337e', 'Lying Leg Curl (Band)', 'Legs', 'Resistance Band', '{"Hamstrings"}'::text[], '{"Glutes"}'::text[], 'Strengthen the back of your thighs with this curling exercise. Secondary activation of your calves provides additional muscle engagement. Performing this lying down removes momentum for stricter form. Resistance bands provide accommodating resistance that increases through the range of motion. Leg training boosts metabolism and builds functional, real-world strength.', '9111201', '09111201-Band-Lying-Leg-Curl-(female)_Thighs_.mp4', 'female', FALSE, '2025-12-03 23:26:30.887491+00', '1. Secure the resistance band appropriately for Band Lying Leg Curl. 2. Lie down in the appropriate position for Band Lying Leg Curl. 3. Curl your heels toward your glutes by bending at the knees. 4. Squeeze your hamstrings at peak contraction. 5. Extend legs back out with control. 6. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'leg_curl', 'Lying Leg Curl', 'romanian_deadlift, hip_thrust', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('242be86a-6f28-4ba0-bc91-e76c4e52ec4d', 'Glute Bridge Single Leg On Floor (Bent Knee)', 'Legs', 'Bodyweight', '{"Glutes"}'::text[], '{"Hamstrings"}'::text[], 'Develop your posterior chain with this bridging movement that emphasizes the glutes. You''ll also feel your hamstrings working to support the movement. No equipment needed—your body provides all the resistance. Strong legs are the foundation for athletic performance and functional fitness. A staple exercise that belongs in most training programs.', '24751201', '24751201-Glute-Bridge-One-Leg-on-Floor-(bent-knee)-(female).mp4', 'female', FALSE, '2025-12-03 23:26:33.778367+00', '1. Position yourself on the floor for Glute Bridge One Leg On Floor. 2. Drive through your heels to lift your hips toward the ceiling. 3. Squeeze your glutes hard at the top of the movement. 4. Lower your hips back down with control. 5. Complete all reps on one side, then switch to the other side. 6. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 60, 7, 8, TRUE, TRUE, 'glute_bridge', 'Glute Bridge Single Leg On Floor', 'hip_thrust, romanian_deadlift', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('2434b905-472a-4d9e-b067-8c2cefa2fc25', 'Bent Over Rear Delt Fly', 'Shoulders', 'Bodyweight', '{"Rear Delts"}'::text[], '{"Upper Back","Traps"}'::text[], 'Build stronger shoulders with this flying movement focusing on your rear delts. Secondary activation of your upper back provides additional muscle engagement. The bent over position requires core engagement to maintain a neutral spine. A versatile bodyweight movement perfect for home or gym training. Shoulder development enhances both performance and upper body aesthetics.', '87621201', '87621201-Bodyweight-Bent-Over-Rear-Delt-Fly-(female)_Should.mp4', 'female', FALSE, '2025-12-03 23:26:31.347577+00', '1. Hinge at your hips, pushing them back while keeping your back flat. 2. With a slight bend in your elbows, move the weight in a wide arc. 3. Squeeze your chest muscles at the center/top of the movement. 4. Return with control, feeling the stretch at the bottom. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'rear_delt', 'Bent Over Rear Delt Fly', 'bench_press, incline_bench_press, push_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('24378401-b9c8-4e45-ae8f-d989621b083c', 'Seated Leg Raise', 'Core', 'Bodyweight', '{"Lower Abs"}'::text[], '{"Hip Flexors"}'::text[], 'This raising exercise engages your abs for improved core stability and strength. Secondary activation of your hip flexors provides additional muscle engagement. Being seated provides stability, allowing you to focus on the working muscles. Building core stability helps with everything from heavy deadlifts to daily activities.', '6891201', '06891201-Seated-Leg-Raise_waist.mp4', 'male', FALSE, '2025-12-03 23:26:27.384461+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Keeping legs mostly straight, raise them toward the ceiling. 3. Lower with control, stopping just before touching down. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Seated', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 72, 5, 7, FALSE, TRUE, 'leg_raise', 'Seated Leg Raise', 'crunch, plank, v_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('24402a9f-7867-480d-84e7-19769f4a9f4e', 'Seated Bicep Curl - Inner (Dumbbell)', 'Arms', 'Dumbbells, Flat Bench', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'Build bigger biceps with this curling movement that targets the front of your arms. Secondary activation of your forearms provides additional muscle engagement. Being seated provides stability, allowing you to focus on the working muscles. Dumbbells allow each arm to work independently, helping correct imbalances. Dedicated arm training builds both strength and muscular definition.', '3931201', '03931201-Dumbbell-Seated-Inner-Biceps-Curl_Upper-Arms_.mp4', 'male', FALSE, '2025-12-03 23:26:30.099411+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Seated Inner Biceps Curl. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Keep your elbows in a fixed position throughout the movement. 4. Curl the weight up by contracting your biceps, squeezing at the top. 5. Lower with control, resisting the weight on the way down. 6. Continue for your target rep count, maintaining good form throughout.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Seated', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 94, 5, 7, FALSE, TRUE, 'bicep_curl', 'Seated Inner Biceps Curl', 'hammer_curl, preacher_curl, cable_curl', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90);
INSERT INTO _exercise_staging (id, name, category, equipment, primary_muscles, secondary_muscles, description, video_code, video_filename, gender, is_custom, created_at, steps_to_perform, movement_pattern, force_type, movement_type, laterality, plane_of_motion, difficulty_level, complexity_score, strength_rating, hypertrophy_rating, power_rating, endurance_rating, body_position, bench_angle, grip_type, grip_width, optimal_rep_range_min, optimal_rep_range_max, placement_in_workout, fatigability, popularity_score, home_gym_friendly, instructions, workout_type, practicality_score, fat_loss_rating, general_fitness_rating, is_compound, supersetable, exercise_family, base_exercise_name, complementary_families, is_equipment_primary, equipment_category, duration_based, recommended_sets, rest_seconds, muscles_worked_count, priority_build_muscle, priority_get_lean, priority_home, priority_gym) VALUES
('24565c82-7d6d-4122-8ede-d167303d0eaa', 'Incline Hammer Chest Press (Machine)', 'Chest', 'Machine', '{"Chest"}'::text[], '{"Front Delts","Triceps"}'::text[], 'Build a stronger chest with this pressing movement that develops pressing power. Your triceps, front delts work as secondary movers, adding to the training stimulus. Using an incline changes the angle of resistance for varied muscle recruitment. The machine guides your movement path for safer, more controlled repetitions. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '36081201', '36081201-Lever-Incline-Hammer-Chest-Press-(female)_Chest.mp4', 'female', FALSE, '2025-12-03 23:26:34.724336+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Incline Hammer Chest Press. 2. Use a hammer/neutral grip with palms facing each other throughout. 3. Lower the weight toward your chest with control. 4. Press the weight up until your arms are extended (don''t lock elbows). 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 81, 7, 8, TRUE, TRUE, 'incline_press', 'Lever Incline Hammer Chest Press', 'bench_press, shoulder_press, chest_fly', FALSE, 'machine', FALSE, 3, 90, 4, 80, 75, 20, 88),
('2461c17f-0c5e-4fdf-8a89-0c3b7bc7edcd', 'Standing Hands Up Knee Tap', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Elevate your training with this movement exercise that develops speed, power, and coordination. Performing this standing challenges your balance and core engagement. A versatile bodyweight movement perfect for home or gym training. Plyometric training builds explosive power that transfers to sports and daily activities.', '89801201', '89801201-Standing-Hands-Up-Knee-Tap-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:38.7451+00', '1. Begin in a standing position with good posture. 2. Set up in the starting position for Standing Hands Up Knee Tap. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'general_exercise', 'Standing Hands Up Knee Tap', 'squat, leg_extension, lunge', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('246234a7-9236-4f5c-a6ef-770a7dbc9069', 'Walking Lunge', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Walking Lunge is a lunging exercise that primarily loads your quadriceps. The glutes, hamstrings assist throughout the movement, making this a well-rounded exercise. This bodyweight exercise requires no equipment and can be done anywhere. Lower body strength improves everything from walking to heavy compound lifts.', '38111201', '38111201-Walking-Lunge-(female)_Thighs-FIX_.mp4', 'female', FALSE, '2025-12-03 23:26:39.91585+00', '1. Step forward into a lunge, then bring your back foot forward for the next step. 2. Push through your front/working leg to return to the starting position. 3. Repeat for the prescribed number of repetitions. Start with lighter weight to perfect your form.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 2, 2, NULL, 10, NULL, NULL, NULL, NULL, 1, 1, NULL, 3, NULL, TRUE, NULL, 'Cardio', 70, 9, 8, FALSE, TRUE, 'lunge', 'Walking Lunge', 'split_squat, step_up, squat', FALSE, 'bodyweight', TRUE, 1, 60, 4, 70, 88, 95, 65),
('2463649f-d9b1-42b4-b011-cac2a187ee61', 'Mixed Grip Chin Up (Pull-Up Bar)', 'Back', 'Pull-Up Bar', '{"Lats"}'::text[], '{"Biceps","Upper Back"}'::text[], 'This movement exercise emphasizes your lats for improved back development. Secondary activation of your biceps provides additional muscle engagement. No equipment needed—your body provides all the resistance. Back development is crucial for pulling strength and overall upper body function.', '6271201', '06271201-Mixed-Grip-Chin-up_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:27.504261+00', '1. Pull yourself up, focusing on bicep and lat engagement. 2. Raise until chin is over the bar, lower with full control. 3. Complete all reps with control before resting. Keep your core engaged for stability.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'pull_up', 'Mixed Grip Chin Up', 'lat_pulldown, bent_over_row, bicep_curl', TRUE, 'pull_up_bar', FALSE, 3, 90, 4, 70, 88, 95, 65),
('2468962b-4fa2-46fa-8cd7-d24a889d880a', 'Mountain Climber Walk', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors","Shoulders"}'::text[], 'This dynamic climbing movement gets your heart rate up while developing explosive strength. You''ll also feel your hip flexors, shoulders working to support the movement. A versatile bodyweight movement perfect for home or gym training. Great for improving athletic performance, burning calories, and building conditioning.', '51161201', '51161201-Mountain-Climber-Walk-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:35.532804+00', '1. From plank position, drive one knee toward your chest. 2. Quickly switch legs, bringing the other knee forward. 3. Continue alternating at a quick pace while maintaining plank form. 4. Continue for your target rep count, maintaining good form throughout. Focus on maintaining proper breathing throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 50, 9, 8, TRUE, TRUE, 'mountain_climber', 'Mountain Climber Walk', 'burpee, plank, high_knees', TRUE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('246b4f2d-8fd3-4a13-9e24-b8fe76960a47', 'Standing Elbow Clap', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{}'::text[], 'Target your chest with the Standing Elbow Clap, an effective movement movement for upper body strength. Performing this standing challenges your balance and core engagement. This bodyweight exercise requires no equipment and can be done anywhere. A well-developed chest contributes to upper body strength and aesthetics.', '53631201', '53631201-Standing-Elbow-Clap-(female)_Chest_.mp4', 'female', FALSE, '2025-12-03 23:26:38.570929+00', '1. Begin in a standing position with good posture. 2. Set up in the starting position for Standing Elbow Clap. 3. Execute the movement with proper form, focusing on your chest. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'boxing', 'Standing Elbow Clap', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('248793b3-43b3-4bd4-a30e-1347b14fa972', 'Half Kneeling Side Lunge', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Inner Thighs"}'::text[], 'The Half Kneeling Side Lunge provides a deep stretch for your quads, ideal for recovery and mobility work. The glutes, hamstrings assist throughout the movement, making this a well-rounded exercise. The kneeling position adds a core stability challenge. Flexibility work like this enhances performance and prevents stiffness.', '87771201', '87771201-Half-Kneeling-Side-Lunge-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:33.778367+00', '1. Get into a half-kneeling position (one knee down, opposite foot forward). 2. Step to the side, bending that knee while keeping the other leg straight. 3. Push through your front/working leg to return to the starting position. Exhale during the exertion phase of the movement.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'lunge', 'Half Kneeling Side Lunge', 'split_squat, step_up, squat', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('248a71b4-9ba5-4ffb-9f0b-ab048961f5e2', 'Low Row - Single Arm (Plate Loaded Machine)', 'Back', 'Machine', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'The Lever One Arm Low Row (plate Loaded) is a rowing exercise that builds thickness in your upper back. Your biceps, rear delts work as secondary movers, adding to the training stimulus. The fixed path allows you to focus purely on muscular effort. Back development is crucial for pulling strength and overall upper body function.', '42151201', '42151201-Lever-One-Arm-Low-Row-(plate-loaded)_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:20.392006+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever One Arm Low Row. 2. Pull the weight toward your torso, leading with your elbow(s). 3. Squeeze your shoulder blades together at the peak contraction. 4. Extend back out with control, feeling the stretch in your back. 5. Complete all reps on one side, then switch to the other side. 6. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 8, NULL, FALSE, NULL, 'Strength', 73, 7, 9, TRUE, FALSE, 'cable_row', 'Lever Single Arm Low Row', 'bent_over_row, lat_pulldown, bicep_curl', FALSE, 'machine', FALSE, 4, 120, 4, 80, 75, 20, 88),
('2493eb5b-e945-493a-b85f-1f0b46dc1dcb', 'Wheel Rollout (Ab Wheel)', 'Core', 'Ab Wheel', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Wheel Rollout is a core movement exercise that primarily targets your abs. You''ll also feel your lats, shoulders working to support the movement. A strong core improves posture, protects your spine, and enhances all other lifts.', '8571201', '08571201-Wheel-Rollout_Waist-FIX2_.mp4', 'male', FALSE, '2025-12-03 23:26:20.392006+00', '1. Set up in the starting position for Wheel Rollout. 2. Execute the movement with proper form, focusing on your abs. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting. Start with lighter weight to perfect your form.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'ab_rollout', 'Wheel Rollout', 'plank, crunch, dead_bug', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('24987eb8-0215-419d-99ec-d64896f62c03', 'Seated Hip Swirl (Chair) - Alternating', 'Core', 'Chair', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build leg strength with this movement movement focusing on your core. The seated position helps isolate the target muscles by removing momentum. Lower body strength improves everything from walking to heavy compound lifts. Progress gradually by increasing resistance over time.', '82841201', '82841201-Seated-Alternate-Hip-Swirl-on-a-Chair-(female)_Hip.mp4', 'female', FALSE, '2025-12-03 23:26:36.581585+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Alternate between sides/arms/legs with each repetition. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 37, 7, 8, TRUE, TRUE, 'glute_exercise', 'Seated Hip Swirl On A Chair - Alternating', 'hip_thrust, lunge, squat', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('24a41760-64b5-43fd-a1fb-560b7a63e238', 'Wood Chop (Dumbbell)', 'Core', 'Dumbbells', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Work your side abdominals with this movement exercise that strengthens your obliques. You''ll also feel your shoulders working to support the movement. Dumbbells allow each arm to work independently, helping correct imbalances. A strong core improves posture, protects your spine, and enhances all other lifts.', '80241201', '80241201-Dumbbell-Wood-Chop-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:21.109351+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Wood Chop. 2. Set up in the starting position for Dumbbell Wood Chop. 3. Execute the movement with proper form, focusing on your obliques. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 62, 9, 8, TRUE, TRUE, 'woodchop', 'Wood Chop', 'russian_twist, pallof_press, cable_crunch', FALSE, 'dumbbell', FALSE, 3, 60, 4, 92, 90, 92, 90),
('24a784f2-6e5d-4605-938b-679f01c86bc6', 'Front Step Criss Cross Arms', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Front Step Criss Cross Arms is an explosive exercise that combines cardiovascular training with dynamic stepping movements. Your quads work as secondary movers, adding to the training stimulus. Great for improving athletic performance, burning calories, and building conditioning.', '88271201', '88271201-Front-Step-Criss-Cross-Arms-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:33.640031+00', '1. Set up a box or step platform at the appropriate height. 2. Set up in the starting position for Front Step Criss Cross Arms. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'boxing', 'Front Step Criss Cross Arms', 'bicep_curl, tricep_extension, hammer_curl', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('24beb87b-46cb-48d3-8b50-1f64df93356e', 'Arm Curl (TRX)', 'Arms', 'TRX', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'The Suspender Arm Curl is a curling exercise that isolates your biceps. Secondary activation of your forearms provides additional muscle engagement. Suspension training adds instability, increasing core activation throughout. Dedicated arm training builds both strength and muscular definition.', '59261201', '59261201-Suspender-Arm-Curl-(male)_Upper-Arms_.mp4', 'male', FALSE, '2025-12-03 23:26:23.689343+00', '1. Adjust the TRX/suspension straps to the appropriate length for Suspender Arm Curl. 2. Keep your elbows in a fixed position throughout the movement. 3. Curl the weight up by contracting your biceps, squeezing at the top. 4. Lower with control, resisting the weight on the way down. 5. Repeat for the prescribed number of repetitions. Maintain a neutral spine throughout.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 60, 5, 7, FALSE, TRUE, 'bicep_curl', 'Suspender Arm Curl', 'hammer_curl, preacher_curl, cable_curl', FALSE, 'trx', FALSE, 3, 60, 2, 68, 85, 85, 70),
('24c822f2-45b7-41b4-ad05-6c5db0656493', 'Incline Single Arm Press (Stability Ball, Dumbbell)', 'Chest', 'Dumbbells, Stability Ball, Incline Bench', '{"Chest"}'::text[], '{"Triceps","Upper Chest"}'::text[], 'This pressing exercise focuses on your pectorals for improved chest strength and development. You''ll also feel your triceps working to support the movement. Using an incline changes the angle of resistance for varied muscle recruitment. The dumbbell variation provides freedom of movement and greater range of motion. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '12821201', '12821201-Dumbbell-Incline-One-Arm-Press-on-Exercise-Ball_Ch.mp4', 'male', FALSE, '2025-12-03 23:26:29.483269+00', '1. Select an appropriate weight dumbbell and hold it in one hand. 2. Lower the weight toward your chest with control. 3. Press the weight up until your arms are extended (don''t lock elbows). 4. Complete all reps on one side, then switch to the other side. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 4, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 72, 7, 8, TRUE, TRUE, 'arm_exercise', 'Incline Single Arm Press On Exercise Ball', 'bench_press, chest_fly, shoulder_press, decline_bench_press', FALSE, 'dumbbell', FALSE, 3, 90, 4, 92, 90, 92, 90),
('24c83ad3-6900-4e80-acde-8a440f205e4b', 'Lying Triceps Extension On Floor (Dumbbell)', 'Arms', 'Dumbbells', '{"Triceps"}'::text[], '{"Chest","Shoulders"}'::text[], 'This extension movement isolates your triceps for improved arm development. Performing this lying down removes momentum for stricter form. Using dumbbells requires more stabilization than barbell variations. Dedicated arm training builds both strength and muscular definition.', '91981201', '91981201-Dumbbell-Lying-Triceps-Extension-on-Floor-(VERSION.mp4', 'female', FALSE, '2025-12-03 23:26:32.914483+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Lying Triceps Extension On Floor (version. 2. Position yourself on the floor for Dumbbell Lying Triceps Extension On Floor (version. 3. Lie down in the appropriate position for Dumbbell Lying Triceps Extension On Floor (version. 4. Extend at the elbow until your arm is straight, squeezing the tricep. 5. Lower with control, keeping your upper arm stationary. 6. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 69, 5, 7, FALSE, TRUE, 'tricep_extension', 'Lying Triceps Extension On Floor', 'tricep_pushdown, close_grip_bench', FALSE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('24dda1d3-2663-4a8d-909f-a8199e0f019c', 'Negative Biceps Leg Concentration Curl', 'Arms', 'Bodyweight', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'This curling exercise focuses on your biceps for improved arm size and strength. Secondary activation of your forearms provides additional muscle engagement. This bodyweight exercise requires no equipment and can be done anywhere. Arm strength supports grip, pulling, and pushing in compound movements.', '68531201', '68531201-Negative-Biceps-Leg-Concentration-Curl_Upper-Arms_.mp4', 'male', FALSE, '2025-12-03 23:26:27.504261+00', '1. Curl your heels toward your glutes by bending at the knees. 2. Squeeze your hamstrings at peak contraction. 3. Extend legs back out with control. 4. Focus on a slow, controlled lowering phase (3-5 seconds). 5. Complete all reps with control before resting.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 80, 5, 7, FALSE, TRUE, 'concentration_curl', 'Negative Biceps Leg Concentration Curl', 'tricep_pushdown, tricep_extension, bicep_curl, hammer_curl', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('24f1fc0c-29d8-4eea-8daa-5fc169cb33ba', 'Side Step Reverse Fly', 'Shoulders', 'Bodyweight', '{"Rear Delts"}'::text[], '{"Upper Back","Traps"}'::text[], 'Build power and athleticism with this high-intensity flying exercise that challenges your entire body. You''ll also feel your upper back working to support the movement. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '97711201', '97711201-Side-Step-Reverse-Fly-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:24.577164+00', '1. Set up a box or step platform at the appropriate height. 2. With a slight bend in your elbows, move the weight in a wide arc. 3. Squeeze your chest muscles at the center/top of the movement. 4. Return with control, feeling the stretch at the bottom. 5. Repeat for the prescribed number of repetitions. Ensure full range of motion on each rep.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'rear_delt', 'Side Step Reverse Fly', 'bench_press, incline_bench_press, push_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('24f299e7-20f3-47e1-b0b5-8e3fd260e8c8', 'Overhead Single Arm Triceps Extension (Band)', 'Arms', 'Resistance Band', '{"Triceps"}'::text[], '{"Shoulders"}'::text[], 'Build stronger triceps with this extension exercise for bigger arms. The band creates increasing tension as it stretches, challenging the lockout. Dedicated arm training builds both strength and muscular definition. Quality repetitions are more important than quantity.', '41401201', '41401201-Band-Overhead-Single-Arm-Triceps-Extension_Upper-A.mp4', 'male', FALSE, '2025-12-03 23:26:25.123298+00', '1. Secure the resistance band appropriately for Band Overhead Single Arm Triceps Extension. 2. Extend at the elbow until your arm is straight, squeezing the tricep. 3. Lower with control, keeping your upper arm stationary. 4. Complete all reps on one side, then switch to the other side. 5. Continue for your target rep count, maintaining good form throughout. Exhale during the exertion phase of the movement.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 80, 5, 7, FALSE, TRUE, 'tricep_extension', 'Overhead Single Arm Triceps Extension', 'tricep_pushdown, close_grip_bench', FALSE, 'band', FALSE, 3, 60, 2, 60, 85, 90, 50),
('25177f2a-424b-49df-8c8d-eb55373f8e56', 'Kneeling To Box Jump (Plyo Box)', 'Legs', 'Plyo Box', '{"Quads"}'::text[], '{"Glutes","Hamstrings","Calves"}'::text[], 'This dynamic jumping movement gets your heart rate up while developing explosive strength. Your quads, calves work as secondary movers, adding to the training stimulus. Kneeling helps eliminate lower body momentum from the movement. Plyometric training builds explosive power that transfers to sports and daily activities.', '107431201', '107431201-Kneeling-to-Box-Jump-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:24.698781+00', '1. Set up a box or step platform at the appropriate height. 2. Kneel on the floor (use a pad for comfort if needed). 3. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 4, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 50, 9, 8, TRUE, TRUE, 'box_jump', 'Kneeling To Box Jump', 'squat, burpee, broad_jump', TRUE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('251bd037-5cfc-4ccc-9288-96dee920eb76', 'Ear To Knee Side Bend', 'Core', 'Bodyweight', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'Build a stronger core with the Ear To Knee Side Bend, focusing on your abs. Your abs work as secondary movers, adding to the training stimulus. This bodyweight exercise requires no equipment and can be done anywhere. A strong core improves posture, protects your spine, and enhances all other lifts.', '64731201', '64731201-Ear-to-Knee-Side-Bend-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:20.847006+00', '1. Set up in the starting position for Ear To Knee Side Bend. 2. Execute the movement with proper form, focusing on your abs. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting. Engage your stabilizer muscles for better control.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'side_bend', 'Ear To Knee Side Bend', 'russian_twist, woodchop, oblique_crunch', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('25315e66-adef-4395-b158-2d42cfe0bc66', 'Standing Overhead Claps', 'Shoulders', 'Bodyweight', '{"Shoulders"}'::text[], '{"Traps"}'::text[], 'This movement exercise works your delts for improved shoulder strength and aesthetics. Performing this standing challenges your balance and core engagement. This bodyweight exercise requires no equipment and can be done anywhere. Shoulder development enhances both performance and upper body aesthetics.', '85781201', '85781201-Standing-Overhead-Claps-(male)_Shoulders_.mp4', 'male', FALSE, '2025-12-03 23:26:29.36063+00', '1. Stand tall with your feet firmly planted. 2. Set up in the starting position for Standing Overhead Claps. 3. Execute the movement with proper form, focusing on your delts. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'general_exercise', 'Standing Overhead Claps', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('253c1efb-566a-43d3-9514-d7952630bcdb', 'Sit Up (Stability Ball)', 'Core', 'Stability Ball', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Sit Up On Stability Ball is a core movement exercise that primarily targets your abs. You''ll also feel your hip flexors working to support the movement. Using a ball requires constant core engagement to maintain balance. A strong core improves posture, protects your spine, and enhances all other lifts.', '69651201', '69651201-Sit-up-on-stability-ball_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:22.123147+00', '1. Position the stability ball as needed for Sit Up On Stability Ball. 2. Set up in the starting position for Sit Up On Stability Ball. 3. Execute the movement with proper form, focusing on your abs. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 62, 5, 7, FALSE, TRUE, 'crunch', 'Sit Up On Stability Ball', 'leg_raise, plank, russian_twist, v_up', FALSE, 'stability_ball', FALSE, 3, 60, 2, 70, 88, 95, 65),
('253dc2e9-f70d-4e76-b80a-5b941249bc88', 'Figure 8 (Towel)', 'Full Body', 'Towel', '{"Full Body"}'::text[], '{}'::text[], 'The Figure 8 With Towels is an explosive exercise that combines cardiovascular training with dynamic movement movements. Great for improving athletic performance, burning calories, and building conditioning.', '83151201', '83151201-Figure-8-with-Towels_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:21.890719+00', '1. Set up in the starting position for Figure 8 With Towels. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 35, 7, 8, TRUE, TRUE, 'general_exercise', 'Figure 8 With Towels', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('254ba661-7217-4791-a008-da92622cadfa', 'Gates Close', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Gates Close is a lower body movement exercise that targets your hip abductors. A versatile bodyweight movement perfect for home or gym training. Lower body strength improves everything from walking to heavy compound lifts.', '105261201', '105261201-Gates-Close-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:23.172397+00', '1. Set up in the starting position for Gates Close. 2. Execute the movement with proper form, focusing on your hip abductors. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Gates Close', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('254c6b38-c877-4d5c-92b1-cc99c4e7cbca', 'Low Lunge To Hamstring Stretch (Gymnastic Rings)', 'Legs', 'Gymnastic Rings', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This stretch specifically works on your hamstrings, promoting flexibility and reducing muscle tightness. You''ll also feel your lower back working to support the movement. Regular stretching improves flexibility, reduces injury risk, and aids recovery. Keep your core engaged throughout the exercise.', '89701201', '89701201-Low-Lunge-to-Hamstring-Stretch-(male)_Stretching_.mp4', 'male', FALSE, '2025-12-03 23:26:21.249384+00', '1. Step forward into a lunge until both knees are at about 90 degrees. 2. Push through your front/working leg to return to the starting position. 3. Move into the stretch position for Low Lunge To Hamstring Stretch. 4. Ease into the stretch until you feel gentle tension (not pain). 5. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. Focus on the mind-muscle connection.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 48, 2, 6, FALSE, TRUE, 'hamstring_stretch', 'Low Lunge To Hamstring Stretch', 'squat, split_squat, step_up, leg_press', FALSE, 'gymnastic_rings', TRUE, 1, 30, 2, 68, 85, 85, 70),
('254e3bad-c43e-409b-a861-81da444776aa', 'Sprinter Lunge Stretch', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This stretch specifically works on your quads, promoting flexibility and reducing muscle tightness. You''ll also feel your glutes, hamstrings working to support the movement. Include this in your routine for better mobility and reduced muscle tension.', '97611201', '97611201-Sprinter-Lunge-Stretch-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:38.153182+00', '1. Step forward into a lunge until both knees are at about 90 degrees. 2. Push through your front/working leg to return to the starting position. 3. Move into the stretch position for Sprinter Lunge Stretch. 4. Ease into the stretch until you feel gentle tension (not pain). 5. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 60, 2, 6, FALSE, TRUE, 'hip_stretch', 'Sprinter Lunge Stretch', 'squat, split_squat, step_up, leg_press', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('25503efc-d4b3-4372-8d0f-18398bfaa48e', 'Mountain Climber And Dynamic Plank', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Shoulders","Lower Back"}'::text[], 'Strengthen your midsection with this stabilization movement that works your abs. The hip flexors, shoulders assist throughout the movement, making this a well-rounded exercise. A versatile bodyweight movement perfect for home or gym training. Core strength is foundational for athletic performance and injury prevention.', '68971201', '68971201-Mountain-Climber-and-Dynamic-Plank-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:35.532804+00', '1. Hold your body in a straight line from head to heels. 2. Don''t let your hips sag or pike up—engage your core and glutes. 3. Breathe steadily while maintaining the position. 4. Repeat for the prescribed number of repetitions. Engage your stabilizer muscles for better control. Include this in your core training.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 70, 9, 8, TRUE, TRUE, 'mountain_climber', 'Mountain Climber And Dynamic Plank', 'crunch, leg_raise, russian_twist, dead_bug', TRUE, 'bodyweight', TRUE, 3, 60, 4, 70, 88, 95, 65),
('255639fa-da92-4c05-a20f-47feb9047afe', 'Arms Forward And Behind The Neck', 'Shoulders', 'Bodyweight', '{"Shoulders"}'::text[], '{"Traps"}'::text[], 'The Arms Forward And Behind The Neck is a movement exercise that targets your delts for shoulder development. A versatile bodyweight movement perfect for home or gym training. Shoulder development enhances both performance and upper body aesthetics.', '76401201', '76401201-Arms-Forward-and-Behind-the-Neck-(male)_Shoulders_.mp4', 'male', FALSE, '2025-12-03 23:26:24.307972+00', '1. Set up in the starting position for Arms Forward And Behind The Neck. 2. Execute the movement with proper form, focusing on your delts. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'arm_exercise', 'Arms Forward And Behind The Neck', 'bicep_curl, tricep_extension, hammer_curl', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('25589fbd-372f-4e71-b8a6-d9f6e2afee2d', 'Incline T Raise (Band)', 'Shoulders', 'Resistance Band, Incline Bench', '{"Rear Delts"}'::text[], '{"Upper Back","Rotator Cuff"}'::text[], 'This raising exercise works your delts for improved shoulder strength and aesthetics. Using an incline changes the angle of resistance for varied muscle recruitment. Bands are joint-friendly and portable, perfect for any training environment. Strong shoulders improve overhead strength and support nearly all upper body movements.', '68661201', '68661201-Band-Incline-T-Raise_Shoulders_.mp4', 'male', FALSE, '2025-12-03 23:26:27.384461+00', '1. Secure the resistance band appropriately for Band Incline T Raise. 2. Raise the weight in the prescribed direction for Band Incline T Raise. 3. Lower with control, maintaining tension throughout. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 78, 5, 7, FALSE, TRUE, 'lateral_raise', 'Incline T Raise', 'shoulder_press, front_raise, rear_delt', FALSE, 'band', FALSE, 3, 60, 2, 60, 85, 90, 50),
('25591e61-543a-4108-ad5c-4ea9505a3920', 'Straight Back Seated Row (Band)', 'Back', 'Resistance Band, Anchor Point', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'This rowing exercise strengthens the muscles between your shoulder blades. Secondary activation of your biceps, lats provides additional muscle engagement. The seated position helps isolate the target muscles by removing momentum. Bands are joint-friendly and portable, perfect for any training environment. A strong back improves posture, prevents injury, and balances pressing movements.', '9291201', '09291201-Band-straight-back-seated-row-(female)_Back.mp4', 'female', FALSE, '2025-12-03 23:26:30.887491+00', '1. Secure the resistance band appropriately for Band Straight Back Seated Row. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Pull the weight toward your torso, leading with your elbow(s). 4. Squeeze your shoulder blades together at the peak contraction. 5. Extend back out with control, feeling the stretch in your back. 6. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 87, 7, 8, TRUE, TRUE, 'cable_row', 'Straight Back Seated Row', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('2562f88c-6a5b-4cb6-b0bb-08c62048d0d5', 'Lying Scalene Muscles Activation', 'Core', 'Bodyweight', '{"Neck"}'::text[], '{}'::text[], 'Strengthen your neck with this movement exercise for improved stability. Performing this lying down removes momentum for stricter form. A versatile bodyweight movement perfect for home or gym training. Include this exercise in your routine for balanced strength development.', '67531201', '67531201-Lying-Scalene-Muscles-Activation-(female)_Neck_.mp4', 'female', FALSE, '2025-12-03 23:26:35.250398+00', '1. Lie down in the appropriate position for Lying Scalene Muscles Activation. 2. Set up in the starting position for Lying Scalene Muscles Activation. 3. Execute the movement with proper form, focusing on your core. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'dynamic_warmup', 'Lying Scalene Muscles Activation', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('257c9e4f-ae86-41ff-9443-097b6d72e485', 'Squat Side Kick', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build stronger quads with this squatting movement that develops leg drive and power. Your glutes, hamstrings work as secondary movers, adding to the training stimulus. This bodyweight exercise requires no equipment and can be done anywhere. Strong legs are the foundation for athletic performance and functional fitness. Start with lighter weight to master the movement pattern.', '14001201', '14001201-Squat-side-kick-(female)_Hips.mp4', 'female', FALSE, '2025-12-03 23:26:38.285955+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. 4. Complete all reps with control before resting. Control the movement—avoid using momentum. Beneficial for overall legs development.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'squat', 'Squat Side Kick', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('25859a96-c13f-446a-afe6-e5d87e484b7a', 'Squat Press Down Twist', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This dynamic pressing movement gets your heart rate up while developing explosive strength. Secondary activation of your abs provides additional muscle engagement. A versatile bodyweight movement perfect for home or gym training. Great for improving athletic performance, burning calories, and building conditioning.', '57901201', '57901201-Squat-Press-Down-Twist-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:24.307972+00', '1. Execute the pressing motion for Squat Press Down Twist, extending through the target muscles. 2. Set up in the starting position for Squat Press Down Twist. 3. Execute the movement with proper form, focusing on your quads. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 85, 5, 7, FALSE, TRUE, 'tricep_pushdown', 'Squat Press Down Twist', 'tricep_extension, close_grip_bench, dip', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('25941c05-3265-4337-8b1c-753f5f701884', 'Standing Balance Hip Abduction (Resistance Band)', 'Legs', 'Resistance Band', '{"Glutes"}'::text[], '{"Hip Abductors"}'::text[], 'Build leg strength with this movement movement focusing on your hip abductors. Your glutes work as secondary movers, adding to the training stimulus. Performing this standing challenges your balance and core engagement. Bands are joint-friendly and portable, perfect for any training environment. Strong legs are the foundation for athletic performance and functional fitness.', '80851201', '80851201-Resistance-Band-Standing-Balance-Hip-Abduction-(ma.mp4', 'male', FALSE, '2025-12-03 23:26:25.991486+00', '1. Secure the resistance band appropriately for Resistance Band Standing Balance Hip Abduction. 2. Stand tall with your feet firmly planted. 3. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 57, 7, 8, TRUE, TRUE, 'hip_abduction', 'Standing Balance Hip Abduction', 'hip_adduction, glute_bridge, clamshell', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('25b6ddd8-05a0-4d9c-8545-11029cade519', 'Hands Hold Step Out', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'A challenging plyometric exercise, the Hands Hold Step Out builds reactive power and improves conditioning. Your quads work as secondary movers, adding to the training stimulus. Great for improving athletic performance, burning calories, and building conditioning.', '58681201', '58681201-Hands-Hold-Step-Out-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:33.960339+00', '1. Set up a box or step platform at the appropriate height. 2. Hold the position for the prescribed time, maintaining tension.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 45, 7, 8, TRUE, TRUE, 'step_up', 'Hands Hold Step Out', 'stretch_hip, dynamic_warmup, yoga_pose', FALSE, 'bodyweight', TRUE, 3, 90, 4, 70, 88, 95, 65),
('25c63b9f-3f7b-4b39-9521-5306ad5096d5', 'Seated Turn And Crunch', 'Core', 'Bodyweight', '{"Obliques"}'::text[], '{"Hip Flexors","Abs"}'::text[], 'This crunching exercise engages your abs for improved core stability and strength. You''ll also feel your hip flexors working to support the movement. The seated position helps isolate the target muscles by removing momentum. A strong core improves posture, protects your spine, and enhances all other lifts.', '78401201', '78401201-Seated-Turn-and-Crunch-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:36.848698+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Curl your shoulders off the floor by contracting your abs. 3. Don''t pull on your neck—focus on the abdominal contraction. 4. Lower with control, maintaining some tension. 5. Continue for your target rep count, maintaining good form throughout. Focus on squeezing the target muscle at peak contraction. Great for building strength in your abs.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Seated', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 72, 5, 7, FALSE, TRUE, 'crunch', 'Seated Turn And Crunch', 'leg_raise, plank, russian_twist, v_up', TRUE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('25d17434-94a2-466c-b733-5c2bef033daf', 'Walk Elliptical Cross Trainer (Elliptical)', 'Legs', 'Elliptical', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Walk Elliptical Cross Trainer is a cardiovascular exercise that improves endurance and heart health. Cardiovascular exercise improves heart health, endurance, and helps manage weight.', '36241201', '36241201-Walk-Elliptical-Cross-Trainer-(female)_Cardio.mp4', 'female', FALSE, '2025-12-03 23:26:39.91585+00', '1. Set up in the starting position for Walk Elliptical Cross Trainer. 2. Execute the movement with proper form, focusing on your cardio. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 2, 2, NULL, 10, NULL, NULL, NULL, NULL, 1, 1, NULL, 3, NULL, FALSE, NULL, 'Cardio', 50, 9, 8, FALSE, TRUE, 'elliptical', 'Walk Elliptical Cross Trainer', 'squat, bench_press, deadlift', FALSE, 'bodyweight', TRUE, 1, 60, 4, 70, 88, 95, 65),
('25d4b706-8ef3-4617-b114-f3b8c5c7b54e', 'Opposite Leg Raise', 'Core', 'Bodyweight', '{"Lower Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Opposite Leg Raise is a lower body raising exercise that targets your abs. Your hip flexors work as secondary movers, adding to the training stimulus. This bodyweight exercise requires no equipment and can be done anywhere. Leg training boosts metabolism and builds functional, real-world strength.', '82781201', '82781201-Opposite-Leg-Raise-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:35.667316+00', '1. Keeping legs mostly straight, raise them toward the ceiling. 2. Lower with control, stopping just before touching down. 3. Repeat for the prescribed number of repetitions. Maintain consistent tempo throughout the set.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'leg_raise', 'Opposite Leg Raise', 'crunch, plank, v_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('25d7a931-e0e5-47f3-b186-749076593d7d', 'Lying Knee Extension on Heels (Pilates Machine)', 'Legs', 'Pilates Machine', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Target the front of your thighs with this extension exercise for quad development. Performing this lying down removes momentum for stricter form. The machine guides your movement path for safer, more controlled repetitions. Leg training boosts metabolism and builds functional, real-world strength.', '106561201', '106561201-Pilates-Machine-Lying-Knee-Extension-on-Heels-(fe.mp4', 'female', FALSE, '2025-12-03 23:26:35.667316+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Pilates Machine Lying Knee Extension On Heels. 2. Lie down in the appropriate position for Pilates Machine Lying Knee Extension On Heels. 3. Extend through the target joint(s) for Pilates Machine Lying Knee Extension On Heels. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, FALSE, NULL, 'Strength', 78, 5, 7, FALSE, TRUE, 'leg_extension', 'Pilates Lying Knee Extension On Heels', 'Pilates Lying Knee Extension On Heels', FALSE, 'machine', FALSE, 3, 60, 2, 80, 75, 20, 88),
('25e57614-edbc-4779-ab86-9055de601b7e', 'Standing Shoulder Flexion With Rope - Alternating', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'This full-body flexion exercise challenges multiple muscle groups simultaneously. Performing this standing challenges your balance and core engagement. Full body exercises are time-efficient and build functional, real-world strength.', '91851201', '91851201-Standing-Alternating-Shoulder-Flexion-with-Rope-(f.mp4', 'female', FALSE, '2025-12-03 23:26:38.285955+00', '1. Stand tall with your feet firmly planted. 2. Alternate between sides/arms/legs with each repetition. 3. Continue for your target rep count, maintaining good form throughout. Keep the movement smooth and controlled.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'shoulder_exercise', 'Standing Shoulder Flexion With Rope - Alternating', 'lateral_raise, shoulder_press, front_raise', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('25ee028a-9414-4004-9038-ef0480ca752d', 'Single Arm Kickback (Dumbbell)', 'Arms', 'Dumbbells', '{"Triceps"}'::text[], '{"Rear Delts"}'::text[], 'This kicking movement isolates your triceps for improved arm development. Your hamstrings work as secondary movers, adding to the training stimulus. Dumbbells allow each arm to work independently, helping correct imbalances. Dedicated arm training builds both strength and muscular definition.', '23731201', '23731201-Dumbbell-One-Arm-Kickback-(female)_Upper-Arms_.mp4', 'female', FALSE, '2025-12-03 23:26:33.034396+00', '1. Select an appropriate weight dumbbell and hold it in one hand. 2. Keep your upper arm stationary and extend your forearm back. 3. Squeeze at full extension, then return with control. 4. Complete all reps on one side, then switch to the other side. 5. Complete all reps with control before resting. Maintain consistent tempo throughout the set.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 57, 5, 7, FALSE, TRUE, 'tricep_kickback', 'Single Arm Kickback', 'bicep_curl, tricep_extension, hammer_curl', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('25f553f0-b2d8-44c2-9e8c-2373af196d15', '21s (EZ Bar)', 'Arms', 'EZ Bar', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'This movement exercise focuses on your biceps for improved arm size and strength. You''ll also feel your forearms working to support the movement. Dedicated arm training builds both strength and muscular definition.', '54501201', '54501201-EZ-bar-21s_Upper-Arms_.mp4', 'male', FALSE, '2025-12-03 23:26:20.392006+00', '1. Grip the EZ bar on the angled portions for a comfortable wrist position. 2. Set up in the starting position for EZ Bar 21s. 3. Execute the movement with proper form, focusing on your biceps. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'EZ Bar 21s', 'tricep_extension, hammer_curl', FALSE, 'ez_bar', FALSE, 3, 90, 4, 95, 80, 65, 95),
('2603a407-9a0b-47fa-a050-112d3635e6eb', 'Standing Arms And Wrist Circle', 'Arms', 'Bodyweight', '{"Forearms"}'::text[], '{}'::text[], 'The Standing Arms And Wrist Circle strengthens your forearms and grip through a movement motion. The standing position engages your core for stability. A versatile bodyweight movement perfect for home or gym training. Dedicated arm training builds both strength and muscular definition.', '104341201', '104341201-Standing-Arms-and-Wrist-Circle-(male)_Forearms_.mp4', 'male', FALSE, '2025-12-03 23:26:25.737494+00', '1. Stand with feet about shoulder-width apart. 2. Set up in the starting position for Standing Arms And Wrist Circle. 3. Execute the movement with proper form, focusing on your forearms. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 52, 5, 7, FALSE, TRUE, 'wrist_stretch', 'Standing Arms And Wrist Circle', 'bicep_curl, tricep_extension, hammer_curl', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('26072ec0-047f-4a32-b451-ae1b9e7a6039', 'Side Kneeling Push Up', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'Build a stronger chest with this pushing movement that develops pressing power. Secondary activation of your triceps, front delts provides additional muscle engagement. Kneeling helps eliminate lower body momentum from the movement. A versatile bodyweight movement perfect for home or gym training. A well-developed chest contributes to upper body strength and aesthetics. Keep your core engaged throughout the exercise.', '67781201', '67781201-Side-Kneeling-Push-up-(male)_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:26.93819+00', '1. Kneel on the floor (use a pad for comfort if needed). 2. Keep your body in a straight line from head to heels throughout. 3. Lower your chest toward the floor by bending your elbows. 4. Push through your palms to return to the starting position. 5. Repeat for the prescribed number of repetitions. Don''t rush—quality over quantity.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'push_up', 'Side Kneeling Push Up', 'bench_press, chest_fly, dip', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('2607e4a0-b001-4659-8695-8dff1d52acb1', 'Standing Side Neck Stretch', 'Neck', 'Bodyweight', '{"Neck"}'::text[], '{"Traps"}'::text[], 'The Standing Side Neck Stretch is a flexibility exercise that targets your neck, helping to release tension and improve range of motion. The standing position engages your core for stability. Include this in your routine for better mobility and reduced muscle tension.', '73061201', '73061201-Standing-Side-Neck-Stretch-(female)_Neck-FIX_.mp4', 'female', FALSE, '2025-12-03 23:26:38.870314+00', '1. Stand with feet about shoulder-width apart. 2. Move into the stretch position for Standing Side Neck Stretch. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. 5. Switch sides and repeat for equal time.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, 'Standing', NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 42, 2, 6, FALSE, TRUE, 'neck_stretch', 'Standing Side Neck Stretch', 'stretch_hip, stretch_back', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('260818aa-6d6f-404b-afcc-c64bc17ff8fd', 'Lying Hyperextension Hold (Hyperextension Bench)', 'Back', 'Hyperextension Bench', '{"Lower Back"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Develop your posterior chain with this extension movement that emphasizes the glutes. Secondary activation of your hamstrings, lower back provides additional muscle engagement. The lying position provides back support and helps isolate the target muscles. Lower body strength improves everything from walking to heavy compound lifts.', '60181201', '60181201-Lying-Hyperextension-Hold-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:35.250398+00', '1. Lie down in the appropriate position for Lying Hyperextension Hold. 2. Raise your torso by extending at the lower back/hips. 3. Lower with control, maintaining tension. 4. Hold the position for the prescribed time, maintaining tension.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 65, 5, 7, FALSE, TRUE, 'back_extension', 'Lying Hyperextension Hold', 'good_morning, bird_dog, superman', FALSE, 'bodyweight', TRUE, 3, 60, 2, 70, 88, 95, 65),
('261ae046-86f0-4143-9e78-4b83b1497e68', 'Overhead Push Knee Raise - Alternating', 'Core', 'Bodyweight', '{"Lower Abs"}'::text[], '{"Hip Flexors"}'::text[], 'This dynamic pushing movement gets your heart rate up while developing explosive strength. Your hip flexors work as secondary movers, adding to the training stimulus. No equipment needed—your body provides all the resistance. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '78131201', '78131201-Overhead-Push-Alternate-Knee-Raise-(female)_Plyome.mp4', 'female', FALSE, '2025-12-03 23:26:35.667316+00', '1. Raise the weight in the prescribed direction for Overhead Push Alternate Knee Raise. 2. Lower with control, maintaining tension throughout. 3. Alternate between sides/arms/legs with each repetition. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'leg_raise', 'Overhead Push Knee Raise - Alternating', 'crunch, plank, v_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('26312d7b-c846-4f09-9fe6-abb77aa21fa5', 'Seated Forward Reach To W Pose', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Seated Forward Reach To W Pose provides a deep stretch for your hamstrings, ideal for recovery and mobility work. You''ll also feel your lower back working to support the movement. Being seated provides stability, allowing you to focus on the working muscles. Flexibility work like this enhances performance and prevents stiffness.', '84371201', '84371201-Seated-Forward-Reach-to-W-Pose-(female)_Stretching.mp4', 'female', FALSE, '2025-12-03 23:26:36.717157+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Move into the stretch position for Seated Forward Reach To W Pose. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, 'Seated', NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 52, 2, 6, FALSE, TRUE, 'hamstring_stretch', 'Seated Forward Reach To W Pose', 'stretch_hip, stretch_back, plank', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('264dd58b-1991-496e-ac24-00f20860fc26', 'Seated Row - Bent Bar (Cable)', 'Back', 'Cables', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'The Cable Seated Row (bent Bar) is a rowing exercise that builds thickness in your upper back. Secondary activation of your biceps, lats provides additional muscle engagement. Being seated provides stability, allowing you to focus on the working muscles. Cables provide constant tension throughout the full range of motion. A strong back improves posture, prevents injury, and balances pressing movements.', '12381201', '12381201-Cable-Seated-Row-(Bent-Bar)_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:25.123298+00', '1. Adjust the cable machine to the correct height and attachment for Cable Seated Row. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Pull the weight toward your torso, leading with your elbow(s). 4. Squeeze your shoulder blades together at the peak contraction. 5. Extend back out with control, feeling the stretch in your back. 6. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 8, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 84, 7, 8, TRUE, TRUE, 'cable_row', 'Seated Row', 'bent_over_row, lat_pulldown, face_pull', TRUE, 'cable', FALSE, 3, 90, 4, 85, 88, 30, 92),
('26735109-619b-45a1-be50-bb04248adad6', 'Glute Single Leg Bridge From Bench', 'Legs', 'Bodyweight', '{"Glutes"}'::text[], '{"Hamstrings"}'::text[], 'Develop your posterior chain with this bridging movement that emphasizes the glutes. You''ll also feel your hamstrings working to support the movement. Lower body strength improves everything from walking to heavy compound lifts.', '80161201', '80161201-Glute-Single-Leg-Bridge-from-Bench-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:27.805708+00', '1. Drive through your heels to lift your hips toward the ceiling. 2. Squeeze your glutes hard at the top of the movement. 3. Lower your hips back down with control. 4. Complete all reps on one side, then switch to the other side. 5. Complete all reps with control before resting. Control the movement—avoid using momentum. Beneficial for overall legs development.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 45, 7, 8, TRUE, TRUE, 'glute_bridge', 'Glute Single Leg Bridge From Bench', 'hip_thrust, romanian_deadlift', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('267de1ab-d2e7-4cb1-b2f5-62a013fd6e42', 'Opposite Reverse Lunge From Deficit (Dumbbell)', 'Legs', 'Dumbbells, Step Platform', '{"Glutes"}'::text[], '{"Quads","Hamstrings"}'::text[], 'Target the front of your thighs with this lunging exercise for quad development. The glutes, hamstrings assist throughout the movement, making this a well-rounded exercise. The dumbbell variation provides freedom of movement and greater range of motion. Leg training boosts metabolism and builds functional, real-world strength.', '104211201', '104211201-Dumbbell-Opposite-Reverse-Lunge-from-Deficit-(mal.mp4', 'male', FALSE, '2025-12-03 23:26:24.941834+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Opposite Reverse Lunge From Deficit. 2. Step backward, lowering your back knee toward the floor. 3. Push through your front/working leg to return to the starting position. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 4, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 82, 7, 8, TRUE, TRUE, 'lunge', 'Opposite Reverse Lunge From Deficit', 'split_squat, step_up, squat', TRUE, 'dumbbell', FALSE, 3, 90, 4, 92, 90, 92, 90),
('268487dc-c0c4-4e17-aefa-8f56ddfedff6', 'Lying Prone V Lift', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build a stronger back with this movement movement targeting your core. Performing this lying down removes momentum for stricter form. No equipment needed—your body provides all the resistance. Back development is crucial for pulling strength and overall upper body function. Progress gradually by increasing resistance over time.', '89941201', '89941201-Lying-Prone-V-Lift-(male)_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:20.847006+00', '1. Lie face down with your body in a straight line. 2. Set up in the starting position for Lying Prone V Lift. 3. Execute the movement with proper form, focusing on your core. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Lying Prone V Lift', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('26a60814-61a8-4329-bc01-64a7d6e3ae5a', 'Stepback Pulldown', 'Back', 'Bodyweight', '{"Lats"}'::text[], '{"Biceps","Upper Back"}'::text[], 'A challenging plyometric exercise, the Stepback Pulldown builds reactive power and improves conditioning. Secondary activation of your biceps, upper back provides additional muscle engagement. Great for improving athletic performance, burning calories, and building conditioning.', '57661201', '57661201-Stepback-Pulldown-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:39.21093+00', '1. Set up a box or step platform at the appropriate height. 2. Pull the bar/handle down toward your upper chest. 3. Drive your elbows down and back, squeezing your lats. 4. Control the weight back up without letting it yank your arms. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'lat_pulldown', 'Stepback Pulldown', 'pull_up, bent_over_row, cable_row, face_pull', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('26c342f7-b00b-4295-9e45-4e7451c996d2', 'Y Raise (Band)', 'Shoulders', 'Resistance Band', '{"Rear Delts"}'::text[], '{"Upper Back","Rotator Cuff"}'::text[], 'Target your delts with the Band Y Raise, an effective shoulder raising exercise. The upper back assist throughout the movement, making this a well-rounded exercise. Resistance bands provide accommodating resistance that increases through the range of motion. Shoulder development enhances both performance and upper body aesthetics.', '10171201', '10171201-Band-Y-Raise_Shoulders_.mp4', 'male', FALSE, '2025-12-03 23:26:21.608253+00', '1. Secure the resistance band appropriately for Band Y Raise. 2. Raise the weight in the prescribed direction for Band Y Raise. 3. Lower with control, maintaining tension throughout. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 75, 5, 7, FALSE, TRUE, 'lateral_raise', 'Y Raise', 'shoulder_press, front_raise, rear_delt', FALSE, 'band', FALSE, 3, 60, 2, 60, 85, 90, 50),
('26c85b47-374e-4d1f-bda4-c5e68de1b767', 'Seated Cross Body Stretch', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Designed to lengthen your full body, the Seated Cross Body Stretch helps improve mobility and prevent stiffness. Being seated provides stability, allowing you to focus on the working muscles. Include this in your routine for better mobility and reduced muscle tension.', '81281201', '81281201-Seated-Cross-Body-Stretch-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:36.717157+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Move into the stretch position for Seated Cross Body Stretch. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, 'Seated', NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 42, 2, 6, FALSE, TRUE, 'shoulder_stretch', 'Seated Cross Body Stretch', 'stretch_hip, stretch_back, stretch_shoulder', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('26ccb876-3057-42f1-9364-8b6c48595a6c', 'Hip Swirls', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This movement exercise isolates your glutes for improved hip strength and power. No equipment needed—your body provides all the resistance. Leg training boosts metabolism and builds functional, real-world strength.', '46151201', '46151201-Hip-Swirls_Hips.mp4', 'male', FALSE, '2025-12-03 23:26:24.698781+00', '1. Set up in the starting position for Hip Swirls. 2. Execute the movement with proper form, focusing on your glutes. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'glute_exercise', 'Hip Swirls', 'hip_thrust, lunge, squat', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('26d9dd32-df57-40d3-adee-75ce26a680a3', 'Kneeling Incline Finger Press', 'Core', 'Bodyweight', '{"Upper Chest","Core"}'::text[], '{"Hip Flexors"}'::text[], 'The Kneeling Incline Finger Press is an arm pressing exercise targeting your core. Kneeling helps eliminate lower body momentum from the movement. Dedicated arm training builds both strength and muscular definition.', '73201201', '73201201-Kneeling-Incline-Finger-Press-(male)_Forearms_.mp4', 'male', FALSE, '2025-12-03 23:26:22.755209+00', '1. Kneel on the floor (use a pad for comfort if needed). 2. Execute the pressing motion for Kneeling Incline Finger Press, extending through the target muscles. 3. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 73, 7, 8, TRUE, TRUE, 'general_exercise', 'Kneeling Incline Finger Press', 'bench_press, chest_fly, shoulder_press, decline_bench_press', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('26e4e937-6767-41ef-aafe-4d93ba57bb0e', 'Goblet Squat (Medicine Ball)', 'Legs', 'Medicine Ball', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Medicine Ball Goblet Squat is a squatting exercise that primarily loads your quadriceps. Secondary activation of your glutes, hamstrings provides additional muscle engagement. Lower body strength improves everything from walking to heavy compound lifts.', '69401201', '69401201-Medicine-Ball-Goblet-Squat-(male)_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:28.079801+00', '1. Hold a medicine ball at the appropriate position for Medicine Ball Goblet Squat. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Repeat for the prescribed number of repetitions.', 'Squat', NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'goblet_squat', 'Medicine Ball Goblet Squat', 'squat, front_squat, lunge', FALSE, 'medicine_ball', FALSE, 3, 90, 4, 70, 88, 95, 65),
('26f31f1e-4be3-4aae-bf20-81265dd790b2', 'Decline Chest Fly Twisting - (Dumbbell)', 'Chest', 'Dumbbells, Decline Bench', '{"Chest","Lower Chest"}'::text[], '{"Abs"}'::text[], 'Target your chest with the Dumbbell Decline Twist Fly, an effective flying movement for upper body strength. Your abs work as secondary movers, adding to the training stimulus. The decline position targets the lower portion of the muscles more intensely. The dumbbell variation provides freedom of movement and greater range of motion. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '3071201', '03071201-Dumbbell-Decline-Twist-Fly_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:23.172397+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Decline Twist Fly. 2. With a slight bend in your elbows, move the weight in a wide arc. 3. Squeeze your chest muscles at the center/top of the movement. 4. Return with control, feeling the stretch at the bottom. 5. Continue for your target rep count, maintaining good form throughout.', 'Fly', NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 85, 5, 7, FALSE, TRUE, 'russian_twist', 'Decline Twist Fly', 'squat, bench_press, deadlift', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('270b4664-f5b4-4ff6-8853-6e5884e688ce', 'Deadlift (Trap Bar)', 'Back', 'Trap Bar', '{"Lower Back"}'::text[], '{"Glutes","Hamstrings","Traps"}'::text[], 'Build leg strength with this hip hinge movement focusing on your hamstrings/glutes. Secondary activation of your glutes, lower back provides additional muscle engagement. Leg training boosts metabolism and builds functional, real-world strength.', '57581201', '57581201-Trap-Bar-Deadlift-(female)_Thighs_.mp4', 'female', FALSE, '2025-12-03 23:26:39.79101+00', '1. Hinge at hips and bend knees to grip the weight. 2. Drive through your heels, extending hips and knees to stand. 3. Lower by reversing the movement with control. 4. Continue for your target rep count, maintaining good form throughout. Keep your shoulders relaxed and away from your ears.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 3, 6, NULL, 10, NULL, TRUE, NULL, 'Strength', 85, 7, 9, TRUE, FALSE, 'deadlift', 'Deadlift', 'romanian_deadlift, hip_thrust, leg_curl', FALSE, 'barbell', FALSE, 4, 120, 6, 95, 80, 65, 95),
('27244c32-9a7e-4584-8ccc-fefff1b0fcba', 'Seated Jack (Chair)', 'Core', 'Chair', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build leg strength with this movement movement focusing on your core. The seated position helps isolate the target muscles by removing momentum. Strong legs are the foundation for athletic performance and functional fitness.', '84221201', '84221201-Seated-Jack-on-a-Chair-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:27.384461+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Complete all reps with control before resting. Keep your shoulders relaxed and away from your ears. This variation specifically emphasizes the core.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 37, 9, 8, TRUE, TRUE, 'general_exercise', 'Seated Jack On A Chair', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('27278aa9-4df1-4f2b-bd43-082297a9ad43', 'Standing Fly (Cable)', 'Chest', 'Cables', '{"Chest"}'::text[], '{"Front Delts"}'::text[], 'The Cable Standing Fly is a flying exercise that targets your chest muscles. Secondary activation of your front delts provides additional muscle engagement. Performing this standing challenges your balance and core engagement. The cable setup allows you to adjust the angle of resistance. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '2271201', '02271201-Cable-Standing-Fly_Chest.mp4', 'male', FALSE, '2025-12-03 23:26:28.968567+00', '1. Adjust the cable machine to the correct height and attachment for Cable Standing Fly. 2. Stand with feet about shoulder-width apart. 3. With a slight bend in your elbows, move the weight in a wide arc. 4. Squeeze your chest muscles at the center/top of the movement. 5. Return with control, feeling the stretch at the bottom. 6. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 82, 5, 7, FALSE, TRUE, 'chest_fly', 'Standing Fly', 'bench_press, incline_press, push_up', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('2727e332-34aa-4849-94f2-4afcfe5892ee', 'Pull Through (Band)', 'Legs', 'Resistance Band, Anchor Point', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This pulling exercise isolates your glutes for improved hip strength and power. Your hamstrings work as secondary movers, adding to the training stimulus. Bands are joint-friendly and portable, perfect for any training environment. Lower body strength improves everything from walking to heavy compound lifts.', '30241201', '30241201-Band-pull-through-(female)_Hips.mp4', 'female', FALSE, '2025-12-03 23:26:30.887491+00', '1. Secure the resistance band appropriately for Band Pull Through. 2. Set up in the starting position for Band Pull Through. 3. Execute the movement with proper form, focusing on your glutes. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 55, 7, 8, TRUE, TRUE, 'pull_through', 'Pull Through', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('272b5c59-f2e0-4d5f-97ce-9af2ae18cd12', 'Lying Triceps Extension (EZ Bar)', 'Arms', 'EZ Bar, Flat Bench', '{"Triceps"}'::text[], '{"Chest","Shoulders"}'::text[], 'Build stronger triceps with this extension exercise for bigger arms. The lying position provides back support and helps isolate the target muscles. The barbell allows you to handle heavier loads for maximum strength gains. Dedicated arm training builds both strength and muscular definition.', '36461201', '36461201-EZ-Barbell-Lying-Triceps-Extension-(female)_Upper-Arms.mp4', 'female', FALSE, '2025-12-03 23:26:33.505723+00', '1. Grip a barbell with hands at the appropriate width for EZ Barbell Lying Triceps Extension. 2. Lie down in the appropriate position for EZ Barbell Lying Triceps Extension. 3. Extend at the elbow until your arm is straight, squeezing the tricep. 4. Lower with control, keeping your upper arm stationary. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 92, 5, 7, FALSE, TRUE, 'tricep_extension', 'EZ Lying Triceps Extension', 'EZ Lying Triceps Extension', TRUE, 'barbell', FALSE, 3, 60, 2, 95, 80, 65, 95),
('272c2e91-4110-4487-9c2e-1702a5f584fe', 'Long Arm Crunch', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'This crunching exercise engages your abs for improved core stability and strength. The hip flexors assist throughout the movement, making this a well-rounded exercise. This bodyweight exercise requires no equipment and can be done anywhere. Core strength is foundational for athletic performance and injury prevention.', '42651201', '42651201-Long-Arm-Crunch-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:34.855778+00', '1. Curl your shoulders off the floor by contracting your abs. 2. Don''t pull on your neck—focus on the abdominal contraction. 3. Lower with control, maintaining some tension. 4. Continue for your target rep count, maintaining good form throughout. Maintain a neutral spine throughout. Works well for abs activation.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'crunch', 'Long Arm Crunch', 'leg_raise, plank, russian_twist, v_up', TRUE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('272c58f7-ad7b-48c0-857f-68b75893ac08', 'Wide Leg Learning Forward', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Target your full body with this movement stretch that helps restore range of motion. Include this in your routine for better mobility and reduced muscle tension. Aim for full range of motion on every rep. Consistency with this movement will yield noticeable results.', '78901201', '78901201-Wide-Leg-Learning-Forward-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:40.037451+00', '1. Move into the stretch position for Wide Leg Learning Forward. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'leg_exercise', 'Wide Leg Learning Forward', 'squat, lunge, leg_press', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('27337610-b913-438a-b618-4dfb8759a663', 'Crunch (Stability Ball)', 'Core', 'Stability Ball', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'This crunching exercise engages your abs for improved core stability and strength. Your hip flexors work as secondary movers, adding to the training stimulus. Using a ball requires constant core engagement to maintain balance. A strong core improves posture, protects your spine, and enhances all other lifts.', '2711201', '02711201-Crunch-(on-stability-ball)_waist.mp4', 'male', FALSE, '2025-12-03 23:26:27.67144+00', '1. Position the stability ball as needed for Crunch. 2. Curl your shoulders off the floor by contracting your abs. 3. Don''t pull on your neck—focus on the abdominal contraction. 4. Lower with control, maintaining some tension. 5. Continue for your target rep count, maintaining good form throughout. Keep the movement smooth and controlled.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 62, 5, 7, FALSE, TRUE, 'crunch', 'Crunch', 'leg_raise, plank, russian_twist, v_up', TRUE, 'stability_ball', FALSE, 3, 60, 2, 70, 88, 95, 65),
('27510167-ed94-44bf-a176-b76c25d98a84', 'Side Slide', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'This movement exercise engages your abs for improved core stability and strength. This bodyweight exercise requires no equipment and can be done anywhere. Building core stability helps with everything from heavy deadlifts to daily activities. Excellent for pre-exhausting the target muscle before compound lifts.', '51411201', '51411201-Side-Slide-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:37.179953+00', '1. Set up in the starting position for Side Slide. 2. Execute the movement with proper form, focusing on your abs. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Side Slide', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('2754facc-3d7f-41e3-b751-93cf8414bf93', 'Single Leg Split Squat (Band)', 'Legs', 'Resistance Band', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Target the front of your thighs with this squatting exercise for quad development. The glutes, hamstrings assist throughout the movement, making this a well-rounded exercise. The band creates increasing tension as it stretches, challenging the lockout. Leg training boosts metabolism and builds functional, real-world strength.', '10011201', '10011201-Band-Single-Leg-Split-Squat_Hips-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:23.172397+00', '1. Secure the resistance band appropriately for Band Single Leg Split Squat. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Complete all reps on one side, then switch to the other side. 6. Continue for your target rep count, maintaining good form throughout.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'split_squat', 'Single Leg Split Squat', 'lunge, bulgarian_split_squat, squat', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('2763e0b9-8ab3-4d38-9d39-ff4a0a0ccf1b', 'Standing Single Arm Twist Row (Band)', 'Back', 'Resistance Band, Anchor Point', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'Target your rhomboids and mid-traps with this rowing movement. Secondary activation of your abs provides additional muscle engagement. The standing position engages your core for stability. Resistance bands provide accommodating resistance that increases through the range of motion. Back development is crucial for pulling strength and overall upper body function.', '41461201', '41461201-Band-Standing-Single-Arm-Twist-Row_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:23.586683+00', '1. Secure the resistance band appropriately for Band Standing Single Arm Twist Row. 2. Stand tall with your feet firmly planted. 3. Pull the weight toward your torso, leading with your elbow(s). 4. Squeeze your shoulder blades together at the peak contraction. 5. Extend back out with control, feeling the stretch in your back. 6. Complete all reps on one side, then switch to the other side. 7. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 72, 7, 8, TRUE, TRUE, 'russian_twist', 'Standing Single Arm Twist Row', 'bent_over_row, lat_pulldown, bicep_curl', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('27bed310-17b4-49f6-a1d9-4621bbf0d391', 'JM Bench Press (Smith Machine)', 'Chest', 'Smith Machine, Flat Bench', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'The Smith JM Bench Press is an arm pressing exercise targeting your chest. Secondary activation of your triceps, front delts provides additional muscle engagement. The machine guides your movement path for safer, more controlled repetitions. Arm strength supports grip, pulling, and pushing in compound movements.', '93851201', '93851201-Smith-JM-Bench-Press_Upper-Arms_.mp4', 'male', FALSE, '2025-12-03 23:26:27.263406+00', '1. Set the Smith machine bar to the appropriate starting height for Smith JM Bench Press. 2. Lower the weight toward your chest with control. 3. Press the weight up until your arms are extended (don''t lock elbows). 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 8, NULL, FALSE, NULL, 'Strength', 93, 7, 9, TRUE, FALSE, 'bench_press', 'Smith JM Bench Press', 'JM Bench Press', FALSE, 'smith_machine', FALSE, 4, 120, 4, 80, 75, 20, 88),
('27d04052-1862-43cd-8fdb-7b983ac24b77', 'Half Kneeling Hamstrings Stretch (Gymnastic Rings)', 'Legs', 'Gymnastic Rings', '{"Hamstrings"}'::text[], '{"Glutes"}'::text[], 'Designed to lengthen your hamstrings, the Half Kneeling Hamstrings Stretch helps improve mobility and prevent stiffness. You''ll also feel your lower back working to support the movement. Kneeling helps eliminate lower body momentum from the movement. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '105921201', '105921201-Half-Kneeling-Hamstrings-Stretch-(male)_Stretchin.mp4', 'male', FALSE, '2025-12-03 23:26:23.79417+00', '1. Get into a half-kneeling position (one knee down, opposite foot forward). 2. Move into the stretch position for Half Kneeling Hamstrings Stretch. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'stretch_general', 'Half Kneeling Hamstrings Stretch', 'stretch_hip, stretch_calf, stretch_back', FALSE, 'gymnastic_rings', TRUE, 1, 30, 2, 68, 85, 85, 70),
('27d26fae-ac84-400e-ab17-54a4e90cc882', 'Parallel Bars Bent Knee Inverted Row (Dip Bars)', 'Back', 'Dip Bars', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'This rowing exercise strengthens the muscles between your shoulder blades. Secondary activation of your biceps provides additional muscle engagement. Back development is crucial for pulling strength and overall upper body function.', '75541201', '75541201-Parallel-Bars-Bent-Knee-Inverted-Row-(male)_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:21.608253+00', '1. Pull the weight toward your torso, leading with your elbow(s). 2. Squeeze your shoulder blades together at the peak contraction. 3. Extend back out with control, feeling the stretch in your back. 4. Complete all reps with control before resting. Engage your stabilizer muscles for better control.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'dip', 'Parallel Bars Bent Knee Inverted Row', 'squat, leg_extension, lunge', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('27d9f0f3-74a5-40af-ac9d-080ce40fa1c2', 'Dynamic Weight Bearing Ankle Dorsi Flexion (Gymnastic Rings)', 'Legs', 'Gymnastic Rings', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Dynamic Weight Bearing Ankle Dorsi Flexion isolates your calf muscles through a flexion motion. Lower body strength improves everything from walking to heavy compound lifts.', '67121201', '67121201-Dynamic-Weight-Bearing-Ankle-Dorsi-Flexion-(male)_.mp4', 'male', FALSE, '2025-12-03 23:26:25.123298+00', '1. Set up in the starting position for Dynamic Weight Bearing Ankle Dorsi Flexion. 2. Execute the movement with proper form, focusing on your calves. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 38, 7, 8, TRUE, TRUE, 'general_exercise', 'Dynamic Weight Bearing Ankle Dorsi Flexion', 'squat, bench_press, deadlift', FALSE, 'gymnastic_rings', FALSE, 3, 90, 4, 68, 85, 85, 70),
('27de6c69-de02-4359-a387-85b7056ac081', 'Sit Up Punches', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Strengthen your midsection with this movement movement that works your abs. Your hip flexors work as secondary movers, adding to the training stimulus. A versatile bodyweight movement perfect for home or gym training. Core strength is foundational for athletic performance and injury prevention.', '68851201', '68851201-Sit-up-Punches-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:20.667107+00', '1. Set up in the starting position for Sit Up Punches. 2. Execute the movement with proper form, focusing on your abs. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'crunch', 'Sit Up Punches', 'leg_raise, plank, russian_twist, v_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('27e677d4-0528-422c-9295-a4c2e4e264de', 'Incline Fly (Stability Ball, Cable)', 'Chest', 'Cables', '{"Chest"}'::text[], '{"Front Delts"}'::text[], 'The Cable Incline Fly (stability Ball) is a flying exercise that targets your chest muscles. Secondary activation of your front delts provides additional muscle engagement. The incline angle shifts emphasis toward the upper portion of the target muscles. Cables provide constant tension throughout the full range of motion. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '97471201', '97471201-Cable-Incline-Fly-(on-stability-ball)-(female)_Che.mp4', 'female', FALSE, '2025-12-03 23:26:31.931873+00', '1. Adjust the cable machine to the correct height and attachment for Cable Incline Fly. 2. With a slight bend in your elbows, move the weight in a wide arc. 3. Squeeze your chest muscles at the center/top of the movement. 4. Return with control, feeling the stretch at the bottom. 5. Complete all reps with control before resting. Ensure full range of motion on each rep.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 67, 5, 7, FALSE, TRUE, 'chest_fly', 'Incline Fly', 'bench_press, incline_press, push_up', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('27e6c444-5f3b-4f9c-ad2f-aae33746b217', 'Seated Cross Body Hamstring Reach (Gymnastic Rings)', 'Legs', 'Gymnastic Rings', '{"Hamstrings"}'::text[], '{"Glutes"}'::text[], 'Use this stretch to open up your hamstrings area and enhance overall flexibility. You''ll also feel your lower back working to support the movement. The seated position helps isolate the target muscles by removing momentum. Flexibility work like this enhances performance and prevents stiffness.', '83821201', '83821201-Seated-Cross-Body-Hamstring-Reach-(female)_Stretch.mp4', 'female', FALSE, '2025-12-03 23:26:36.717157+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Move into the stretch position for Seated Cross Body Hamstring Reach. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 40, 7, 8, TRUE, TRUE, 'shoulder_stretch', 'Seated Cross Body Hamstring Reach', 'squat, lunge, leg_press', FALSE, 'gymnastic_rings', FALSE, 3, 90, 4, 68, 85, 85, 70),
('27e754e9-b45c-4367-8ef4-9a05171f8512', 'Downward Dog Squat', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Designed to lengthen your quads, the Downward Dog Squat helps improve mobility and prevent stiffness. Secondary activation of your hamstrings, shoulders provides additional muscle engagement. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '87511201', '87511201-Downward-Dog-Squat-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:32.624497+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. Maintain consistent tempo throughout the set. Works well for quads activation.', 'Squat', NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 15, 2, 6, FALSE, TRUE, 'yoga', 'Downward Dog Squat', 'stretch_hip, stretch_back, plank', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('27f9d76e-9c80-4ac2-8953-75db7c4ca8a5', 'Inverted Row Parallel To The Floor (TRX)', 'Back', 'TRX', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'Target your rhomboids and mid-traps with this rowing movement. You''ll also feel your biceps working to support the movement. Suspension training adds instability, increasing core activation throughout. A strong back improves posture, prevents injury, and balances pressing movements.', '94981201', '94981201-Suspender-Inverted-Row-parallel-to-the-floor-(male.mp4', 'male', FALSE, '2025-12-03 23:26:24.203368+00', '1. Adjust the TRX/suspension straps to the appropriate length for Suspender Inverted Row Parallel To The Floor. 2. Position yourself on the floor for Suspender Inverted Row Parallel To The Floor. 3. Pull the weight toward your torso, leading with your elbow(s). 4. Squeeze your shoulder blades together at the peak contraction. 5. Extend back out with control, feeling the stretch in your back. 6. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 55, 7, 8, TRUE, TRUE, 'general_exercise', 'Suspender Inverted Row Parallel To The Floor', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'trx', FALSE, 3, 90, 4, 68, 85, 85, 70),
('27fa978d-1cb0-4e4d-997b-2fbfd4a5898b', 'Lying Pelvic Floor Relaxation And Deep Breathing', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'This movement exercise engages your core for improved core stability and strength. Performing this lying down removes momentum for stricter form. This bodyweight exercise requires no equipment and can be done anywhere. Building core stability helps with everything from heavy deadlifts to daily activities.', '81461201', '81461201-Lying-Pelvic-Floor-Relaxation-and-Deep-Breathing-(.mp4', 'female', FALSE, '2025-12-03 23:26:35.250398+00', '1. Position yourself on the floor for Lying Pelvic Floor Relaxation And Deep Breathing (. 2. Lie down in the appropriate position for Lying Pelvic Floor Relaxation And Deep Breathing (. 3. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 45, 7, 8, TRUE, TRUE, 'breathing', 'Lying Pelvic Floor Relaxation And Deep Breathing (', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('28071bf2-528b-4170-88aa-74dec6ac58d9', 'Tree Yoga Pose Vrksasana', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Designed to lengthen your full body, the Tree Yoga Pose Vrksasana helps improve mobility and prevent stiffness. Include this in your routine for better mobility and reduced muscle tension.', '95291201', '95291201-Tree-Yoga-Pose-Vrksasana-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:39.79101+00', '1. Move into the stretch position for Tree Yoga Pose Vrksasana. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 15, 2, 6, FALSE, TRUE, 'yoga', 'Tree Yoga Pose Vrksasana', 'stretch_hip, stretch_back, plank', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('281083db-b577-4099-8ae2-afc30170e8c7', 'Reverse Hyperextension On Bench (Hyperextension Bench)', 'Back', 'Hyperextension Bench', '{"Lower Back"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Develop your posterior chain with this extension movement that emphasizes the glutes. Your hamstrings, lower back work as secondary movers, adding to the training stimulus. Strong legs are the foundation for athletic performance and functional fitness. Quality repetitions are more important than quantity.', '58031201', '58031201-Reverse-Hyperextension-on-Bench_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:26.39056+00', '1. Raise your torso by extending at the lower back/hips. 2. Lower with control, maintaining tension. 3. Complete all reps with control before resting. Focus on the mind-muscle connection.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'back_extension', 'Reverse Hyperextension On Bench', 'good_morning, bird_dog, superman', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('2812e112-24e9-4102-b41a-4d07a5012015', 'Twist Knee Raise Side Step Jack', 'Core', 'Bodyweight', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'A challenging plyometric exercise, the Twist Knee Raise Side Step Jack builds reactive power and improves conditioning. The hip flexors assist throughout the movement, making this a well-rounded exercise. Plyometric training builds explosive power that transfers to sports and daily activities.', '64761201', '64761201-Twist-Knee-Raise-Side-Step-Jack-(male)_Plyometrics.mp4', 'male', FALSE, '2025-12-03 23:26:26.808474+00', '1. Set up a box or step platform at the appropriate height. 2. Raise your arms out to the sides until parallel to the floor. 3. Lower with control, maintaining tension throughout. 4. Continue for your target rep count, maintaining good form throughout. Don''t rush—quality over quantity.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 70, 9, 8, TRUE, TRUE, 'leg_raise', 'Twist Knee Raise Side Step Jack', 'crunch, plank, v_up', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('283df40b-98c6-4a7c-9276-cd0715f9134c', 'Side Rollout (Barbell)', 'Core', 'Barbell', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Barbell Side Rollout is a lower body movement exercise that targets your abs. Your lats, shoulders work as secondary movers, adding to the training stimulus. The barbell allows you to handle heavier loads for maximum strength gains. Leg training boosts metabolism and builds functional, real-world strength.', '103701201', '103701201-Barbell-Side-Rollout_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:24.203368+00', '1. Grip a barbell with hands at the appropriate width for Barbell Side Rollout. 2. Set up in the starting position for Barbell Side Rollout. 3. Execute the movement with proper form, focusing on your abs. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 62, 7, 8, TRUE, TRUE, 'ab_rollout', 'Side Rollout', 'plank, crunch, dead_bug', FALSE, 'barbell', FALSE, 3, 90, 4, 95, 80, 65, 95),
('284a4a37-8f91-4067-8142-73a8825fb0d6', 'Surrender Side Bend', 'Core', 'Bodyweight', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'Strengthen your midsection with this movement movement that works your abs. The abs assist throughout the movement, making this a well-rounded exercise. A versatile bodyweight movement perfect for home or gym training. Building core stability helps with everything from heavy deadlifts to daily activities.', '93511201', '93511201-Surrender-Side-Bend-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:39.340041+00', '1. Set up in the starting position for Surrender Side Bend. 2. Execute the movement with proper form, focusing on your abs. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions. Focus on the mind-muscle connection.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'side_bend', 'Surrender Side Bend', 'russian_twist, woodchop, oblique_crunch', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('285d7ecd-4e55-47bd-a90d-cbd50502ea3d', 'Standing Obliques Pulse Twist - Alternating', 'Core', 'Bodyweight', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'Build rotational power and define your waistline with the Alternate Obliques Pulse Twist Side Reach. Your abs work as secondary movers, adding to the training stimulus. This bodyweight exercise requires no equipment and can be done anywhere. Building core stability helps with everything from heavy deadlifts to daily activities.', '89091201', '89091201-Alternate-Obliques-Pulse-Twist-Side-Reach-(male)_W.mp4', 'male', FALSE, '2025-12-03 23:26:26.808474+00', '1. Rotate your torso through the movement pattern for Alternate Obliques Pulse Twist Side Reach. 2. Control the rotation in both directions—avoid using momentum. 3. At the bottom or top, pulse up and down in small movements before completing the rep. 4. Alternate between sides/arms/legs with each repetition. 5. Complete all reps with control before resting. Focus on squeezing the target muscle at peak contraction.', NULL, 'Pull', 'Compound', 'Bilateral (Alternating)', NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 52, 5, 7, FALSE, TRUE, 'russian_twist', 'Standing Obliques Pulse Twist - Alternating', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('2860488b-d413-4975-85f4-5a61d8699a50', 'Overhead Clap Knee Raise', 'Core', 'Bodyweight', '{"Lower Abs"}'::text[], '{"Hip Flexors"}'::text[], 'A challenging plyometric exercise, the Overhead Clap Knee Raise builds reactive power and improves conditioning. The hip flexors assist throughout the movement, making this a well-rounded exercise. No equipment needed—your body provides all the resistance. Plyometric training builds explosive power that transfers to sports and daily activities.', '85161201', '85161201-Overhead-Clap-Knee-Raise-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:35.667316+00', '1. Raise the weight in the prescribed direction for Overhead Clap Knee Raise. 2. Lower with control, maintaining tension throughout. 3. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'leg_raise', 'Overhead Clap Knee Raise', 'crunch, plank, v_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('2865d14a-bddd-4ec0-ae7d-44b8803c40a6', 'Cross Body Crunch', 'Core', 'Bodyweight', '{"Obliques"}'::text[], '{"Hip Flexors"}'::text[], 'This dynamic crunching movement gets your heart rate up while developing explosive strength. The shoulders, core assist throughout the movement, making this a well-rounded exercise. This bodyweight exercise requires no equipment and can be done anywhere. Great for improving athletic performance, burning calories, and building conditioning.', '2621201', '02621201-Cross-Body-Crunch_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:23.288245+00', '1. Curl your shoulders off the floor by contracting your abs. 2. Don''t pull on your neck—focus on the abdominal contraction. 3. Lower with control, maintaining some tension. 4. Continue for your target rep count, maintaining good form throughout. Don''t rush—quality over quantity.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'shoulder_stretch', 'Cross Body Crunch', 'plank, leg_raise, russian_twist, sit_up', TRUE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('286dbd8c-b470-4f64-9af0-99e2c2c3003b', 'Lying Sartorius Stretch', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'The Lying Sartorius Stretch is a flexibility exercise that targets your full body, helping to release tension and improve range of motion. The lying position provides back support and helps isolate the target muscles. Flexibility work like this enhances performance and prevents stiffness.', '82601201', '82601201-Lying-Sartorius-Stretch-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:35.250398+00', '1. Lie down in the appropriate position for Lying Sartorius Stretch. 2. Move into the stretch position for Lying Sartorius Stretch. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, 'Lying', NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'hip_stretch', 'Lying Sartorius Stretch', 'stretch_hip, stretch_back, stretch_shoulder', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('2874a6a6-4141-49f2-9a34-0078f2934b8e', 'Walkout Lat Stretch', 'Back', 'Bodyweight', '{"Lats"}'::text[], '{"Lower Back"}'::text[], 'The Walkout Lat Stretch provides a deep stretch for your lats, ideal for recovery and mobility work. The shoulders assist throughout the movement, making this a well-rounded exercise. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '105901201', '105901201-Walkout-Lat-Stretch-(male)_Stretching_.mp4', 'male', FALSE, '2025-12-03 23:26:24.577164+00', '1. Move into the stretch position for Walkout Lat Stretch. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'lat_stretch', 'Walkout Lat Stretch', 'stretch_hip, stretch_back', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('2877ae35-ae11-4b49-9c61-101b10e1d8ec', 'Kneeling Triceps Extension', 'Arms', 'Bodyweight', '{"Triceps"}'::text[], '{"Chest","Shoulders"}'::text[], 'The Bodyweight Kneeling Triceps Extension targets your triceps through a extension motion. Kneeling helps eliminate lower body momentum from the movement. No equipment needed—your body provides all the resistance. Arm strength supports grip, pulling, and pushing in compound movements.', '30361201', '30361201-Bodyweight-Kneeling-Triceps-Extension-(female)_Upper-Arms.mp4', 'female', FALSE, '2025-12-03 23:26:31.347577+00', '1. Kneel on the floor (use a pad for comfort if needed). 2. Extend at the elbow until your arm is straight, squeezing the tricep. 3. Lower with control, keeping your upper arm stationary. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 80, 5, 7, FALSE, TRUE, 'tricep_extension', 'Kneeling Triceps Extension', 'tricep_pushdown, close_grip_bench', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('287be71c-f194-4791-972e-d0322ccb10da', 'Squat Row (Band)', 'Full Body', 'Resistance Band, Anchor Point', '{"Quads","Glutes"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'Target your rhomboids and mid-traps with this rowing movement. You''ll also feel your glutes, hamstrings working to support the movement. Resistance bands provide accommodating resistance that increases through the range of motion. A strong back improves posture, prevents injury, and balances pressing movements.', '10031201', '10031201-Band-Squat-Row_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:22.755209+00', '1. Secure the resistance band appropriately for Band Squat Row. 2. Pull the weight toward your torso, leading with your elbow(s). 3. Squeeze your shoulder blades together at the peak contraction. 4. Extend back out with control, feeling the stretch in your back. 5. Continue for your target rep count, maintaining good form throughout.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 90, 7, 8, TRUE, TRUE, 'squat', 'Squat Row', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('2888be29-25d9-4292-ba6b-f7386282e4e9', 'Split Forward Fold Yoga Pose', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This stretch specifically works on your hamstrings, promoting flexibility and reducing muscle tightness. The lower back, calves assist throughout the movement, making this a well-rounded exercise. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '97661201', '97661201-Split-Forward-Fold-Yoga-Pose-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:38.153182+00', '1. Move into the stretch position for Split Forward Fold Yoga Pose. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 15, 2, 6, FALSE, TRUE, 'hamstring_stretch', 'Split Forward Fold Yoga Pose', 'stretch_hip, stretch_back, plank', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('2890997b-8754-472d-bd9d-3b458798349a', 'Bicep Curl - Single Arm - Neutral Grip (Cable)', 'Arms', 'Cables', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'This curling exercise focuses on your biceps for improved arm size and strength. The forearms assist throughout the movement, making this a well-rounded exercise. The cable setup allows you to adjust the angle of resistance. Arm strength supports grip, pulling, and pushing in compound movements.', '65381201', '65381201-Cable-One-Arm-Neutral-Grip-Biceps-Curl_Upper-Arms_.mp4', 'male', FALSE, '2025-12-03 23:26:21.995567+00', '1. Adjust the cable machine to the correct height and attachment for Cable One Arm Neutral Grip Biceps Curl. 2. Use a neutral grip with palms facing each other. 3. Keep your elbows in a fixed position throughout the movement. 4. Curl the weight up by contracting your biceps, squeezing at the top. 5. Lower with control, resisting the weight on the way down. 6. Complete all reps on one side, then switch to the other side. 7. Complete all reps with control before resting.', 'Curl', 'Pull', NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 85, 5, 7, FALSE, TRUE, 'bicep_curl', 'Single Arm Biceps Curl - Neutral Grip', 'One Arm Biceps Curl - Neutral Grip', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('28966785-6925-433e-b3c3-f4ff756b2baa', 'Standing Air Bike Punch', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{"Shoulders"}'::text[], 'Elevate your training with this movement exercise that develops speed, power, and coordination. Your shoulders work as secondary movers, adding to the training stimulus. Performing this standing challenges your balance and core engagement. A versatile bodyweight movement perfect for home or gym training. Great for improving athletic performance, burning calories, and building conditioning.', '68571201', '68571201-Standing-Air-Bike-Punch-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:38.285955+00', '1. Begin in a standing position with good posture. 2. Set up in the starting position for Standing Air Bike Punch. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 2, 2, NULL, 10, 'Standing', NULL, NULL, NULL, 1, 1, NULL, 3, NULL, TRUE, NULL, 'Cardio', 37, 9, 8, FALSE, TRUE, 'boxing', 'Standing Air Bike Punch', 'core_exercise, shoulder_exercise, burpee', FALSE, 'bodyweight', TRUE, 1, 60, 4, 70, 88, 95, 65),
('2897d73a-6250-4be8-a188-8c3d58dc2e78', 'Lying Bent Knee Hip Abduction (Resistance Band)', 'Legs', 'Resistance Band', '{"Glutes"}'::text[], '{"Hip Abductors"}'::text[], 'The Resistance Band Lying Bent Knee Hip Abduction is a lower body movement exercise that targets your hip abductors. Your glutes work as secondary movers, adding to the training stimulus. Performing this lying down removes momentum for stricter form. The band creates increasing tension as it stretches, challenging the lockout. Lower body strength improves everything from walking to heavy compound lifts.', '71991201', '71991201-Resistance-Band-Lying-Bent-Knee-Hip-Abduction-(fem.mp4', 'female', FALSE, '2025-12-03 23:26:36.128549+00', '1. Secure the resistance band appropriately for Resistance Band Lying Bent Knee Hip Abduction. 2. Lie down in the appropriate position for Resistance Band Lying Bent Knee Hip Abduction. 3. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 55, 7, 8, TRUE, TRUE, 'hip_abduction', 'Lying Bent Knee Hip Abduction', 'hip_adduction, glute_bridge, clamshell', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('289f3815-089c-468c-bd37-24111c4281cb', 'Hack Squat (Smith Machine)', 'Legs', 'Smith Machine', '{Quadriceps}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build stronger quads with this squatting movement that develops leg drive and power. Secondary activation of your glutes provides additional muscle engagement. The machine guides your movement path for safer, more controlled repetitions. Leg training boosts metabolism and builds functional, real-world strength.', '7551201', '07551201-Smith-Hack-Squat_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:22.417605+00', '1. Set the Smith machine bar to the appropriate starting height for Smith Hack Squat. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Repeat for the prescribed number of repetitions.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 9, NULL, FALSE, NULL, 'Strength', 93, 7, 9, TRUE, FALSE, 'hack_squat', 'Smith Hack Squat', 'Hack Squat', FALSE, 'smith_machine', FALSE, 4, 120, 5, 80, 75, 20, 88),
('28ac7812-1639-4f67-8e96-df2844e38f62', 'Twist Lunge Stretch (Stick)', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Target the front of your thighs with this lunging exercise for quad development. The glutes, hamstrings assist throughout the movement, making this a well-rounded exercise. This bodyweight exercise requires no equipment and can be done anywhere. Lower body strength improves everything from walking to heavy compound lifts.', '54081201', '54081201-Stick-Twist-Lunge-Stretch-(female)_Thighs_.mp4', 'female', FALSE, '2025-12-03 23:26:39.340041+00', '1. Step forward into a lunge until both knees are at about 90 degrees. 2. Push through your front/working leg to return to the starting position. 3. Continue for your target rep count, maintaining good form throughout. Keep your shoulders relaxed and away from your ears.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 60, 2, 6, FALSE, TRUE, 'hip_stretch', 'Stick Twist Lunge Stretch', 'squat, split_squat, step_up, leg_press', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('28c20d59-8285-47e0-b63c-f93d956d824d', 'Pass Around Stretch (Stick)', 'Shoulders', 'Bodyweight', '{"Shoulders"}'::text[], '{"Traps"}'::text[], 'Target your delts with the Stick Pass Around Stretch, an effective shoulder stretching exercise. A versatile bodyweight movement perfect for home or gym training. Shoulder development enhances both performance and upper body aesthetics.', '54041201', '54041201-Stick-Pass-Around-Stretch-(female)_Shoulders_.mp4', 'female', FALSE, '2025-12-03 23:26:39.21093+00', '1. Set up in the starting position for Stick Pass Around Stretch. 2. Execute the movement with proper form, focusing on your delts. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'stretch_general', 'Stick Pass Around Stretch', 'stretch_hip, stretch_back, stretch_shoulder', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('28c29370-364c-4d42-ba63-e2100dc3e519', 'Shrug (Barbell)', 'Back', 'Barbell', '{"Traps"}'::text[], '{"Upper Back"}'::text[], 'Build a stronger back with this shrugging movement targeting your traps. Barbells enable bilateral loading for building raw strength. Back development is crucial for pulling strength and overall upper body function.', '951201', '00951201-Barbell-Shrug_Back.mp4', 'male', FALSE, '2025-12-03 23:26:27.504261+00', '1. Grip a barbell with hands at the appropriate width for Barbell Shrug. 2. Shrug your shoulders straight up toward your ears. 3. Hold briefly at the top, then lower with control. 4. Repeat for the prescribed number of repetitions.', 'Pull', 'Pull', 'Isolation', 'Bilateral', NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, 'Overhand', 'Standard', 10, 15, NULL, 4, NULL, FALSE, NULL, 'Strength', 82, 5, 7, FALSE, TRUE, 'shrug', 'Shrug', 'deadlift, bent_over_row, face_pull', FALSE, 'barbell', FALSE, 3, 60, 2, 95, 80, 65, 95);
